def _coerce_unmatched_vehicle_listcar_to_owner_prompt(event: dict, user_text: str | None) -> dict | None:
    if event.get("template") != "listCar":
        return None
    event_data = event.get("data")
    if not isinstance(event_data, dict):
        return None
    plate_match = _VEHICLE_PLATE_RE.search(user_text or "")
    if not plate_match:
        return None
    requested_plate = re.sub(r"[^0-9가-힣]", "", plate_match.group(0))
    metadata = event_data.get("metadata")
    if not isinstance(metadata, list):
        return None
    returned_plates = {
        re.sub(r"[^0-9가-힣]", "", str(meta.get("carNo") or ""))
        for meta in metadata
        if isinstance(meta, dict)
    }
    if requested_plate and requested_plate not in returned_plates:
        return _vehicle_owner_lookup_prompt_event(
            requested_plate,
            owner_provided=bool(_VEHICLE_OWNER_TEXT_RE.search(user_text or "")),
        )
    return None


def _should_reuse_pending_vehicle_lookup_car_no(
    latest_quickreply_tmpl: dict | None,
    user_text: str | None,
    pending_car_no: str | None,
) -> bool:
    if not pending_car_no or not _OWNER_NAME_ONLY_RE.match(user_text or ""):
        return False
    # Primary condition: the immediately previous turn left an unmatched plate
    # waiting for owner-name completion, and the user now provided only a
    # plausible Korean owner name. This is enough to safely reconstruct
    # "car_no + owner_nm" even if template-history persistence races.
    if not isinstance(latest_quickreply_tmpl, dict):
        return True
    template_data = latest_quickreply_tmpl.get("data")
    if not isinstance(template_data, dict):
        return True
    assistant_response = str(template_data.get("assistantResponse") or "")
    quick_replies = template_data.get("quickReplies") or []
    labels = {
        str(chip.get("label") or "").strip()
        for chip in quick_replies
        if isinstance(chip, dict)
    }
    return (
        "차량번호 + 소유주명" in assistant_response
        or "차량번호와 소유주명" in assistant_response
        or "차번+이름으로 검색" in labels
        or "차번+이름 다시 입력" in labels
    )


def _build_maintenance_focus_response(car_name: str, items: list[dict], user_query: str) -> str | None:
    focus = _requested_maintenance_focus(user_query)
    if focus is None:
        return None

    label, patterns, action = focus
    matched_item = next(
        (
            item
            for item in items
            if isinstance(item, dict)
            and any(re.search(pattern, str(item.get("kind_nm") or ""), re.IGNORECASE) for pattern in patterns)
            and str(item.get("exp_dt") or "").strip()
        ),
        None,
    )
    if matched_item is None:
        return None

    exp_dt = str(matched_item.get("exp_dt") or "").strip()
    return (
        f"{car_name}의 {label} 일정은 지난 교체일 기준 {exp_dt}에 {action}하는 것을 권장 드려요. "
        "정확한 진단은 매장에서 받아 보실 수 있어요 😊"
    )


def _build_maintenance_dday_event(tool_result: dict, selected_vehicle: dict, user_query: str) -> dict:
    data = tool_result.get("data") if isinstance(tool_result, dict) else {}
    if isinstance(data, dict) and isinstance(data.get("data"), dict):
        data = data["data"]
    cars = data.get("cars") if isinstance(data, dict) else []
    car_rows = [row for row in cars or [] if isinstance(row, dict)]
    selected_meta = selected_vehicle.get("meta") or {}
    selected_car = selected_vehicle.get("car") or {}
    selected_seq = str(selected_meta.get("mbrCarRegSeq") or "")
    if selected_seq:
        filtered = [row for row in car_rows if str(row.get("mbr_car_reg_seq") or "") == selected_seq]
        if filtered:
            car_rows = filtered
    if not car_rows:
        response = "선택하신 차량의 정비 일정을 확인하지 못했어요. 정비이력 페이지에서 다시 확인해 주세요."
    else:
        lines: list[str] = []
        for car_row in car_rows:
            name = str(car_row.get("car_nm") or selected_car.get("info") or "선택하신 차량").strip()
            focus_response = _build_maintenance_focus_response(name, car_row.get("items") or [], user_query)
            if focus_response:
                response = focus_response
                break
            lines.append(name)
            for item in (car_row.get("items") or [])[:7]:
                if isinstance(item, dict):
                    lines.append(_format_maintenance_dday_item(item))
            lines.append("")
        else:
            lines.append("정비 시기는 차량 등록일·운행 환경에 따라 차이가 있을 수 있어요. 정확한 진단은 매장에서 받아 보실 수 있어요 😊")
            response = "\n".join(lines).strip()
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.SUPPORT.value,
        "assistant_response_source": "code_vehicle_auto_select",
        "data": {
            "assistantResponse": response,
            "quickReplies": [
                {"label": "all my T 점검", "url": CTAUrls.MEMBERSHIP_DASHBOARD, "domain": "SUPPORT"},
                {"label": "매장 예약", "domain": "TRANSACTION"},
                {"label": "타이어 추천 받기", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["SUPPORT", "TRANSACTION", "DISCOVERY"],
        },
    }


_MAINTENANCE_HISTORY_LOOKUP_RE = re.compile(
    r"정비\s*이력|정비이력|정비\s*내역|정비내역|관리받은\s*(?:내역|거)|관리\s*받은\s*(?:내역|거)|"
    r"서비스\s*(?:이력|내역)|받은\s*(?:서비스|정비)|"
    r"(?:마지막|최근|전에|예전에).{0,24}"
    r"(?:휠\s*얼라인먼트|얼라인먼트|오일\s*필터|오일필터|엔진\s*오일|엔진오일|배터리|와이퍼|실내\s*필터|"
    r"타이어\s*(?:교체|장착)|경정비).{0,24}(?:언제|받|교체|갈|했|한\s*적)|"
    r"(?:휠\s*얼라인먼트|얼라인먼트|오일\s*필터|오일필터|엔진\s*오일|엔진오일|배터리|와이퍼|실내\s*필터|"
    r"타이어\s*(?:교체|장착)|경정비).{0,24}(?:받은|교체한|갈았|했던|한)\s*(?:날|날짜|때|적|게)?"
    r".{0,16}(?:언제|있)",
    re.IGNORECASE,
)
_MAINTENANCE_HISTORY_ACCESS_POLICY_RE = re.compile(
    r"(?:(?:정비|서비스|관리)\s*(?:이력|내역)|정비이력|정비내역|관리받은\s*(?:내역|거)|"
    r"관리\s*받은\s*(?:내역|거)|내\s*차\s*(?:이력|내역)).{0,60}"
    r"(?:조회\s*가능|확인\s*가능|볼\s*수|볼수|조회할\s*수|확인할\s*수|매장(?:에서)?\s*(?:조회|확인)|"
    r"아무\s*(?:티스테이션\s*)?(?:매장|지점)|다른\s*(?:지역|매장|지점)|이사|타\s*지역)|"
    r"(?:부산|여수|서울|제주|광주|대전|대구|울산|인천|경기|분당|판교|한남|모란).{0,40}"
    r"(?:(?:정비|서비스|관리)\s*(?:이력|내역)|정비이력|정비내역).{0,40}"
    r"(?:조회\s*가능|확인\s*가능|볼\s*수|볼수|매장(?:에서)?\s*(?:조회|확인))",
    re.IGNORECASE,
)
_MAINTENANCE_HISTORY_SERVICE_RULES: tuple[tuple[str, tuple[str, ...]], ...] = (
    ("휠얼라인먼트", (r"휠\s*얼라인먼트", r"얼라인먼트")),
    ("오일필터", (r"오일\s*필터", r"오일필터")),
    ("엔진오일", (r"엔진\s*오일", r"엔진오일")),
    ("배터리", (r"배터리",)),
    ("와이퍼", (r"와이퍼",)),
    ("실내필터", (r"실내\s*필터", r"에어컨\s*필터", r"캐빈\s*필터")),
    ("타이어 교체", (r"타이어\s*(?:교체|장착)",)),
    ("경정비", (r"경정비",)),
)


def _is_maintenance_history_lookup_query(user_text: str | None) -> bool:
    text = user_text or ""
    return bool(_MAINTENANCE_HISTORY_LOOKUP_RE.search(text) and not _is_maintenance_history_access_policy_query(text))


def _is_maintenance_history_access_policy_query(user_text: str | None) -> bool:
    return bool(_MAINTENANCE_HISTORY_ACCESS_POLICY_RE.search(user_text or ""))


def _requested_maintenance_history_item(user_text: str | None) -> tuple[str, tuple[str, ...]] | None:
    text = user_text or ""
    for label, patterns in _MAINTENANCE_HISTORY_SERVICE_RULES:
        if any(re.search(pattern, text, re.IGNORECASE) for pattern in patterns):
            return label, patterns
    return None


def _maintenance_history_items(tool_result: dict) -> list[dict]:
    data = _unwrap_tool_data(tool_result)
    raw_items = data.get("items") or data.get("histories") or data.get("maintenance_history") or []
    if isinstance(raw_items, dict):
        raw_items = raw_items.get("items") or raw_items.get("list") or []
    if not isinstance(raw_items, list):
        return []
    return [item for item in raw_items if isinstance(item, dict)]


def _maintenance_history_text(item: dict) -> str:
    values = [
        item.get("car_svc_info"),
        item.get("item_nm"),
        item.get("svc_nm"),
        item.get("service_nm"),
        item.get("svc_tp"),
        item.get("goods_nm"),
    ]
    return " ".join(str(value or "") for value in values)


def _maintenance_history_matches_item(item: dict, patterns: tuple[str, ...]) -> bool:
    haystack = _maintenance_history_text(item)
    return any(re.search(pattern, haystack, re.IGNORECASE) for pattern in patterns)


def _maintenance_history_field(item: dict, *keys: str) -> str:
    for key in keys:
        value = str(item.get(key) or "").strip()
        if value:
            return value
    return ""


def _format_maintenance_history_row(item: dict) -> str:
    date = _maintenance_history_field(item, "car_svc_dt", "svc_dt", "service_dt", "ord_dt", "date")
    shop = _maintenance_history_field(item, "shop_nm", "store_nm", "shop_name")
    service = _maintenance_history_field(item, "car_svc_info", "item_nm", "svc_nm", "service_nm", "svc_tp")
    qty = _maintenance_history_field(item, "car_svc_qty", "qty", "quantity")
    parts = [part for part in (date, shop, service) if part]
    if qty:
        parts.append(f"{qty}개")
    return " / ".join(parts) if parts else "정비 이력 항목"


def _build_maintenance_history_event(tool_result: dict, user_query: str) -> dict:
    items = _maintenance_history_items(tool_result)
    focus = _requested_maintenance_history_item(user_query)
    rows = items
    if focus is not None:
        _label, patterns = focus
        matched_rows = [item for item in items if _maintenance_history_matches_item(item, patterns)]
        rows = matched_rows

    if tool_result.get("status") == "error":
        assistant_response = (
            "정비이력 조회 중 오류가 발생했어요. 잠시 후 다시 시도하거나 정비이력 페이지에서 확인해 주세요."
        )
    elif not items:
        assistant_response = "최근 5년 내 확인되는 정비이력이 없어요.\n\n자세한 내용은 정비이력 페이지에서 확인할 수 있어요."
    elif focus is not None and not rows:
        label = focus[0]
        assistant_response = (
            f"최근 정비이력에서 {label} 항목은 확인되지 않아요.\n\n"
            "전체 정비이력은 정비이력 페이지에서 직접 확인할 수 있어요."
        )
    elif focus is not None:
        label = focus[0]
        top = rows[0]
        assistant_response = (
            f"최근 {label} 이력은 다음과 같이 확인돼요.\n"
            f"• {_format_maintenance_history_row(top)}\n\n"
            "자세한 내용은 정비이력 페이지에서 확인할 수 있어요."
        )
    else:
        lines = ["최근 정비이력은 다음과 같이 확인돼요."]
        lines.extend(f"• {_format_maintenance_history_row(item)}" for item in rows[:5])
        lines.append("")
        lines.append("자세한 내용은 정비이력 페이지에서 확인할 수 있어요.")
        assistant_response = "\n".join(lines).strip()

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_maintenance_history_lookup",
        "data": {
            "assistantResponse": assistant_response,
            "quickReplies": [
                {"label": "정비이력보기", "url": CTAUrls.STORE_SERVICE_HISTORY, "domain": "SUPPORT"},
                {"label": "내 주문 조회", "domain": "TRANSACTION"},
                {"label": "다른 정비 문의", "domain": "SUPPORT"},
            ],
            "predictedDomains": ["TRANSACTION", "SUPPORT"],
            "metadata": {
                "responseShapeKey": "maintenance_history_lookup",
                "requestedServiceItem": focus[0] if focus else None,
            },
        },
    }


def _build_maintenance_history_access_policy_event(user_query: str) -> dict:
    assistant_response = (
        "티스테이션 매장에서는 고객/차량 정보 기준으로 정비·서비스 이력 확인이 가능할 수 있어요.\n\n"
        "다른 지역 매장에 방문하더라도 차량번호나 예약자 정보로 확인을 요청해 주세요. "
        "다만 매장 시스템 권한이나 이력 종류에 따라 확인 범위가 달라질 수 있어요.\n\n"
        "상세 이력은 마이페이지 > 매장서비스 내역에서도 확인할 수 있어요."
    )
    if re.search(r"아무\s*(?:티스테이션\s*)?(?:매장|지점)|다른\s*(?:지역|매장|지점)|이사", user_query, re.IGNORECASE):
        assistant_response = (
            "이사 후 다른 지역 티스테이션 매장에 방문해도 고객/차량 정보 기준으로 정비·서비스 이력 확인을 요청할 수 있어요.\n\n"
            "방문 시 차량번호나 예약자 정보를 알려주시면 매장에서 확인을 도와드릴 수 있고, "
            "시스템 권한이나 이력 종류에 따라 확인 범위는 달라질 수 있어요.\n\n"
            "상세 이력은 마이페이지 > 매장서비스 내역에서도 확인할 수 있어요."
        )
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.SUPPORT.value,
        "assistant_response_source": "code_maintenance_history_access_policy",
        "data": {
            "assistantResponse": assistant_response,
            "quickReplies": [
                {"label": "매장서비스 내역", "url": CTAUrls.STORE_SERVICE_HISTORY, "domain": "SUPPORT"},
                {"label": "가까운 매장 찾기", "domain": "TRANSACTION"},
                {"label": "정비이력 조회", "domain": "TRANSACTION"},
            ],
            "predictedDomains": ["SUPPORT", "TRANSACTION"],
            "metadata": {
                "responseShapeKey": "maintenance_history_access_policy",
                "maintenanceHistoryAccessPolicy": True,
            },
        },
    }


def _build_vehicle_size_guidance_event(selected_vehicle: dict) -> dict | None:
    selected_car = selected_vehicle.get("car") or {}
    selected_meta = selected_vehicle.get("meta") or {}
    front_size = str(selected_meta.get("tireSize") or "").strip()
    rear_size = str(selected_meta.get("tireSizeRe") or "").strip()
    car_info = str(selected_car.get("info") or selected_car.get("description") or "선택하신 차량").strip()
    car_no = str(selected_meta.get("carNo") or selected_car.get("licensePlate") or "").strip()
    if not front_size and not rear_size:
        return None

    if front_size and rear_size and front_size != rear_size:
        response = (
            f"**{car_info} ({car_no})**의 순정 규격은 전륜 **{front_size}**, 후륜 **{rear_size}**예요.\n\n"
            "앞뒤 규격이 다르면 한 가지 사이즈만 보면 안 되고, 전륜용 2개와 후륜용 2개를 각각 맞는 규격으로 확인해야 해요."
        )
    else:
        size = front_size or rear_size
        response = (
            f"**{car_info} ({car_no})**의 전/후륜 규격은 동일하게 **{size}**예요.\n\n"
            "같은 규격으로 상품을 확인하시면 됩니다."
        )

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_vehicle_auto_select",
        "data": {
            "assistantResponse": response,
            "quickReplies": [
                {"label": "사이즈 직접 입력", "domain": "DISCOVERY"},
                {"label": "맞는 타이어 추천", "domain": "DISCOVERY"},
                {"label": "다른 차량 확인", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["DISCOVERY"],
        },
    }


def _build_vehicle_information_event(selected_vehicle: dict, user_text: str) -> dict | None:
    if _VEHICLE_SIZE_GUIDANCE_TEXT_RE.search(user_text or ""):
        return _build_vehicle_size_guidance_event(selected_vehicle)

    if not _VEHICLE_INFO_TEXT_RE.search(user_text or ""):
        return None

    selected_car = selected_vehicle.get("car") or {}
    selected_meta = selected_vehicle.get("meta") or {}
    front_size = str(selected_meta.get("tireSize") or "").strip()
    rear_size = str(selected_meta.get("tireSizeRe") or "").strip()
    car_info = str(selected_car.get("info") or selected_car.get("description") or "선택하신 차량").strip()
    car_no = str(selected_meta.get("carNo") or selected_car.get("licensePlate") or "").strip()

    size_line = ""
    if front_size and rear_size and front_size != rear_size:
        size_line = f"전륜 **{front_size}**, 후륜 **{rear_size}**"
    elif front_size or rear_size:
        size_line = f"전/후륜 동일 규격 **{front_size or rear_size}**"

    response = f"**{car_info} ({car_no})** 차량으로 확인했어요."
    if size_line:
        response += f"\n\n현재 확인되는 규격은 {size_line}예요."
    response += "\n\n원하시는 항목을 선택해 주시면 그 기준으로 이어서 도와드릴게요."

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_vehicle_auto_select",
        "data": {
            "assistantResponse": response,
            "quickReplies": [
                {"label": "전/후륜 규격 보기", "domain": "DISCOVERY"},
                {"label": "맞는 타이어 추천", "domain": "DISCOVERY"},
                {"label": "동일 상품 찾기", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["DISCOVERY"],
        },
    }


_FRONT_TIRE_CHIP_LABEL = "앞바퀴사이즈"
_REAR_TIRE_CHIP_LABEL = "뒷바퀴사이즈"
_CUSTOM_TIRE_CHIP_LABEL = "다른 사이즈 입력"
_FRONT_TIRE_SELECTION_RE = re.compile(r"앞\s*바퀴|전륜|앞\s*타이어", re.IGNORECASE)
_REAR_TIRE_SELECTION_RE = re.compile(r"뒤\s*바퀴|뒷\s*바퀴|후륜|뒤\s*타이어|뒷\s*타이어", re.IGNORECASE)
_TIRE_POSITION_FOLLOWUP_ACTION_RE = re.compile(
    r"추천|찾|검색|재고|가격|주문|구매|장착|진행|볼래|봐줘|알려줘|도\s*추천",
    re.IGNORECASE,
)
_QUANTITYLESS_CART_ORDER_CTA_RE = re.compile(
    r"^\s*(?:장바구니\s*담기|장바구니에?\s*담(?:아줘|기)?|담아줘|구매하기|주문하기|바로\s*주문|결제하기)\s*$",
    re.IGNORECASE,
)
_PREORDER_CONFIRMATION_RE = re.compile(
    r"^\s*(?:"
    r"주문\s*확정|구매하기|주문하기|결제하기|"
    r"주문해줘|구매해줘|결제해줘|"
    r"주문\s*진행|결제\s*진행|진행해(?:줘)?|바로\s*주문|"
    r"네|넵|넹|예|응|그래|좋아|ㅇㅇ|ㅇㅋ|ok|okay"
    r")\s*$",
    re.IGNORECASE,
)


def _normalize_vehicle_tire_size_pair(selected_meta: dict[str, Any]) -> tuple[str | None, str | None]:
    front_size = normalize_tire_size(str(selected_meta.get("tireSize") or selected_meta.get("tire_size") or ""))
    rear_size = normalize_tire_size(str(selected_meta.get("tireSizeRe") or selected_meta.get("tire_size_re") or ""))
    return front_size, rear_size


def _has_staggered_vehicle_tire_sizes(front_size: str | None, rear_size: str | None) -> bool:
    return bool(front_size and rear_size and front_size != rear_size)


def _preorder_payload(template_data: dict | None) -> dict[str, Any] | None:
    if not isinstance(template_data, dict):
        return None
    if template_data.get("template") == "preOrder" and isinstance(template_data.get("data"), dict):
        return template_data["data"]
    return template_data if isinstance(template_data.get("orderInfo"), dict) else None


def _is_ready_preorder_template(template_data: dict | None) -> bool:
    payload = _preorder_payload(template_data)
    return bool(isinstance(payload, dict) and payload.get("isReadyToOrder"))


def _is_preorder_confirmation_reply(user_text: str | None, latest_preorder_tmpl: dict | None) -> bool:
    if not _is_ready_preorder_template(latest_preorder_tmpl):
        return False
    return bool(_PREORDER_CONFIRMATION_RE.match(str(user_text or "").strip()))


def _is_staggered_selected_tire_size_context(slots: Any) -> bool:
    front_size = normalize_tire_size(str(getattr(slots, "tire_size_front", None) or ""))
    rear_size = normalize_tire_size(str(getattr(slots, "tire_size_rear", None) or ""))
    selected_size = normalize_tire_size(str(getattr(slots, "tire_size", None) or ""))
    return (
        _has_staggered_vehicle_tire_sizes(front_size, rear_size)
        and selected_size in {front_size, rear_size}
    )


def _build_staggered_tire_quantity_limit_event(slots: Any) -> dict | None:
    if not _is_staggered_selected_tire_size_context(slots):
        return None

    selected_size = normalize_tire_size(str(getattr(slots, "tire_size", None) or ""))
    front_size = normalize_tire_size(str(getattr(slots, "tire_size_front", None) or ""))
    rear_size = normalize_tire_size(str(getattr(slots, "tire_size_rear", None) or ""))
    axle_label = "앞바퀴" if selected_size == front_size else "뒷바퀴" if selected_size == rear_size else "선택한"
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_staggered_tire_quantity_limit",
        "data": {
            "assistantResponse": (
                f"앞/뒤 사이즈가 다른 차량은 {axle_label} 규격 **{selected_size}** 기준으로 "
                "최대 2개까지 선택할 수 있어요.\n\n수량을 다시 선택해 주세요."
            ),
            "quickReplies": [
                {"label": "1개", "domain": "TRANSACTION"},
                {"label": "2개", "domain": "TRANSACTION"},
            ],
            "predictedDomains": ["TRANSACTION"],
        },
    }


def _build_order_quantity_prompt_event(slots: Any) -> dict:
    selected_size = normalize_tire_size(str(getattr(slots, "tire_size", None) or ""))
    if _is_staggered_selected_tire_size_context(slots):
        front_size = normalize_tire_size(str(getattr(slots, "tire_size_front", None) or ""))
        rear_size = normalize_tire_size(str(getattr(slots, "tire_size_rear", None) or ""))
        axle_label = "앞바퀴" if selected_size == front_size else "뒷바퀴" if selected_size == rear_size else "현재"
        assistant_response = (
            f"{axle_label} **{selected_size}** 기준으로 몇 개 구매하실까요?\n\n"
            "이 차량은 앞/뒤 규격이 달라 현재 규격은 최대 2개까지 선택할 수 있어요."
        )
        quick_replies = [
            {"label": "1개", "domain": "TRANSACTION"},
            {"label": "2개", "domain": "TRANSACTION"},
        ]
    else:
        size_text = f" **{selected_size}** 기준으로" if selected_size else ""
        assistant_response = f"타이어{size_text} 몇 개 구매하실까요?"
        quick_replies = [
            {"label": "1개", "domain": "TRANSACTION"},
            {"label": "2개", "domain": "TRANSACTION"},
            {"label": "3개", "domain": "TRANSACTION"},
            {"label": "4개", "domain": "TRANSACTION"},
        ]

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_order_quantity_prompt",
        "data": {
            "assistantResponse": assistant_response,
            "quickReplies": quick_replies,
            "predictedDomains": ["TRANSACTION"],
        },
    }


def _should_prompt_order_quantity_before_store(
    user_text: str | None,
    slots: Any,
    *,
    goods_no_resolved_this_turn: bool = False,
) -> bool:
    from schemas.tstation.slots import ConversationSlots

    text = str(user_text or "").strip()
    if getattr(slots, "goods_no", None) is None:
        return False
    if getattr(slots, "ord_qty", None) is not None:
        return False
    if getattr(slots, "pending_intent", None) != "order" and getattr(slots, "goal_type", None) != "place_order":
        return False
    if ConversationSlots.extract_from_user_text(text).ord_qty is not None:
        return False
    if goods_no_resolved_this_turn:
        return True
    return _is_order_quantity_prompt_continuation_text(text)


def _is_order_quantity_prompt_continuation_text(user_text: str | None) -> bool:
    text = str(user_text or "").strip()
    if not text:
        return False

    if re.search(
        r"내역|조회|취소|변경|내\s*차|내차|차량|쿠폰|정비|질소|얼라인먼트|무료|잘\s*봐|"
        r"상세\s*정보|상세정보|정보|설명|어때|뭐야|다른\s*상품|추천|아니|처음|문의|고객센터",
        text,
        re.IGNORECASE,
    ):
        return False

    if _QUANTITYLESS_CART_ORDER_CTA_RE.search(text):
        return True

    frame = build_transaction_intent_frame(text)
    has_bare_location = bool(frame.entities.get("store_name") or frame.entities.get("region")) and len(text) <= 12
    if has_bare_location:
        return True

    if re.search(
        r"근처\s*매장|주변\s*매장|매장\s*찾|오늘\s*장착|당일\s*장착|장착\s*가능|"
        r"재고|예약\s*가능|가능\s*시간|가능\s*일정|방문\s*예약|구매|주문|결제",
        text,
        re.IGNORECASE,
    ):
        return True

    return False


def _is_quantityless_cart_or_order_cta(user_text: str | None) -> bool:
    return bool(_QUANTITYLESS_CART_ORDER_CTA_RE.search(str(user_text or "")))


def _build_staggered_vehicle_tire_selection_event(selected_vehicle: dict) -> dict | None:
    selected_car = selected_vehicle.get("car") or {}
    selected_meta = selected_vehicle.get("meta") or {}
    front_size, rear_size = _normalize_vehicle_tire_size_pair(selected_meta)
    if not _has_staggered_vehicle_tire_sizes(front_size, rear_size):
        return None

    car_info = str(selected_car.get("info") or selected_car.get("description") or "선택하신 차량").strip()
    car_no = str(selected_meta.get("carNo") or selected_car.get("licensePlate") or "").strip()
    vehicle_label = f"**{car_info} ({car_no})**" if car_no else f"**{car_info}**"
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_vehicle_staggered_tire_prompt",
        "data": {
            "assistantResponse": (
                f"{vehicle_label}의 규격은 전륜 **{front_size}**, 후륜 **{rear_size}**예요.\n\n"
                "앞/뒤 사이즈가 다릅니다. 어떤 사이즈 기준으로 검색할까요?"
            ),
            "quickReplies": [
                {"label": _FRONT_TIRE_CHIP_LABEL, "domain": "DISCOVERY"},
                {"label": _REAR_TIRE_CHIP_LABEL, "domain": "DISCOVERY"},
                {"label": _CUSTOM_TIRE_CHIP_LABEL, "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["DISCOVERY"],
        },
    }


def _build_manual_tire_size_input_event() -> dict:
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_vehicle_manual_tire_size_prompt",
        "data": {
            "assistantResponse": "검색할 타이어 사이즈를 직접 입력해 주세요. 예: 225/50R18",
            "quickReplies": [
                {"label": "앞바퀴사이즈", "domain": "DISCOVERY"},
                {"label": "뒷바퀴사이즈", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["DISCOVERY"],
        },
    }


def _listcar_allows_staggered_tire_prompt(template_data: dict | None) -> bool:
    if not isinstance(template_data, dict):
        return True
    source_domain = str(template_data.get("source_domain") or "").strip().lower()
    return source_domain in {"", MultiAgentDomain.Domain.DISCOVERY.value}


def _quickreply_labels(template_data: dict | None) -> set[str]:
    labels: set[str] = set()
    if not isinstance(template_data, dict):
        return labels
    data = template_data.get("data")
    if not isinstance(data, dict):
        return labels
    for quick_reply in data.get("quickReplies") or []:
        if isinstance(quick_reply, dict):
            label = str(quick_reply.get("label") or "").strip()
            if label:
                labels.add(label)
    return labels


def _is_manual_tire_size_input_selection(user_text: str | None, latest_quickreply_tmpl: dict | None) -> bool:
    return (
        str(user_text or "").strip() == _CUSTOM_TIRE_CHIP_LABEL
        and _CUSTOM_TIRE_CHIP_LABEL in _quickreply_labels(latest_quickreply_tmpl)
    )


def _resolve_vehicle_tire_position_selection(
    user_text: str | None,
    slots: Any,
    latest_quickreply_tmpl: dict | None = None,
) -> str | None:
    text = str(user_text or "").strip()
    if not text or normalize_tire_size(text):
        return None

    front_size = normalize_tire_size(str(getattr(slots, "tire_size_front", None) or ""))
    rear_size = normalize_tire_size(str(getattr(slots, "tire_size_rear", None) or ""))
    if not _has_staggered_vehicle_tire_sizes(front_size, rear_size):
        return None

    latest_labels = _quickreply_labels(latest_quickreply_tmpl)

    if text == _FRONT_TIRE_CHIP_LABEL and _FRONT_TIRE_CHIP_LABEL in latest_labels:
        return front_size
    if text == _REAR_TIRE_CHIP_LABEL and _REAR_TIRE_CHIP_LABEL in latest_labels:
        return rear_size
    if text == _CUSTOM_TIRE_CHIP_LABEL and _CUSTOM_TIRE_CHIP_LABEL in latest_labels:
        return None
    if (
        _FRONT_TIRE_SELECTION_RE.search(text)
        and not _REAR_TIRE_SELECTION_RE.search(text)
        and _TIRE_POSITION_FOLLOWUP_ACTION_RE.search(text)
    ):
        return _FRONT_TIRE_SELECTION_RE.sub(front_size, text, count=1)
    if _REAR_TIRE_SELECTION_RE.search(text) and _TIRE_POSITION_FOLLOWUP_ACTION_RE.search(text):
        return _REAR_TIRE_SELECTION_RE.sub(rear_size, text, count=1)
    return None


def _normalize_vehicle_type_from_car_type(raw_car_type: Any, *, fallback_text: str | None = None) -> str | None:
    """Normalize registered car type into recommendation vehicle_type."""
    combined = " ".join(
        part
        for part in (
            str(raw_car_type or "").strip(),
            str(fallback_text or "").strip(),
        )
        if part
    )
    if not combined:
        return None

    normalized = re.sub(r"[\s_\-/]+", "", combined).lower()
    if re.search(r"전기차|electric|아이오닉|ioniq|electrified|gv70ev|\bev\b", combined, re.IGNORECASE):
        return "ev"
    if "스포츠유틸리티" in normalized or "suv" in normalized:
        return "suv"
    if any(token in normalized for token in ("승용차", "승용", "세단", "sedan", "스포츠카", "passenger")):
        return "passenger"
    if any(token in normalized for token in ("경트럭", "트럭", "truck", "밴", "van", "화물")):
        return "truck_van"
    return None


def _vehicle_selection_slot_values(selected_vehicle: dict | None) -> dict[str, Any]:
    selected_car = (selected_vehicle or {}).get("car") or {}
    selected_meta = (selected_vehicle or {}).get("meta") or {}
    front_size, rear_size = _normalize_vehicle_tire_size_pair(selected_meta)

    slot_values: dict[str, Any] = {}
    if front_size:
        slot_values["tire_size_front"] = front_size
    if rear_size:
        slot_values["tire_size_rear"] = rear_size
    if front_size and (not rear_size or front_size == rear_size):
        slot_values["tire_size"] = front_size
    elif rear_size and not front_size:
        slot_values["tire_size"] = rear_size

    raw_car_model = (
        selected_meta.get("carModel")
        or selected_meta.get("carNm")
        or selected_car.get("model")
        or selected_car.get("name")
    )
    car_model = str(raw_car_model or "").strip()
    if car_model:
        slot_values["car_model"] = car_model
    car_no = str(selected_meta.get("carNo") or selected_car.get("licensePlate") or "").strip()
    if car_no:
        slot_values["car_no"] = car_no
    car_lnc_cd = str(selected_meta.get("carLncCd") or "").strip()
    if car_lnc_cd:
        slot_values["car_lnc_cd"] = car_lnc_cd
    raw_car_type = (
        selected_meta.get("carType")
        or selected_meta.get("car_type")
        or selected_meta.get("carTypeNm")
        or selected_meta.get("car_type_nm")
        or selected_car.get("carType")
        or selected_car.get("car_type")
        or selected_car.get("type")
        or selected_car.get("vehicleType")
    )
    car_type = str(raw_car_type or "").strip()
    vehicle_type = _normalize_vehicle_type_from_car_type(
        car_type,
        fallback_text=" ".join(
            part
            for part in (
                car_model,
                str(selected_car.get("info") or selected_car.get("description") or "").strip(),
            )
            if part
        ),
    )
    if car_type:
        slot_values["car_type"] = car_type
    if vehicle_type:
        slot_values["vehicle_type"] = vehicle_type
    mbr_car_reg_seq = str(selected_meta.get("mbrCarRegSeq") or "").strip()
    if mbr_car_reg_seq:
        slot_values["mbr_car_reg_seq"] = mbr_car_reg_seq

    return slot_values


def _apply_vehicle_selection_slot_values(base_slots: Any, slot_values: dict[str, Any]) -> Any:
    """Apply selected-vehicle slots as one atomic replacement.

    Generic ConversationSlots.merge() is field-ordered and may reset front/rear
    sizes after setting them when car_model/car_no changes. Vehicle selection is
    different: the vehicle identity and tire sizes arrive as one confirmed set.
    """
    updated = base_slots.model_copy()

    vehicle_fields = {
        "car_model",
        "car_no",
        "car_lnc_cd",
        "car_type",
        "vehicle_type",
        "mbr_car_reg_seq",
        "tire_size",
        "tire_size_front",
        "tire_size_rear",
    }
    for field in vehicle_fields:
        setattr(updated, field, slot_values.get(field))

    if getattr(updated, "tire_size", None) != getattr(base_slots, "tire_size", None):
        updated.goods_no = None
        updated.payment_amount = None

    if (
        getattr(updated, "car_no", None) != getattr(base_slots, "car_no", None)
        or getattr(updated, "car_lnc_cd", None) != getattr(base_slots, "car_lnc_cd", None)
        or getattr(updated, "car_model", None) != getattr(base_slots, "car_model", None)
    ):
        updated.goods_no = None
        updated.payment_amount = None

    return updated


def _brand_label_for_code(brand_cd: str) -> str:
    return {
        "HK": "한국타이어",
        "LF": "라우펜",
        "MC": "미쉐린",
        "PI": "피렐리",
        "BS": "브리지스톤",
        "CT": "콘티넨탈",
        "GY": "굿이어",
    }.get(str(brand_cd or "").strip().upper(), "해당 브랜드")


def _is_order_history_reorder_query(user_text: str | None) -> bool:
    text = user_text or ""
    if not text:
        return False
    if _OE_REPLACEMENT_STRONG_ANCHOR_RE.search(text):
        return False
    return bool(
        _ORDER_HISTORY_REORDER_PREVIOUS_RE.search(text)
        and _ORDER_HISTORY_REORDER_ACTION_RE.search(text)
        and _ORDER_HISTORY_REORDER_SAME_RE.search(text)
    )


def _extract_vehicle_plate_from_text(user_text: str | None) -> str | None:
    match = _VEHICLE_PLATE_RE.search(user_text or "")
    if not match:
        return None
    return re.sub(r"[^0-9가-힣]", "", match.group(0))


def _is_oe_replacement_equivalent_query(user_text: str | None) -> bool:
    if _is_order_history_reorder_query(user_text):
        return False
    return bool(_OE_REPLACEMENT_EQUIVALENT_RE.search(user_text or ""))


def _is_owned_vehicle_selection_cta(user_text: str | None) -> bool:
    return bool(_OWNED_VEHICLE_SELECTION_CTA_RE.match(user_text or ""))


def _is_oe_replacement_context(context_text: str | None, current_text: str | None) -> bool:
    return _is_oe_replacement_equivalent_query(context_text) and not _is_owned_vehicle_selection_cta(current_text)


def _should_force_best_seller_code_route(user_text: str | None, domains: list[MultiAgentDomain.Domain]) -> bool:
    """Use deterministic best-seller tool routing even if 구매한 biases domain classification.

    Aggregate sales questions such as "이번 달 제일 많이 산 타이어" are Discovery
    best-seller lookups, not the user's own purchase/order flow.
    """
    text = user_text or ""
    if not best_seller_period_from_text(text):
        return False
    frame = build_discovery_intent_frame(text)
    if frame.sub_intent != "best_seller_search":
        return False
    if domains == [MultiAgentDomain.Domain.DISCOVERY]:
        return True
    return is_best_seller_request(text, include_demographic_preference=False)


def _enrich_best_selling_result_for_product_cards(tool_result: dict) -> dict:
    data = tool_result.get("data") if isinstance(tool_result, dict) else None
    if not isinstance(data, dict) or not isinstance(data.get("items"), list):
        return tool_result

    from services.tstation.agents.b_discovery_agent.tools import enrich_product_card_items

    enriched_data = dict(data)
    enriched_data["items"] = enrich_product_card_items(data["items"])
    enriched_result = dict(tool_result)
    enriched_result["data"] = enriched_data
    return enriched_result


def _is_oe_replacement_followup_query(user_text: str | None) -> bool:
    return bool(_OE_REPLACEMENT_FOLLOWUP_RE.search(user_text or ""))


def _should_reuse_vehicle_slots_for_oe_followup(
    recent_context_text: str | None,
    current_text: str | None,
    tire_size: str | None,
) -> bool:
    text = current_text or ""
    if not tire_size:
        return False
    if not _is_oe_replacement_context(recent_context_text, current_text):
        return False
    if not _is_oe_replacement_followup_query(text):
        return False
    if _NON_SELF_CAR_RE.search(text):
        return False
    if _VEHICLE_BOUND_REQUEST_RE.search(text) or _VEHICLE_LIST_REQUEST_RE.search(text):
        return False
    return True


def _build_oe_replacement_followup_recommendation_args(
    current_text: str,
    recent_context_text: str,
    tire_size: str | None,
) -> dict[str, Any] | None:
    if not _should_reuse_vehicle_slots_for_oe_followup(recent_context_text, current_text, tire_size):
        return None

    tool_input: dict[str, Any] = {
        "rcmd_type": _recommendation_type_for_vehicle_auto_continue(current_text),
        "limit": 3,
        "tire_size": str(tire_size),
        "brand_cd": "HK",
    }
    return tool_input


def _oe_replacement_followup_brand_cd(current_text: str, recent_context_text: str) -> str | None:
    current_frame = build_discovery_intent_frame(current_text)
    current_brand_cd = str(current_frame.entities.get("brand_cd") or "").strip()
    if current_brand_cd:
        return current_brand_cd

    context_frame = build_discovery_intent_frame(recent_context_text)
    context_brand_cd = str(context_frame.entities.get("brand_cd") or "").strip()
    if context_brand_cd:
        return context_brand_cd

    return None


def _build_oe_replacement_same_product_search_args(
    current_text: str,
    recent_context_text: str,
    tire_size: str | None,
) -> dict[str, Any] | None:
    if not _should_reuse_vehicle_slots_for_oe_followup(recent_context_text, current_text, tire_size):
        return None
    if not re.search(r"동일(?:한)?\s*상품|같은\s*상품", current_text, re.IGNORECASE):
        return None
    brand_cd = _oe_replacement_followup_brand_cd(current_text, recent_context_text)
    if not brand_cd:
        return None

    return {
        "size": str(tire_size),
        "brand_cd": brand_cd,
        "limit": 10,
    }


