def _coerce_non_selection_listcar_to_quickreply(event: dict) -> dict | None:
    """Suppress direct listCar JSON when the answer is plain advice.

    The template mapper already suppresses get_my_cars_tool → listCar for
    generic advice turns. This catches the sibling path where the LLM emits a
    valid listCar JSON directly, bypassing the mapper guard.
    """
    if event.get("template") != "listCar":
        return None
    source_domain = str(event.get("source_domain") or "").lower()
    if source_domain != "discovery":
        return None
    event_data = event.get("data")
    if not isinstance(event_data, dict):
        return None
    assistant_text = str(event_data.get("assistantResponse") or "")
    if _looks_like_vehicle_selection_prompt(assistant_text):
        return None
    recovery = _discovery_recovery_chips_for_text(assistant_text, event.get("source_domain"))
    if recovery is None:
        chips = list(_DISCOVERY_DEFAULT_CHIPS)
    else:
        chips, _label = recovery
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": event.get("source_domain"),
        "assistant_response_source": "code_mapper_listcar_advice_guard",
        "data": {
            "assistantResponse": assistant_text,
            "quickReplies": chips,
            "predictedDomains": ["DISCOVERY"],
        },
    }


_ORDER_SUMMARY_LINE_RE = re.compile(r"^\s*([^:\n]+)\s*:\s*(.+?)\s*$", re.MULTILINE)


def _parse_order_summary_lines(text: str) -> dict[str, str]:
    parsed: dict[str, str] = {}
    for match in _ORDER_SUMMARY_LINE_RE.finditer(text):
        key = re.sub(r"^[\s\-•*]+", "", match.group(1)).strip()
        value = match.group(2).strip()
        if key and value:
            parsed[key] = value
    return parsed


def _normalize_order_booking_datetime(raw: str) -> str:
    raw = str(raw or "").strip()
    match = re.search(
        r"(\d{4})\D+(\d{1,2})\D+(\d{1,2})\D+(?:\([^)]*\)\s*)?(\d{1,2})\s*(?::\s*\d{1,2}|시)?",
        raw,
    )
    if not match:
        return raw
    year, month, day, hour = (int(part) for part in match.groups())
    try:
        dt = datetime.datetime(year, month, day)
    except ValueError:
        return raw
    return f"{year}년 {month}월 {day}일 ({_WEEKDAY_KO[dt.weekday()]}) {hour:02d}:00"


def _parse_krw_amount(raw: str) -> int | None:
    digits = re.sub(r"\D", "", str(raw or ""))
    return int(digits) if digits else None


def _coerce_order_summary_quickreply_to_preorder(
    event: dict,
    slot_state: Any | None,
) -> dict | None:
    """Convert text-only order previews back into the FE preOrder card.

    The transaction LLM occasionally summarizes all preOrder fields inside a
    quickReply instead of emitting the `preOrder` template. That makes the FE
    render a plain text block and loses the built-in order/cart buttons. This
    guard only fires when the assistant text already contains a complete order
    summary.
    """
    if event.get("template") != "quickReply":
        return None
    source_domain = str(event.get("source_domain") or "").lower()
    if source_domain != MultiAgentDomain.Domain.TRANSACTION.value:
        return None
    event_data = event.get("data")
    if not isinstance(event_data, dict):
        return None
    assistant_text = str(event_data.get("assistantResponse") or "")
    if "주문 정보" not in assistant_text and "주문을 진행" not in assistant_text:
        return None

    fields = _parse_order_summary_lines(assistant_text)
    product = fields.get("상품")
    qty_raw = fields.get("수량")
    store_name = fields.get("장착 매장") or fields.get("매장")
    booking_raw = fields.get("방문 예정") or fields.get("방문일시") or fields.get("예약 일시")
    amount_raw = fields.get("결제 예상금액") or fields.get("결제금액") or fields.get("결제 금액")
    if not (product and qty_raw and store_name and booking_raw):
        return None

    qty_match = re.search(r"\d+", qty_raw)
    if not qty_match:
        return None
    payment_amount = _parse_krw_amount(amount_raw or "")
    if payment_amount is None and slot_state is not None:
        payment_amount = getattr(slot_state, "payment_amount", None)
    requested_cal_day = _cal_day_from_korean_date_text(booking_raw)
    rsv_hour = _reservation_hour_from_text(booking_raw)
    product_name = re.sub(
        r"\s*\d{3}\s*/?\s*\d{2}\s*R?\s*\d{2}\s*$",
        "",
        product,
        flags=re.IGNORECASE,
    ).strip() or product
    tire_size = normalize_tire_size(product)

    return {
        "type": "data",
        "template": "preOrder",
        "source_domain": event.get("source_domain") or MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_preorder_summary_guard",
        "data": {
            "assistantResponse": "주문 정보를 확인해 주세요.",
            "orderInfo": {
                "carInfo": None,
                "product": product,
                "quantity": int(qty_match.group(0)),
                "storeName": store_name,
                "bookingDateTime": _normalize_order_booking_datetime(booking_raw),
                "paymentAmount": payment_amount,
            },
            "isReadyToOrder": True,
            "isReadyToAddToCart": False,
            "metadata": {
                "goodsNo": getattr(slot_state, "goods_no", None) if slot_state is not None else None,
                "goodsId": getattr(slot_state, "goods_no", None) if slot_state is not None else None,
                "shopId": getattr(slot_state, "shop_id", None) if slot_state is not None else None,
                "shopName": getattr(slot_state, "shop_name", None) if slot_state is not None else store_name,
                "ordQty": int(qty_match.group(0)),
                "requestedCalDay": requested_cal_day,
                "rsvHour": rsv_hour,
                "paymentAmount": payment_amount,
                "productName": product_name,
                "tireSize": tire_size,
                "carNo": None,
                "carLncCd": None,
            },
        },
        "nextAction": {"type": "stop", "domain": None},
    }


def _standardize_preorder_metadata(event_data: dict, slot_state: Any | None) -> None:
    if not isinstance(event_data, dict) or event_data.get("isReadyToOrder") is not True:
        return
    order_info = event_data.get("orderInfo") if isinstance(event_data.get("orderInfo"), dict) else {}
    metadata = event_data.get("metadata") if isinstance(event_data.get("metadata"), dict) else {}
    if not isinstance(metadata, dict):
        metadata = {}
        event_data["metadata"] = metadata

    canonical_event = canonical_context_from_template_boundary(event_data)
    canonical_metadata = canonical_context_from_template_boundary(metadata)
    canonical_slots = canonical_context_from_slots(slot_state)
    product_text = str(order_info.get("product") or metadata.get("productName") or "").strip()
    booking_text = str(order_info.get("bookingDateTime") or metadata.get("bookingDateTime") or "").strip()
    requested_cal_day = (
        str(canonical_metadata.get("requested_cal_day") or canonical_event.get("requested_cal_day") or "").strip()
        or _cal_day_from_korean_date_text(booking_text)
    )
    rsv_hour = (
        str(canonical_metadata.get("rsv_hour") or canonical_event.get("rsv_hour") or "").strip()
        or _reservation_hour_from_text(booking_text)
    )
    quantity = canonical_metadata.get("ord_qty") or canonical_event.get("ord_qty") or order_info.get("quantity")
    payment_amount = (
        metadata.get("paymentAmount")
        or metadata.get("payment_amount")
        or order_info.get("paymentAmount")
        or (getattr(slot_state, "payment_amount", None) if slot_state is not None else None)
    )
    goods_no = canonical_metadata.get("goods_no") or canonical_event.get("goods_no") or canonical_slots.get("goods_no")
    product_name = (
        canonical_metadata.get("product_name")
        or canonical_event.get("product_name")
        or canonical_slots.get("product_name")
        or re.sub(r"\s*\d{3}\s*/?\s*\d{2}\s*R?\s*\d{2}\s*$", "", product_text, flags=re.IGNORECASE).strip()
        or product_text
    )
    tire_size = (
        canonical_metadata.get("tire_size")
        or canonical_event.get("tire_size")
        or normalize_tire_size(product_text)
        or canonical_slots.get("tire_size")
    )
    shop_id = canonical_metadata.get("shop_id") or canonical_event.get("shop_id") or canonical_slots.get("shop_id")
    store_name = (
        canonical_metadata.get("shop_name")
        or canonical_event.get("shop_name")
        or order_info.get("storeName")
        or canonical_slots.get("shop_name")
    )

    metadata["goodsNo"] = goods_no
    metadata.setdefault("goodsId", goods_no)
    metadata["ordQty"] = quantity
    metadata["shopId"] = shop_id
    metadata["requestedCalDay"] = requested_cal_day
    metadata["rsvHour"] = rsv_hour
    metadata["paymentAmount"] = payment_amount
    metadata["productName"] = product_name
    metadata["tireSize"] = tire_size
    metadata["storeName"] = store_name
    metadata.setdefault("shopName", store_name)
    metadata.setdefault("bookingDateTime", booking_text)
    for canonical, legacy in (
        ("carNo", "car_no"),
        ("carLncCd", "car_lnc_cd"),
        ("mbrCarRegSeq", "mbr_car_reg_seq"),
    ):
        value = metadata.get(canonical) or metadata.get(legacy) or (
            getattr(slot_state, legacy, None) if slot_state is not None else None
        )
        if value not in (None, ""):
            metadata[canonical] = value


def _choose_quickreply_fallback(
    called_tool_names: set[str],
    source_domain: str | None,
    assistant_text: str | None = None,
) -> tuple[list[dict], str]:
    """Pick a context-aware fallback chip set when the LLM emits empty quickReplies.

    Returns (chips, label) where label is a short tag for logging/telemetry.

    Routing priority:
      1. Tool-based dispatch (order/coupon) — turn ran a tool that needs a specific CTA.
      2. Domain/context dispatch — store/schedule, order/price, support info, discovery.
      3. LEADING domain → 진행형 chip ([상품 검색, 타이어 추천]). 인사/일반
         문의에서 "1:1 문의" 로 떨어지는 부자연스러운 fallback 을 방지.
      4. Generic discovery/transaction chips — 마지막 안전망. 1:1 문의는 true dead-end 에서만 노출.
    """
    for tool_set, chips, label in _FALLBACK_DISPATCH:
        if called_tool_names & tool_set:
            return chips, label
    domain = (source_domain or "").lower()
    text = assistant_text or ""
    if domain == "transaction":
        if _PURCHASE_STORE_SELECTION_TEXT_RE.search(text):
            return _FALLBACK_TRANSACTION_STORE_SEARCH, "transaction_purchase_store_search"
        if _STORE_SCHEDULE_FALLBACK_RE.search(text):
            return _FALLBACK_TRANSACTION_STORE, "transaction_store_schedule"
        if _ORDER_PRICE_FALLBACK_RE.search(text) or called_tool_names & {
            "get_final_price_tool",
            "get_store_inventory_tool",
            "get_logistics_inventory_tool",
            "quick_order_tool",
            "save_to_cart_tool",
        }:
            return _FALLBACK_TRANSACTION_ORDER, "transaction_order_price"
        return _FALLBACK_TRANSACTION_STORE, "transaction_context"
    if domain == "support":
        if _SUPPORT_DEAD_END_FALLBACK_RE.search(text):
            return _FALLBACK_SUPPORT_ESCALATION, "support_recovery"
        return _FALLBACK_SUPPORT_INFO, "support_info"
    if domain == "discovery":
        if _DISCOVERY_FALLBACK_RE.search(text) or called_tool_names & {
            "search_product_tool",
            "get_products_recommendations_tool",
            "get_product_description_tool",
        }:
            return _FALLBACK_DISCOVERY_PRODUCT, "discovery_product"
        return _FALLBACK_DISCOVERY_PRODUCT, "discovery_context"
    if domain == "leading":
        return _FALLBACK_LEADING_PROGRESS, "leading_progress"
    return _FALLBACK_GENERIC, "generic"


def _unwrap_tool_data(payload: Any) -> dict:
    if not isinstance(payload, dict):
        return {}
    data = payload.get("data")
    if isinstance(data, dict):
        nested = data.get("data")
        return nested if isinstance(nested, dict) else data
    return payload


def _normalize_coupon_match_text(value: object) -> str:
    return re.sub(r"[^0-9a-zA-Z가-힣]+", "", str(value or "")).lower()


def _strip_coupon_match_token_suffix(token: str) -> str:
    for suffix in _COUPON_MATCH_TOKEN_SUFFIXES:
        if token.endswith(suffix) and len(token) - len(suffix) >= 2:
            return token[: -len(suffix)]
    return token


