    {"ventuss2", "벤투스s2"},
    {"ventuss2as", "벤투스s2as"},
    {"ventuss1evozas", "벤투스s1evozas", "벤투스s1에보zas"},
    {"ventuss1evoz", "벤투스s1evoz", "벤투스s1에보z"},
    {"sfitas", "에스핏as"},
    {"sfit", "에스핏"},
    {"ionevoassuv", "아이온에보assuv"},
    {"ionevoas", "아이온에보as"},
    {"ionevo", "아이온에보"},
    {"mileageplus3", "마일리지플러스3"},
