_STORE_ATTRIBUTE_SVC_CODE_LABELS: dict[str, str] = {
    "113": "타이어 온라인 주문",
    "116": "배터리",
    "119": "타이어 보관",
    "120": "수입타이어",
    "121": "경정비",
    "122": "경정비 당일",
    "124": "얼라인먼트",
    "125": "얼라인먼트",
    "126": "무상점검",
}
_STORE_ATTRIBUTE_SVC_PATTERNS: tuple[tuple[re.Pattern[str], tuple[str, ...], str], ...] = (
    (re.compile(r"보관|타이어\s*호텔|윈터\s*타이어|겨울\s*타이어", re.IGNORECASE), ("119",), "타이어 보관"),
    (re.compile(r"얼라인먼트|휠\s*얼라이먼트|휠\s*얼라인먼트", re.IGNORECASE), ("124", "125"), "얼라인먼트"),
    (re.compile(r"경정비|엔진\s*오일|엔진오일|실내\s*필터|필터|와이퍼", re.IGNORECASE), ("121", "122"), "경정비"),
    (re.compile(r"배터리", re.IGNORECASE), ("116",), "배터리"),
    (re.compile(r"무상\s*점검|무료\s*점검|all\s*my\s*t|올마이티", re.IGNORECASE), ("126",), "무상점검"),
    (re.compile(r"수입\s*타이어", re.IGNORECASE), ("120",), "수입타이어"),
)


def _store_attribute_row_from_entries(store_info_entries: list[dict] | None) -> dict:
    for entry in reversed(store_info_entries or []):
        raw = _unwrap_tool_data(entry.get("data"))
        if not isinstance(raw, dict):
            continue
        if entry.get("tool") == "get_store_detail_tool":
            return raw
        stores = raw.get("stores")
        if isinstance(stores, list) and stores and isinstance(stores[0], dict):
            return stores[0]
    return {}


def _store_attribute_svc_codes(row: Mapping[str, Any]) -> set[str]:
    raw_codes = row.get("svc_codes") or row.get("svcCodes") or row.get("serviceCodes")
    if isinstance(raw_codes, list):
        return {str(code).strip() for code in raw_codes if str(code).strip()}
    if isinstance(raw_codes, str):
        return {code.strip() for code in re.split(r"[,|/\s]+", raw_codes) if code.strip()}
    return set()


def _store_attribute_svc_labels(codes: set[str]) -> list[str]:
    labels: list[str] = []
    seen: set[str] = set()
    for code in sorted(codes):
        label = _STORE_ATTRIBUTE_SVC_CODE_LABELS.get(code)
        if label and label not in seen:
            labels.append(label)
            seen.add(label)
    return labels


def _store_attribute_operating_hours_text(row: Mapping[str, Any]) -> str:
    weekday_start = _normalize_store_time(str(row.get("shop_biz_strt_time") or "").strip())
    weekday_end = _normalize_store_time(str(row.get("shop_biz_end_time") or "").strip())
    sat_start = _normalize_store_time(str(row.get("shop_sat_strt_time") or "").strip())
    sat_end = _normalize_store_time(str(row.get("shop_sat_end_time") or "").strip())
    parts: list[str] = []
    if weekday_start and weekday_end:
        parts.append(f"평일 {weekday_start}~{weekday_end}")
    if sat_start and sat_end:
        parts.append(f"토요일 {sat_start}~{sat_end}")
    return ", ".join(parts)


def _store_attribute_assessment_text(
    *,
    store_label: str,
    attribute_text: str,
    attribute_type: str,
    verification_level: str,
    store_info_entries: list[dict] | None,
) -> tuple[str, str]:
    row = _store_attribute_row_from_entries(store_info_entries)
    if not row:
        return (
            f"{store_label}의 {attribute_text} 가능 여부는 매장 운영 조건과 당일 작업 상황에 따라 달라질 수 있어요. "
            "현재 조회된 매장 정보가 없어 가능 여부를 확정해서 단정하기 어렵습니다.",
            "not_checked",
        )

    attr = str(attribute_text or "").strip()
    attr_type = str(attribute_type or "")
    level = str(verification_level or "")
    codes = _store_attribute_svc_codes(row)
    for pattern, expected_codes, label in _STORE_ATTRIBUTE_SVC_PATTERNS:
        if not pattern.search(attr):
            continue
        matched = bool(codes.intersection(expected_codes))
        if matched:
            return (
                f"{store_label}의 {label} 항목은 조회된 매장 서비스 정보에서 확인돼요. "
                "다만 실제 접수 가능 여부와 시간은 당일 작업 상황에 따라 달라질 수 있어요.",
                "matched",
            )
        labels = _store_attribute_svc_labels(codes)
        visible = f" 현재 조회된 서비스 항목은 {', '.join(labels)}입니다." if labels else ""
        return (
            f"{store_label}의 {label} 항목은 조회된 매장 서비스 정보에서 확인되지 않아요.{visible} "
            "미노출 서비스나 현장 운영 조건은 다를 수 있으니 방문 전 매장에 직접 확인해 주세요.",
            "not_matched",
        )

    if re.search(r"야간|퇴근\s*후|저녁|늦게", attr, re.IGNORECASE):
        hours = _store_attribute_operating_hours_text(row)
        hours_sentence = f" 조회된 영업시간은 {hours}입니다." if hours else ""
        return (
            f"{store_label}의 {attr}는 조회된 매장 정보에 별도 서비스 항목으로 확인되지 않아요.{hours_sentence} "
            "영업시간 내 접수 가능 여부도 당일 작업 상황에 따라 달라질 수 있으니 방문 전 매장에 직접 확인해 주세요.",
            "contact_required",
        )

    if level == "tool_verifiable" or re.search(r"주소|전화|전화번호|연락처|영업\s*시간|운영\s*시간|휴무|위치", attr, re.IGNORECASE):
        return (
            f"{store_label}의 {attr}는 아래 조회된 매장 기본정보에서 확인해 주세요.",
            "tool_verifiable",
        )

    if attr_type == "subjective_quality":
        return (
            f"{store_label}의 {attr}는 조회된 매장 기본정보만으로 판단하기 어려운 항목이에요. "
            "방문 전 매장에 직접 문의하거나 상세 페이지의 리뷰/평점을 함께 확인해 주세요.",
            "unsupported_or_policy",
        )

    return (
        f"{store_label}의 {attr} 여부는 조회된 매장 기본정보에 별도 항목으로 확인되지 않아요. "
        "방문 전 매장에 직접 확인해 주세요.",
        "contact_required",
    )


def _store_attribute_inquiry_event(
    user_text: str,
    *,
    store_name: str | None = None,
    attribute_text: str | None = None,
    attribute_type: str | None = None,
    verification_level: str | None = None,
    store_info_entries: list[dict] | None = None,
) -> dict | None:
    inquiry = extract_store_attribute_inquiry(user_text or "", store_name=store_name)
    labels = unverifiable_store_preference_labels(user_text or "")
    explicit_attribute_text = str(attribute_text or "").strip()
    if inquiry is None and not labels and not explicit_attribute_text:
        return None
    service_label = (
        explicit_attribute_text
        or (inquiry.attribute_text if inquiry is not None else "")
        or (labels[0] if labels else "")
    ).strip()
    store_label = str(store_name or (inquiry.store_name if inquiry is not None else "")).strip()
    attribute_type = str(attribute_type or (inquiry.attribute_type if inquiry is not None else "service") or "unknown")
    verification_level = str(
        verification_level
        or (inquiry.verification_level if inquiry is not None else "store_contact_required")
        or "store_contact_required"
    )
    store_info_summary = _build_store_detail_summary_from_context(store_info_entries or [])
    if store_label:
        assessment_text, assessment_status = _store_attribute_assessment_text(
            store_label=store_label,
            attribute_text=service_label,
            attribute_type=attribute_type,
            verification_level=verification_level,
            store_info_entries=store_info_entries,
        )
        store_info_block = f"\n\n확인된 매장 정보\n{store_info_summary}" if store_info_summary else ""
        contact_sentence = "" if "방문 전" in assessment_text else "\n\n방문 전 해당 매장에 직접 확인해 주세요."
        assistant_response = (
            f"{assessment_text}{contact_sentence}{store_info_block}"
        )
        quick_replies = [
            {"label": "매장 전화번호 확인", "domain": "TRANSACTION"},
            {"label": "매장 상세보기", "domain": "TRANSACTION"},
            {"label": "매장 예약", "domain": "TRANSACTION"},
        ]
        for entry in store_info_entries or []:
            raw = _unwrap_tool_data(entry.get("data"))
            if not isinstance(raw, dict):
                continue
            store_seq = str(raw.get("shop_seq") or raw.get("shop_id") or "").strip()
            if store_seq:
                quick_replies[1] = {
                    "label": "매장 상세보기",
                    "url": CTAUrls.STORE_DETAIL.replace("<shop_seq>", store_seq),
                    "domain": "TRANSACTION",
                }
                break
    else:
        assessment_status = "missing_store"
        assistant_response = (
            f"{service_label}는 매장별 운영 조건과 현장 상황에 따라 달라질 수 있어요. "
            "어느 매장 기준인지 알려주시면 해당 매장 기준으로 확인 방법을 안내해드릴게요.\n\n"
            "확인할 매장명을 알려주시면 매장 기본정보와 함께 안내해드릴게요."
        )
        quick_replies = [
            {"label": "매장명 입력", "domain": "SUPPORT"},
            {"label": "매장 찾기", "domain": "TRANSACTION"},
            {"label": "1:1 문의하기", "domain": "SUPPORT"},
        ]
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value if store_info_summary else MultiAgentDomain.Domain.SUPPORT.value,
        "assistant_response_source": (
            "code_store_attribute_inquiry_with_store_info"
            if store_info_summary
            else "code_store_attribute_inquiry_guard"
        ),
        "data": {
            "assistantResponse": assistant_response,
            "quickReplies": quick_replies,
            "predictedDomains": ["TRANSACTION", "SUPPORT"],
            "metadata": {
                "responseShapeKey": "store_attribute_inquiry",
                "store_attribute_inquiry_intent": True,
                "store_service_availability_intent": True,
                "storeServiceLabel": service_label,
                "attributeText": service_label,
                "attributeType": attribute_type,
                "verificationLevel": verification_level,
                "attributeAssessmentStatus": assessment_status,
                "carried_store_context": store_label,
                "store_info_lookup": bool(store_info_summary),
                "store_search_suppressed": not bool(store_label),
                "override_blocked_reason": "store_attribute_inquiry_contact_required",
                "userText": user_text,
            },
        },
    }


def _store_service_availability_event(user_text: str, *, store_name: str | None = None) -> dict | None:
    return _store_attribute_inquiry_event(user_text, store_name=store_name)


_MAINTENANCE_ADDON_CODES = frozenset({"121", "122"})


def _maintenance_addon_store_context_from_location_template(user_text: str, template_data: dict | None) -> dict | None:
    selection = TStationChatServiceV2._resolve_store_selection_from_history_template(user_text, template_data)
    if not isinstance(selection, dict):
        if not isinstance(template_data, dict):
            return None
        target_template: dict | None = None
        if template_data.get("template") == "location" and isinstance(template_data.get("data"), dict):
            target_template = template_data.get("data")
        elif isinstance(template_data.get("stores"), list):
            target_template = template_data
        if not isinstance(target_template, dict):
            return None
        stores = target_template.get("stores") or []
        metadata = target_template.get("metadata") or []
        if not isinstance(stores, list) or not isinstance(metadata, list) or len(stores) != len(metadata):
            return None
        store_match = re.search(r"([가-힣A-Za-z0-9]+(?:점|매장))", user_text or "")
        store_anchor = store_match.group(1) if store_match else ""
        if not store_anchor:
            return None
        matched: list[dict[str, Any]] = []
        for store, meta in zip(stores, metadata):
            if not isinstance(store, dict) or not isinstance(meta, dict):
                continue
            name = str(store.get("nameAddress") or store.get("name") or store.get("title") or "")
            meta_name = str(meta.get("shopName") or meta.get("shop_name") or meta.get("shop_nm") or "")
            if store_anchor in name or store_anchor in meta_name:
                matched.append({"store": store, "meta": meta})
        if len(matched) != 1:
            return None
        selection = matched[0]
    store = selection.get("store") if isinstance(selection.get("store"), dict) else {}
    meta = selection.get("meta") if isinstance(selection.get("meta"), dict) else {}
    if not store and not meta:
        return None
    return {"store": store, "meta": meta}


def _maintenance_addon_svc_codes(store_context: dict | None) -> set[str]:
    if not isinstance(store_context, dict):
        return set()
    codes: set[str] = set()
    for source_key in ("store", "meta"):
        source = store_context.get(source_key)
        if not isinstance(source, dict):
            continue
        raw_codes = source.get("svc_codes") or source.get("svcCodes") or source.get("serviceCodes")
        if isinstance(raw_codes, list):
            codes.update(str(code).strip() for code in raw_codes if str(code).strip())
        elif isinstance(raw_codes, str):
            codes.update(code.strip() for code in re.split(r"[,|/\s]+", raw_codes) if code.strip())
    return codes


def _maintenance_addon_store_name(store_context: dict | None, fallback: str | None = None) -> str:
    if isinstance(store_context, dict):
        for source_key in ("store", "meta"):
            source = store_context.get(source_key)
            if not isinstance(source, dict):
                continue
            for key in ("shopName", "shop_name", "shop_nm", "nameAddress", "name", "title"):
                value = str(source.get(key) or "").strip()
                if value:
                    return value
    return str(fallback or "").strip()


def _maintenance_addon_store_is_allmyt(store_context: dict | None) -> bool:
    if not isinstance(store_context, dict):
        return False
    for source_key in ("store", "meta"):
        source = store_context.get(source_key)
        if not isinstance(source, dict):
            continue
        for key in ("isAllMyT", "is_all_my_t", "allMyT", "all_my_t"):
            value = source.get(key)
            if isinstance(value, bool):
                return value
            if str(value).strip().lower() in {"true", "y", "1"}:
                return True
    return False


def _maintenance_addon_store_description(store_context: dict | None) -> str:
    parts: list[str] = []
    if isinstance(store_context, dict):
        for source_key in ("store", "meta"):
            source = store_context.get(source_key)
            if not isinstance(source, dict):
                continue
            for key in ("description", "services", "serviceDescription", "svcLabels"):
                value = source.get(key)
                if isinstance(value, list):
                    parts.extend(str(item) for item in value if str(item).strip())
                elif value:
                    parts.append(str(value))
    return " | ".join(parts)


def _maintenance_addon_supported_by_context(store_context: dict | None) -> bool:
    codes = _maintenance_addon_svc_codes(store_context)
    if codes & _MAINTENANCE_ADDON_CODES:
        return True
    if _maintenance_addon_store_is_allmyt(store_context):
        return True
    description = _maintenance_addon_store_description(store_context)
    return bool(re.search(r"경정비|엔진\s*오일|실내\s*필터|와이퍼|배터리", description, re.IGNORECASE))


def _maintenance_addon_with_tire_service_event(
    user_text: str,
    *,
    store_context: dict | None = None,
    store_name: str | None = None,
) -> dict:
    store_label = _maintenance_addon_store_name(store_context, store_name)
    store_phrase = f"{store_label}은 " if store_label else "해당 매장은 "
    supported = _maintenance_addon_supported_by_context(store_context)
    if supported:
        assistant_response = (
            f"{store_phrase}경정비 가능 매장으로 확인돼요. 온라인으로 타이어를 주문할 때 "
            "엔진오일/실내필터 같은 경정비 상품을 함께 담아 주문할 수 있는지 확인하고, "
            "세부 작업 가능 여부는 주문 전후 매장에 한 번 더 확인해 주세요."
        )
    else:
        assistant_response = (
            f"{store_phrase}현재 확인된 매장 정보만으로는 엔진오일·실내필터 같은 경정비 동시 주문 가능 여부가 "
            "확인되지 않아요. 타이어 장착은 온라인 주문/예약으로 진행하고, 엔진오일·실내필터는 "
            "방문예약 또는 매장 방문 전 전화로 요청 가능 여부를 확인해 주세요."
        )
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_maintenance_addon_with_tire_service",
        "data": {
            "assistantResponse": assistant_response,
            "quickReplies": [
                {"label": "타이어 주문하기", "domain": "TRANSACTION"},
                {"label": "매장 정보 확인", "domain": "TRANSACTION"},
                {"label": "정비 문의하기", "domain": "SUPPORT"},
            ],
            "predictedDomains": ["TRANSACTION", "SUPPORT"],
            "metadata": {
                "responseShapeKey": "maintenance_addon_with_tire_service",
                "storeName": store_label,
                "maintenanceAddonAvailable": supported,
                "svcCodes": sorted(_maintenance_addon_svc_codes(store_context)),
                "userText": user_text,
            },
        },
    }


_PAST_EVENT_QUERY_RE = re.compile(
    r"(?=.*(?:지난|종료(?:된|한)?|끝난|과거|예전|이전|마감(?:된)?))(?=.*(?:이벤트|행사))",
    re.IGNORECASE,
)
_PAST_EVENT_RESTORE_RE = re.compile(r"원복|복구|재사용|다시\s*쓰|혜택", re.IGNORECASE)


def _past_event_page_event(user_text: str) -> dict | None:
    """Route past/ended event list inquiries to the official past-event page."""
    if not user_text or not _PAST_EVENT_QUERY_RE.search(user_text):
        return None
    if _PAST_EVENT_RESTORE_RE.search(user_text):
        return None
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_past_event_page",
        "data": {
            "assistantResponse": (
                "지난 이벤트와 종료된 이벤트는 티스테이션 이벤트의 '지난 이벤트' 페이지에서 확인하실 수 있어요."
            ),
            "quickReplies": [
                {
                    "label": "지난 이벤트 보기",
                    "url": CTAUrls.PROMOTION_PAST_EVENT_LIST,
                    "domain": "DISCOVERY",
                },
                {
                    "label": "진행 중인 이벤트",
                    "url": CTAUrls.PROMOTION_EVENT_LIST,
                    "domain": "DISCOVERY",
                },
            ],
            "predictedDomains": ["DISCOVERY"],
        },
    }


def _date_label(value: object) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    return re.split(r"[T\s]", text, maxsplit=1)[0]


def _field(row: dict, *keys: str) -> str:
    for key in keys:
        value = row.get(key)
        if value is not None and str(value).strip():
            return str(value).strip()
    return ""


def _tool_items(tool_result: dict, *list_keys: str) -> list[dict]:
    data = _unwrap_tool_data(tool_result)
    for key in (*list_keys, "items"):
        rows = data.get(key) if isinstance(data, dict) else None
        if isinstance(rows, list):
            return [row for row in rows if isinstance(row, dict)]
    return []


def _benefit_line(row: dict, *, kind: str) -> str:
    if kind == "event":
        name = _field(row, "evt_nm", "eventName", "event_name", "title")
        start = _date_label(_field(row, "evt_strt_dtime", "evt_strt_date", "startDate", "start_date"))
        end = _date_label(_field(row, "evt_end_dtime", "evt_end_date", "endDate", "end_date"))
        link = _field(row, "evt_url_addr", "dtl_conts_url_addr", "eventUrl", "url", "actionLink")
    else:
        name = _field(row, "deal_nm", "dealName", "deal_name", "title")
        start = _date_label(_field(row, "deal_strt_dtime", "deal_strt_date", "startDate", "start_date"))
        end = _date_label(_field(row, "deal_end_dtime", "deal_end_date", "endDate", "end_date"))
        link = _field(row, "deal_url_addr", "dtl_conts_url_addr", "dealUrl", "url", "actionLink")

    if not name:
        return ""
    period = f"{start} ~ {end}" if start and end else start or end
    pieces = [name]
    if period:
        pieces.append(period)
    if link:
        pieces.append(link)
    return f"- {' · '.join(pieces)}"


def _build_default_benefit_event(events_result: dict, deals_result: dict) -> dict:
    event_rows = _tool_items(events_result, "events")[:5]
    deal_rows = _tool_items(deals_result, "deals")[:5]
    event_lines = [line for row in event_rows if (line := _benefit_line(row, kind="event"))]
    deal_lines = [line for row in deal_rows if (line := _benefit_line(row, kind="deal"))]

    if not event_lines and not deal_lines:
        assistant_response = "현재 진행 중인 이벤트나 기획전이 없어요. 잠시 후에 다시 확인해 주세요 😊"
    else:
        lines = ["현재 진행 중인 이벤트와 기획전을 안내드릴게요."]
        if event_lines:
            lines.extend(["", "이벤트", *event_lines])
        if deal_lines:
            lines.extend(["", "기획전", *deal_lines])
        lines.extend(["", "자세한 조건은 변경될 수 있어요. 상세 페이지에서 꼭 확인해 주세요 😊"])
        assistant_response = "\n".join(lines)

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_default_benefit_event_deal",
        "data": {
            "assistantResponse": assistant_response,
            "quickReplies": [
                {
                    "label": "진행 중인 이벤트 보기",
                    "url": CTAUrls.PROMOTION_EVENT_LIST,
                    "domain": "DISCOVERY",
                },
                {"label": "처음으로", "domain": "LEADING"},
            ],
            "predictedDomains": ["DISCOVERY"],
            "metadata": {
                "eventCount": len(event_rows),
                "dealCount": len(deal_rows),
            },
        },
    }


def _price_policy_guard_event(user_text: str) -> dict | None:
    """Return a deterministic price/coupon policy guard event, if one applies."""
    if not user_text:
        return None
    frame = build_price_intent_frame(user_text)
    if frame.intent not in _PRICE_POLICY_GUARD_INTENTS:
        return None

    decision = decide_price_response(frame)
    plan = plan_price_tools(frame)
    logger.info(
        "[POLICY][price] runtime guard intent=%s decision=%s forbidden_tools=%s",
        frame.intent,
        decision.metadata.get("response_shape_key"),
        plan.forbidden_tools,
    )

    if frame.intent == "coupon_issue_request":
        return {
            **_coupon_issue_event(),
            "assistant_response_source": "code_price_policy_guard",
        }

    if frame.intent == "expired_coupon_or_event":
        return {
            "type": "data",
            "template": "quickReply",
            "source_domain": MultiAgentDomain.Domain.SUPPORT.value,
            "assistant_response_source": "code_price_policy_guard",
            "data": {
                "assistantResponse": (
                    "만료된 쿠폰이나 종료된 이벤트 혜택은 원칙적으로 원복 또는 재사용이 어렵습니다. "
                    "자세한 확인이 필요하시면 1:1 문의로 접수해 주세요."
                ),
                "quickReplies": [
                    {"label": "1:1 문의하기", "domain": "SUPPORT"},
                    {"label": "내 쿠폰함", "url": CTAUrls.MY_COUPON_LIST_PC, "domain": "TRANSACTION"},
                ],
                "predictedDomains": ["SUPPORT", "TRANSACTION"],
            },
        }

    if frame.intent == "nonexistent_benefit":
        return {
            "type": "data",
            "template": "quickReply",
            "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
            "assistant_response_source": "code_price_policy_guard",
            "data": {
                "assistantResponse": (
                    "확인되지 않은 VIP/블랙카드/50% 전용 혜택이나 할인 링크는 제공할 수 없어요. "
                    "공식 쿠폰함과 진행 중인 이벤트에서 확인되는 혜택만 안내드릴 수 있습니다."
                ),
                "quickReplies": [
                    {"label": "내 쿠폰함", "url": CTAUrls.MY_COUPON_LIST_PC, "domain": "TRANSACTION"},
                    {"label": "진행 중인 이벤트", "url": CTAUrls.PROMOTION_EVENT_LIST, "domain": "DISCOVERY"},
                    {"label": "1:1 문의하기", "domain": "SUPPORT"},
                ],
                "predictedDomains": ["TRANSACTION", "DISCOVERY", "SUPPORT"],
            },
        }

    return None


def _build_coupon_applicability_event(
    tool_result: dict,
    coupon_row: dict,
    *,
    target_product_name: str | None = None,
    target_brand: dict | None = None,
) -> dict:
    data = _unwrap_tool_data(tool_result)
    coupon_name = str(coupon_row.get("cpn_nm") or "해당 쿠폰")
    products: list[dict] = []
    stores: list[dict] = []

    for group in data.get("coupons") or []:
        if isinstance(group, dict) and isinstance(group.get("items"), list):
            products.extend(item for item in group["items"] if isinstance(item, dict))
    for group in data.get("stores") or []:
        if isinstance(group, dict) and isinstance(group.get("items"), list):
            stores.extend(item for item in group["items"] if isinstance(item, dict))

    total_products = int(data.get("total_products") or len(products))
    total_stores = int(data.get("total_stores") or len(stores))

    lines: list[str] = []
    if target_brand:
        target_brand_cd = str(target_brand.get("brand_cd") or "").strip().upper()
        target_brand_label = str(target_brand.get("label") or _brand_label_for_code(target_brand_cd)).strip()
        matched_products: list[str] = []
        for item in products:
            row_brand_cd = str(item.get("brand_cd") or item.get("brandCode") or "").strip().upper()
            row_brand_nm = str(item.get("brand_nm") or item.get("brand_name") or item.get("brandName") or "").strip()
            row_goods_nm = str(canonical_context_from_tool_boundary(item).get("product_name") or "").strip()
            if not row_goods_nm:
                continue
            if (
                (target_brand_cd and row_brand_cd == target_brand_cd)
                or (target_brand_label and target_brand_label.casefold() in row_brand_nm.casefold())
                or (target_brand_label and target_brand_label.casefold() in row_goods_nm.casefold())
            ):
                matched_products.append(row_goods_nm)
        if matched_products:
            lines.append(f"‘{coupon_name}’은 {target_brand_label} 상품에도 적용 가능해요.")
            lines.append("확인된 대표 상품은 " + ", ".join(matched_products[:5]) + "입니다.")
        else:
            lines.append(f"적용 가능 상품 목록에서 {target_brand_label} 상품은 확인되지 않았어요.")
            lines.append("쿠폰함에서 상세 적용 조건을 확인해 주세요.")
        quick_replies = [
            {"label": "쿠폰함 바로가기", "url": CTAUrls.MY_COUPON_LIST_PC, "domain": "TRANSACTION"},
            {"label": "내 쿠폰 조회", "domain": "TRANSACTION"},
            {"label": "적용 상품 다시 확인", "domain": "TRANSACTION"},
        ]
        return {
            "type": "data",
            "template": "quickReply",
            "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
            "assistant_response_source": "code_coupon_resolver",
            "data": {
                "assistantResponse": "\n".join(lines),
                "quickReplies": quick_replies,
                "predictedDomains": ["TRANSACTION"],
            },
        }

    target_keys = _coupon_product_match_keys(target_product_name)
    if target_keys:
        product_names = [
            str(canonical_context_from_tool_boundary(item).get("product_name") or "").strip()
            for item in products
            if str(canonical_context_from_tool_boundary(item).get("product_name") or "").strip()
        ]
        matched_product_names = [
            name for name in product_names
            if bool(target_keys & _coupon_product_match_keys(name))
        ]
        target_display_name = matched_product_names[0] if matched_product_names else str(target_product_name or "해당 상품")
        if matched_product_names:
            lines.append(
                f"보유 쿠폰에서 ‘{coupon_name}’을 확인했고, 이 쿠폰은 {target_display_name} 패턴에 적용 가능해요."
            )
            lines.append(
                f"{target_display_name}를 주문하시겠어요? 주문하시려면 타이어 사이즈를 입력하거나 "
                "보유차량 중에서 선택해 맞는 모델을 찾을게요."
            )
        elif products:
            lines.append(
                f"보유 쿠폰에서 ‘{coupon_name}’을 확인했지만, 적용 가능 상품 목록에서 {target_display_name} 패턴은 확인되지 않았어요."
            )
            lines.append("쿠폰함의 적용 조건을 다시 확인해 주세요.")
    elif products:
        lines.append(f"‘{coupon_name}’ 적용 가능 상품은 {total_products}개예요.")
        for item in products[:5]:
            goods_nm = str(canonical_context_from_tool_boundary(item).get("product_name") or "").strip()
            if goods_nm:
                lines.append(f"- {goods_nm}")
        if total_products > 5:
            lines.append(f"외 {total_products - 5}개 상품이 더 있어요.")
    if stores:
        store_names = [
            str(item.get("shop_nm") or "").strip()
            for item in stores[:5]
            if str(item.get("shop_nm") or "").strip()
        ]
        if store_names:
            lines.append(f"사용 가능 매장은 {', '.join(store_names)}예요.")
            if total_stores > 5:
                lines.append(f"외 {total_stores - 5}개 매장이 더 있어요.")

    quick_replies = [
        {"label": "보유차량 중 선택", "domain": "DISCOVERY"},
        {"label": "사이즈 직접 입력", "domain": "DISCOVERY"},
        {"label": "내 쿠폰 조회", "domain": "TRANSACTION"},
    ]
    predicted_domains = ["DISCOVERY", "TRANSACTION"]
    if not lines:
        lines.append("해당 쿠폰의 적용 정보를 찾을 수 없어요. 쿠폰함에서 적용 대상을 확인해 주세요.")
        quick_replies = [dict(chip) for chip in _COUPON_BOX_CHIPS]
        predicted_domains = ["TRANSACTION"]

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_coupon_resolver",
        "data": {
            "assistantResponse": "\n".join(lines),
            "quickReplies": quick_replies,
            "predictedDomains": predicted_domains,
        },
    }


def _build_product_coupon_eligibility_event(
    tool_result: dict,
    coupon_rows: list[dict],
    *,
    target_product_name: str,
    target_brand: dict | None = None,
) -> dict:
    data = _unwrap_tool_data(tool_result)
    target_display_name = str(target_product_name or "해당 상품").strip() or "해당 상품"
    if target_brand:
        target_brand_cd = str(target_brand.get("brand_cd") or "").strip().upper()
        target_brand_label = str(target_brand.get("label") or _brand_label_for_code(target_brand_cd)).strip()
        target_display_name = target_brand_label or target_display_name
        target_keys = set()
    else:
        target_keys = _coupon_product_match_keys(target_display_name)
    coupon_name_by_no = {
        str(row.get("cpn_no") or "").strip(): str(row.get("cpn_nm") or row.get("disp_nm") or "해당 쿠폰").strip()
        for row in coupon_rows
        if str(row.get("cpn_no") or "").strip()
    }
    applicable_coupon_names: list[str] = []
    matched_product_name = ""

    for group in data.get("coupons") or []:
        if not isinstance(group, dict):
            continue
        cpn_no = str(group.get("cpn_no") or "").strip()
        coupon_name = coupon_name_by_no.get(cpn_no) or cpn_no or "해당 쿠폰"
        items = group.get("items")
        if not isinstance(items, list):
            continue
        for item in items:
            if not isinstance(item, dict):
                continue
            goods_nm = str(canonical_context_from_tool_boundary(item).get("product_name") or "").strip()
            if not goods_nm:
                continue
            if target_brand:
                row_brand_cd = str(item.get("brand_cd") or item.get("brandCode") or "").strip().upper()
                row_brand_nm = str(item.get("brand_nm") or item.get("brand_name") or item.get("brandName") or "").strip()
                matched_target = (
                    (target_brand_cd and row_brand_cd == target_brand_cd)
                    or (target_brand_label and target_brand_label.casefold() in row_brand_nm.casefold())
                    or (target_brand_label and target_brand_label.casefold() in goods_nm.casefold())
                )
            else:
                matched_target = bool(
                    target_keys and (
                        target_keys & _coupon_product_match_keys(goods_nm)
                        or any(
                            target and row_term and (target in row_term or row_term in target)
                            for target in target_keys
                            for row_term in _coupon_product_match_keys(goods_nm)
                        )
                    )
                )
            if matched_target:
                if coupon_name not in applicable_coupon_names:
                    applicable_coupon_names.append(coupon_name)
                matched_product_name = matched_product_name or goods_nm
                break

    if applicable_coupon_names:
        if target_brand:
            lines = [
                f"보유 쿠폰 기준으로 {target_display_name} 상품에도 적용 가능한 쿠폰을 확인했어요.",
                *[f"- {name}" for name in applicable_coupon_names[:5]],
            ]
        else:
            product_label = matched_product_name or target_display_name
            lines = [
                f"보유 쿠폰 기준으로 {product_label} 패턴에 적용 가능한 쿠폰을 확인했어요.",
                *[f"- {name}" for name in applicable_coupon_names[:5]],
            ]
        if len(applicable_coupon_names) > 5:
            lines.append(f"외 {len(applicable_coupon_names) - 5}개 쿠폰이 더 있어요.")
        if not target_brand:
            lines.append("정확한 최종 혜택가는 차량이나 타이어 사이즈를 선택한 뒤 확인할 수 있어요.")
    else:
        if target_brand:
            lines = [
                f"보유 쿠폰 기준 적용 가능 상품 목록에서 {target_display_name} 상품은 확인되지 않았어요.",
                "쿠폰함에서 상세 적용 조건을 확인해 주세요.",
            ]
        else:
            lines = [
                f"보유 쿠폰 중 {target_display_name} 패턴에 바로 적용 가능한 쿠폰은 확인되지 않았어요.",
                "쿠폰함의 적용 조건이나 진행 중인 이벤트를 다시 확인해 주세요.",
            ]
    quick_replies = (
        [
            {"label": "쿠폰함 바로가기", "url": CTAUrls.MY_COUPON_LIST_PC, "domain": "TRANSACTION"},
            {"label": "내 쿠폰 조회", "domain": "TRANSACTION"},
            {"label": "적용 상품 다시 확인", "domain": "TRANSACTION"},
        ]
        if target_brand
        else [
            {"label": "보유차량 중 선택", "domain": "DISCOVERY"},
            {"label": "사이즈 직접 입력", "domain": "DISCOVERY"},
            {"label": "내 쿠폰 조회", "domain": "TRANSACTION"},
        ]
    )
    predicted_domains = ["TRANSACTION"] if target_brand else ["DISCOVERY", "TRANSACTION"]

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_product_coupon_resolver",
        "data": {
            "assistantResponse": "\n".join(lines),
            "quickReplies": quick_replies,
            "predictedDomains": predicted_domains,
        },
    }


_COUPON_PRICE_AMOUNT_QUERY_RE = re.compile(
    r"할인\s*받|할인\s*금액|할인액|얼마\s*(?:할인|빠지|깎)|최종\s*(?:혜택가|금액|가격)|"
    r"쿠폰\s*적용\s*(?:하면|시).*얼마|얼마야|얼마\s*나와",
    re.IGNORECASE,
)
_COUPON_WORD_RE = re.compile(r"쿠폰|할인권|혜택", re.IGNORECASE)


def _is_product_coupon_price_amount_query(user_text: str | None) -> bool:
    text = str(user_text or "")
    return bool(_COUPON_WORD_RE.search(text) and _COUPON_PRICE_AMOUNT_QUERY_RE.search(text))


_COUPON_DISCOUNT_AMOUNT_GOAL_TYPES = frozenset({
    "coupon_discount_amount",
    "product_coupon_discount_amount",
})


def _is_coupon_discount_amount_context(slots: Any | None) -> bool:
    if slots is None:
        return False
    if isinstance(slots, Mapping):
        pending_intent = str(slots.get("pending_intent") or "").strip()
        goal_type = str(slots.get("goal_type") or "").strip()
    else:
        pending_intent = str(getattr(slots, "pending_intent", None) or "").strip()
        goal_type = str(getattr(slots, "goal_type", None) or "").strip()
    return pending_intent == "price" and goal_type in _COUPON_DISCOUNT_AMOUNT_GOAL_TYPES


def _is_coupon_discount_amount_size_list_followup(user_text: str | None, slots: Any | None) -> bool:
    return _is_coupon_discount_amount_context(slots) and _is_product_size_list_intent(str(user_text or ""))


def _price_row_from_final_price_result(price_result: dict) -> dict | None:
    data = _unwrap_tool_data(price_result)
    if not isinstance(data, dict) or not data:
        return None
    rows = data.get("items")
    if isinstance(rows, list) and rows and isinstance(rows[0], dict):
        return rows[0]
    if any(key in data for key in ("sale_prc", "cheapest_final_prc", "extra_fvr_sale_prc")):
        return data
    return None


def _build_product_coupon_price_amount_event(
    price_result: dict,
    *,
    product_name: str,
    tire_size: str,
    quantity: int,
) -> dict | None:
    row = _price_row_from_final_price_result(price_result)
    if row is None:
        return None

    sale_unit = _to_int(row.get("sale_prc"))
    final_unit = _final_price_from_row(row)
    unit_discount = _to_int(row.get("cheapest_total_discount"))
    if sale_unit is not None and final_unit is not None:
        unit_discount = max(0, sale_unit - final_unit)
    if sale_unit is None or final_unit is None:
        return None

    quantity = max(1, int(quantity or 1))
    base_total = sale_unit * quantity
    final_total = final_unit * quantity
    discount_total = (unit_discount or 0) * quantity

    coupons = row.get("cheapest_applied_coupons") or row.get("applied_coupons")
    coupon_names: list[str] = []
    if isinstance(coupons, list):
        for coupon in coupons:
            if not isinstance(coupon, dict):
                continue
            coupon_name = str(coupon.get("cpn_nm") or "").strip()
            if coupon_name and coupon_name not in coupon_names:
                coupon_names.append(coupon_name)

    lines = [
        f"{product_name} {tire_size} {quantity}개 기준으로 보유 쿠폰 적용 혜택가를 확인했어요.",
        "",
        f"- 정가 합계: {_format_krw(base_total)}",
        f"- 쿠폰 적용 할인액: {_format_krw(discount_total) or '0원'}",
        f"- 최종 혜택가: {_format_krw(final_total)}",
    ]
    if coupon_names:
        lines.append(f"- 적용 기준 쿠폰: {', '.join(coupon_names[:3])}")

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_product_coupon_price_resolver",
        "data": {
            "assistantResponse": "\n".join(lines),
            "quickReplies": [
                {"label": "장바구니 담기", "domain": "TRANSACTION"},
                {"label": "구매하기", "domain": "TRANSACTION"},
                {"label": "내 쿠폰 조회", "domain": "TRANSACTION"},
            ],
            "predictedDomains": ["TRANSACTION"],
        },
    }


