def _coupon_target_product_name_for_query(user_text: str) -> str | None:
    frame = build_price_intent_frame(user_text)
    if frame.intent not in {"product_coupon_eligibility", "product_coupon_discount_amount"}:
        return None
    product_name = str(frame.entities.get("product_name") or "").strip()
    normalized = _split_product_size_quantity_from_text(product_name, user_text)
    return str(normalized.get("product_name") or "").strip() or None


_COUPON_TARGET_BRAND_ALIASES: tuple[tuple[str, str, tuple[str, ...]], ...] = (
    ("HK", "한국타이어", ("한국타이어", "hankook")),
    ("LF", "라우펜", ("라우펜", "laufenn")),
    ("MC", "미쉐린", ("미쉐린", "michelin")),
    ("PI", "피렐리", ("피렐리", "pirelli")),
    ("BS", "브리지스톤", ("브리지스톤", "bridgestone")),
    ("CT", "콘티넨탈", ("콘티넨탈", "continental")),
    ("GY", "굿이어", ("굿이어", "goodyear")),
)


def _coupon_target_brand_for_query(user_text: str) -> dict | None:
    text = str(user_text or "")
    if not text:
        return None
    if not _COUPON_WORD_RE.search(text):
        return None
    if not re.search(r"적용|사용|쓸\s*수|먹", text, re.IGNORECASE):
        return None

    for brand_cd, label, aliases in _COUPON_TARGET_BRAND_ALIASES:
        for alias in aliases:
            if not re.search(rf"{re.escape(alias)}\s*(?:도|에도|상품|타이어|브랜드)", text, re.IGNORECASE):
                continue
            return {"brand_cd": brand_cd, "label": label}
    return None


def _unsupported_brand_policy_guard_event(user_text: str, recent_context: str = "") -> dict | None:
    match = unsupported_brand_policy_match(user_text, recent_context=recent_context)
    if match is None:
        return None

    supported_labels = ", ".join(SUPPORTED_BRANDS.values())
    lines = [
        f"현재 챗봇에서 바로 안내 가능한 브랜드는 {supported_labels}예요.",
        f"{match.label} 등은 현재 상품 검색/추천 대상 브랜드가 아니어서 가격·재고·장착 가능 여부를 확정 안내하기 어려워요.",
    ]
    if match.has_store_context:
        lines.append("매장별 별도 취급 여부는 실시간 데이터가 없어 확정할 수 없으니 매장에 직접 확인해 주세요.")

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_unsupported_brand_policy_guard",
        "data": {
            "assistantResponse": "\n".join(lines),
            "quickReplies": [
                {"label": "지원 브랜드 상품 보기", "domain": "DISCOVERY"},
                {"label": "다른 브랜드 추천", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["DISCOVERY"],
            "metadata": {
                "unsupportedBrand": match.label,
                "supportedBrandCodes": list(SUPPORTED_BRANDS.keys()),
                "hasStoreContext": match.has_store_context,
            },
        },
    }


def _is_strong_coupon_applicability_query(user_text: str) -> bool:
    if _is_product_coupon_price_amount_query(user_text):
        return False
    frame = build_price_intent_frame(user_text)
    if _COUPON_ISSUE_INTENT_RE.search(user_text):
        return False
    if frame.intent in {"coupon_issue_request", "nonexistent_benefit"}:
        return False
    return frame.intent == "coupon_applicable_products"


def _is_product_coupon_eligibility_query(user_text: str) -> bool:
    frame = build_price_intent_frame(user_text)
    if _COUPON_ISSUE_INTENT_RE.search(user_text):
        return False
    if frame.intent in {"coupon_issue_request", "nonexistent_benefit"}:
        return False
    return frame.intent == "product_coupon_eligibility" and bool(frame.entities.get("product_name"))


def _is_product_coupon_eligibility_decision(decision: CouponQueryGateDecision | None) -> bool:
    return (
        decision is not None
        and decision.is_actionable
        and decision.intent == CouponQueryIntent.PRODUCT_COUPON_ELIGIBILITY
        and bool(decision.product_name)
    )


def _is_coupon_applicable_products_decision(
    decision: CouponQueryGateDecision | None,
    *,
    user_text: str | None = None,
    slots: Any | None = None,
    recent_context: str | None = None,
) -> bool:
    if _is_product_coupon_price_amount_query(user_text) or _is_coupon_discount_amount_context(slots):
        return False
    if (
        decision is not None
        and decision.intent == CouponQueryIntent.COUPON_APPLICABLE_PRODUCTS
        and not str(decision.product_name or "").strip()
        and not _coupon_hint_is_specific(decision.coupon_hint)
    ):
        if _recent_product_coupon_followup_target(user_text, recent_context):
            return False
        return False
    return (
        decision is not None
        and decision.is_actionable
        and decision.intent == CouponQueryIntent.COUPON_APPLICABLE_PRODUCTS
    )


def _is_owned_coupon_best_discount_decision(decision: CouponQueryGateDecision | None) -> bool:
    return (
        decision is not None
        and decision.is_actionable
        and decision.intent == CouponQueryIntent.BEST_DISCOUNT
    )


