def _grade_rank_value(value: str | None) -> int:
    return _GRADE_RANK.get(str(value or "").strip(), 0)


def _preferred_product_search_keyword(product_name: str) -> str:
    raw = str(product_name or "").strip()
    normalized = _normalize_coupon_match_text(raw)
    return _PRODUCT_SEARCH_KEYWORD_OVERRIDES.get(normalized, raw)


def _product_search_keyword_candidates(product_name: str) -> tuple[str, ...]:
    raw = str(product_name or "").strip()
    candidates: list[str] = []

    def _add(value: str) -> None:
        item = str(value or "").strip()
        if item and item not in candidates:
            candidates.append(item)

    _add(_preferred_product_search_keyword(raw))
    _add(raw)
    for canonical_name in extract_product_names(raw):
        _add(_preferred_product_search_keyword(canonical_name))
        _add(canonical_name)

    return tuple(candidates)


def _pick_product_row_from_search_result(
    tool_result: dict,
    product_name: str,
    *match_hints: str,
    allow_first_row_fallback: bool = False,
) -> dict | None:
    data = _unwrap_tool_data(tool_result)
    rows = data.get("items") if isinstance(data, dict) else None
    if not isinstance(rows, list):
        return None
    target_terms: set[str] = set()
    for value in (product_name, *match_hints):
        target_terms.update(_coupon_product_match_keys(value))
    target_canonical_names: set[str] = set()
    for value in (product_name, *match_hints):
        target_canonical_names.update(extract_product_names(str(value or "")))
    best_row: dict | None = None
    best_score = -1
    for row in rows:
        if not isinstance(row, dict):
            continue
        row_name = str(canonical_context_from_tool_boundary(row).get("product_name") or "").strip()
        if not row_name:
            continue
        row_canonical_names = set(extract_product_names(row_name))
        if target_canonical_names and row_canonical_names and not (target_canonical_names & row_canonical_names):
            continue
        row_terms = _coupon_product_match_keys(row_name)
        score = len(target_terms & row_terms)
        if score <= 0 and any(
            target and row_term and (target in row_term or row_term in target)
            for target in target_terms
            for row_term in row_terms
        ):
            score = 1
        if score > best_score:
            best_score = score
            best_row = row
    if best_score <= 0:
        if allow_first_row_fallback:
            for row in rows:
                if not isinstance(row, dict):
                    continue
                row_name = str(canonical_context_from_tool_boundary(row).get("product_name") or "").strip()
                if row_name:
                    return row
        return None
    return best_row


def _resolved_comparison_rows_are_distinct(product_rows: list[tuple[str, dict | None]]) -> bool:
    if len(product_rows) < 2:
        return False
    (left_name, left_row), (right_name, right_row) = product_rows[:2]
    if not isinstance(left_row, dict) or not isinstance(right_row, dict):
        return False

    left_canonical_row = canonical_context_from_tool_boundary(left_row)
    right_canonical_row = canonical_context_from_tool_boundary(right_row)
    left_goods_no = str(left_canonical_row.get("goods_no") or "").strip()
    right_goods_no = str(right_canonical_row.get("goods_no") or "").strip()
    if left_goods_no and right_goods_no and left_goods_no == right_goods_no:
        return False

    left_label = str(left_canonical_row.get("product_name") or left_name or "")
    right_label = str(right_canonical_row.get("product_name") or right_name or "")
    left_canonical = set(extract_product_names(left_label))
    right_canonical = set(extract_product_names(right_label))
    if left_canonical and right_canonical and (left_canonical & right_canonical):
        return False

    left_norm = _normalize_coupon_match_text(left_label)
    right_norm = _normalize_coupon_match_text(right_label)
    return bool(left_norm and right_norm and left_norm != right_norm)


def _unique_product_row_from_sized_search_result(tool_result: dict, product_name: str, tire_size: str) -> dict | None:
    data = _unwrap_tool_data(tool_result)
    rows = data.get("items") if isinstance(data, dict) else None
    if not isinstance(rows, list):
        return None

    requested_size = normalize_tire_size(tire_size)
    matched_by_goods_no: dict[str, dict] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        canonical_row = canonical_context_from_tool_boundary(row)
        goods_no = str(canonical_row.get("goods_no") or "").strip()
        if not goods_no:
            continue
        row_size = normalize_tire_size(str(canonical_row.get("tire_size") or row.get("tire_size_2") or ""))
        if requested_size and row_size and row_size != requested_size:
            continue
        row_name = canonical_row.get("product_name")
        if product_name and not _is_strong_product_name_match(product_name, row_name):
            continue
        matched_by_goods_no.setdefault(goods_no, row)
    if len(matched_by_goods_no) != 1:
        return None
    return next(iter(matched_by_goods_no.values()))


def _format_krw(value: Any) -> str:
    try:
        amount = int(float(str(value).replace(",", "")))
    except (TypeError, ValueError):
        return ""
    if amount <= 0:
        return ""
    return f"{amount:,}원"


def _tire_sizes_from_product_rows(rows: list[dict]) -> list[str]:
    sizes: list[str] = []
    seen_sizes: set[str] = set()
    for row in rows:
        if not isinstance(row, dict):
            continue
        tire_size = normalize_tire_size(str(canonical_context_from_tool_boundary(row).get("tire_size") or ""))
        if not tire_size:
            tire_size = normalize_tire_size(str(row.get("tire_size_2") or ""))
        if not tire_size:
            continue
        compact_size = re.sub(r"[^0-9]", "", tire_size)
        if compact_size in seen_sizes:
            continue
        seen_sizes.add(compact_size)
        sizes.append(tire_size)
    return sizes


def _current_product_claim_check_type() -> str:
    try:
        decision = _response_decision_for_source_domain(MultiAgentDomain.Domain.DISCOVERY.value)
    except Exception:
        return "none"
    metadata = getattr(decision, "metadata", None) or {}
    return str(metadata.get("claim_check_type") or "none")


def _product_description_lines_and_metadata(
    row: dict,
    *,
    size_specific: bool = True,
) -> tuple[list[str], dict[str, str]]:
    canonical_row = canonical_context_from_tool_boundary(row)
    goods_no = str(canonical_row.get("goods_no") or "").strip()
    name = str(canonical_row.get("product_name") or row.get("big_goods_nm") or "상품").strip()
    tire_size = normalize_tire_size(str(canonical_row.get("tire_size") or row.get("tire_size_2") or ""))
    slogan = _clean_product_sentence(row.get("slogan"))
    tech = _clean_product_sentence(row.get("pc_prod_tech_desc"))
    season = str(row.get("season_nm") or "").strip()
    car_kind = str(row.get("car_knd_nm") or "").strip()
    performance = str(row.get("goods_pfm_nm") or "").strip()
    comfort = _to_float(row.get("t_comfort"))
    silence = _to_float(row.get("t_silence"))
    life_span = _to_float(row.get("t_life_span"))
    wet = row.get("wet")
    rr = row.get("rr")

    intro_subject = f"{name}는"
    if slogan:
        intro = f"{intro_subject} {slogan} 상품이에요."
    elif performance:
        intro = f"{intro_subject} {performance} 타이어예요."
    else:
        intro = f"{intro_subject} 상세 정보가 확인되는 타이어예요."

    lines = []
    if _current_product_claim_check_type() == "unverified_external_claim":
        lines.extend([
            "말씀하신 내용은 현재 상품 설명 데이터에서 직접 확인하기 어려워요.",
            "확인 가능한 상품 설명 기준으로 안내드릴게요.",
            "",
        ])
    lines.append(intro)
    available_sizes = row.get("_available_tire_sizes")
    if isinstance(available_sizes, list):
        available_sizes = [normalize_tire_size(str(size or "")) for size in available_sizes]
        available_sizes = [size for size in available_sizes if size]
    else:
        available_sizes = []

    if size_specific and tire_size:
        lines.extend(["", f"선택한 규격은 {tire_size}예요."])
    elif available_sizes:
        visible_sizes = available_sizes[:8]
        suffix = " 등" if len(available_sizes) > len(visible_sizes) else ""
        lines.extend(["", f"확인 가능한 규격은 {', '.join(visible_sizes)}{suffix}이에요."])

    classification_parts: list[str] = []
    if season:
        classification_parts.append(season)
    if car_kind:
        classification_parts.append(car_kind)
    if performance and performance not in classification_parts:
        classification_parts.append(performance)
    if classification_parts:
        lines.extend(["", f"상품 분류는 {' · '.join(classification_parts)} 기준으로 확인돼요."])

    if tech:
        lines.extend(["", tech[:160]])

    performance_bits: list[str] = []
    if comfort and comfort > 0:
        performance_bits.append(f"승차감 {comfort:g}/5")
    if silence and silence > 0:
        performance_bits.append(f"정숙성 {silence:g}/5")
    if life_span and life_span > 0:
        performance_bits.append(f"마일리지 {life_span:g}/5")
    if wet not in (None, "", 0, "0"):
        performance_bits.append(f"젖은노면 {wet}등급")
    if rr not in (None, "", 0, "0"):
        performance_bits.append(f"회전저항 {rr}등급")
    if performance_bits:
        lines.extend(["", f"주요 성능은 {', '.join(performance_bits)} 수준이에요."])

    rating = row.get("rating") if isinstance(row.get("rating"), dict) else {}
    review_count = row.get("review_count") or rating.get("review_count")
    rating_avg = row.get("rating_avg") or row.get("rate") or rating.get("rating_avg")
    if review_count and rating_avg:
        lines.extend(["", f"리뷰는 {review_count}건, 평균 평점은 {rating_avg}점입니다."])
    elif review_count:
        lines.extend(["", f"리뷰는 {review_count}건입니다."])
    elif rating_avg:
        lines.extend(["", f"평균 평점은 {rating_avg}점입니다."])

    metadata: dict[str, str] = {}
    if goods_no:
        metadata["goodsId"] = goods_no
    if tire_size:
        metadata["tireSize"] = tire_size
    if name:
        metadata["productName"] = name

    return lines, metadata


