def _build_product_description_quickreply_event(detail_result: dict) -> dict | None:
    row = _unwrap_tool_data(detail_result)
    if not isinstance(row, dict) or not row:
        return None

    lines, metadata = _product_description_lines_and_metadata(row)

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_product_description",
        "data": {
            "assistantResponse": "\n".join(lines),
            "quickReplies": [dict(chip) for chip in _PRODUCT_DESCRIPTION_INFO_CHIPS],
            "predictedDomains": ["DISCOVERY", "TRANSACTION"],
            "metadata": metadata,
        },
    }


_PRODUCT_COMPARE_TEXT_RE = re.compile(r"비교|차이|다른|달라|어느\s*게|뭐가\s*(?:더|나아|좋)", re.IGNORECASE)
_PRODUCT_COMPARE_FOLLOWUP_RE = re.compile(
    r"비교|차이|다른|달라|어느\s*게|뭐가\s*(?:더|나아|좋)|어떤\s*게\s*더\s*좋|"
    r"둘\s*중|두\s*개\s*중|이\s*2\s*개\s*중|이\s*두\s*개\s*중",
    re.IGNORECASE,
)
_PRODUCT_COMPARE_CONTEXT_RESET_RE = re.compile(
    r"(?:두\s*개|둘|이\s*2\s*개|이\s*두\s*개)\s*말고|"
    r"(?:이거|요거|그거|기존\s*상품|비교\s*상품)\s*말고|"
    r"(?:아까|이전|기존)\s*(?:두\s*개|둘|상품|거)\s*말고|"
    r"다른\s*(?:후보|거|걸|걸로)|"
    r"다른\s*(?:추천\s*)?상품|다른\s*추천|추천\s*상품|"
    r"다른\s*상품\s*비교",
    re.IGNORECASE,
)
_PRODUCT_COMPARE_RECENT_TWO_FOLLOWUP_RE = re.compile(
    r"둘\s*중|두\s*개\s*중|이\s*2\s*개\s*중|이\s*두\s*개\s*중|"
    r"두\s*상품|두\s*개\s*(?:특징|설명|차이|비교)|"
    r"(?:가격|금액|혜택가|최종가|할인가|저렴|비싸).*(?:둘|두\s*개|두\s*상품)|"
    r"(?:둘|두\s*개|두\s*상품).*(?:가격|금액|혜택가|최종가|할인가|저렴|비싸)",
    re.IGNORECASE,
)
_PRODUCT_DESCRIPTION_COMPARE_FOLLOWUP_RE = re.compile(
    r"(?:상품\s*)?(?:설명|특징|장점|후기|리뷰)\s*비교|비교.*(?:설명|특징|장점|후기|리뷰)",
    re.IGNORECASE,
)
_PRODUCT_PRICE_COMPARE_TEXT_RE = re.compile(r"가격|금액|혜택가|최종가|할인가|얼마|저렴|비싸", re.IGNORECASE)
_PRODUCT_RELEASE_COMPARE_TEXT_RE = re.compile(r"신상|신상품|신제품|출시|출시일|최근|최신|새로운|새로\s*나온", re.IGNORECASE)
_PRODUCT_CAR_TYPE_COMPARE_TEXT_RE = re.compile(r"차종\s*기준|SUV\s*용|승용\s*/\s*SUV|승용차\s*/\s*SUV", re.IGNORECASE)
_PRODUCT_GRADE_COMPARE_TEXT_RE = re.compile(r"등급|프리미엄|스탠다드|상위", re.IGNORECASE)
_PRODUCT_MILEAGE_COMPARE_TEXT_RE = re.compile(r"마일리지|수명|오래\s*가|내구", re.IGNORECASE)
_PRODUCT_NOISE_COMPARE_TEXT_RE = re.compile(r"소음|조용|정숙", re.IGNORECASE)
_PRODUCT_WET_COMPARE_TEXT_RE = re.compile(r"빗길|젖은\s*노면|wet", re.IGNORECASE)
_PRODUCT_AXIS_OMITTED_COMPARE_RE = re.compile(
    r"(?:중에서는|중에(?:는)?|둘은|두\s*상품은|는\s*\?|은\s*\?|어때|어떤데)\s*$",
    re.IGNORECASE,
)
_PRODUCT_COMPARE_REASK_RE = re.compile(
    r"뭐가\s*더\s*(?:신상|신상품|최신|최근|새로운|저렴|비싸|조용|좋|나아)|"
    r"그래서\s*뭐가\s*더|다시\s*(?:비교|말해|알려)|"
    r"(?:신상|최신|가격|등급|마일리지|소음|빗길).*(?:뭐냐고|냐고|라고)",
    re.IGNORECASE,
)
_COMPARISON_METRICS = {
    "release",
    "price",
    "grade",
    "mileage",
    "noise",
    "fuel_efficiency",
    "wet",
    "car_type",
    "detail",
}


def _comparison_context_dict(value: Any) -> dict[str, Any]:
    if value is None:
        return {}
    if isinstance(value, Mapping):
        data = dict(value)
    elif hasattr(value, "to_policy_dict"):
        data = value.to_policy_dict()
    elif hasattr(value, "model_dump"):
        data = value.model_dump(exclude_none=True)
    else:
        return {}
    product_names = data.get("product_names") or data.get("productNames")
    if isinstance(product_names, (list, tuple)):
        data["product_names"] = [str(name).strip() for name in product_names if str(name or "").strip()][:2]
    return data


def _comparison_context_from_slots(slots: Any | None) -> dict[str, Any]:
    if slots is None:
        return {}
    if isinstance(slots, Mapping):
        value = slots.get("comparison_context")
    else:
        value = getattr(slots, "comparison_context", None)
    return _comparison_context_dict(value)


def _explicit_compare_metric_from_text(user_text: str) -> str:
    text = user_text or ""
    if _PRODUCT_RELEASE_COMPARE_TEXT_RE.search(text):
        return "release"
    if _PRODUCT_PRICE_COMPARE_TEXT_RE.search(text):
        return "price"
    if _PRODUCT_CAR_TYPE_COMPARE_TEXT_RE.search(text):
        return "car_type"
    if _PRODUCT_GRADE_COMPARE_TEXT_RE.search(text):
        return "grade"
    if _PRODUCT_MILEAGE_COMPARE_TEXT_RE.search(text):
        return "mileage"
    if _PRODUCT_NOISE_COMPARE_TEXT_RE.search(text):
        return "noise"
    if _PRODUCT_WET_COMPARE_TEXT_RE.search(text):
        return "wet"
    return ""


def _comparison_query_metric_phrase(compare_metric: str) -> str:
    return {
        "release": "출시일 비교",
        "price": "가격 비교",
        "grade": "등급 비교",
        "mileage": "마일리지 비교",
        "noise": "소음 비교",
        "fuel_efficiency": "연비 비교",
        "wet": "빗길 성능 비교",
        "car_type": "차종 기준 비교",
        "detail": "비교",
    }.get(compare_metric, "비교")


def _comparison_context_values_from_event(event: dict | None) -> dict[str, Any]:
    if not isinstance(event, dict):
        return {}
    if str(event.get("assistant_response_source") or "") != "code_product_compare_resolver":
        return {}
    data = event.get("data")
    if not isinstance(data, dict):
        return {}
    metadata = data.get("metadata")
    if not isinstance(metadata, dict):
        return {}
    response_shape_key = str(metadata.get("response_shape_key") or "").strip()
    if response_shape_key not in {"metric_comparison_summary", "grade_comparison_summary"}:
        return {}
    compare_metric = str(metadata.get("compareMetric") or metadata.get("compare_metric") or "detail").strip()
    if compare_metric not in _COMPARISON_METRICS:
        compare_metric = "detail"
    product_names = metadata.get("productNames") or metadata.get("product_names")
    if not isinstance(product_names, (list, tuple)) or len(product_names) < 2:
        return {}
    names = [str(name).strip() for name in product_names if str(name or "").strip()][:2]
    if len(names) < 2:
        return {}
    return {
        "comparison_context": {
            "product_names": names,
            "compare_metric": compare_metric,
            "response_shape_key": response_shape_key,
            "comparison_followup_intent": str(metadata.get("comparison_followup_intent") or "none"),
            "source": "code_product_compare_resolver",
        }
    }


def _product_comparison_names(user_text: str) -> tuple[str, ...]:
    frame = build_discovery_intent_frame(user_text)
    product_names = tuple(frame.entities.get("product_names") or ())
    if len(product_names) < 2:
        return ()
    if frame.sub_intent in {"grade_compare", "mileage_compare", "latest_compare", "attribute_compare", "general_compare"}:
        return product_names
    if frame.intent in {"product_search", "product_description"} and _PRODUCT_COMPARE_TEXT_RE.search(user_text):
        return product_names
    return ()


def _product_names_in_text(user_text: str) -> tuple[str, ...]:
    frame = build_discovery_intent_frame(user_text)
    return tuple(frame.entities.get("product_names") or ())


def _recent_product_names_for_comparison(messages: list[dict]) -> tuple[str, ...]:
    recent_names: list[str] = []
    for message in messages[:-1]:
        if message.get("role") != "user":
            continue
        content = str(message.get("content") or "")
        for product_name in _product_names_in_text(content):
            if product_name in recent_names:
                recent_names.remove(product_name)
            recent_names.append(product_name)
    return tuple(recent_names[-2:])


def _is_product_compare_context_reset_query(user_text: str) -> bool:
    text = user_text or ""
    if _product_names_in_text(text):
        return False
    return bool(_PRODUCT_COMPARE_CONTEXT_RESET_RE.search(text))


def _is_compare_target_prompt_template(template_data: dict | None) -> bool:
    if not isinstance(template_data, dict):
        return False
    source = str(template_data.get("assistant_response_source") or "").strip()
    if source == "code_product_compare_target_prompt":
        return True
    data = template_data.get("data") if isinstance(template_data.get("data"), dict) else template_data
    assistant = str(data.get("assistantResponse") or "") if isinstance(data, dict) else ""
    return "비교할 다른 상품명을 알려주시면" in assistant


def _has_recent_compare_target_prompt(messages: list[dict], latest_quickreply_tmpl: dict | None = None) -> bool:
    if _is_compare_target_prompt_template(latest_quickreply_tmpl):
        return True
    for message in reversed(messages[:-1]):
        if message.get("role") != "assistant":
            continue
        template_data = message.get("template_data")
        if _is_compare_target_prompt_template(template_data):
            return True
        content = str(message.get("content") or "")
        if "비교할 다른 상품명을 알려주시면" in content:
            return True
        break
    return False


def _can_reuse_recent_products_for_comparison(user_text: str, *, is_description_compare: bool = False) -> bool:
    text = user_text or ""
    if _is_product_compare_context_reset_query(text):
        return False
    if is_description_compare:
        return True
    return bool(_PRODUCT_COMPARE_RECENT_TWO_FOLLOWUP_RE.search(text))


def _should_prompt_for_new_product_compare_target(user_text: str, messages: list[dict]) -> bool:
    return _is_product_compare_context_reset_query(user_text) and len(_recent_product_names_for_comparison(messages)) >= 2


def _should_clarify_ambiguous_multi_product_query(
    user_text: str,
    messages: list[dict],
    latest_quickreply_tmpl: dict | None = None,
) -> bool:
    product_names = _product_names_in_text(user_text)
    if len(product_names) < 2:
        return False
    if _product_comparison_names(user_text):
        return False
    if _has_recent_compare_target_prompt(messages, latest_quickreply_tmpl):
        return False
    if _PRODUCT_DESCRIPTION_COMPARE_FOLLOWUP_RE.search(user_text):
        return False
    if re.search(r"각각|둘\s*다|둘\s*모두|상품\s*정보|설명|알려", user_text or "", re.IGNORECASE):
        return False
    return True


def _multi_product_clarification_metadata_product_names(template_data: dict | None) -> tuple[str, ...]:
    if not isinstance(template_data, dict):
        return ()
    if str(template_data.get("assistant_response_source") or "").strip() != "code_multi_product_intent_clarification":
        return ()
    data = template_data.get("data") if isinstance(template_data.get("data"), dict) else template_data
    metadata = data.get("metadata") if isinstance(data, dict) else None
    if not isinstance(metadata, dict):
        return ()
    names = metadata.get("pendingProductNames") or metadata.get("productNames")
    if not isinstance(names, list):
        return ()
    return tuple(str(name).strip() for name in names if str(name or "").strip())[:2]


def _is_multi_product_intent_clarification_template(template_data: dict | None) -> bool:
    if not isinstance(template_data, dict):
        return False
    if _multi_product_clarification_metadata_product_names(template_data):
        return True
    source = str(template_data.get("assistant_response_source") or "").strip()
    if source == "code_multi_product_intent_clarification":
        return True
    data = template_data.get("data") if isinstance(template_data.get("data"), dict) else template_data
    assistant = str(data.get("assistantResponse") or "") if isinstance(data, dict) else ""
    return "두 상품을 비교해드릴까요" in assistant and "각각 상품을 찾아드릴까요" in assistant


def _is_multi_product_intent_clarification_text(content: str) -> bool:
    return "두 상품을 비교해드릴까요" in content and "각각 상품을 찾아드릴까요" in content


def _recent_multi_product_clarification_names(
    messages: list[dict],
    latest_quickreply_tmpl: dict | None = None,
) -> tuple[str, ...]:
    names = _multi_product_clarification_metadata_product_names(latest_quickreply_tmpl)
    if len(names) >= 2:
        return names

    for idx in range(len(messages) - 2, -1, -1):
        message = messages[idx]
        if message.get("role") != "assistant":
            continue
        template_data = message.get("template_data")
        content = str(message.get("content") or "")
        if not (
            _is_multi_product_intent_clarification_template(template_data)
            or _is_multi_product_intent_clarification_text(content)
        ):
            continue
        names = _multi_product_clarification_metadata_product_names(template_data)
        if len(names) >= 2:
            return names
        for prev_idx in range(idx - 1, -1, -1):
            prev_message = messages[prev_idx]
            if prev_message.get("role") != "user":
                continue
            names = _product_names_in_text(str(prev_message.get("content") or ""))
            if len(names) >= 2:
                return names[:2]
            break
        return ()

    if _is_multi_product_intent_clarification_template(latest_quickreply_tmpl):
        for message in reversed(messages[:-1]):
            if message.get("role") != "user":
                continue
            names = _product_names_in_text(str(message.get("content") or ""))
            if len(names) >= 2:
                return names[:2]
            break
    return ()


def _is_multi_product_detail_continuation(user_text: str) -> bool:
    return bool(
        re.search(
            r"각각\s*(?:찾아|검색|설명|알려|보기)|각각|둘\s*다|둘\s*모두|"
            r"(?:두\s*상품|두\s*제품|두\s*개|이\s*두\s*개).*(?:정보|보여|찾아|검색|설명|알려)|"
            r"(?:정보|보여|찾아|검색|설명|알려).*(?:두\s*상품|두\s*제품|두\s*개|이\s*두\s*개)",
            user_text or "",
            re.IGNORECASE,
        )
    )


def _is_multi_product_compare_continuation(user_text: str) -> bool:
    return bool(re.search(r"두\s*상품\s*비교|비교", user_text or "", re.IGNORECASE))


def _multi_product_detail_continuation_names(
    user_text: str,
    messages: list[dict],
    latest_quickreply_tmpl: dict | None = None,
) -> tuple[str, ...]:
    if not _is_multi_product_detail_continuation(user_text):
        return ()
    names = _recent_multi_product_clarification_names(messages, latest_quickreply_tmpl)
    if len(names) >= 2:
        return names
    return _recent_product_names_for_comparison(messages)


def _multi_product_compare_continuation_query(
    user_text: str,
    messages: list[dict],
    latest_quickreply_tmpl: dict | None = None,
) -> str | None:
    if not _is_multi_product_compare_continuation(user_text):
        return None
    names = _recent_multi_product_clarification_names(messages, latest_quickreply_tmpl)
    if len(names) < 2:
        return None
    return f"{names[0]}랑 {names[1]} 비교"


def _should_resolve_compare_target_product_pair(
    user_text: str,
    messages: list[dict],
    latest_quickreply_tmpl: dict | None = None,
    slots: Any | None = None,
) -> bool:
    if _is_product_compare_context_reset_query(user_text):
        return False
    if not _has_recent_compare_target_prompt(messages, latest_quickreply_tmpl):
        comparison_context = _comparison_context_from_slots(slots)
        context_metric = str(comparison_context.get("compare_metric") or "").strip()
        current_names = _product_names_in_text(user_text)
        if not (
            context_metric in _COMPARISON_METRICS
            and len(current_names) >= 2
            and _PRODUCT_AXIS_OMITTED_COMPARE_RE.search(user_text or "")
        ):
            return False
    comparison_query = _comparison_query_with_recent_context(user_text, messages, latest_quickreply_tmpl, slots=slots)
    return len(_product_comparison_names(comparison_query)) >= 2


def _comparison_query_with_recent_context(
    user_text: str,
    messages: list[dict],
    latest_quickreply_tmpl: dict | None = None,
    slots: Any | None = None,
) -> str:
    if _product_comparison_names(user_text):
        return user_text
    user_text = user_text or ""
    if _is_product_compare_context_reset_query(user_text):
        return user_text
    comparison_context = _comparison_context_from_slots(slots)
    context_names = tuple(comparison_context.get("product_names") or ())
    context_metric = str(comparison_context.get("compare_metric") or "").strip()
    if context_metric not in _COMPARISON_METRICS:
        context_metric = ""
    explicit_metric = _explicit_compare_metric_from_text(user_text)
    effective_metric = explicit_metric or context_metric
    current_names = _product_names_in_text(user_text)
    if len(current_names) >= 2 and context_metric and _PRODUCT_AXIS_OMITTED_COMPARE_RE.search(user_text):
        return f"{current_names[0]}랑 {current_names[1]} {_comparison_query_metric_phrase(effective_metric)}"
    if len(current_names) == 0 and len(context_names) >= 2 and effective_metric and _PRODUCT_COMPARE_REASK_RE.search(user_text):
        return f"{context_names[0]}랑 {context_names[1]} {_comparison_query_metric_phrase(effective_metric)}"
    is_description_compare = bool(_PRODUCT_DESCRIPTION_COMPARE_FOLLOWUP_RE.search(user_text))
    if not (is_description_compare or _PRODUCT_COMPARE_FOLLOWUP_RE.search(user_text)):
        if len(current_names) >= 2 and _has_recent_compare_target_prompt(messages, latest_quickreply_tmpl):
            return f"{current_names[0]}랑 {current_names[1]} 비교"
        return user_text

    suffix = "상품 설명 비교" if is_description_compare else "비교"
    if effective_metric and not is_description_compare:
        suffix = _comparison_query_metric_phrase(effective_metric)

    if len(current_names) >= 2 and _has_recent_compare_target_prompt(messages, latest_quickreply_tmpl):
        return f"{current_names[0]}랑 {current_names[1]} {suffix}"

    if len(current_names) == 1:
        recent_names = _recent_product_names_for_comparison(messages)
        current_name = current_names[0]
        for recent_name in reversed(recent_names):
            if recent_name != current_name:
                return f"{recent_name}랑 {current_name} {suffix}"

    if len(current_names) == 0 and len(context_names) >= 2 and _can_reuse_recent_products_for_comparison(
        user_text,
        is_description_compare=is_description_compare,
    ):
        return f"{context_names[0]}랑 {context_names[1]} {suffix}"

    recent_names = _recent_product_names_for_comparison(messages)
    if (
        len(current_names) == 0
        and len(recent_names) >= 2
        and _can_reuse_recent_products_for_comparison(user_text, is_description_compare=is_description_compare)
    ):
        return f"{recent_names[0]}랑 {recent_names[1]} {suffix}"
    return user_text


