def _quantity_benefit_pending_values_from_template(template_data: dict | None) -> dict[str, Any]:
    if not isinstance(template_data, dict):
        return {}
    data = template_data.get("data") if isinstance(template_data.get("data"), dict) else template_data
    metadata = data.get("metadata") if isinstance(data, dict) else None
    quantity_meta = data.get("quantityBenefitComparison") if isinstance(data, dict) else None
    if isinstance(quantity_meta, dict):
        metadata = quantity_meta
    if not isinstance(metadata, dict):
        return {}
    if metadata.get("pendingIntent") != "quantity_benefit_comparison":
        return {}
    canonical_metadata = canonical_context_from_template_boundary(metadata)
    product_name = str(canonical_metadata.get("product_name") or "").strip()
    quantity_options = metadata.get("quantityOptions")
    if not isinstance(quantity_options, list):
        return {}
    quantities: list[int] = []
    for value in quantity_options:
        try:
            quantity = int(value)
        except (TypeError, ValueError):
            continue
        if quantity > 0 and quantity not in quantities:
            quantities.append(quantity)
    if not product_name or len(quantities) < 2:
        return {}
    return {
        "product_name": product_name,
        "quantity_options": quantities[:2],
        "required_slot": str(metadata.get("missingSlot") or "tire_size"),
    }


def _quantity_benefit_pending_values_from_slots(slots: Any | None) -> dict[str, Any]:
    if getattr(slots, "pending_intent", None) != "quantity_benefit_comparison":
        return {}
    product_name = str(getattr(slots, "pending_product_name", None) or "").strip()
    quantity_options = getattr(slots, "pending_quantity_options", None)
    if not isinstance(quantity_options, list):
        return {}
    quantities: list[int] = []
    for value in quantity_options:
        try:
            quantity = int(value)
        except (TypeError, ValueError):
            continue
        if quantity > 0 and quantity not in quantities:
            quantities.append(quantity)
    if not product_name or len(quantities) < 2:
        return {}
    return {
        "product_name": product_name,
        "quantity_options": quantities[:2],
        "required_slot": str(getattr(slots, "pending_required_slot", None) or "tire_size"),
    }


_KOREAN_SELECTION_ORDINALS: tuple[tuple[tuple[str, ...], int], ...] = (
    (("첫번째", "첫째"), 0),
    (("두번째", "둘째"), 1),
    (("세번째", "셋째"), 2),
    (("네번째", "넷째"), 3),
    (("다섯번째", "다섯째"), 4),
    (("여섯번째", "여섯째"), 5),
    (("일곱번째", "일곱째"), 6),
    (("여덟번째", "여덟째"), 7),
    (("아홉번째", "아홉째"), 8),
    (("열번째", "열째"), 9),
)


def _selection_ordinal_index(user_text: str, item_count: int) -> int | None:
    if not user_text or item_count <= 0:
        return None

    text = user_text.strip()
    numeric_match = re.match(r"^\s*(\d+)\s*(?:[\.\)번:]|번째|째)", text)
    if numeric_match:
        idx = int(numeric_match.group(1)) - 1
        return idx if 0 <= idx < item_count else None

    compact = re.sub(r"\s+", "", text)
    if compact.startswith(("마지막", "끝번째", "끝째")):
        return item_count - 1

    for prefixes, idx in _KOREAN_SELECTION_ORDINALS:
        if any(compact.startswith(prefix) for prefix in prefixes):
            return idx if idx < item_count else None
    return None


def _resolve_goods_no_from_product_template_selection(user_text: str, template_data: dict | None) -> str | None:
    if not user_text or not isinstance(template_data, dict):
        return None
    data = template_data.get("data") if isinstance(template_data.get("data"), dict) else template_data
    if not isinstance(data, dict):
        return None
    products = data.get("products")
    metadata = data.get("metadata")
    if not isinstance(products, list) or not isinstance(metadata, list):
        return None
    if not products or len(products) != len(metadata):
        return None

    text = user_text.strip()
    ordinal_idx = _selection_ordinal_index(text, len(metadata))
    if ordinal_idx is not None and isinstance(metadata[ordinal_idx], dict):
        goods_no = str(canonical_context_from_template_boundary(metadata[ordinal_idx]).get("goods_no") or "").strip()
        return goods_no or None

    target_size = normalize_tire_size(text)
    tokens = [t.lower() for t in re.findall(r"[A-Za-z가-힣0-9]+", text) if len(t) >= 2]
    best_goods_no = ""
    best_score = 0
    tied = False
    for product, meta in zip(products, metadata):
        if not isinstance(product, dict) or not isinstance(meta, dict):
            continue
        canonical_product = canonical_context_from_template_boundary(product)
        canonical_meta = canonical_context_from_template_boundary(meta)
        product_size = normalize_tire_size(str(canonical_product.get("tire_size") or ""))
        if target_size and product_size != target_size:
            continue
        title = " ".join(
            str(part or "")
            for part in (
                canonical_product.get("product_name"),
                product.get("title"),
            )
        ).lower()
        score = sum(1 for token in tokens if token in title)
        goods_no = str(canonical_meta.get("goods_no") or "").strip()
        if score > best_score:
            best_score = score
            best_goods_no = goods_no
            tied = False
        elif score == best_score and score > 0:
            tied = True
    if best_goods_no and best_score >= 2 and not tied:
        return best_goods_no
    return None


def _quantity_benefit_continuation_frame_from_pending(
    user_text: str,
    *,
    slots: Any | None = None,
    latest_quickreply_tmpl: dict | None = None,
    latest_product_tmpl: dict | None = None,
    current_goods_no: str | None = None,
) -> IntentFrame | None:
    current_size = normalize_tire_size(user_text)
    goods_no = str(
        current_goods_no
        or _resolve_goods_no_from_product_template_selection(user_text, latest_product_tmpl)
        or getattr(slots, "goods_no", None)
        or ""
    ).strip()
    if not current_size and not goods_no:
        return None
    pending = (
        _quantity_benefit_pending_values_from_slots(slots)
        or _quantity_benefit_pending_values_from_template(latest_quickreply_tmpl)
        or _quantity_benefit_pending_values_from_template(latest_product_tmpl)
    )
    if not pending:
        return None

    product_name = pending["product_name"]
    quantities = tuple(sorted(int(quantity) for quantity in pending["quantity_options"][:2]))
    known_slots: dict[str, Any] = {}
    if current_size:
        known_slots["tire_size"] = current_size
    if goods_no:
        known_slots["goods_no"] = goods_no
    synthetic_text = f"{product_name} {' '.join(f'{quantity}개' for quantity in quantities)} 할인 비교"
    synthetic_frame = build_discovery_intent_frame(synthetic_text, known_slots=known_slots)
    entities = dict(synthetic_frame.entities)
    entities["product_names"] = tuple(entities.get("product_names") or (product_name,))
    entities["quantity_options"] = quantities
    entities["compare_metric"] = "discount"
    if current_size:
        entities["tire_size"] = current_size
        entities["explicit_tire_size"] = current_size
    return IntentFrame(
        domain=PolicyDomain.DISCOVERY,
        intent="product_comparison",
        sub_intent="quantity_benefit_comparison",
        entities=entities,
        known_slots=known_slots,
        missing_slots=(),
        confidence=0.9,
    )


def _build_quantity_benefit_comparison_event(price_results: dict[int, dict]) -> dict | None:
    summaries: list[dict[str, Any]] = []
    for quantity in sorted(price_results):
        summary = _quantity_price_summary(price_results[quantity], quantity)
        if summary is None:
            return None
        summaries.append(summary)
    if len(summaries) < 2:
        return None

    left, right = summaries[0], summaries[-1]
    product_name = str(right.get("product_name") or left.get("product_name") or "선택하신 상품")
    left_unit_discount = int(left["sale_unit"]) - int(left["final_unit"])
    right_unit_discount = int(right["sale_unit"]) - int(right["final_unit"])
    if int(right["final_unit"]) < int(left["final_unit"]):
        verdict = f"{right['quantity']}개 구매가 개당 기준으로 더 저렴합니다."
    elif right_unit_discount > left_unit_discount:
        verdict = f"{right['quantity']}개 구매가 개당 할인 기준으로 더 유리합니다."
    elif int(right["discount_total"]) > int(left["discount_total"]):
        verdict = (
            f"{right['quantity']}개는 총 할인액은 더 크지만, 개당 혜택은 {left['quantity']}개와 동일하거나 "
            "추가 할인으로 보기는 어렵습니다."
        )
    else:
        verdict = f"{right['quantity']}개 구매라고 해서 추가 할인이 더 적용되지는 않습니다."

    lines = [
        f"{product_name} 기준으로 {left['quantity']}개와 {right['quantity']}개 실제 혜택가를 비교했어요.",
        "",
        "| 수량 | 정상가 합계 | 할인 합계 | 최종 결제금액 | 개당 혜택가 |",
        "|---|---:|---:|---:|---:|",
    ]
    for summary in summaries:
        lines.append(
            "| {quantity}개 | {base_total} | -{discount_total} | {final_total} | {final_unit} |".format(
                quantity=summary["quantity"],
                base_total=_format_krw(summary["base_total"]),
                discount_total=_format_krw(summary["discount_total"]) or "0원",
                final_total=_format_krw(summary["final_total"]),
                final_unit=_format_krw(summary["final_unit"]),
            )
        )
    coupon_names: list[str] = []
    for summary in summaries:
        for coupon_name in summary.get("coupon_names") or []:
            if coupon_name not in coupon_names:
                coupon_names.append(coupon_name)
    if coupon_names:
        lines.extend(["", f"적용 기준 쿠폰: {', '.join(coupon_names[:3])}"])
    lines.extend(["", verdict])

    goods_no = str(right.get("goods_no") or left.get("goods_no") or "").strip()
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_quantity_benefit_comparison",
        "data": {
            "assistantResponse": "\n".join(lines),
            "quickReplies": [
                {"label": f"{right['quantity']}개로 구매", "domain": "TRANSACTION"},
                {"label": f"{left['quantity']}개로 구매", "domain": "TRANSACTION"},
                {"label": "다른 상품 비교", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["TRANSACTION", "DISCOVERY"],
            "metadata": {
                "goodsId": goods_no or None,
                "quantityOptions": [summary["quantity"] for summary in summaries],
                "productName": product_name,
            },
        },
    }


def _goods_no_from_template_event(event: dict | None) -> str:
    if not isinstance(event, dict):
        return ""
    data = event.get("data")
    if not isinstance(data, dict):
        return ""
    metadata = data.get("metadata")
    if isinstance(metadata, dict):
        canonical_metadata = canonical_context_from_template_boundary(metadata)
        goods_no = str(canonical_metadata.get("goods_no") or metadata.get("goodsIdList") or "").strip()
        if goods_no.startswith("G"):
            return goods_no
    for key in ("products", "productList", "items"):
        rows = data.get(key)
        if not isinstance(rows, list) or len(rows) != 1 or not isinstance(rows[0], dict):
            continue
        row_goods_no = str(canonical_context_from_template_boundary(rows[0]).get("goods_no") or "").strip()
        if row_goods_no.startswith("G"):
            return row_goods_no
    return ""


def _build_product_comparison_event(
    user_text: str,
    product_rows: list[tuple[str, dict | None]],
) -> dict:
    product_rows = [
        (
            str((row or {}).get("goods_nm") or (row or {}).get("title") or name).strip() or name,
            row,
        )
        for name, row in product_rows
    ]
    fallback_event = _build_product_comparison_fallback_event(product_rows)
    if fallback_event:
        return fallback_event

    compare_metric, comparison_followup_intent, sub_intent = _comparison_context_from_policy_or_text(user_text)
    (left_name, left_row), (right_name, right_row) = product_rows[:2]  # guarded by fallback above

    if not compare_metric and sub_intent not in {"grade_compare", "mileage_compare", "latest_compare", "attribute_compare"}:
        assistant = _build_product_feature_review_comparison(left_name, left_row, right_name, right_row)
    elif sub_intent == "grade_compare" or compare_metric in {"grade", "price_grade"}:
        left_grade = str(left_row.get("prc_grd_nm") or "").strip() or "미확인"
        right_grade = str(right_row.get("prc_grd_nm") or "").strip() or "미확인"
        if _grade_rank_value(left_grade) == _grade_rank_value(right_grade):
            verdict = (
                f"{left_name}와 {right_name}는 모두 {left_grade} 등급으로 확인돼요. "
                "두 상품은 같은 등급 안에서 포지션 차이가 있을 수 있어요."
            )
        else:
            better_name = left_name if _grade_rank_value(left_grade) > _grade_rank_value(right_grade) else right_name
            worse_name = right_name if better_name == left_name else left_name
            better_grade = left_grade if better_name == left_name else right_grade
            worse_grade = right_grade if worse_name == right_name else left_grade
            verdict = (
                f"{better_name}이 {worse_name}보다 상위 등급입니다. "
                f"({better_name}: {better_grade}, {worse_name}: {worse_grade})"
            )
        assistant = _build_product_comparison_table(
            left_name,
            left_row,
            right_name,
            right_row,
            rows=(("상품 등급", "grade"), ("특징", "feature"), ("리뷰", "review")),
            verdict=verdict,
        )
    elif sub_intent == "latest_compare" or compare_metric == "release":
        left_release = str(left_row.get("t_rls_yearmon") or left_row.get("sys_reg_dtime") or "").strip()
        right_release = str(right_row.get("t_rls_yearmon") or right_row.get("sys_reg_dtime") or "").strip()
        if left_release and right_release and left_release != right_release:
            newer_name = left_name if left_release > right_release else right_name
            verdict = f"최신 상품은 {newer_name}입니다."
        else:
            verdict = f"{left_name}와 {right_name}의 출시 시점 차이는 추가 확인이 필요해요."
        assistant = _build_product_comparison_table(
            left_name,
            left_row,
            right_name,
            right_row,
            rows=(("출시 시점", "release"), ("상품 등급", "grade"), ("특징", "feature")),
            verdict=verdict,
        )
    elif sub_intent == "mileage_compare" or compare_metric == "mileage":
        summary = _compare_numeric_metric(
            left_name,
            _to_float(left_row.get("t_life_span") or left_row.get("t_milg_cvs")),
            right_name,
            _to_float(right_row.get("t_life_span") or right_row.get("t_milg_cvs")),
            higher_is_better=True,
            metric_label="마일리지/수명",
        )
        assistant = _build_product_comparison_table(
            left_name,
            left_row,
            right_name,
            right_row,
            rows=(("마일리지/수명", "mileage"), ("상품 등급", "grade"), ("리뷰", "review")),
            verdict=summary or f"{left_name}와 {right_name}의 마일리지/수명 차이는 추가 확인이 필요해요.",
        )
    elif compare_metric == "noise":
        summary = _compare_numeric_metric(
            left_name,
            _to_float(left_row.get("t_silence") or left_row.get("t_com_sil_avg")),
            right_name,
            _to_float(right_row.get("t_silence") or right_row.get("t_com_sil_avg")),
            higher_is_better=True,
            metric_label="정숙성",
        )
        assistant = _build_product_comparison_table(
            left_name,
            left_row,
            right_name,
            right_row,
            rows=(("정숙성", "noise"), ("상품 등급", "grade"), ("리뷰", "review")),
            verdict=summary or f"{left_name}와 {right_name}의 정숙성 차이는 추가 확인이 필요해요.",
        )
    elif compare_metric == "fuel_efficiency":
        summary = _compare_numeric_metric(
            left_name,
            _to_float(left_row.get("t_fuel_eff_convert")),
            right_name,
            _to_float(right_row.get("t_fuel_eff_convert")),
            higher_is_better=True,
            metric_label="연비",
        )
        assistant = _build_product_comparison_table(
            left_name,
            left_row,
            right_name,
            right_row,
            rows=(("연비/회전저항", "fuel_efficiency"), ("상품 등급", "grade"), ("리뷰", "review")),
            verdict=summary or f"{left_name}와 {right_name}의 연비 차이는 추가 확인이 필요해요.",
        )
    elif compare_metric == "wet":
        summary = _compare_numeric_metric(
            left_name,
            _to_float(left_row.get("wet")),
            right_name,
            _to_float(right_row.get("wet")),
            higher_is_better=True,
            metric_label="빗길 성능",
        )
        assistant = _build_product_comparison_table(
            left_name,
            left_row,
            right_name,
            right_row,
            rows=(("빗길 성능", "wet"), ("상품 등급", "grade"), ("리뷰", "review")),
            verdict=summary or f"{left_name}와 {right_name}의 빗길 성능 차이는 추가 확인이 필요해요.",
        )
    elif compare_metric == "price":
        left_final = _final_price_from_row(left_row)
        right_final = _final_price_from_row(right_row)
        if left_final is not None and right_final is not None and left_final != right_final:
            cheaper_name = left_name if left_final < right_final else right_name
            diff = abs(left_final - right_final)
            verdict = f"{cheaper_name}이 {diff:,}원 더 저렴해요."
        elif left_final is not None and right_final is not None:
            verdict = f"{left_name}와 {right_name}는 최종 가격이 동일해요."
        else:
            verdict = f"{left_name}와 {right_name}의 가격 차이는 추가 확인이 필요해요."
        assistant = _build_product_comparison_table(
            left_name,
            left_row,
            right_name,
            right_row,
            rows=(("최종 혜택가", "price"), ("상품 등급", "grade"), ("리뷰", "review")),
            verdict=verdict,
        )
    elif compare_metric == "car_type":
        left_car_type = str(left_row.get("car_knd_nm") or left_row.get("car_type") or "").strip() or "미확인"
        right_car_type = str(right_row.get("car_knd_nm") or right_row.get("car_type") or "").strip() or "미확인"
        if left_car_type == right_car_type:
            verdict = f"{left_name}와 {right_name}는 모두 {left_car_type} 기준 상품으로 확인돼요."
        else:
            verdict = f"{left_name}는 {left_car_type}, {right_name}는 {right_car_type} 기준 상품으로 확인돼요."
        assistant = _build_product_comparison_table(
            left_name,
            left_row,
            right_name,
            right_row,
            rows=(("차종", "car_type"), ("상품 등급", "grade"), ("특징", "feature")),
            verdict=verdict,
        )
    else:
        left_grade = str(left_row.get("prc_grd_nm") or "").strip() or "미확인"
        right_grade = str(right_row.get("prc_grd_nm") or "").strip() or "미확인"
        assistant = _build_product_comparison_table(
            left_name,
            left_row,
            right_name,
            right_row,
            rows=(("상품 등급", "grade"), ("특징", "feature"), ("리뷰", "review")),
            verdict=(
                f"{left_name}는 {left_grade}, {right_name}는 {right_grade} 등급으로 확인돼요. "
                f"비교하실 항목({_metric_label(compare_metric or 'grade')})을 더 구체적으로 알려주시면 이어서 정리해 드릴게요."
            ),
        )

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_product_compare_resolver",
        "data": {
            "assistantResponse": assistant,
            "quickReplies": [
                {"label": "구매하기", "domain": "TRANSACTION"},
                {"label": "다른 상품 비교", "domain": "DISCOVERY"},
                {"label": "내 차량 보기", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["DISCOVERY", "TRANSACTION"],
            "metadata": {
                "response_shape_key": (
                    "grade_comparison_summary"
                    if compare_metric in {"grade", "price_grade"}
                    else "metric_comparison_summary"
                ),
                "productNames": [left_name, right_name],
                "compareMetric": compare_metric or "detail",
                "compare_metric": compare_metric or "detail",
                "comparison_followup_intent": comparison_followup_intent or "none",
            },
        },
    }


def _build_product_comparison_event_from_search_results(
    user_text: str,
    search_results: list[tuple[str, dict]],
) -> dict | None:
    product_names = _product_comparison_names(user_text)
    if not product_names:
        return None
    if len(product_names) < 2 or not search_results:
        return None

    product_rows: list[tuple[str, dict | None]] = []
    remaining_results = list(search_results)
    for product_name in product_names[:2]:
        preferred_keyword = _preferred_product_search_keyword(product_name)
        target_terms = _coupon_product_match_keys(product_name) | _coupon_product_match_keys(preferred_keyword)
        best_idx = -1
        best_score = -1
        best_result: dict | None = None
        best_keyword = ""
        for idx, (keyword, result) in enumerate(remaining_results):
            keyword_terms = _coupon_product_match_keys(keyword)
            score = len(target_terms & keyword_terms)
            row = _pick_product_row_from_search_result(
                result,
                product_name,
                preferred_keyword,
                keyword,
                allow_first_row_fallback=score > 0,
            )
            if row is None:
                continue
            if score > best_score:
                best_idx = idx
                best_score = score
                best_result = result
                best_keyword = keyword
        if best_result is None:
            best_row = None
        else:
            if best_idx >= 0:
                remaining_results.pop(best_idx)
            best_row = _pick_product_row_from_search_result(
                best_result,
                product_name,
                preferred_keyword,
                best_keyword,
                allow_first_row_fallback=best_score > 0,
            )
        product_rows.append((product_name, best_row))

    if any(row is None for _, row in product_rows):
        return None
    if not _resolved_comparison_rows_are_distinct(product_rows):
        return None

    return _build_product_comparison_event(user_text, product_rows)


def _first_product_row_from_search_result(tool_result: dict) -> dict | None:
    data = _unwrap_tool_data(tool_result)
    rows = data.get("items") if isinstance(data, dict) else None
    if not isinstance(rows, list):
        return None
    return next((row for row in rows if isinstance(row, dict)), None)


def _build_external_price_comparison_event_from_search_results(
    user_text: str,
    search_results: list[tuple[str, dict]],
) -> dict | None:
    frame = build_discovery_intent_frame(user_text)
    if frame.sub_intent != "external_price_comparison_request":
        return None

    product_names = tuple(frame.entities.get("product_names") or ())
    row: dict | None = None
    if product_names:
        product_name = product_names[0]
        preferred_keyword = _preferred_product_search_keyword(product_name)
        for keyword, result in search_results:
            row = _pick_product_row_from_search_result(
                result,
                product_name,
                preferred_keyword,
                keyword,
                allow_first_row_fallback=True,
            )
            if row is not None:
                break
    else:
        for _keyword, result in search_results:
            row = _first_product_row_from_search_result(result)
            if row is not None:
                break

    lines = [
        "다나와/구글/네이버 같은 외부 사이트의 실시간 최저가를 제가 직접 수집하거나 비교할 수는 없어요.",
        "대신 T'Station 내부 판매가와 회원 쿠폰 기준 최저 혜택가는 확인해 드릴 수 있습니다.",
    ]
    if row is not None:
        canonical_row = canonical_context_from_tool_boundary(row)
        product_label = str(canonical_row.get("product_name") or "").strip()
        tire_size = str(canonical_row.get("tire_size") or row.get("tire_size_2") or frame.entities.get("tire_size") or "").strip()
        final_price = _final_price_from_row(row)
        sale_price = _to_int(row.get("sale_prc"))
        price_bits: list[str] = []
        if sale_price is not None:
            price_bits.append(f"정가 {sale_price:,}원")
        if final_price is not None:
            price_bits.append(f"내부 최저 혜택가 {final_price:,}원")
        target = product_label or (product_names[0] if product_names else "요청하신 상품")
        if tire_size:
            target = f"{target} {tire_size}"
        if price_bits:
            lines.extend(["", f"T'Station 기준으로는 {target}: {', '.join(price_bits)}까지 확인돼요."])
        else:
            lines.extend(["", f"T'Station 기준 상품은 {target}까지 확인됐고, 정확한 혜택가는 가격 확인 단계에서 안내드릴게요."])

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_external_price_comparison_policy",
        "data": {
            "assistantResponse": "\n".join(lines),
            "quickReplies": [
                {"label": "T'Station 가격 확인", "domain": "TRANSACTION"},
                {"label": "회원 쿠폰 적용가 보기", "domain": "TRANSACTION"},
                {"label": "다른 사이즈 확인", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["TRANSACTION", "DISCOVERY"],
        },
    }


def _external_price_search_results_from_sources(
    structured_sources: list[tuple[str, dict]],
) -> list[tuple[str, dict]]:
    results: list[tuple[str, dict]] = []
    for tool_name, result in structured_sources:
        if tool_name == "search_product_tool":
            results.append(("", result))
        elif tool_name == "get_product_description_tool":
            data = _unwrap_tool_data(result)
            if data:
                results.append(("", {"status": result.get("status", "success"), "data": {"items": [data]}}))
    return results


def _build_product_attribute_event_from_search_results(
    user_text: str,
    search_results: list[tuple[str, dict]],
) -> dict | None:
    if is_external_price_comparison_request(user_text):
        return None
    if _is_ev_suitability_turn(user_text):
        return None
    if is_warranty_claim_signal(user_text):
        return None
    frame = build_discovery_intent_frame(user_text)
    requested_product_attribute = _requested_product_attribute_from_context(user_text)
    decision = current_discovery_response_decision.get()
    decision_shape_key = str((decision.metadata or {}).get("response_shape_key") or "") if decision is not None else ""
    if frame.sub_intent != "product_attribute_lookup" and not (
        decision_shape_key == "product_attribute_summary" and requested_product_attribute
    ):
        return None
    product_names = tuple(frame.entities.get("product_names") or ())
    if not product_names or not search_results:
        return None

    product_name = product_names[0]
    preferred_keyword = _preferred_product_search_keyword(product_name)
    target_terms = _coupon_product_match_keys(product_name) | _coupon_product_match_keys(preferred_keyword)
    best_keyword = ""
    best_result: dict | None = None
    best_score = -1
    for keyword, result in search_results:
        row = _pick_product_row_from_search_result(result, product_name, preferred_keyword, keyword)
        score = len(target_terms & _coupon_product_match_keys(keyword))
        if row is None and score <= 0:
            continue
        if score > best_score:
            best_score = score
            best_keyword = keyword
            best_result = result

    if best_result is None:
        return None

    from services.tstation.template_mapper import (
        _DISCOVERY_POLICY_QUICKREPLY_CHIPS,
        _product_attribute_policy_response,
    )

    response = _product_attribute_policy_response([
        {"tool": "search_product_tool", "args": {"keyword": best_keyword or preferred_keyword}, "data": best_result}
    ])
    if not response:
        return None
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_product_attribute_resolver",
        "data": {
            "assistantResponse": response,
            "quickReplies": _DISCOVERY_POLICY_QUICKREPLY_CHIPS,
            "predictedDomains": ["DISCOVERY"],
            "metadata": {
                "response_shape_key": "product_attribute_summary",
                "requested_product_attribute": requested_product_attribute or str(
                    frame.entities.get("requested_product_attribute") or ""
                ),
            },
        },
    }


def _is_product_comparison_query(user_text: str) -> bool:
    return len(_product_comparison_names(user_text)) >= 2


def _should_skip_product_compare_override(user_text: str, called_tool_names: set[str]) -> bool:
    return _is_product_compare_context_reset_query(user_text) and (
        not called_tool_names or "get_products_recommendations_tool" in called_tool_names
    )


def _is_product_attribute_lookup_query(user_text: str) -> bool:
    if is_external_price_comparison_request(user_text):
        return False
    if _is_ev_suitability_turn(user_text):
        return False
    if is_warranty_claim_signal(user_text):
        return False
    frame = build_discovery_intent_frame(user_text)
    product_names = tuple(frame.entities.get("product_names") or ())
    if frame.sub_intent == "product_attribute_lookup" and bool(product_names):
        return True
    decision = current_discovery_response_decision.get()
    decision_shape_key = str((decision.metadata or {}).get("response_shape_key") or "") if decision is not None else ""
    return bool(product_names) and decision_shape_key == "product_attribute_summary" and bool(
        _requested_product_attribute_from_context(user_text)
    )


def _should_apply_product_attribute_resolver(user_text: str, called_tool_names: set[str]) -> bool:
    if "get_product_description_tool" in called_tool_names:
        return False
    return _is_product_attribute_lookup_query(user_text)


_BARE_PRODUCT_SEARCH_BLOCK_RE = re.compile(
    r"가격|얼마|재고|구매|주문|결제|장바구니|담아|담기|카트|장착|매장|근처|주변|할인|쿠폰|스마트\s*페이|스마트페이|"
    r"비교|보다|중에|뭐야|무슨|가능|어때|맞아|추천",
    re.IGNORECASE,
)
_BARE_PRODUCT_SEARCH_ALLOW_RE = re.compile(r"\b(search|find|show)\b|검색|찾아|보여|알려", re.IGNORECASE)
_SIZED_PRODUCT_SEARCH_SIZE_RE = re.compile(r"\b\d{3}\s*/?\s*\d{2}\s*R?\s*\d{2}\b", re.IGNORECASE)
_PRODUCT_QUERY_QUANTITY_RE = re.compile(r"\b(\d{1,2})\s*(?:개|본|짝)\b")
_SIZED_PRODUCT_KEYWORD_STOPWORDS = {"타이어", "상품", "제품", "검색", "찾아", "찾기", "보여", "알려", "추천"}
_FOLLOWUP_PRODUCT_REFERENCE_RE = re.compile(
    r"두\s*개\s*다|두개다|둘\s*다|둘다|둘\s*모두|세\s*개\s*다|세개다|셋\s*다|셋다|셋\s*모두|"
    r"두\s*상품|세\s*상품|위\s*상품들?|이\s*상품들?|각각",
    re.IGNORECASE,
)
_SIZED_PRODUCT_AVAILABILITY_HINT_RE = re.compile(
    r"사이즈|규격|있을까|있나요|있는지|있어|확인|될까|되나요",
    re.IGNORECASE,
)
_SIZED_PRODUCT_TRANSACTION_HINT_STOP_RE = re.compile(
    r"타이어|상품|제품|사이즈|규격|구매하고|구매|주문|결제|장착|장바구니|담|사려고|사려|사고|살래|"
    r"싶은데|싶|원해|주세요|해줘|할게|하고|가능|가격|재고|\d+\s*개",
    re.IGNORECASE,
)
_RECENT_PRODUCT_SIZE_AVAILABILITY_RE = re.compile(
    r"(?:사이즈|규격).*(?:있|가능|확인)|(?:있|가능|확인).*(?:사이즈|규격)|있을까|있나요|있어\??",
    re.IGNORECASE,
)
_STORE_AVAILABILITY_CONTINUATION_RE = re.compile(
    r"장착\s*가능|오늘|내일|예약|매장|지점|재고|스케줄|시간|방문",
    re.IGNORECASE,
)


def _fallback_sized_product_keyword(user_text: str) -> str:
    text = str(user_text or "").strip()
    if not normalize_tire_size(text):
        return ""
    keyword = _SIZED_PRODUCT_SEARCH_SIZE_RE.sub(" ", text)
    keyword = _FOLLOWUP_PRODUCT_REFERENCE_RE.sub(" ", keyword)
    keyword = _SIZED_PRODUCT_AVAILABILITY_HINT_RE.sub(" ", keyword)
    keyword = re.sub(r"\s+", " ", keyword).strip(" ,./")
    keyword_tokens = [tok for tok in re.findall(r"[0-9A-Za-z가-힣*+.-]+", keyword) if tok]
    meaningful_tokens = [tok for tok in keyword_tokens if tok not in _SIZED_PRODUCT_KEYWORD_STOPWORDS]
    if not meaningful_tokens:
        return ""
    if sum(len(tok) for tok in meaningful_tokens) < 2:
        return ""
    if all(tok.isdigit() for tok in meaningful_tokens):
        return ""
    return keyword


def _split_product_size_quantity_from_text(product_name: str | None, user_text: str | None = None) -> dict[str, Any]:
    """Split model, compact tire size and quantity when an upstream gate merged them."""
    product_text = str(product_name or "").strip()
    full_text = " ".join(part for part in (product_text, str(user_text or "").strip()) if part)
    tire_size = normalize_tire_size(full_text)
    quantity_match = _PRODUCT_QUERY_QUANTITY_RE.search(full_text)

    cleaned = product_text
    if cleaned:
        cleaned = _SIZED_PRODUCT_SEARCH_SIZE_RE.sub(" ", cleaned)
        cleaned = _PRODUCT_QUERY_QUANTITY_RE.sub(" ", cleaned)
        cleaned = re.sub(r"\s+", " ", cleaned).strip(" ,./")
    if not cleaned and user_text:
        fallback = _fallback_sized_product_keyword(str(user_text))
        cleaned = _SIZED_PRODUCT_TRANSACTION_HINT_STOP_RE.sub(" ", fallback)
        cleaned = re.sub(r"\s+", " ", cleaned).strip(" ,./")

    return {
        "product_name": cleaned or product_text,
        "tire_size": tire_size,
        "quantity": int(quantity_match.group(1)) if quantity_match else None,
    }


def _has_sized_product_name_hint(user_text: str) -> bool:
    """Return True when a sized transactional turn still contains product-name words.

    `_is_sized_product_name_search_query()` intentionally blocks transactional
    words such as "구매/주문" so bare search does not steal order flows. For stale
    slot clearing we need the opposite: detect that the current order turn names
    a new product even when it also says "구매".
    """
    keyword = _fallback_sized_product_keyword(user_text)
    if not keyword:
        return False
    keyword = _SIZED_PRODUCT_TRANSACTION_HINT_STOP_RE.sub(" ", keyword)
    keyword = re.sub(r"\s+", " ", keyword).strip(" ,./")
    tokens = [tok for tok in re.findall(r"[A-Za-z가-힣*+.-]+", keyword) if tok]
    if not tokens:
        return False
    return sum(len(tok) for tok in tokens) >= 2


def _is_bare_product_name_search_query(user_text: str) -> bool:
    text = str(user_text or "").strip()
    if not text:
        return False
    frame = build_discovery_intent_frame(text)
    product_names = tuple(frame.entities.get("product_names") or ())
    if not product_names or frame.intent != "product_search" or frame.sub_intent != "product_name_search":
        return False
    if _BARE_PRODUCT_SEARCH_BLOCK_RE.search(text):
        return False
    return len(text) <= 48 or bool(_BARE_PRODUCT_SEARCH_ALLOW_RE.search(text))


def _is_sized_product_name_search_query(user_text: str) -> bool:
    text = str(user_text or "").strip()
    if not text or _BARE_PRODUCT_SEARCH_BLOCK_RE.search(text):
        return False
    if _FOLLOWUP_PRODUCT_REFERENCE_RE.search(text):
        return False
    frame = build_discovery_intent_frame(text)
    product_names = tuple(frame.entities.get("product_names") or ())
    return bool((product_names or _fallback_sized_product_keyword(text)) and (frame.entities.get("tire_size") or normalize_tire_size(text)))


def _recent_product_listing_context(prev_tool_data: list[dict] | None = None) -> dict | None:
    PRODUCT_LIST_TOOLS = {"search_product_tool", "get_products_recommendations_tool"}
    for entry in prev_tool_data or []:
        tool_name = str(entry.get("tool") or "")
        if tool_name not in PRODUCT_LIST_TOOLS:
            continue
        rows = _search_product_rows_from_payload(entry.get("data"))
        if rows:
            return {"tool": tool_name, "rows": rows}
    return None


def _recent_product_names_from_template_metadata(template_data: dict | None) -> tuple[str, ...]:
    if not isinstance(template_data, dict):
        return ()
    data = template_data.get("data") if isinstance(template_data.get("data"), dict) else template_data
    metadata = data.get("metadata") if isinstance(data, dict) else None
    if not isinstance(metadata, dict):
        return ()
    names = metadata.get("productNames") or metadata.get("pendingProductNames")
    if not isinstance(names, list):
        return ()
    parsed: list[str] = []
    for name in names:
        normalized = str(name or "").strip()
        if not normalized or normalized in parsed:
            continue
        parsed.append(normalized)
    return tuple(parsed)


_ASSISTANT_PRODUCT_BULLET_RE = re.compile(r"^\s*[-*]\s*([^:\n]+?)\s*:\s*", re.MULTILINE)


def _recent_product_names_from_assistant_text(content: str) -> tuple[str, ...]:
    text = str(content or "").strip()
    if not text:
        return ()
    parsed: list[str] = []
    for match in _ASSISTANT_PRODUCT_BULLET_RE.finditer(text):
        candidate = str(match.group(1) or "").strip()
        if not candidate:
            continue
        if candidate in parsed:
            continue
        parsed.append(candidate)
    return tuple(parsed)


def _recent_product_listing_context_from_messages(
    messages: list[dict],
    *,
    latest_quickreply_tmpl: dict | None = None,
) -> dict | None:
    template_names = _recent_product_names_from_template_metadata(latest_quickreply_tmpl)
    if len(template_names) >= 2:
        return {"tool": "assistant_template_metadata", "rows": [], "product_names": list(template_names)}

    if isinstance(latest_quickreply_tmpl, dict):
        data = latest_quickreply_tmpl.get("data") if isinstance(latest_quickreply_tmpl.get("data"), dict) else latest_quickreply_tmpl
        assistant = str(data.get("assistantResponse") or "") if isinstance(data, dict) else ""
        text_names = _recent_product_names_from_assistant_text(assistant)
        if len(text_names) >= 2:
            return {"tool": "assistant_quickreply_text", "rows": [], "product_names": list(text_names)}

    for message in reversed(messages[:-1]):
        if str(message.get("role") or "") != "assistant":
            continue
        template_data = message.get("template_data")
        template_names = _recent_product_names_from_template_metadata(template_data)
        if len(template_names) >= 2:
            return {"tool": "assistant_template_metadata", "rows": [], "product_names": list(template_names)}
        text_names = _recent_product_names_from_assistant_text(str(message.get("content") or ""))
        if len(text_names) >= 2:
            return {"tool": "assistant_quickreply_text", "rows": [], "product_names": list(text_names)}
    return None


def _is_recent_product_size_availability_query(user_text: str) -> bool:
    text = str(user_text or "").strip()
    if not text:
        return False
    if not normalize_tire_size(text):
        return False
    if not _RECENT_PRODUCT_SIZE_AVAILABILITY_RE.search(text):
        return False
    frame = build_discovery_intent_frame(text)
    if tuple(frame.entities.get("product_names") or ()):
        return False
    return not _fallback_sized_product_keyword(text)


def _build_recent_product_size_availability_missing_context_event(target_size: str | None) -> dict:
    size_text = target_size or "원하시는 규격"
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_recent_product_size_availability_prompt",
        "data": {
            "assistantResponse": (
                f"{size_text} 기준으로 확인할 상품이 아직 정해지지 않았어요. "
                "어떤 상품들 기준인지 알려주시면 규격 보유 여부를 바로 확인해드릴게요."
            ),
            "quickReplies": [
                {"label": "추천 상품 다시 보기", "domain": "DISCOVERY"},
                {"label": "상품명 입력", "domain": "DISCOVERY"},
                {"label": "타이어 추천 받기", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["DISCOVERY"],
            "metadata": {
                "source": "recent_product_listing_missing_context",
                "tireSize": target_size,
            },
        },
    }


def _recent_product_set_size_availability_context(
    user_text: str,
    *,
    prev_tool_data: list[dict] | None = None,
    routing_result: Any | None = None,
    messages: list[dict] | None = None,
    latest_quickreply_tmpl: dict | None = None,
) -> dict | None:
    followup_intent = str(getattr(routing_result, "discovery_followup_intent", "") or "").strip()
    llm_marked_followup = followup_intent == "recent_product_set_size_availability"
    if not llm_marked_followup and not _is_recent_product_size_availability_query(user_text):
        return None

    listing_context = _recent_product_listing_context(prev_tool_data)
    if not listing_context:
        listing_context = _recent_product_listing_context_from_messages(
            messages or [],
            latest_quickreply_tmpl=latest_quickreply_tmpl,
        )
    if not listing_context:
        return None

    fallback_keyword = _fallback_sized_product_keyword(user_text)
    if fallback_keyword:
        return None

    product_names: list[str] = list(listing_context.get("product_names") or [])
    if not product_names:
        for row in listing_context["rows"]:
            product_name = str(canonical_context_from_tool_boundary(row).get("product_name") or "").strip()
            if not product_name or product_name in product_names:
                continue
            product_names.append(product_name)

    if len(product_names) < 2:
        return None

    return {
        "tool": listing_context["tool"],
        "rows": listing_context["rows"],
        "tire_size": normalize_tire_size(user_text),
        "product_names": product_names,
        "has_reference_signal": bool(_FOLLOWUP_PRODUCT_REFERENCE_RE.search(user_text)),
        "llm_marked_followup": llm_marked_followup,
    }


def _build_recent_product_size_availability_event(
    target_size: str,
    product_names: list[str],
    available_names: list[str],
    missing_names: list[str],
    *,
    source_tool: str | None = None,
) -> dict | None:
    if not target_size or len(product_names) < 2:
        return None
    if not available_names and not missing_names:
        return None

    lines = [f"직전 추천 상품 기준으로 {target_size} 규격을 확인했어요."]
    if available_names:
        lines.append(f"{', '.join(available_names)}는 확인돼요.")
    if missing_names:
        lines.append(f"{', '.join(missing_names)}는 해당 규격을 찾지 못했어요.")

    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_recent_product_size_availability",
        "data": {
            "assistantResponse": " ".join(lines),
            "quickReplies": [
                {"label": "다른 사이즈 확인", "domain": "DISCOVERY"},
                {"label": "가격 조회", "domain": "DISCOVERY"},
                {"label": "타이어 추천 받기", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["DISCOVERY"],
            "metadata": {
                "source": "recent_product_listing",
                "sourceTool": source_tool,
                "tireSize": target_size,
                "productNames": product_names,
                "availableProductNames": available_names,
                "missingProductNames": missing_names,
            },
        },
    }


def _build_recent_product_size_availability_event_from_rows(
    user_text: str,
    *,
    prev_tool_data: list[dict] | None = None,
    messages: list[dict] | None = None,
    latest_quickreply_tmpl: dict | None = None,
) -> dict | None:
    context = _recent_product_set_size_availability_context(
        user_text,
        prev_tool_data=prev_tool_data,
        messages=messages,
        latest_quickreply_tmpl=latest_quickreply_tmpl,
    )
    if not context:
        return None
    if not context["rows"]:
        return None

    size_map: dict[str, set[str]] = {}
    for row in context["rows"]:
        canonical_row = canonical_context_from_tool_boundary(row)
        product_name = str(canonical_row.get("product_name") or "").strip()
        if not product_name:
            continue
        tire_size = normalize_tire_size(str(canonical_row.get("tire_size") or ""))
        size_map.setdefault(product_name, set())
        if tire_size:
            size_map[product_name].add(tire_size)

    available_names = [name for name in context["product_names"] if context["tire_size"] in size_map.get(name, set())]
    missing_names = [name for name in context["product_names"] if context["tire_size"] not in size_map.get(name, set())]
    return _build_recent_product_size_availability_event(
        context["tire_size"],
        context["product_names"],
        available_names,
        missing_names,
        source_tool=context["tool"],
    )


def _build_bare_product_search_tool_input(user_text: str) -> dict | None:
    frame = build_discovery_intent_frame(user_text)
    product_names = tuple(frame.entities.get("product_names") or ())
    fallback_keyword = _fallback_sized_product_keyword(user_text)
    if not product_names and not fallback_keyword:
        return None

    product_name = product_names[0] if product_names else fallback_keyword
    preferred_keyword = _preferred_product_search_keyword(product_name)
    tool_input = {"keyword": preferred_keyword, "limit": 10}
    tire_size = frame.entities.get("tire_size") or normalize_tire_size(user_text)
    if tire_size:
        tool_input["size"] = tire_size
    if frame.entities.get("brand_cd"):
        tool_input["brand_cd"] = frame.entities["brand_cd"]
    return tool_input


def _recent_context_product_keyword_for_size_only_search(user_text: str, recent_context: str) -> str | None:
    current_size = normalize_tire_size(user_text)
    if not current_size:
        return None
    for line in reversed([part.strip() for part in str(recent_context or "").splitlines() if part.strip()]):
        if normalize_tire_size(line) == current_size and not _fallback_sized_product_keyword(line):
            continue
        frame = build_discovery_intent_frame(line)
        product_names = tuple(frame.entities.get("product_names") or ())
        if product_names:
            return _preferred_product_search_keyword(str(product_names[0]))
        coupon_product = _coupon_target_product_name_for_query(line)
        if coupon_product:
            return _preferred_product_search_keyword(coupon_product)
    return None


def _recent_product_keyword_for_size_only_search(
    user_text: str,
    *,
    prev_tool_data: list[dict] | None = None,
    recent_context: str = "",
    slots: Any | None = None,
) -> str | None:
    if not normalize_tire_size(user_text):
        return None
    if _fallback_sized_product_keyword(user_text):
        return None

    canonical_slots = canonical_context_from_slots(slots)
    slot_product_name = str(canonical_slots.get("product_name") or "").strip()
    if slot_product_name:
        return _preferred_product_search_keyword(slot_product_name)

    for entry in reversed(prev_tool_data or []):
        if entry.get("tool") != "search_product_tool":
            continue
        tool_input = entry.get("input") if isinstance(entry.get("input"), dict) else entry.get("args")
        if isinstance(tool_input, dict):
            keyword = str(tool_input.get("keyword") or "").strip()
            if keyword:
                return _preferred_product_search_keyword(keyword)
        data = _unwrap_tool_data(entry.get("data"))
        rows = data.get("items") if isinstance(data, dict) else None
        if isinstance(rows, list):
            for row in rows:
                if not isinstance(row, dict):
                    continue
                row_name = str(canonical_context_from_tool_boundary(row).get("product_name") or "").strip()
                if row_name:
                    return _preferred_product_search_keyword(row_name)

    if _STORE_AVAILABILITY_CONTINUATION_RE.search(str(recent_context or "")):
        context_keyword = _recent_context_product_keyword_for_size_only_search(user_text, recent_context)
        if context_keyword:
            return context_keyword

    return _recent_context_product_keyword_for_size_only_search(user_text, recent_context)


def _build_size_only_product_search_tool_input(
    user_text: str,
    *,
    prev_tool_data: list[dict] | None = None,
    recent_context: str = "",
    slots: Any | None = None,
) -> dict | None:
    tire_size = normalize_tire_size(user_text)
    if not tire_size:
        return None
    keyword = _recent_product_keyword_for_size_only_search(
        user_text,
        prev_tool_data=prev_tool_data,
        recent_context=recent_context,
        slots=slots,
    )
    if not keyword:
        return None
    return {"keyword": keyword, "limit": 10, "size": tire_size}


_PRODUCT_SIZE_LIST_INTENT_RE = re.compile(
    r"(?:다른|가능한|어떤)\s*(?:사이즈|규격)"
    r"|(?:사이즈|규격)\s*(?:목록|리스트|보기|보여|알려|있어|있나요|뭐)",
    re.IGNORECASE,
)


def _is_product_size_list_intent(user_text: str) -> bool:
    text = str(user_text or "").strip()
    if not text:
        return False
    return bool(_PRODUCT_SIZE_LIST_INTENT_RE.search(text))


def _search_product_rows_from_payload(payload: Any) -> list[dict]:
    candidates: list[Any] = [payload]
    if isinstance(payload, dict):
        data = payload.get("data")
        candidates.append(data)
        if isinstance(data, dict):
            nested = data.get("data")
            candidates.append(nested)

    for candidate in candidates:
        if isinstance(candidate, list):
            return [row for row in candidate if isinstance(row, dict) and not row.get("_truncated")]
        if not isinstance(candidate, dict):
            continue
        for key in ("items", "products", "data"):
            value = candidate.get(key)
            if isinstance(value, list):
                return [row for row in value if isinstance(row, dict) and not row.get("_truncated")]
            if isinstance(value, dict) and isinstance(value.get("items"), list):
                return [row for row in value["items"] if isinstance(row, dict) and not row.get("_truncated")]
    return []


def _product_size_list_keyword_from_context(
    user_text: str,
    search_results: list[tuple[str, dict]] | None = None,
    *,
    prev_tool_data: list[dict] | None = None,
    recent_context: str = "",
    slots: Any | None = None,
) -> str | None:
    frame = build_discovery_intent_frame(user_text)
    product_names = tuple(frame.entities.get("product_names") or ())
    if product_names:
        return _preferred_product_search_keyword(str(product_names[0]))

    canonical_slots = canonical_context_from_slots(slots)
    slot_product_name = str(canonical_slots.get("product_name") or "").strip()
    if slot_product_name:
        return _preferred_product_search_keyword(slot_product_name)

    for keyword, _result in reversed(search_results or []):
        keyword = str(keyword or "").strip()
        if keyword:
            return _preferred_product_search_keyword(keyword)

    for entry in reversed(prev_tool_data or []):
        if entry.get("tool") != "search_product_tool":
            continue
        tool_input = entry.get("input") if isinstance(entry.get("input"), dict) else entry.get("args")
        if isinstance(tool_input, dict):
            keyword = str(tool_input.get("keyword") or "").strip()
            if keyword:
                return _preferred_product_search_keyword(keyword)

    for line in reversed([part.strip() for part in str(recent_context or "").splitlines() if part.strip()]):
        frame = build_discovery_intent_frame(line)
        product_names = tuple(frame.entities.get("product_names") or ())
        if product_names:
            return _preferred_product_search_keyword(str(product_names[0]))
    return None


def _product_size_list_row_matches_keyword(row: dict, keyword: str | None) -> bool:
    if not keyword:
        return True
    row_name = str(canonical_context_from_tool_boundary(row).get("product_name") or "")
    if not row_name:
        return False
    return _is_strong_product_name_match(keyword, row_name)


def _build_product_size_list_not_found_event(product_name: str) -> dict:
    product_label = str(product_name or "해당 상품").strip() or "해당 상품"
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_product_size_list_not_found",
        "data": {
            "assistantResponse": (
                f"{product_label}의 다른 규격을 현재 찾을 수 없어요.\n"
                "제품명을 다시 확인하거나 다른 모델명으로 검색해 주세요."
            ),
            "quickReplies": [
                {"label": "상품명 다시 입력", "domain": "DISCOVERY"},
                {"label": "타이어 추천 받기", "domain": "DISCOVERY"},
                {"label": "사이즈 직접 입력", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["DISCOVERY"],
            "metadata": {"productName": product_label},
        },
    }


def _build_product_size_list_event_from_search_results(
    user_text: str,
    search_results: list[tuple[str, dict]] | None = None,
    *,
    prev_tool_data: list[dict] | None = None,
    recent_context: str = "",
    slots: Any | None = None,
) -> dict | None:
    if not _is_product_size_list_intent(user_text):
        return None

    keyword = _product_size_list_keyword_from_context(
        user_text,
        search_results,
        prev_tool_data=prev_tool_data,
        recent_context=recent_context,
        slots=slots,
    )
    rows: list[dict] = []
    for _keyword, result in reversed(search_results or []):
        rows.extend(_search_product_rows_from_payload(result))
    for entry in reversed(prev_tool_data or []):
        if entry.get("tool") != "search_product_tool":
            continue
        rows.extend(_search_product_rows_from_payload(entry.get("data")))

    if keyword:
        matched_rows = [row for row in rows if _product_size_list_row_matches_keyword(row, keyword)]
        if matched_rows:
            rows = matched_rows
        elif rows:
            return None

    sizes: list[str] = []
    seen_sizes: set[str] = set()
    first_product_name = ""
    for row in rows:
        canonical_row = canonical_context_from_tool_boundary(row)
        if not first_product_name:
            first_product_name = str(canonical_row.get("product_name") or "").strip()
        tire_size = normalize_tire_size(str(canonical_row.get("tire_size") or ""))
        if not tire_size:
            tire_size = normalize_tire_size(str(row.get("tire_size_2") or ""))
        if not tire_size:
            continue
        compact_size = re.sub(r"[^0-9]", "", tire_size)
        if compact_size in seen_sizes:
            continue
        seen_sizes.add(compact_size)
        sizes.append(tire_size)

    if not sizes:
        return None

    product_label = keyword or first_product_name or "해당 상품"
    visible_sizes = sizes[:8]
    suffix = " 등" if len(sizes) > len(visible_sizes) else ""
    if _is_coupon_discount_amount_context(slots):
        assistant_response = (
            f"{product_label} 쿠폰 할인금액 확인을 위해 선택 가능한 규격을 확인했어요.\n"
            f"확인되는 규격은 {', '.join(visible_sizes)}{suffix}입니다. "
            "원하시는 규격을 선택하면 쿠폰 적용 예상 할인액을 이어서 계산해 드릴게요."
        )
    else:
        assistant_response = (
            f"{product_label}에서 확인되는 규격은 {', '.join(visible_sizes)}{suffix}이에요.\n"
            "원하시는 규격을 선택하거나 사이즈를 직접 입력해 주세요."
        )
    quick_replies = [{"label": size, "domain": "DISCOVERY"} for size in sizes[:6]]
    quick_replies.append({"label": "사이즈 직접 입력", "domain": "DISCOVERY"})
    metadata: dict[str, Any] = {
        "productName": product_label,
        "sizes": sizes,
    }
    if _is_coupon_discount_amount_context(slots):
        metadata["pendingIntent"] = "price"
        metadata["goalType"] = "coupon_discount_amount"
        for source_key, metadata_key in (
            ("pending_product_name", "productName"),
            ("ord_qty", "ordQty"),
            ("quantity", "quantity"),
        ):
            value = _slot_value(slots, source_key)
            if value not in (None, ""):
                metadata[metadata_key] = value
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_product_size_list",
        "data": {
            "assistantResponse": assistant_response,
            "quickReplies": quick_replies,
            "predictedDomains": ["DISCOVERY"],
            "metadata": metadata,
        },
    }


def _transactional_pending_intent_from_slots(slots: Any | None) -> str | None:
    if slots is None:
        return None
    if isinstance(slots, Mapping):
        pending_intent = str(slots.get("pending_intent") or "").strip()
        goal_type = str(slots.get("goal_type") or "").strip()
    else:
        pending_intent = str(getattr(slots, "pending_intent", None) or "").strip()
        goal_type = str(getattr(slots, "goal_type", None) or "").strip()
    if pending_intent in {"order", "price", "stock"}:
        return pending_intent
    return {
        "place_order": "order",
        "price_inquiry": "price",
        "coupon_discount_amount": "price",
        "product_coupon_discount_amount": "price",
        "store_with_stock": "stock",
    }.get(goal_type)


def _slot_value(slots: Any | None, key: str) -> Any:
    if slots is None:
        return None
    if isinstance(slots, Mapping):
        return slots.get(key)
    return getattr(slots, key, None)


def _transactional_resolution_action_label(intent: str | None, slots: Any | None = None) -> str:
    normalized_intent = str(intent or "").strip()
    if normalized_intent == "order":
        availability_intent = str(_slot_value(slots, "availability_intent") or "").strip()
        if availability_intent == "today_install" or _slot_value(slots, "requested_cal_day"):
            return "오늘서비스 구매"
        return "구매"
    if normalized_intent == "price" and _is_coupon_discount_amount_context(slots):
        return "쿠폰 할인금액 확인"
    return {
        "price": "가격 확인",
        "stock": "재고 확인",
    }.get(normalized_intent, "확인")


def _build_transaction_unresolved_product_not_found_event(
    product_name: str,
    *,
    pending_intent: str | None,
) -> dict[str, Any]:
    product_label = str(product_name or "해당 상품").strip() or "해당 상품"
    action_label = _transactional_resolution_action_label(pending_intent)
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_transaction_product_resolution_not_found",
        "data": {
            "assistantResponse": (
                f"{product_label} 상품을 찾지 못해 {action_label} 흐름을 이어서 진행하지 못했어요.\n"
                "정확한 상품명이나 규격을 알려주시면 다시 확인해드릴게요."
            ),
            "quickReplies": [
                {"label": "상품명 다시 입력", "domain": "DISCOVERY"},
                {"label": "사이즈 직접 입력", "domain": "DISCOVERY"},
                {"label": "타이어 추천", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["TRANSACTION", "DISCOVERY"],
            "metadata": {
                "productName": product_label,
                "pendingIntent": pending_intent,
            },
        },
    }


def _build_transaction_unresolved_product_size_clarification_event(
    product_name: str,
    sizes: list[str],
    *,
    pending_intent: str | None,
    slots: Any | None = None,
) -> dict[str, Any]:
    product_label = str(product_name or "해당 상품").strip() or "해당 상품"
    action_label = _transactional_resolution_action_label(pending_intent, slots)
    visible_sizes = sizes[:8]
    suffix = " 등" if len(sizes) > len(visible_sizes) else ""
    assistant_response = (
        f"{product_label} {action_label}를 진행하려면 타이어 사이즈를 선택해 주세요.\n"
        f"현재 확인되는 규격은 {', '.join(visible_sizes)}{suffix}예요."
    )
    quick_replies = [{"label": size, "domain": "DISCOVERY"} for size in sizes[:6]]
    quick_replies.append({"label": "사이즈 직접 입력", "domain": "DISCOVERY"})
    metadata = {
        "productName": product_label,
        "sizes": sizes,
        "pendingIntent": pending_intent,
    }
    for source_key, metadata_key in (
        ("ord_qty", "ordQty"),
        ("quantity", "quantity"),
        ("shop_name", "shopName"),
        ("store_name", "storeName"),
        ("requested_cal_day", "requestedCalDay"),
        ("availability_intent", "availabilityIntent"),
        ("goal_type", "goalType"),
    ):
        value = _slot_value(slots, source_key)
        if value not in (None, ""):
            metadata[metadata_key] = value
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_transaction_product_resolution_size_clarification",
        "data": {
            "assistantResponse": assistant_response,
            "quickReplies": quick_replies,
            "predictedDomains": ["TRANSACTION", "DISCOVERY"],
            "metadata": metadata,
        },
    }


def _search_result_size_candidates(rows: list[dict]) -> list[str]:
    sizes: list[str] = []
    seen_sizes: set[str] = set()
    for row in rows:
        canonical_row = canonical_context_from_tool_boundary(row)
        tire_size = normalize_tire_size(str(canonical_row.get("tire_size") or ""))
        if not tire_size:
            tire_size = normalize_tire_size(str(row.get("tire_size_2") or ""))
        if not tire_size:
            continue
        compact_size = re.sub(r"[^0-9]", "", tire_size)
        if compact_size in seen_sizes:
            continue
        seen_sizes.add(compact_size)
        sizes.append(tire_size)
    return sizes


def _search_result_rows_for_product(rows: list[dict], product_name: str) -> list[dict]:
    product_label = str(product_name or "").strip()
    if not product_label:
        return rows
    target_names = set(extract_product_names(product_label))
    matched_rows: list[dict] = []
    for row in rows:
        row_name = str(canonical_context_from_tool_boundary(row).get("product_name") or "").strip()
        if not row_name:
            matched_rows.append(row)
            continue
        row_names = set(extract_product_names(row_name))
        if (target_names and row_names and target_names & row_names) or _is_strong_product_name_match(
            product_label,
            row_name,
        ):
            matched_rows.append(row)
    return matched_rows


def _build_transaction_unresolved_product_resolution_event(
    *,
    user_text: str,
    slots: Any | None,
    tool_data_list: list[dict] | None = None,
) -> dict[str, Any] | None:
    pending_intent = _transactional_pending_intent_from_slots(slots)
    if pending_intent not in {"order", "price", "stock"}:
        return None
    slot_goods_no = slots.get("goods_no") if isinstance(slots, Mapping) else getattr(slots, "goods_no", None)
    slot_tire_size = slots.get("tire_size") if isinstance(slots, Mapping) else getattr(slots, "tire_size", None)
    slot_tire_model = slots.get("tire_model") if isinstance(slots, Mapping) else getattr(slots, "tire_model", None)
    slot_pending_product_name = (
        slots.get("pending_product_name") if isinstance(slots, Mapping) else getattr(slots, "pending_product_name", None)
    )
    if slots is None or slot_goods_no is not None:
        return None
    if normalize_tire_size(user_text or "") or slot_tire_size:
        return None

    last_search_entry: dict[str, Any] | None = None
    for entry in reversed(tool_data_list or []):
        if entry.get("tool") == "search_product_tool":
            last_search_entry = entry
            break
    if last_search_entry is None:
        return None

    search_input = last_search_entry.get("input") if isinstance(last_search_entry.get("input"), dict) else last_search_entry.get("args")
    if not isinstance(search_input, dict):
        search_input = {}
    if search_input.get("size"):
        return None

    product_name = str(
        slot_tire_model
        or slot_pending_product_name
        or search_input.get("keyword")
        or ""
    ).strip()
    if not product_name:
        return None

    rows = _search_product_rows_from_payload(last_search_entry.get("data"))
    if not rows:
        return _build_transaction_unresolved_product_not_found_event(
            product_name,
            pending_intent=pending_intent,
        )

    matched_rows = _search_result_rows_for_product(rows, product_name)
    if rows and not matched_rows:
        return _build_transaction_unresolved_product_not_found_event(
            product_name,
            pending_intent=pending_intent,
        )

    sizes = _search_result_size_candidates(matched_rows)
    if sizes:
        return _build_transaction_unresolved_product_size_clarification_event(
            product_name,
            sizes,
            pending_intent=pending_intent,
            slots=slots,
        )

    return _build_transaction_unresolved_product_not_found_event(
        product_name,
        pending_intent=pending_intent,
    )


def _is_compare_contract_for_no_output(contract: TurnContract | None) -> bool:
    if contract is None:
        return False
    if str(contract.intent or "") == "product_comparison":
        return True
    response_decision = contract.response_decision or {}
    response_shape_key = str(response_decision.get("metadata", {}).get("response_shape_key") or "")
    return response_shape_key in {"metric_comparison_summary", "grade_comparison_summary"}


def _search_results_from_structured_sources(
    structured_sources: list[tuple[str, dict]],
) -> list[tuple[str, dict]]:
    results: list[tuple[str, dict]] = []
    for tool_name, tool_output in structured_sources:
        if tool_name != "search_product_tool" or not isinstance(tool_output, dict):
            continue
        rows = _search_product_rows_from_payload(tool_output)
        if not rows:
            continue
        keyword = ""
        first_row = rows[0]
        if isinstance(first_row, dict):
            keyword = str(canonical_context_from_tool_boundary(first_row).get("product_name") or "").strip()
        results.append((keyword, tool_output))
    return results


def _build_no_visible_output_fallback_event(
    *,
    user_text: str,
    turn_contract: TurnContract | None,
    structured_sources: list[tuple[str, dict]],
    tool_data_list: list[dict] | None = None,
    called_tool_names: set[str],
    source_domain: str,
) -> dict[str, Any] | None:
    if _is_compare_contract_for_no_output(turn_contract):
        compare_event = _build_product_comparison_event_from_search_results(
            user_text,
            _search_results_from_structured_sources(structured_sources),
        )
        if compare_event is not None:
            return compare_event

    unresolved_event = (
        _build_transaction_unresolved_product_resolution_event(
            user_text=user_text,
            slots=None if turn_contract is None else turn_contract.known_slots,
            tool_data_list=tool_data_list
            if tool_data_list is not None
            else [
                {"tool": tool_name, "data": data}
                for tool_name, data in structured_sources
            ],
        )
        if called_tool_names
        and turn_contract is not None
        and turn_contract.action_mode in {"unspecified", "purchase_continuation", "stock_check"}
        else None
    )
    if unresolved_event is not None:
        return unresolved_event

    repaired_description_event = _build_repaired_product_description_event(
        structured_sources=structured_sources,
        called_tool_names=called_tool_names,
        source_domain=source_domain,
        user_text=user_text,
    )
    if repaired_description_event is not None:
        return repaired_description_event

    return None


def _build_turn_contract_required_slot_guard_event(
    *,
    turn_contract: TurnContract | None,
    user_text: str,
    tool_data_list: list[dict] | None = None,
) -> dict[str, Any] | None:
    if turn_contract is None:
        return None
    if turn_contract.action_mode not in {"unspecified", "purchase_continuation", "stock_check"}:
        return build_required_slot_clarification_event(turn_contract)
    unresolved_event = _build_transaction_unresolved_product_resolution_event(
        user_text=user_text,
        slots=turn_contract.known_slots,
        tool_data_list=tool_data_list,
    )
    if unresolved_event is not None:
        return unresolved_event
    return build_required_slot_clarification_event(turn_contract)


def _build_turn_contract_fallback_event(
    *,
    turn_contract: TurnContract | None,
    user_text: str,
    tool_data_list: list[dict] | None = None,
) -> dict[str, Any] | None:
    if turn_contract is None:
        return None
    if turn_contract.action_mode not in {"unspecified", "purchase_continuation", "stock_check"}:
        if should_guard_required_slots(turn_contract):
            return build_required_slot_clarification_event(turn_contract)
        return build_response_policy_guard_event(turn_contract)
    unresolved_event = _build_transaction_unresolved_product_resolution_event(
        user_text=user_text,
        slots=turn_contract.known_slots,
        tool_data_list=tool_data_list,
    )
    if unresolved_event is not None:
        return unresolved_event
    if should_guard_required_slots(turn_contract):
        return build_required_slot_clarification_event(turn_contract)
    return build_response_policy_guard_event(turn_contract)


def _build_recommendation_contract_fallback_event(
    violations: list[dict[str, Any]] | tuple[dict[str, Any], ...],
    turn_contract: TurnContract | None,
) -> dict[str, Any] | None:
    violation_types = {str(violation.get("type") or "") for violation in violations}
    if not (
        "recommendation_tool_input_drift" in violation_types
        or "claim_unsupported_scenario_as_exact" in violation_types
    ):
        return None
    known_slots = turn_contract.known_slots if turn_contract is not None else {}
    tire_size = str(known_slots.get("tire_size") or "").strip()
    scenario = str(known_slots.get("recommendation_scenario") or "").strip()
    if "claim_unsupported_scenario_as_exact" in violation_types and scenario == "offroad":
        assistant = (
            "오프로드 전용 상품으로 단정할 수는 없어요. "
            "SUV/하중 안정성 기준으로 근사 추천을 다시 확인할 수 있게 조건을 선택해 주세요."
        )
    else:
        assistant = "추천 조건과 실제 조회 조건이 맞지 않아 조건을 다시 선택해 주세요."
    if tire_size:
        assistant += f" 현재 확인된 사이즈는 {tire_size}입니다."
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
        "assistant_response_source": "code_recommendation_contract_guard",
        "data": {
            "assistantResponse": assistant,
            "quickReplies": [
                {"label": "추천 조건 다시 선택", "domain": "DISCOVERY"},
                {"label": "사이즈 직접 입력", "domain": "DISCOVERY"},
                {"label": "내 차량 보기", "domain": "DISCOVERY"},
            ],
            "predictedDomains": ["DISCOVERY"],
            "metadata": {
                "response_shape_key": "recommendation_contract_guard",
                "violation_types": sorted(violation_types),
            },
        },
    }


def _is_size_only_store_availability_continuation(
    user_text: str,
    *,
    prev_tool_data: list[dict] | None = None,
    recent_context: str = "",
    messages: list[dict] | None = None,
    slots: Any | None = None,
) -> bool:
    if not _SIZE_ONLY_RE.match(str(user_text or "")):
        return False
    if not _build_size_only_product_search_tool_input(
        user_text,
        prev_tool_data=prev_tool_data,
        recent_context=recent_context,
        slots=slots,
    ):
        return False
    context_parts = [recent_context]
    for message in reversed((messages or [])[-8:]):
        content = str(message.get("content") or "")
        template_data = message.get("template_data")
        if isinstance(template_data, dict):
            content += " " + json.dumps(template_data, ensure_ascii=False)
        context_parts.append(content)
    context_blob = "\n".join(part for part in context_parts if part)
    return bool(_STORE_AVAILABILITY_CONTINUATION_RE.search(context_blob))


_INVALID_STORE_SLOT_VALUES = frozenset({"평점", "별점", "리뷰", "후기", "평가"})


def _is_invalid_store_slot_value(value: str | None) -> bool:
    normalized = re.sub(r"\s+", "", str(value or "")).strip().lower()
    normalized = re.sub(r"^(?:티스테이션|더타이어샵|t'?station)", "", normalized, flags=re.IGNORECASE)
    return normalized in _INVALID_STORE_SLOT_VALUES


def _clear_invalid_store_identity_slots(slots: ConversationSlots, *, source: str) -> dict[str, Any]:
    shop_name = str(getattr(slots, "shop_name", None) or "").strip()
    if not _is_invalid_store_slot_value(shop_name):
        return {}
    cleared = {"shop_name": shop_name, "source": source}
    slots.shop_name = None
    if getattr(slots, "shop_id", None) and source != "slot_sanitizer_keep_shop_id":
        cleared["shop_id"] = slots.shop_id
        slots.shop_id = None
    context = dict(getattr(slots, "availability_context", None) or {})
    pending_context = context.get("pending_order_context")
    if isinstance(pending_context, dict) and _is_invalid_store_slot_value(str(pending_context.get("shop_name") or "")):
        pending_context = dict(pending_context)
        pending_context.pop("shop_name", None)
        context["pending_order_context"] = pending_context
        slots.availability_context = context
        cleared["pending_order_context_shop_name"] = shop_name
    return cleared


def _recent_store_name_for_availability_continuation(
    *,
    prev_tool_data: list[dict] | None = None,
    recent_context: str = "",
    messages: list[dict] | None = None,
    slots: Any | None = None,
) -> str | None:
    slot_store = str(getattr(slots, "shop_name", None) or "").strip() if slots is not None else ""
    if slot_store and not _is_invalid_store_slot_value(slot_store):
        return slot_store

    for entry in reversed(prev_tool_data or []):
        if entry.get("tool") not in ("search_stores_tool", "get_nearby_stores_tool", "get_store_list_tool"):
            continue
        data = entry.get("data")
        items: list[dict] = []
        if isinstance(data, list):
            items = [item for item in data if isinstance(item, dict) and not item.get("_truncated")]
        elif isinstance(data, dict) and isinstance(data.get("stores"), list):
            items = [item for item in data["stores"] if isinstance(item, dict)]
        if len(items) == 1:
            store_name = str(items[0].get("shop_nm") or items[0].get("name") or "").strip()
            if store_name and not _is_invalid_store_slot_value(store_name):
                return store_name

    context_parts = [recent_context]
    for message in reversed((messages or [])[-8:]):
        context_parts.append(str(message.get("content") or ""))
    context_blob = "\n".join(part for part in context_parts if part)
    match = re.search(r"(?:티스테이션\s*)?([A-Za-z0-9가-힣]+점)", context_blob)
    if match and not _is_invalid_store_slot_value(match.group(0).strip()):
        return match.group(0).strip()
    return None


def _requested_cal_day_from_availability_context(user_text: str, recent_context: str) -> str | None:
    if _parse_requested_reservation_date(user_text) is not None:
        return _requested_reservation_cal_day_or_today(user_text)
    for line in reversed([part.strip() for part in str(recent_context or "").splitlines() if part.strip()]):
        if _parse_requested_reservation_date(line) is not None:
            return _requested_reservation_cal_day_or_today(line)
    return None


def _requested_day_label_from_availability_context(user_text: str, recent_context: str) -> str:
    text = f"{user_text}\n{recent_context}"
    for label in ("오늘", "내일", "모레"):
        if label in text:
            return label
    return "오늘"


def _is_quantity_only_stock_followup_text(text: str) -> bool:
    normalized = str(text or "").strip()
    if not normalized:
        return False
    parsed = ConversationSlots.extract_from_user_text(normalized)
    return bool(
        parsed.ord_qty is not None
        and normalize_tire_size(normalized) is None
        and parsed.shop_name is None
        and parsed.region is None
        and not ConversationSlots.has_product_keyword(normalized)
        and not re.search(r"예약|장착|오늘\s*서비스|오늘서비스|당일|방문|가능\s*시간|스케줄", normalized, re.IGNORECASE)
    )


def _is_pure_inventory_stock_ready(slots: Any | None) -> bool:
    if slots is None:
        return False

    def _slot_value(name: str) -> Any:
        if isinstance(slots, Mapping):
            return slots.get(name)
        return getattr(slots, name, None)

    try:
        qty = int(_slot_value("ord_qty") or _slot_value("quantity") or 0)
    except (TypeError, ValueError):
        qty = 0
    return bool(
        (_slot_value("pending_intent") == "stock" or _slot_value("goal_type") == "store_with_stock")
        and _slot_value("goods_no")
        and _slot_value("tire_size")
        and qty > 0
        and (_slot_value("shop_id") or _slot_value("shop_name") or _slot_value("store_name"))
    )


def _is_resolved_size_store_availability_transaction_continuation(
    user_text: str,
    *,
    slots: Any | None,
    routing_result: Any | None = None,
    size_only_store_availability_continuation: bool = False,
) -> bool:
    if not size_only_store_availability_continuation:
        return False
    if not _SIZE_ONLY_RE.match(str(user_text or "")):
        return False

    def _slot_value(name: str) -> Any:
        if slots is None:
            return None
        if isinstance(slots, Mapping):
            return slots.get(name)
        return getattr(slots, name, None)

    if not (_slot_value("goods_no") and _slot_value("tire_size")):
        return False
    pending_intent = str(_slot_value("pending_intent") or "").strip()
    goal_type = str(_slot_value("goal_type") or "").strip()
    if pending_intent != "stock" and goal_type != "store_with_stock":
        return False
    has_scope = bool(
        _slot_value("region")
        or _slot_value("shop_id")
        or _slot_value("shop_name")
        or _slot_value("store_name")
    )
    availability_context = _slot_value("availability_context")
    if isinstance(availability_context, Mapping):
        pending_context = availability_context.get("pending_order_context")
        if isinstance(pending_context, Mapping):
            has_scope = has_scope or bool(pending_context.get("region") or pending_context.get("shop_id") or pending_context.get("shop_name"))
    if not has_scope:
        return False
    routing_topic = str(getattr(routing_result, "pending_check_topic", "") or "").strip()
    followup_intent = str(getattr(routing_result, "discovery_followup_intent", "") or "").strip()
    execution_plan = " ".join(str(item) for item in (getattr(routing_result, "execution_plan", []) or []))
    return bool(
        routing_topic in {"store_inventory", "today_install", "none", ""}
        or followup_intent == "recent_product_set_size_availability"
        or re.search(r"stock|inventory|재고|장착|store", execution_plan, re.IGNORECASE)
    )


def _store_name_exact_match_row(store_name: str, stores: list[dict[str, Any]]) -> dict[str, Any] | None:
    target = re.sub(r"\s+", "", str(store_name or "")).lower()
    target = re.sub(r"^(?:티스테이션|더타이어샵|t'?station)", "", target, flags=re.IGNORECASE)
    matches: list[dict[str, Any]] = []
    for store in stores:
        if not isinstance(store, dict):
            continue
        shop_name = re.sub(r"\s+", "", str(store.get("shop_nm") or store.get("shop_name") or "")).lower()
        shop_name = re.sub(r"^(?:티스테이션|더타이어샵|t'?station)", "", shop_name, flags=re.IGNORECASE)
        if shop_name == target:
            matches.append(store)
    if len(matches) == 1:
        return matches[0]
    return None


_PREVIOUS_SELECTION_DATA_MARKER = "[이전 선택된 상품 데이터]"


def _template_data_from_assistant_message(message: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(message, dict) or message.get("role") != "assistant":
        return None
    template_data = message.get("template_data")
    if isinstance(template_data, dict):
        return template_data
    content = str(message.get("content") or "")
    if _PREVIOUS_SELECTION_DATA_MARKER not in content:
        return None
    _, _, suffix = content.partition(_PREVIOUS_SELECTION_DATA_MARKER)
    raw_json = suffix.strip()
    if not raw_json:
        return None
    try:
        parsed = json.loads(raw_json)
    except Exception:
        return None
    return parsed if isinstance(parsed, dict) else None


def _recent_compare_context_from_messages(user_text: str, messages: list[dict[str, Any]] | None) -> dict[str, str]:
    if not messages:
        return {}
    current_frame = build_discovery_intent_frame(user_text)
    current_product_names = tuple(current_frame.entities.get("product_names") or ())
    if len(current_product_names) < 2:
        return {}

    prior_compare_metric = ""
    for message in reversed(messages):
        template_data = _template_data_from_assistant_message(message)
        if not isinstance(template_data, dict):
            continue
        if str(template_data.get("assistant_response_source") or "").strip() != "code_product_compare_resolver":
            continue
        data = template_data.get("data")
        if not isinstance(data, dict):
            continue
        metadata = data.get("metadata")
        if not isinstance(metadata, dict):
            continue
        response_shape_key = str(metadata.get("response_shape_key") or "").strip()
        if response_shape_key not in {"metric_comparison_summary", "grade_comparison_summary"}:
            continue
        candidate_metric = str(metadata.get("compareMetric") or metadata.get("compare_metric") or "").strip()
        if candidate_metric in {"release", "price", "grade", "mileage", "noise", "fuel_efficiency", "wet", "car_type", "detail"}:
            prior_compare_metric = candidate_metric
            break
    if not prior_compare_metric:
        return {}

    current_compare_metric = str(current_frame.entities.get("compare_metric") or "").strip()
    current_sub_intent = str(current_frame.sub_intent or "").strip()
    if not current_compare_metric:
        current_attribute_metrics = tuple(extract_product_attribute_metrics(user_text))
        if "price" in current_attribute_metrics or _PRODUCT_PRICE_COMPARE_TEXT_RE.search(user_text):
            current_compare_metric = "price"
            current_sub_intent = "attribute_compare"
        elif "car_type" in current_attribute_metrics:
            current_compare_metric = "car_type"
            current_sub_intent = "attribute_compare"
    if current_sub_intent in {"latest_compare", "grade_compare", "mileage_compare", "attribute_compare"} and current_compare_metric:
        return {
            "comparison_followup_intent": (
                "continue_previous_compare_metric"
                if current_compare_metric == prior_compare_metric
                else "new_compare_metric"
            ),
            "comparison_metric": current_compare_metric,
        }
    if current_sub_intent == "general_compare":
        return {
            "comparison_followup_intent": "continue_previous_compare_metric",
            "comparison_metric": prior_compare_metric,
        }
    return {}


def _datepick_template_recovery_candidate_from_messages(
    messages: list[dict] | None,
) -> dict[str, Any] | None:
    if not messages:
        return None
    for message in reversed(messages):
        if message.get("role") != "assistant":
            continue
        template_data = _template_data_from_assistant_message(message)
        if not isinstance(template_data, dict):
            return None
        if str(template_data.get("template") or "") == "datepick":
            return template_data
        return None
    return None


def _has_sufficient_datepick_order_metadata(slot_values: Mapping[str, Any] | None) -> bool:
    if not isinstance(slot_values, Mapping):
        return False
    goods_no = str(slot_values.get("goods_no") or "").strip()
    tire_size = str(slot_values.get("tire_size") or "").strip()
    shop_id = str(slot_values.get("shop_id") or "").strip()
    ord_qty = slot_values.get("ord_qty")
    try:
        qty_ok = int(ord_qty) > 0
    except (TypeError, ValueError):
        qty_ok = False
    return bool(goods_no and tire_size and shop_id and qty_ok)


def _verified_datepick_order_values(slot_values: Mapping[str, Any] | None) -> dict[str, Any]:
    if not _has_sufficient_datepick_order_metadata(slot_values):
        return {}
    verified: dict[str, Any] = {}
    for field in (
        "goods_no",
        "tire_model",
        "tire_size",
        "ord_qty",
        "shop_id",
        "shop_name",
        "requested_cal_day",
        "rsv_hour",
        "payment_amount",
    ):
        value = slot_values.get(field) if isinstance(slot_values, Mapping) else None
        if value is not None:
            verified[field] = value
    return verified


_ORDER_SNAPSHOT_FIELDS: tuple[str, ...] = (
    "goods_no",
    "tire_model",
    "tire_size",
    "ord_qty",
    "shop_id",
    "shop_name",
    "requested_cal_day",
    "rsv_hour",
    "payment_amount",
)


def _apply_order_snapshot_slots(
    slots: ConversationSlots,
    values: Mapping[str, Any] | None,
    *,
    source: str,
    fill_only: bool = False,
) -> ConversationSlots:
    """Commit a verified order-flow snapshot without product/store dependency resets.

    Order snapshots come from current-turn tool/template metadata that already
    ties product, quantity, store, date and amount together. Applying these
    fields one-by-one through runtime dependency resets can erase the same
    snapshot (e.g. shop_id change clearing payment_amount), so this helper
    updates the snapshot atomically and marks the active order flow.
    """
    del source  # kept for log call sites and future provenance metadata.
    if not isinstance(values, Mapping):
        return slots

    update: dict[str, Any] = {}
    for field in _ORDER_SNAPSHOT_FIELDS:
        value = values.get(field)
        if value in (None, ""):
            continue
        if field == "ord_qty":
            try:
                value = int(value)
            except (TypeError, ValueError):
                continue
            if value <= 0:
                continue
        if field == "payment_amount":
            try:
                value = int(value)
            except (TypeError, ValueError):
                continue
            if value <= 0:
                continue
        if fill_only and getattr(slots, field, None) is not None:
            continue
        update[field] = value

    update["pending_intent"] = "order"
    update["goal_type"] = "place_order"
    if not update:
        return slots
    return slots.model_copy(update=update)


def _build_store_availability_quantity_prompt_event(
    *,
    product_keyword: str,
    tire_size: str,
    store_name: str | None,
    goods_no: str | None = None,
    requested_day_label: str = "오늘",
) -> dict:
    store_label = str(store_name or "해당 매장").strip()
    day_label = str(requested_day_label or "오늘").strip()
    return {
        "type": "data",
        "template": "quickReply",
        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
        "assistant_response_source": "code_store_availability_size_followup_quantity_prompt",
        "data": {
            "assistantResponse": (
                f"{product_keyword} {tire_size} 상품은 확인했어요. "
                f"{store_label} {day_label} 장착 가능 여부를 확인하려면 장착 수량을 알려주세요."
            ),
            "quickReplies": [
                {"label": "1개", "domain": "TRANSACTION"},
                {"label": "2개", "domain": "TRANSACTION"},
                {"label": "3개", "domain": "TRANSACTION"},
                {"label": "4개", "domain": "TRANSACTION"},
            ],
            "predictedDomains": ["TRANSACTION"],
            "metadata": {
                "goodsId": goods_no,
                "goodsNo": goods_no,
                "goods_no": goods_no,
                "tireSize": tire_size,
                "tire_size": tire_size,
                "productName": product_keyword,
                "product_name": product_keyword,
                "storeName": store_name,
            },
        },
    }


def _recent_product_coupon_price_target(user_text: str, recent_context: str) -> dict[str, Any] | None:
    current_size = normalize_tire_size(user_text)
    if not current_size:
        return None
    for line in reversed([part.strip() for part in str(recent_context or "").splitlines() if part.strip()]):
        if line == str(user_text or "").strip():
            continue
        if not _is_product_coupon_price_amount_query(line):
            continue
        product_name = _coupon_target_product_name_for_query(line)
        parsed = _split_product_size_quantity_from_text(product_name, line)
        if not parsed.get("product_name") or not parsed.get("quantity"):
            continue
        parsed["tire_size"] = current_size
        return parsed
    return None


def _should_suppress_inherited_recommendation_context_for_product_attribute(user_text: str) -> bool:
    if _is_ev_suitability_turn(user_text):
        return False
    frame = build_discovery_intent_frame(user_text)
    product_names = tuple(frame.entities.get("product_names") or ())
    if frame.intent != "product_description" or not product_names:
        return False
    return normalize_tire_size(user_text) is None


def _recommendation_context_policy_dict(value: Any) -> dict[str, Any]:
    if value is None:
        return {}
    if isinstance(value, RecommendationContext):
        return value.to_policy_dict()
    if isinstance(value, Mapping):
        context = RecommendationContext.from_mapping(value)
        if context is not None:
            return context.to_policy_dict()
    return {}


def _should_replace_listcar_with_product_attribute_lookup(event: dict | None, user_text: str) -> bool:
    """Return true when a vehicle-list card is an accidental detour for a product attribute question."""
    if not isinstance(event, dict) or event.get("template") != "listCar":
        return False
    return _is_product_attribute_lookup_query(user_text)


def _is_product_attribute_fallback_event(event: dict | None) -> bool:
    if not isinstance(event, dict):
        return False
    data = event.get("data")
    if not isinstance(data, dict):
        return False
    assistant = str(data.get("assistantResponse") or "")
    return (
        "상품명을 알려주시면" in assistant
        or "상세 정보를 확인해 드릴게요" in assistant
        or "사용자가 물은 상품 상세 항목" in assistant
    )


def _is_product_compare_missing_event(event: dict | None) -> bool:
    if not isinstance(event, dict):
        return False
    if event.get("assistant_response_source") != "code_product_compare_resolver":
        return False
    data = event.get("data")
    if not isinstance(data, dict):
        return False
    assistant = str(data.get("assistantResponse") or "")
    return "상품은 찾지 못했어요" in assistant or "비교할 상품명을 다시" in assistant


_PRODUCT_DETAIL_PRICE_OR_COUPON_RE = re.compile(
    r"가격|얼마|혜택가|최종가|할인가|쿠폰|할인",
    re.IGNORECASE,
)


def _is_explicit_product_price_or_coupon_turn(user_text: str) -> bool:
    text = str(user_text or "").strip()
    if not text:
        return False
    if _is_product_coupon_price_amount_query(text) or _is_product_coupon_eligibility_query(text):
        return True
    price_frame = build_price_intent_frame(text)
    if price_frame.intent in {
        "price_coupon_summary",
        "product_coupon_eligibility",
        "coupon_applicable_products",
    }:
        return True
    return bool(_PRODUCT_DETAIL_PRICE_OR_COUPON_RE.search(text))


def _repair_assistant_response(assistant_response: str, mismatches: list[Any]) -> str | None:
    text = str(assistant_response or "").strip()
    if not text or not mismatches:
        return None

    mismatch_values = [str(getattr(mismatch, "value", "") or "").strip() for mismatch in mismatches if mismatch is not None]
    mismatch_values = [value for value in mismatch_values if value]
    if not mismatch_values:
        return None

    lines = [line.strip() for line in text.splitlines() if line.strip()]
    kept_lines = [
        line for line in lines
        if not any(value in line for value in mismatch_values)
    ]
    fields = {str(getattr(mismatch, "field", "") or "") for mismatch in mismatches if mismatch is not None}
    repairable_fields = {"price", "goods_no", "shop_id", "tire_size"}
    if not fields or not fields <= repairable_fields:
        return None

    guidance: list[str] = []
    if "price" in fields:
        guidance.append("정확한 가격은 다시 확인해서 안내드릴게요.")
    if "goods_no" in fields:
        guidance.append("상품 정보는 상품명 기준으로 다시 정리해 드릴게요.")
    if "shop_id" in fields:
        guidance.append("매장 정보는 다시 확인해서 안내드릴게요.")
    if "tire_size" in fields:
        guidance.append("규격 정보는 다시 확인해서 안내드릴게요.")

    repaired_lines = kept_lines or [line for line in guidance if line]
    if kept_lines and guidance:
        repaired_lines.extend(line for line in guidance if line not in repaired_lines)
    repaired = "\n\n".join(line for line in repaired_lines if line).strip()
    return repaired or None


def _repair_qc_mismatch_event(
    event: dict[str, Any] | None,
    *,
    mismatches: list[Any],
) -> dict[str, Any] | None:
    if not isinstance(event, dict):
        return None
    data = event.get("data")
    if not isinstance(data, dict):
        return None
    repaired_response = _repair_assistant_response(str(data.get("assistantResponse") or ""), mismatches)
    if not repaired_response:
        return None

    repaired_event = dict(event)
    repaired_data = dict(data)
    repaired_data["assistantResponse"] = repaired_response
    metadata = dict(repaired_data.get("metadata") or {})
    metadata["qcRepair"] = {
        "attempted": True,
        "fields": sorted({
            str(getattr(mismatch, "field", "") or "")
            for mismatch in mismatches
            if mismatch is not None
        }),
    }
    repaired_data["metadata"] = metadata
    repaired_event["data"] = repaired_data
    repaired_event["assistant_response_source"] = "code_qc_mismatch_repair"
    return repaired_event


def _build_repaired_product_description_event(
    *,
    structured_sources: list[tuple[str, dict]],
    called_tool_names: set[str],
    source_domain: str,
    user_text: str,
) -> dict[str, Any] | None:
    if source_domain != MultiAgentDomain.Domain.DISCOVERY.value:
        return None
    if "get_product_description_tool" not in called_tool_names:
        return None
    if _is_explicit_product_price_or_coupon_turn(user_text):
        return None
    for tool_name, tool_output in reversed(structured_sources):
        if tool_name != "get_product_description_tool":
            continue
        return _build_product_description_quickreply_event(tool_output)
    return None


def _normalize_unmatched_coupon_quickreply(
    event_data: dict[str, Any],
    *,
    called_tool_names: set[str],
    source_domain: str,
    last_user_text: str,
) -> bool:
    if source_domain != MultiAgentDomain.Domain.TRANSACTION.value:
        return False
    if "get_my_coupons_tool" not in called_tool_names:
        return False
    if "get_coupon_applicable_products_tool" in called_tool_names:
        return False
    assistant_text = str(event_data.get("assistantResponse") or "")
    if not _COUPON_UNMATCHED_TEXT_RE.search(assistant_text):
        return False
    if not _COUPON_APPLICABILITY_INTENT_RE.search(last_user_text):
        return False

    event_data["assistantResponse"] = (
        "고객님 보유 쿠폰에서 해당 쿠폰을 찾지 못했어요. 쿠폰함에서 쿠폰명을 확인해 주세요."
    )
    event_data["quickReplies"] = [dict(chip) for chip in _COUPON_BOX_CHIPS]
    event_data["predictedDomains"] = ["TRANSACTION"]
    return True


_SIZE_FIRST_COUPON_TEXT_RE = re.compile(
    r"사이즈|규격|타이어\s*크기|상품을?\s*먼저\s*선택|상품\s*선택.*쿠폰",
    re.IGNORECASE,
)


def _normalize_price_policy_quickreply(
    event_data: dict[str, Any],
    *,
    source_domain: str,
    last_user_text: str,
) -> bool:
    """Apply price/coupon ResponseDecision to LLM-written quickReply payloads."""
    if source_domain != MultiAgentDomain.Domain.TRANSACTION.value:
        return False
    frame = build_price_intent_frame(last_user_text)
    decision = decide_price_response(frame)
    assistant_text = str(event_data.get("assistantResponse") or "")
    changed = False

    if "매핑" in assistant_text:
        event_data["assistantResponse"] = assistant_text.replace("매핑", "적용 정보")
        assistant_text = str(event_data.get("assistantResponse") or "")
        changed = True

    if (
        frame.intent == "product_coupon_eligibility"
        and decision.forbids("require_size_first")
        and _SIZE_FIRST_COUPON_TEXT_RE.search(assistant_text)
    ):
        # Do not rewrite this into another instruction/CTA. The streaming
        # coordinator should run the coupon resolver and replace the reply
        # with an applicability answer based on coupon tools.
        return False

    return changed


def _normalize_discovery_policy_quickreply(
    event_data: dict[str, Any],
    *,
    source_domain: str,
    decision: Any,
) -> bool:
    if source_domain != MultiAgentDomain.Domain.DISCOVERY.value:
        return False
    if decision is None or not getattr(decision, "metadata", None):
        return False
    response_shape_key = str(decision.metadata.get("response_shape_key") or "")

    assistant_text = str(event_data.get("assistantResponse") or "")
    if response_shape_key == "similar_price_range_recommendation":
        if not (
            assistant_text == str(getattr(decision, "assistant_guidance", "") or "")
            or "정가 기준 가격대" in assistant_text
            or "최종 구매 가격은 규격 확인 후 안내" in assistant_text
            or "range로 유사 상품" in assistant_text
        ):
            return False

        event_data["assistantResponse"] = (
            "비슷한 가격대 상품으로 더 추천해 드릴게요. "
            "정확한 장착 가능 여부와 혜택가는 차량이나 타이어 사이즈를 확인한 뒤 안내드릴 수 있어요."
        )
        event_data["quickReplies"] = [
            {"label": "사이즈 직접 입력", "domain": "DISCOVERY"},
            {"label": "차량번호로 확인", "domain": "DISCOVERY"},
            {"label": "내 차량 보기", "domain": "DISCOVERY"},
        ]
        event_data["predictedDomains"] = ["DISCOVERY"]
        return True

    if response_shape_key == "grade_comparison_summary":
        if not (
            assistant_text == str(getattr(decision, "assistant_guidance", "") or "")
            or "등급/포지션 근거로 비교" in assistant_text
        ):
            return False

        event_data["assistantResponse"] = (
            "두 상품의 프리미엄 등급 여부를 비교하려면 각 상품명을 정확히 확인해야 해요. "
            "비교할 상품명을 다시 알려주시면 등급과 포지션 기준으로 정리해 드릴게요."
        )
        event_data["quickReplies"] = [
            {"label": "상품명 다시 입력", "domain": "DISCOVERY"},
            {"label": "사이즈 직접 입력", "domain": "DISCOVERY"},
            {"label": "내 차량 보기", "domain": "DISCOVERY"},
        ]
        event_data["predictedDomains"] = ["DISCOVERY"]
        return True

    return False


_RECOMMENDATION_APPROXIMATION_NOTICE_RE = re.compile(
    r"근사|전용(?:\s*필터)?(?:가|는)?\s*아니|하중\s*안정|SUV\s*/?\s*하중|기준으로\s*추천",
    re.IGNORECASE,
)
_OFFROAD_EXACT_CLAIM_RE = re.compile(r"오프로드\s*전용", re.IGNORECASE)
_OFFROAD_NEGATED_EXACT_CLAIM_RE = re.compile(
    r"오프로드\s*전용(?:\s*필터)?(?:이|가|은|는)?\s*(?:아니라|아니고|아님|아닙니다|아닌)",
    re.IGNORECASE,
)
_SENTENCE_WITH_OFFROAD_EXACT_CLAIM_RE = re.compile(
    r"[^.!?\n。！？]*오프로드\s*전용[^.!?\n。！？]*(?:[.!?。！？]+|$)",
    re.IGNORECASE,
)


def _offroad_exact_claim_sentences(text: str) -> list[str]:
    return [
        match.group(0)
        for match in _SENTENCE_WITH_OFFROAD_EXACT_CLAIM_RE.finditer(str(text or ""))
        if _OFFROAD_EXACT_CLAIM_RE.search(match.group(0))
        and not _OFFROAD_NEGATED_EXACT_CLAIM_RE.search(match.group(0))
    ]


def _recommendation_contract_metadata(contract: Any | None) -> dict[str, Any]:
    if contract is None:
        return {}
    known_slots = getattr(contract, "known_slots", {}) or {}
    data: dict[str, Any] = {}
    context = _recommendation_context_policy_dict(known_slots.get("recommendation_context"))
    data.update(context)
    for key in (
        "recommendation_scenario",
        "applied_rcmd_type",
        "applied_vehicle_type",
        "applied_season_nm",
        "approximation",
        "approximation_basis",
    ):
        if known_slots.get(key) not in (None, ""):
            data[key] = known_slots[key]
    response_decision = getattr(contract, "response_decision", {}) or {}
    response_metadata = response_decision.get("metadata") if isinstance(response_decision, Mapping) else {}
    if isinstance(response_metadata, Mapping):
        data.update({key: value for key, value in response_metadata.items() if value not in (None, "")})
    return data


def _normalize_recommendation_approximation_response(event_data: dict[str, Any], contract: Any | None) -> bool:
    metadata = _recommendation_contract_metadata(contract)
    if metadata.get("approximation") is not True:
        return False
    assistant_text = str(event_data.get("assistantResponse") or "")
    if not assistant_text:
        return False
    exact_claim_sentences = _offroad_exact_claim_sentences(assistant_text)
    if exact_claim_sentences:
        basis = str(metadata.get("approximation_basis") or "SUV/하중 안정성").strip()
        event_data["assistantResponse"] = _SENTENCE_WITH_OFFROAD_EXACT_CLAIM_RE.sub(
            lambda match: (
                f"오프로드 전용 필터가 아니라 {basis} 기준으로 근사 추천한 결과예요."
                if match.group(0) in exact_claim_sentences
                else match.group(0)
            ),
            assistant_text,
        )
        metadata_data = event_data.get("metadata")
        if isinstance(metadata_data, dict):
            metadata_data["recommendationApproximation"] = True
            metadata_data["approximationBasis"] = basis
            metadata_data["exactOffroadClaimRepaired"] = True
        return True
    if _RECOMMENDATION_APPROXIMATION_NOTICE_RE.search(assistant_text):
        return False
    basis = str(metadata.get("approximation_basis") or "SUV/하중 안정성").strip()
    notice = f" 참고로 오프로드 전용 필터가 아니라 {basis} 기준으로 근사 추천한 결과예요."
    event_data["assistantResponse"] = assistant_text.rstrip() + notice
    metadata_data = event_data.get("metadata")
    if isinstance(metadata_data, dict):
        metadata_data["recommendationApproximation"] = True
        metadata_data["approximationBasis"] = basis
    return True


