        async def _resolve_store_holiday_period_with_code() -> tuple[list[dict], dict] | None:
            if not _is_store_holiday_period_info_query(user_query):
                return None
            store_name = _extract_store_holiday_store_name(user_query)
            if not store_name:
                return None

            from services.tstation.agents.c_transaction_agent.tools import (
                get_store_detail_tool as _store_detail_tool,
                get_store_list_tool as _store_list_tool,
            )

            emitted_events: list[dict] = []
            list_input = {"store_nm": store_name, "limit": 3}
            emitted_events.append({
                "type": "status",
                "status": "tool_start",
                "tool": "get_store_list_tool",
                "display_name": "매장 조회 중...",
                "source_domain": "transaction",
            })
            try:
                raw_list = await asyncio.to_thread(_store_list_tool.invoke, list_input)
                list_result = _tool_result_dict(raw_list)
            except Exception as exc:
                logger.exception("[STORE_HOLIDAY] store list tool failed")
                list_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
            _record_code_tool_result("get_store_list_tool", list_input, list_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Store AF]",
                "agent_class": "Transaction Agent",
                "status": list_result.get("status", "success"),
                "source_domain": "transaction",
            })
            emitted_events.append({
                "type": "tool",
                "input": list_input,
                "output": json.dumps(list_result, ensure_ascii=False),
                "node": "tools",
                "tool": "get_store_list_tool",
                "source_domain": "transaction",
            })

            list_data = _unwrap_tool_data(list_result)
            stores = list_data.get("stores") if isinstance(list_data, dict) else None
            if not isinstance(stores, list) or not stores:
                return None
            store_row = stores[0] if isinstance(stores[0], dict) else {}
            shop_id = str(store_row.get("shop_id") or "").strip()
            if not shop_id:
                return None

            detail_input = {"shop_id": shop_id, "cal_day": _requested_reservation_cal_day_or_today(user_query)}
            emitted_events.append({
                "type": "status",
                "status": "tool_start",
                "tool": "get_store_detail_tool",
                "display_name": "매장 상세 정보 조회 중...",
                "source_domain": "transaction",
            })
            try:
                raw_detail = await asyncio.to_thread(_store_detail_tool.invoke, detail_input)
                detail_result = _tool_result_dict(raw_detail)
            except Exception as exc:
                logger.exception("[STORE_HOLIDAY] store detail tool failed")
                detail_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
            _record_code_tool_result("get_store_detail_tool", detail_input, detail_result)
            if isinstance(detail_result, dict) and detail_result.get("status") == "success":
                detail_data = _unwrap_tool_data(detail_result)
                if initial_slots is not None:
                    initial_slots.shop_id = shop_id
                    if isinstance(detail_data, dict):
                        detail_store_name = str(detail_data.get("shop_nm") or store_row.get("shop_nm") or "").strip()
                        if detail_store_name:
                            initial_slots.shop_name = detail_store_name
                    if session_id:
                        try:
                            from services.tstation.chat_history_service import get_chat_history_service

                            history_svc = get_chat_history_service()
                            await history_svc.save_slots_async(session_id, initial_slots, user_id=user_id)
                        except Exception:
                            logger.exception("[STORE_HOLIDAY] failed to persist store slots")
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Store AF]",
                "agent_class": "Transaction Agent",
                "status": detail_result.get("status", "success"),
                "source_domain": "transaction",
            })
            emitted_events.append({
                "type": "tool",
                "input": detail_input,
                "output": json.dumps(detail_result, ensure_ascii=False),
                "node": "tools",
                "tool": "get_store_detail_tool",
                "source_domain": "transaction",
            })
            return emitted_events, _build_store_holiday_period_event(user_query, store_row, detail_result)

        async def _resolve_store_attribute_inquiry_with_code() -> tuple[list[dict], dict] | None:
            router_policy_intent = str(getattr(routing_result, "policy_intent", "") or "")
            router_store_name = str(getattr(routing_result, "store_attribute_store_name", "") or "").strip()
            router_attribute_text = str(getattr(routing_result, "store_attribute_text", "") or "").strip()
            router_attribute_type = str(getattr(routing_result, "store_attribute_type", "") or "").strip()
            router_verification_level = str(
                getattr(routing_result, "store_attribute_verification_level", "") or ""
            ).strip()
            slot_store_name = ""
            if initial_slots is not None:
                slot_store_name = str(
                    getattr(initial_slots, "shop_name", None)
                    or getattr(initial_slots, "store_name", None)
                    or ""
                ).strip()
            inquiry = extract_store_attribute_inquiry(user_query, store_name=slot_store_name or None)
            current_store_name = _extract_plain_store_info_store_name(user_query)
            continuation_inquiry = _store_attribute_selection_continuation_inquiry(
                user_text=user_query,
                messages=messages,
                store_name=str(router_store_name or current_store_name or slot_store_name or "").strip(),
                routing_result=routing_result,
            )
            labels = unverifiable_store_preference_labels(user_query)
            if (
                router_policy_intent != "store_attribute_inquiry"
                and inquiry is None
                and continuation_inquiry is None
                and not (slot_store_name and labels)
            ):
                return None
            store_name = str(
                router_store_name
                or (inquiry.store_name if inquiry is not None else "")
                or (continuation_inquiry.store_name if continuation_inquiry is not None else "")
                or current_store_name
                or slot_store_name
                or ""
            ).strip()
            attribute_text = (
                router_attribute_text
                or (inquiry.attribute_text if inquiry is not None else "")
                or (continuation_inquiry.attribute_text if continuation_inquiry is not None else "")
            )
            attribute_type = (
                router_attribute_type
                or (inquiry.attribute_type if inquiry is not None else "")
                or (continuation_inquiry.attribute_type if continuation_inquiry is not None else "")
            )
            verification_level = router_verification_level or (
                inquiry.verification_level if inquiry is not None else ""
            ) or (
                continuation_inquiry.verification_level if continuation_inquiry is not None else ""
            )
            if not store_name:
                event = _store_attribute_inquiry_event(
                    user_query,
                    store_name=None,
                    attribute_text=attribute_text,
                    attribute_type=attribute_type,
                    verification_level=verification_level,
                )
                return ([], event) if event is not None else None

            from services.tstation.agents.c_transaction_agent.tools import (
                get_store_detail_tool as _store_detail_tool,
                get_store_list_tool as _store_list_tool,
            )

            emitted_events: list[dict] = []
            list_input = {"store_nm": store_name, "limit": 3}
            emitted_events.append({
                "type": "status",
                "status": "tool_start",
                "tool": "get_store_list_tool",
                "display_name": "매장 조회 중...",
                "source_domain": "transaction",
            })
            try:
                raw_list = await asyncio.to_thread(_store_list_tool.invoke, list_input)
                list_result = _tool_result_dict(raw_list)
            except Exception as exc:
                logger.exception("[STORE_ATTRIBUTE] store list tool failed")
                list_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
            _record_code_tool_result("get_store_list_tool", list_input, list_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Store AF]",
                "agent_class": "Transaction Agent",
                "status": list_result.get("status", "success"),
                "source_domain": "transaction",
            })
            emitted_events.append({
                "type": "tool",
                "input": list_input,
                "output": json.dumps(list_result, ensure_ascii=False),
                "node": "tools",
                "tool": "get_store_list_tool",
                "source_domain": "transaction",
            })

            list_data = _unwrap_tool_data(list_result)
            stores = list_data.get("stores") if isinstance(list_data, dict) else None
            if not isinstance(stores, list) or not stores:
                event = _store_attribute_inquiry_event(
                    user_query,
                    store_name=store_name,
                    attribute_text=attribute_text,
                    attribute_type=attribute_type,
                    verification_level=verification_level,
                )
                return (emitted_events, event) if event is not None else None
            store_rows = [store for store in stores if isinstance(store, dict)]
            store_row = _store_name_exact_match_row(store_name, store_rows)
            if store_row is None:
                logger.info("[STORE_ATTRIBUTE] ambiguous store match; skip arbitrary detail store=%r rows=%d", store_name, len(store_rows))
                event = _store_attribute_inquiry_event(
                    user_query,
                    store_name=store_name,
                    attribute_text=attribute_text,
                    attribute_type=attribute_type,
                    verification_level=verification_level,
                )
                return (emitted_events, event) if event is not None else None

            shop_id = str(store_row.get("shop_id") or store_row.get("shop_seq") or "").strip()
            if not shop_id:
                event = _store_attribute_inquiry_event(
                    user_query,
                    store_name=store_name,
                    attribute_text=attribute_text,
                    attribute_type=attribute_type,
                    verification_level=verification_level,
                    store_info_entries=[{"tool": "get_store_list_tool", "args": list_input, "data": list_result}],
                )
                return (emitted_events, event) if event is not None else None

            detail_input = {"shop_id": shop_id, "cal_day": _requested_reservation_cal_day_or_today(user_query)}
            emitted_events.append({
                "type": "status",
                "status": "tool_start",
                "tool": "get_store_detail_tool",
                "display_name": "매장 상세 정보 조회 중...",
                "source_domain": "transaction",
            })
            try:
                raw_detail = await asyncio.to_thread(_store_detail_tool.invoke, detail_input)
                detail_result = _tool_result_dict(raw_detail)
            except Exception as exc:
                logger.exception("[STORE_ATTRIBUTE] store detail tool failed")
                detail_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
            _record_code_tool_result("get_store_detail_tool", detail_input, detail_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Store AF]",
                "agent_class": "Transaction Agent",
                "status": detail_result.get("status", "success"),
                "source_domain": "transaction",
            })
            emitted_events.append({
                "type": "tool",
                "input": detail_input,
                "output": json.dumps(detail_result, ensure_ascii=False),
                "node": "tools",
                "tool": "get_store_detail_tool",
                "source_domain": "transaction",
            })
            if initial_slots is not None and isinstance(detail_result, dict) and detail_result.get("status") == "success":
                detail_data = _unwrap_tool_data(detail_result)
                initial_slots.shop_id = shop_id
                if isinstance(detail_data, dict):
                    initial_slots.shop_name = str(detail_data.get("shop_nm") or store_row.get("shop_nm") or store_name).strip()
                if session_id:
                    try:
                        from services.tstation.chat_history_service import get_chat_history_service

                        history_svc = get_chat_history_service()
                        await history_svc.save_slots_async(session_id, initial_slots, user_id=user_id)
                    except Exception:
                        logger.exception("[STORE_ATTRIBUTE] failed to persist store slots")

            event = _store_attribute_inquiry_event(
                user_query,
                store_name=store_name,
                attribute_text=attribute_text,
                attribute_type=attribute_type,
                verification_level=verification_level,
                store_info_entries=[
                    {"tool": "get_store_list_tool", "args": list_input, "data": list_result},
                    {"tool": "get_store_detail_tool", "args": detail_input, "data": detail_result},
                ],
            )
            return (emitted_events, event) if event is not None else None

        async def _resolve_plain_store_info_with_code() -> tuple[list[dict], dict] | None:
            store_name = _extract_plain_store_info_store_name(user_query)
            if not store_name:
                return None

            from services.tstation.agents.c_transaction_agent.tools import (
                get_store_detail_tool as _store_detail_tool,
                get_store_list_tool as _store_list_tool,
            )
            from services.tstation.template_mapper import try_build_template

            emitted_events: list[dict] = []
            list_input = {"store_nm": store_name, "limit": 3}
            emitted_events.append({
                "type": "status",
                "status": "tool_start",
                "tool": "get_store_list_tool",
                "display_name": "매장 조회 중...",
                "source_domain": "transaction",
            })
            try:
                raw_list = await asyncio.to_thread(_store_list_tool.invoke, list_input)
                list_result = _tool_result_dict(raw_list)
            except Exception as exc:
                logger.exception("[STORE_INFO] store list tool failed")
                list_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
            _record_code_tool_result("get_store_list_tool", list_input, list_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Store AF]",
                "agent_class": "Transaction Agent",
                "status": list_result.get("status", "success"),
                "source_domain": "transaction",
            })
            emitted_events.append({
                "type": "tool",
                "input": list_input,
                "output": json.dumps(list_result, ensure_ascii=False),
                "node": "tools",
                "tool": "get_store_list_tool",
                "source_domain": "transaction",
            })

            list_data = _unwrap_tool_data(list_result)
            stores = list_data.get("stores") if isinstance(list_data, dict) else None
            if not isinstance(stores, list) or not stores:
                return None
            store_row = stores[0] if isinstance(stores[0], dict) else {}
            shop_id = str(store_row.get("shop_id") or "").strip()
            if not shop_id:
                return None

            detail_input = {"shop_id": shop_id, "cal_day": _requested_reservation_cal_day_or_today(user_query)}
            emitted_events.append({
                "type": "status",
                "status": "tool_start",
                "tool": "get_store_detail_tool",
                "display_name": "매장 상세 정보 조회 중...",
                "source_domain": "transaction",
            })
            try:
                raw_detail = await asyncio.to_thread(_store_detail_tool.invoke, detail_input)
                detail_result = _tool_result_dict(raw_detail)
            except Exception as exc:
                logger.exception("[STORE_INFO] store detail tool failed")
                detail_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
            _record_code_tool_result("get_store_detail_tool", detail_input, detail_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Store AF]",
                "agent_class": "Transaction Agent",
                "status": detail_result.get("status", "success"),
                "source_domain": "transaction",
            })
            emitted_events.append({
                "type": "tool",
                "input": detail_input,
                "output": json.dumps(detail_result, ensure_ascii=False),
                "node": "tools",
                "tool": "get_store_detail_tool",
                "source_domain": "transaction",
            })

            detail_event = try_build_template(
                [{"tool": "get_store_detail_tool", "data": detail_result}],
                f"{store_name} 정보를 확인했어요.",
            )
            if not isinstance(detail_event, dict) or detail_event.get("template") != "quickReply":
                return None
            if is_store_visual_detail_request(user_query):
                event_data = detail_event.get("data")
                detail_data = _unwrap_tool_data(detail_result)
                if isinstance(event_data, dict) and isinstance(detail_data, dict):
                    store_seq = str(
                        detail_data.get("shop_seq")
                        or detail_data.get("shop_id")
                        or store_row.get("shop_seq")
                        or store_row.get("shop_id")
                        or ""
                    ).strip()
                    if store_seq:
                        response = str(event_data.get("assistantResponse") or "").strip()
                        visual_guidance = "매장 전경이나 사진은 매장 상세 페이지에서 확인해 주세요."
                        if visual_guidance not in response:
                            event_data["assistantResponse"] = f"{response}\n\n{visual_guidance}".strip()
                        detail_chip = {
                            "label": "매장 상세 페이지로 이동",
                            "url": CTAUrls.STORE_DETAIL.replace("<shop_seq>", store_seq),
                            "domain": "TRANSACTION",
                        }
                        chips = event_data.get("quickReplies")
                        if not isinstance(chips, list):
                            chips = []
                        event_data["quickReplies"] = [
                            detail_chip,
                            *[
                                chip for chip in chips
                                if not (
                                    isinstance(chip, dict)
                                    and str(chip.get("label") or "").strip()
                                    in {"매장 상세 페이지로 이동", "매장 찾기"}
                                )
                            ],
                        ]
                        predicted = event_data.get("predictedDomains")
                        if isinstance(predicted, list):
                            event_data["predictedDomains"] = _dedupe_domain_values(["TRANSACTION", *predicted])
                        else:
                            event_data["predictedDomains"] = ["TRANSACTION"]
                        detail_event["assistant_response_source"] = "code_store_visual_detail_cta"
            return emitted_events, detail_event

        async def _resolve_coupon_applicability_with_code(
            my_coupons_result: dict | None = None,
        ) -> tuple[list[dict], dict]:
            emitted_events: list[dict] = []
            from services.tstation.agents.c_transaction_agent.tools import (
                get_coupon_applicable_products_tool as _coupon_applicable_tool,
                get_my_coupons_tool as _my_coupons_tool,
            )

            if my_coupons_result is None:
                my_coupons_input = {"lang_cd": "ko"}
                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "get_my_coupons_tool",
                    "display_name": "내 쿠폰 조회 중...",
                    "source_domain": "transaction",
                })
                try:
                    raw_my_coupons = await asyncio.to_thread(
                        _my_coupons_tool.invoke,
                        my_coupons_input,
                    )
                    my_coupons_result = _tool_result_dict(raw_my_coupons)
                except Exception as exc:
                    logger.exception("[COUPON_RESOLVER] my coupons tool failed")
                    my_coupons_result = {
                        "status": "error",
                        "http_status": None,
                        "message": str(exc),
                        "data": {},
                    }
                _record_code_tool_result("get_my_coupons_tool", my_coupons_input, my_coupons_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Price AF]",
                    "agent_class": "Transaction Agent",
                    "status": my_coupons_result.get("status", "success"),
                    "source_domain": "transaction",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": my_coupons_input,
                    "output": json.dumps(my_coupons_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "get_my_coupons_tool",
                    "source_domain": "transaction",
                })

            matched_coupon, ambiguous_coupons = _find_single_confident_coupon_from_owned_coupons(
                user_query,
                my_coupons_result,
            )
            if matched_coupon is None:
                return emitted_events, _build_coupon_match_failure_event(user_query, ambiguous_coupons)

            matched_cpn_no = str(matched_coupon.get("cpn_no") or "").strip()
            if not matched_cpn_no:
                return emitted_events, _build_coupon_match_failure_event(user_query)

            matched_channel_type = _coupon_channel_type(matched_coupon)
            is_channel_usage_query = _is_specific_coupon_usage_query(user_query)
            if matched_channel_type in {"offline", "partner_only"} and is_channel_usage_query:
                channel_event = _build_coupon_channel_policy_event(
                    matched_coupon,
                    target_product_name=_coupon_target_product_name_for_query(user_query),
                )
                if channel_event is not None:
                    return emitted_events, channel_event

            followup_tool_name = "get_coupon_applicable_products_tool"
            followup_input = {"cpn_no": [matched_cpn_no], "deal_no": None}
            emitted_events.append({
                "type": "status",
                "status": "tool_start",
                "tool": followup_tool_name,
                "display_name": "답변 중...",
                "source_domain": "transaction",
            })
            try:
                raw_followup = await asyncio.to_thread(
                    _coupon_applicable_tool.invoke,
                    followup_input,
                )
                followup_result = _tool_result_dict(raw_followup)
            except Exception as exc:
                logger.exception("[COUPON_RESOLVER] follow-up tool failed")
                followup_result = {
                    "status": "error",
                    "http_status": None,
                    "message": str(exc),
                    "data": {},
                }
            _record_code_tool_result(followup_tool_name, followup_input, followup_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Price AF]",
                "agent_class": "Transaction Agent",
                "status": followup_result.get("status", "success"),
                "source_domain": "transaction",
            })
            emitted_events.append({
                "type": "tool",
                "input": followup_input,
                "output": json.dumps(followup_result, ensure_ascii=False),
                "node": "tools",
                "tool": followup_tool_name,
                "source_domain": "transaction",
            })
            if is_channel_usage_query:
                channel_event = _build_coupon_channel_policy_event(
                    matched_coupon,
                    applicable_result=followup_result,
                    target_product_name=_coupon_target_product_name_for_query(user_query),
                )
                if channel_event is not None and (
                    matched_channel_type in {"store_only", "offline", "partner_only"}
                    or not _coupon_target_product_name_for_query(user_query)
                ):
                    return emitted_events, channel_event
            return emitted_events, _build_coupon_applicability_event(
                followup_result,
                matched_coupon,
                target_product_name=_coupon_target_product_name_for_query(user_query),
                target_brand=_coupon_target_brand_for_query(user_query),
            )

