        async def _resolve_oe_replacement_followup_with_code(
            confirmed_tire_size: str | None,
        ) -> tuple[list[dict], dict] | None:
            if (
                _should_reuse_vehicle_slots_for_oe_followup(
                    recent_user_context_text,
                    user_query,
                    confirmed_tire_size,
                )
                and re.search(r"동일(?:한)?\s*상품|같은\s*상품", user_query, re.IGNORECASE)
                and _oe_replacement_followup_brand_cd(user_query, recent_user_context_text) is None
            ):
                return [], _build_oe_replacement_same_product_brand_prompt_event(confirmed_tire_size)

            same_product_search_input = _build_oe_replacement_same_product_search_args(
                user_query,
                recent_user_context_text,
                confirmed_tire_size,
            )
            if same_product_search_input is not None:
                emitted_events: list[dict] = []
                from services.tstation.agents.b_discovery_agent.tools import (
                    search_product_tool as _search_product_tool,
                )
                from services.tstation.template_mapper import try_build_template

                tool_name = "search_product_tool"
                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": tool_name,
                    "display_name": "상품 검색 중...",
                    "source_domain": "discovery",
                })
                try:
                    raw_result = await asyncio.to_thread(_search_product_tool.invoke, same_product_search_input)
                    tool_result = _tool_result_dict(raw_result)
                except Exception as exc:
                    logger.exception("[OE_REPLACEMENT_FOLLOWUP] search tool failed")
                    tool_result = {
                        "status": "error",
                        "http_status": None,
                        "message": str(exc),
                        "data": {},
                    }
                _record_code_tool_result(tool_name, same_product_search_input, tool_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Product Search AF]",
                    "agent_class": "Discovery Agent",
                    "status": tool_result.get("status", "success"),
                    "source_domain": "discovery",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": same_product_search_input,
                    "output": json.dumps(tool_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": tool_name,
                    "source_domain": "discovery",
                })

                brand_label = _brand_label_for_code(str(same_product_search_input.get("brand_cd") or ""))
                intro = (
                    f"{brand_label} {confirmed_tire_size} 기준으로 동일 상품 후보를 찾았어요. "
                    "원하시는 상품을 선택해 주세요."
                )
                mapped_event = try_build_template(
                    [{"tool": tool_name, "args": same_product_search_input, "data": tool_result}],
                    intro,
                )
                if mapped_event is None:
                    return None
                mapped_event["source_domain"] = MultiAgentDomain.Domain.DISCOVERY.value
                mapped_event["assistant_response_source"] = "code_oe_replacement_same_product_search"
                return emitted_events, mapped_event

            followup_input = _build_oe_replacement_followup_recommendation_args(
                user_query,
                recent_user_context_text,
                confirmed_tire_size,
            )
            if followup_input is None:
                return None

            emitted_events: list[dict] = []
            from services.tstation.agents.b_discovery_agent.tools import (
                get_products_recommendations_tool as _recommendations_tool,
            )
            from services.tstation.template_mapper import try_build_template

            tool_name = "get_products_recommendations_tool"
            emitted_events.append({
                "type": "status",
                "status": "tool_start",
                "tool": tool_name,
                "display_name": "상품 추천 중...",
                "source_domain": "discovery",
            })
            try:
                raw_result = await asyncio.to_thread(_recommendations_tool.invoke, followup_input)
                tool_result = _tool_result_dict(raw_result)
            except Exception as exc:
                logger.exception("[OE_REPLACEMENT_FOLLOWUP] recommendations tool failed")
                tool_result = {
                    "status": "error",
                    "http_status": None,
                    "message": str(exc),
                    "data": {},
                }
            _record_code_tool_result(tool_name, followup_input, tool_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Product Recommendation AF]",
                "agent_class": "Discovery Agent",
                "status": tool_result.get("status", "success"),
                "source_domain": "discovery",
            })
            emitted_events.append({
                "type": "tool",
                "input": followup_input,
                "output": json.dumps(tool_result, ensure_ascii=False),
                "node": "tools",
                "tool": tool_name,
                "source_domain": "discovery",
            })

            intro = f"{confirmed_tire_size} 기준으로 찾은 상품입니다. 원하시는 상품을 선택해 주세요."
            mapped_event = try_build_template(
                [{"tool": tool_name, "args": followup_input, "data": tool_result}],
                intro,
            )
            if mapped_event is None:
                return None
            mapped_event["source_domain"] = MultiAgentDomain.Domain.DISCOVERY.value
            mapped_event["assistant_response_source"] = "code_oe_replacement_followup"
            return emitted_events, mapped_event

        async def _resolve_product_coupon_eligibility_with_code(
            my_coupons_result: dict | None = None,
            target_product_name: str | None = None,
        ) -> tuple[list[dict], dict] | None:
            restored_followup_target = _recent_product_coupon_followup_target_for_turn()
            target_product_name = (
                target_product_name
                or str((restored_followup_target or {}).get("product_name") or "").strip()
                or _coupon_target_product_name_for_query(user_query)
            )
            normalized_target = _split_product_size_quantity_from_text(target_product_name, user_query)
            if restored_followup_target:
                if not normalized_target.get("tire_size") and restored_followup_target.get("tire_size"):
                    normalized_target["tire_size"] = restored_followup_target["tire_size"]
                if not normalized_target.get("quantity") and restored_followup_target.get("quantity"):
                    normalized_target["quantity"] = restored_followup_target["quantity"]
            if (
                not normalized_target.get("product_name")
                and normalize_tire_size(user_query)
                and _recent_product_coupon_price_target(user_query, recent_user_context_text)
            ):
                normalized_target = _recent_product_coupon_price_target(user_query, recent_user_context_text) or normalized_target
            target_product_name = str(normalized_target.get("product_name") or "").strip()
            if not target_product_name:
                return None
            target_tire_size = str(normalized_target.get("tire_size") or "").strip()
            target_quantity = normalized_target.get("quantity")

            emitted_events: list[dict] = []
            specific_coupon_row: dict | None = None
            specific_coupon_hint = _specific_owned_coupon_lookup_hint(user_query)
            if specific_coupon_hint or _COUPON_DIRECT_ID_RE.search(user_query) or re.search(r"딜|deal", user_query, re.IGNORECASE):
                from services.tstation.agents.c_transaction_agent.tools import get_my_coupons_tool as _my_coupons_tool

                if my_coupons_result is None:
                    my_coupons_input = {"lang_cd": "ko"}
                    emitted_events.append({
                        "type": "status",
                        "status": "tool_start",
                        "tool": "get_my_coupons_tool",
                        "display_name": "내 쿠폰 조회 중...",
                        "source_domain": "transaction",
                    })
                    try:
                        raw_my_coupons = await asyncio.to_thread(_my_coupons_tool.invoke, my_coupons_input)
                        my_coupons_result = _tool_result_dict(raw_my_coupons)
                    except Exception as exc:
                        logger.exception("[PRODUCT_COUPON_RESOLVER] my coupons tool failed")
                        my_coupons_result = {
                            "status": "error",
                            "http_status": None,
                            "message": str(exc),
                            "data": {},
                        }
                    _record_code_tool_result("get_my_coupons_tool", my_coupons_input, my_coupons_result)
                    emitted_events.append({
                        "type": "agent_flow",
                        "agent": "[Price AF]",
                        "agent_class": "Transaction Agent",
                        "status": my_coupons_result.get("status", "success"),
                        "source_domain": "transaction",
                    })
                    emitted_events.append({
                        "type": "tool",
                        "input": my_coupons_input,
                        "output": json.dumps(my_coupons_result, ensure_ascii=False),
                        "node": "tools",
                        "tool": "get_my_coupons_tool",
                        "source_domain": "transaction",
                    })

                specific_coupon_row, ambiguous_coupons = _find_single_confident_coupon_from_owned_coupons(
                    user_query,
                    my_coupons_result,
                )
                if specific_coupon_row is None:
                    return emitted_events, _build_coupon_match_failure_event(user_query, ambiguous_coupons)
                if (
                    _is_specific_coupon_usage_query(user_query)
                    and _coupon_channel_type(specific_coupon_row) in {"store_only", "offline", "partner_only"}
                ):
                    channel_event = _build_coupon_channel_policy_event(
                        specific_coupon_row,
                        target_product_name=target_product_name,
                    )
                    if channel_event is not None:
                        return emitted_events, channel_event

            if (
                target_tire_size
                and target_quantity
                and (
                    _is_product_coupon_price_amount_query(user_query)
                    or _is_coupon_discount_amount_context(initial_slots)
                    or _recent_product_coupon_price_target(user_query, recent_user_context_text)
                )
            ):
                from services.tstation.agents.b_discovery_agent.tools import search_product_tool as _search_product_tool
                from services.tstation.agents.c_transaction_agent.tools import get_final_price_tool as _final_price_tool

                preferred_keyword = _preferred_product_search_keyword(target_product_name)
                search_input = {"keyword": preferred_keyword, "size": target_tire_size, "limit": 10}
                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "search_product_tool",
                    "display_name": "상품 검색 중...",
                    "source_domain": "discovery",
                })
                try:
                    raw_search = await asyncio.to_thread(_search_product_tool.invoke, search_input)
                    search_result = _tool_result_dict(raw_search)
                except Exception as exc:
                    logger.exception("[PRODUCT_COUPON_PRICE] search_product_tool failed for %s", preferred_keyword)
                    search_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
                _record_code_tool_result("search_product_tool", search_input, search_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Product Compatibility AF]",
                    "agent_class": "Discovery Agent",
                    "status": search_result.get("status", "success"),
                    "source_domain": "discovery",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": search_input,
                    "output": json.dumps(search_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "search_product_tool",
                    "source_domain": "discovery",
                })

                product_row = _unique_product_row_from_sized_search_result(
                    search_result,
                    preferred_keyword,
                    target_tire_size,
                )
                goods_no = str((product_row or {}).get("goods_no") or "").strip()
                if not goods_no:
                    fallback_search_input = {"keyword": preferred_keyword, "limit": 10}
                    emitted_events.append({
                        "type": "status",
                        "status": "tool_start",
                        "tool": "search_product_tool",
                        "display_name": "다른 규격 확인 중...",
                        "source_domain": "discovery",
                    })
                    try:
                        raw_fallback_search = await asyncio.to_thread(
                            _search_product_tool.invoke,
                            fallback_search_input,
                        )
                        fallback_search_result = _tool_result_dict(raw_fallback_search)
                    except Exception as exc:
                        logger.exception(
                            "[PRODUCT_COUPON_PRICE] fallback search_product_tool failed for %s",
                            preferred_keyword,
                        )
                        fallback_search_result = {
                            "status": "error",
                            "http_status": None,
                            "message": str(exc),
                            "data": {},
                        }
                    _record_code_tool_result("search_product_tool", fallback_search_input, fallback_search_result)
                    emitted_events.append({
                        "type": "agent_flow",
                        "agent": "[Product Compatibility AF]",
                        "agent_class": "Discovery Agent",
                        "status": fallback_search_result.get("status", "success"),
                        "source_domain": "discovery",
                    })
                    emitted_events.append({
                        "type": "tool",
                        "input": fallback_search_input,
                        "output": json.dumps(fallback_search_result, ensure_ascii=False),
                        "node": "tools",
                        "tool": "search_product_tool",
                        "source_domain": "discovery",
                    })
                    fallback_rows = _search_result_rows_for_product(
                        _search_product_rows_from_payload(fallback_search_result),
                        preferred_keyword,
                    )
                    fallback_sizes = _search_result_size_candidates(fallback_rows)
                    if fallback_sizes:
                        coupon_slots = {
                            "pending_intent": "price",
                            "goal_type": "coupon_discount_amount",
                            "pending_product_name": preferred_keyword,
                            "tire_model": preferred_keyword,
                            "ord_qty": int(target_quantity),
                        }
                        return emitted_events, _build_transaction_unresolved_product_size_clarification_event(
                            preferred_keyword,
                            fallback_sizes,
                            pending_intent="price",
                            slots=coupon_slots,
                        )
                    return emitted_events, _build_product_coupon_price_no_product_event(
                        preferred_keyword,
                        target_tire_size,
                        quantity=int(target_quantity),
                    )

                price_input = {"goods_no": goods_no}
                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "get_final_price_tool",
                    "display_name": "최종 혜택가 확인 중...",
                    "source_domain": "transaction",
                })
                try:
                    raw_price = await asyncio.to_thread(_final_price_tool.invoke, price_input)
                    price_result = _tool_result_dict(raw_price)
                except Exception as exc:
                    logger.exception("[PRODUCT_COUPON_PRICE] get_final_price_tool failed for %s", goods_no)
                    price_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
                _record_code_tool_result("get_final_price_tool", price_input, price_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Price AF]",
                    "agent_class": "Transaction Agent",
                    "status": price_result.get("status", "success"),
                    "source_domain": "transaction",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": price_input,
                    "output": json.dumps(price_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "get_final_price_tool",
                    "source_domain": "transaction",
                })
                price_event = _build_product_coupon_price_amount_event(
                    price_result,
                    product_name=str((product_row or {}).get("goods_nm") or target_product_name),
                    tire_size=target_tire_size,
                    quantity=int(target_quantity),
                )
                if price_event is not None:
                    return emitted_events, price_event
                return None

            from services.tstation.agents.c_transaction_agent.tools import (
                get_coupon_applicable_products_tool as _coupon_applicable_tool,
                get_my_coupons_tool as _my_coupons_tool,
            )

            if my_coupons_result is None:
                my_coupons_input = {"lang_cd": "ko"}
                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "get_my_coupons_tool",
                    "display_name": "내 쿠폰 조회 중...",
                    "source_domain": "transaction",
                })
                try:
                    raw_my_coupons = await asyncio.to_thread(_my_coupons_tool.invoke, my_coupons_input)
                    my_coupons_result = _tool_result_dict(raw_my_coupons)
                except Exception as exc:
                    logger.exception("[PRODUCT_COUPON_RESOLVER] my coupons tool failed")
                    my_coupons_result = {
                        "status": "error",
                        "http_status": None,
                        "message": str(exc),
                        "data": {},
                    }
                _record_code_tool_result("get_my_coupons_tool", my_coupons_input, my_coupons_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Price AF]",
                    "agent_class": "Transaction Agent",
                    "status": my_coupons_result.get("status", "success"),
                    "source_domain": "transaction",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": my_coupons_input,
                    "output": json.dumps(my_coupons_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "get_my_coupons_tool",
                    "source_domain": "transaction",
                })

            coupon_rows = [specific_coupon_row] if specific_coupon_row else _coupon_rows_from_my_coupons(my_coupons_result)
            cpn_nos = [str(row.get("cpn_no") or "").strip() for row in coupon_rows if str(row.get("cpn_no") or "").strip()]
            if not cpn_nos:
                return emitted_events, _coupon_box_event(
                    "현재 보유 쿠폰을 확인하지 못했어요. 쿠폰함에서 보유 쿠폰을 먼저 확인해 주세요."
                )

            followup_tool_name = "get_coupon_applicable_products_tool"
            followup_input = {"cpn_no": cpn_nos, "deal_no": None}
            emitted_events.append({
                "type": "status",
                "status": "tool_start",
                "tool": followup_tool_name,
                "display_name": "쿠폰 적용 상품 확인 중...",
                "source_domain": "transaction",
            })
            try:
                raw_followup = await asyncio.to_thread(_coupon_applicable_tool.invoke, followup_input)
                followup_result = _tool_result_dict(raw_followup)
            except Exception as exc:
                logger.exception("[PRODUCT_COUPON_RESOLVER] applicable products tool failed")
                followup_result = {
                    "status": "error",
                    "http_status": None,
                    "message": str(exc),
                    "data": {},
                }
            _record_code_tool_result(followup_tool_name, followup_input, followup_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Price AF]",
                "agent_class": "Transaction Agent",
                "status": followup_result.get("status", "success"),
                "source_domain": "transaction",
            })
            emitted_events.append({
                "type": "tool",
                "input": followup_input,
                "output": json.dumps(followup_result, ensure_ascii=False),
                "node": "tools",
                "tool": followup_tool_name,
                "source_domain": "transaction",
            })
            return emitted_events, _build_product_coupon_eligibility_event(
                followup_result,
                coupon_rows,
                target_product_name=target_product_name,
                target_brand=_coupon_target_brand_for_query(user_query),
            )

        async def _resolve_product_comparison_with_code(
            comparison_query_override: str | None = None,
        ) -> tuple[list[dict], dict] | None:
            comparison_query = comparison_query_override or _comparison_query_with_recent_context(
                user_query,
                messages,
                latest_quickreply_tmpl,
                slots=pending_slots or initial_slots,
            )
            product_names = _product_comparison_names(comparison_query)
            if len(product_names) < 2:
                return None
            frame = build_discovery_intent_frame(comparison_query)
            tire_size = frame.entities.get("tire_size") or getattr(initial_slots, "tire_size", None)

            emitted_events: list[dict] = []
            from services.tstation.agents.b_discovery_agent.tools import (
                get_product_description_tool as _get_product_description_tool,
            )
            from services.tstation.agents.b_discovery_agent.tools import search_product_tool as _search_product_tool

            product_rows: list[tuple[str, dict | None]] = []
            for product_name in product_names[:2]:
                keyword_candidates = _product_search_keyword_candidates(product_name)
                row: dict | None = None
                search_result: dict | None = None
                matched_keyword = ""
                for idx, keyword_candidate in enumerate(keyword_candidates):
                    tool_input = {"keyword": keyword_candidate, "limit": 10}
                    if tire_size:
                        tool_input["size"] = tire_size
                    emitted_events.append({
                        "type": "status",
                        "status": "tool_start",
                        "tool": "search_product_tool",
                        "display_name": "상품 검색 중...",
                        "source_domain": "discovery",
                    })
                    try:
                        raw_result = await asyncio.to_thread(_search_product_tool.invoke, tool_input)
                        search_result = _tool_result_dict(raw_result)
                    except Exception as exc:
                        logger.exception("[GRADE_COMPARE] search_product_tool failed for %s", product_name)
                        search_result = {
                            "status": "error",
                            "http_status": None,
                            "message": str(exc),
                            "data": {},
                        }
                    _record_code_tool_result("search_product_tool", tool_input, search_result)
                    emitted_events.append({
                        "type": "agent_flow",
                        "agent": "[Product Compatibility AF]",
                        "agent_class": "Discovery Agent",
                        "status": search_result.get("status", "success"),
                        "source_domain": "discovery",
                    })
                    emitted_events.append({
                        "type": "tool",
                        "input": tool_input,
                        "output": json.dumps(search_result, ensure_ascii=False),
                        "node": "tools",
                        "tool": "search_product_tool",
                        "source_domain": "discovery",
                    })
                    row = _pick_product_row_from_search_result(
                        search_result,
                        product_name,
                        *keyword_candidates,
                        keyword_candidate,
                        allow_first_row_fallback=idx == len(keyword_candidates) - 1,
                    )
                    if row is not None:
                        matched_keyword = keyword_candidate
                        break
                if row and row.get("goods_no"):
                    detail_input = {"goods_no": row["goods_no"]}
                    emitted_events.append({
                        "type": "status",
                        "status": "tool_start",
                        "tool": "get_product_description_tool",
                        "display_name": "상품 상세 정보 조회 중...",
                        "source_domain": "discovery",
                    })
                    try:
                        raw_detail = await asyncio.to_thread(_get_product_description_tool.invoke, detail_input)
                        detail_result = _tool_result_dict(raw_detail)
                    except Exception as exc:
                        logger.exception("[PRODUCT_COMPARE] get_product_description_tool failed for %s", row["goods_no"])
                        detail_result = {
                            "status": "error",
                            "http_status": None,
                            "message": str(exc),
                            "data": {},
                        }
                    _record_code_tool_result("get_product_description_tool", detail_input, detail_result)
                    emitted_events.append({
                        "type": "agent_flow",
                        "agent": "[Product Description AF]",
                        "agent_class": "Discovery Agent",
                        "status": detail_result.get("status", "success"),
                        "source_domain": "discovery",
                    })
                    emitted_events.append({
                        "type": "tool",
                        "input": detail_input,
                        "output": json.dumps(detail_result, ensure_ascii=False),
                        "node": "tools",
                        "tool": "get_product_description_tool",
                        "source_domain": "discovery",
                    })
                    detail_data = _unwrap_tool_data(detail_result)
                    if isinstance(detail_data, dict) and detail_data:
                        row = {**row, **detail_data}
                elif search_result is not None:
                    logger.info(
                        "[PRODUCT_COMPARE] unresolved comparison target after keyword fallbacks: %s candidates=%s matched_keyword=%s",
                        product_name,
                        keyword_candidates,
                        matched_keyword,
                    )
                product_rows.append((product_name, row))

            compare_event = _build_product_comparison_event(comparison_query, product_rows)
            _stage_comparison_context_slots(compare_event)
            return emitted_events, compare_event

        def _stage_comparison_context_slots(event: dict | None) -> None:
            nonlocal pending_slots
            values = _comparison_context_values_from_event(event)
            if not values:
                return
            from schemas.tstation.slots import ComparisonContext, ConversationSlots

            context = ComparisonContext.from_mapping(values.get("comparison_context"))
            if context is None:
                return
            base_slots = pending_slots
            if base_slots is None:
                base_slots = initial_slots.model_copy() if initial_slots is not None else ConversationSlots()
            updated_slots = base_slots.apply_runtime_values(
                {"comparison_context": context},
                source="comparison_event",
            )
            if updated_slots.model_dump() != base_slots.model_dump():
                pending_slots = updated_slots
                logger.info(
                    "[COMPARISON_CONTEXT] staged comparison context for next turn: %s",
                    context.to_policy_dict(),
                )

        async def _persist_pending_slots_for_direct_return() -> None:
            if not session_id or pending_slots is None:
                return
            try:
                from services.tstation.chat_history_service import get_chat_history_service

                history_svc = get_chat_history_service()
                await history_svc.save_slots_async(session_id, pending_slots, user_id=user_id)
            except Exception:
                logger.exception("[COMPARISON_CONTEXT] failed to persist direct-return pending slots")

        async def _resolve_multi_product_detail_with_code(
            product_names: tuple[str, ...],
        ) -> tuple[list[dict], dict] | None:
            if len(product_names) < 2:
                return None

            from services.tstation.agents.b_discovery_agent.tools import (
                get_product_description_tool as _get_product_description_tool,
            )
            from services.tstation.agents.b_discovery_agent.tools import search_product_tool as _search_product_tool

            frame = build_discovery_intent_frame(user_query)
            tire_size = frame.entities.get("tire_size") or getattr(initial_slots, "tire_size", None)
            tire_size = normalize_tire_size(str(tire_size or ""))
            size_specific = bool(tire_size)
            emitted_events: list[dict] = []
            product_rows: list[tuple[str, dict | None]] = []
            for product_name in product_names[:2]:
                preferred_keyword = _preferred_product_search_keyword(product_name)
                tool_input = {"keyword": preferred_keyword, "limit": 10}
                if tire_size:
                    tool_input["size"] = tire_size
                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "search_product_tool",
                    "display_name": "상품 검색 중...",
                    "source_domain": "discovery",
                })
                try:
                    raw_search = await asyncio.to_thread(_search_product_tool.invoke, tool_input)
                    search_result = _tool_result_dict(raw_search)
                except Exception as exc:
                    logger.exception("[MULTI_PRODUCT_DETAIL] search_product_tool failed for %s", product_name)
                    search_result = {
                        "status": "error",
                        "http_status": None,
                        "message": str(exc),
                        "data": {},
                    }
                _record_code_tool_result("search_product_tool", tool_input, search_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Product Compatibility AF]",
                    "agent_class": "Discovery Agent",
                    "status": search_result.get("status", "success"),
                    "source_domain": "discovery",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": tool_input,
                    "output": json.dumps(search_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "search_product_tool",
                    "source_domain": "discovery",
                })

                row = _pick_product_row_from_search_result(
                    search_result,
                    product_name,
                    preferred_keyword,
                    allow_first_row_fallback=True,
                )
                search_data = _unwrap_tool_data(search_result)
                search_rows = search_data.get("items") if isinstance(search_data, dict) else None
                available_sizes = _tire_sizes_from_product_rows(search_rows) if isinstance(search_rows, list) else []
                if row and row.get("goods_no"):
                    detail_input = {"goods_no": row["goods_no"]}
                    emitted_events.append({
                        "type": "status",
                        "status": "tool_start",
                        "tool": "get_product_description_tool",
                        "display_name": "상품 상세 정보 조회 중...",
                        "source_domain": "discovery",
                    })
                    try:
                        raw_detail = await asyncio.to_thread(_get_product_description_tool.invoke, detail_input)
                        detail_result = _tool_result_dict(raw_detail)
                    except Exception as exc:
                        logger.exception(
                            "[MULTI_PRODUCT_DETAIL] get_product_description_tool failed for %s",
                            row["goods_no"],
                        )
                        detail_result = {
                            "status": "error",
                            "http_status": None,
                            "message": str(exc),
                            "data": {},
                        }
                    _record_code_tool_result("get_product_description_tool", detail_input, detail_result)
                    emitted_events.append({
                        "type": "agent_flow",
                        "agent": "[Product Description AF]",
                        "agent_class": "Discovery Agent",
                        "status": detail_result.get("status", "success"),
                        "source_domain": "discovery",
                    })
                    emitted_events.append({
                        "type": "tool",
                        "input": detail_input,
                        "output": json.dumps(detail_result, ensure_ascii=False),
                        "node": "tools",
                        "tool": "get_product_description_tool",
                        "source_domain": "discovery",
                    })
                    detail_data = _unwrap_tool_data(detail_result)
                    if isinstance(detail_data, dict) and detail_data:
                        row = {**row, **detail_data}
                if row is not None and available_sizes:
                    row = {**row, "_available_tire_sizes": available_sizes}
                product_rows.append((product_name, row))

            return emitted_events, _build_multi_product_detail_quickreply_event(
                product_rows,
                size_specific=size_specific,
            )

        async def _resolve_product_attribute_with_code() -> tuple[list[dict], dict] | None:
            if is_external_price_comparison_request(user_query):
                return None
            if is_warranty_claim_signal(user_query):
                return None
            frame = build_discovery_intent_frame(user_query)
            if frame.sub_intent != "product_attribute_lookup":
                return None
            product_names = tuple(frame.entities.get("product_names") or ())
            if not product_names:
                return None

            from services.tstation.agents.b_discovery_agent.tools import search_product_tool as _search_product_tool

            product_name = product_names[0]
            preferred_keyword = _preferred_product_search_keyword(product_name)
            tool_input = {"keyword": preferred_keyword, "limit": 10}
            if frame.entities.get("tire_size"):
                tool_input["size"] = frame.entities["tire_size"]
            if frame.entities.get("brand_cd"):
                tool_input["brand_cd"] = frame.entities["brand_cd"]

            emitted_events: list[dict] = [{
                "type": "status",
                "status": "tool_start",
                "tool": "search_product_tool",
                "display_name": "상품 검색 중...",
                "source_domain": "discovery",
            }]
            try:
                raw_result = await asyncio.to_thread(_search_product_tool.invoke, tool_input)
                search_result = _tool_result_dict(raw_result)
            except Exception as exc:
                logger.exception("[PRODUCT_ATTRIBUTE] search_product_tool failed for %s", product_name)
                search_result = {
                    "status": "error",
                    "http_status": None,
                    "message": str(exc),
                    "data": {},
                }
            _record_code_tool_result("search_product_tool", tool_input, search_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Product Recommendation AF]",
                "agent_class": "Discovery Agent",
                "status": search_result.get("status", "success"),
                "source_domain": "discovery",
            })
            emitted_events.append({
                "type": "tool",
                "input": tool_input,
                "output": json.dumps(search_result, ensure_ascii=False),
                "node": "tools",
                "tool": "search_product_tool",
                "source_domain": "discovery",
            })

            event = _build_product_attribute_event_from_search_results(
                user_query,
                [(preferred_keyword, search_result)],
            )
            if event is None:
                return None
            return emitted_events, event

        async def _save_quantity_benefit_pending_slots(frame: Any) -> None:
            if not session_id:
                return
            product_names = tuple(frame.entities.get("product_names") or ())
            quantities = [int(quantity) for quantity in tuple(frame.entities.get("quantity_options") or (2, 4))[:2]]
            if not product_names or len(quantities) < 2:
                return
            base_slots = initial_slots.model_copy() if initial_slots is not None else ConversationSlots()
            base_slots.pending_intent = "quantity_benefit_comparison"
            base_slots.pending_product_name = str(product_names[0])
            base_slots.pending_quantity_options = quantities
            base_slots.pending_required_slot = "tire_size" if not frame.entities.get("tire_size") else "goods_no"
            try:
                from services.tstation.chat_history_service import get_chat_history_service

                history_svc = get_chat_history_service()
                await history_svc.save_slots_async(session_id, base_slots, user_id=user_id)
            except Exception as exc:
                logger.warning("[QTY_BENEFIT] failed to save pending slots: %s", exc)

        async def _clear_quantity_benefit_pending_slots() -> None:
            if not session_id or getattr(initial_slots, "pending_intent", None) != "quantity_benefit_comparison":
                return
            cleared_slots = initial_slots.model_copy()
            cleared_slots.pending_intent = None
            cleared_slots.pending_product_name = None
            cleared_slots.pending_quantity_options = None
            cleared_slots.pending_required_slot = None
            try:
                from services.tstation.chat_history_service import get_chat_history_service

                history_svc = get_chat_history_service()
                await history_svc.save_slots_async(session_id, cleared_slots, user_id=user_id)
            except Exception as exc:
                logger.warning("[QTY_BENEFIT] failed to clear pending slots: %s", exc)

        def _stage_resolved_product_slots_for_direct_return(
            *,
            goods_no: str,
            tire_size: str | None = None,
            product_name: str | None = None,
            pending_intent: str | None = None,
            goal_type: str | None = None,
        ) -> None:
            nonlocal pending_slots
            normalized_goods_no = str(goods_no or "").strip()
            if not normalized_goods_no:
                return

            from schemas.tstation.slots import ConversationSlots

            base_slots = pending_slots
            if base_slots is None:
                base_slots = initial_slots.model_copy() if initial_slots is not None else ConversationSlots()

            values: dict[str, Any] = {"goods_no": normalized_goods_no}
            normalized_tire_size = normalize_tire_size(tire_size or "")
            if normalized_tire_size:
                values["tire_size"] = normalized_tire_size
            normalized_product_name = str(product_name or "").strip()
            if normalized_product_name:
                values["tire_model"] = normalized_product_name
                values["pending_product_name"] = normalized_product_name
            if pending_intent:
                values["pending_intent"] = pending_intent
            if goal_type:
                values["goal_type"] = goal_type

            updated_slots = base_slots.apply_runtime_values(
                values,
                source="resolved_product_direct_return",
            )
            context = dict(updated_slots.availability_context or {})
            pending_order_context = dict(context.get("pending_order_context") or {})
            pending_order_context.update({
                "goods_no": normalized_goods_no,
            })
            if normalized_tire_size:
                pending_order_context["tire_size"] = normalized_tire_size
            if normalized_product_name:
                pending_order_context["product_name"] = normalized_product_name
            if pending_intent:
                pending_order_context["pending_intent"] = pending_intent
            if goal_type:
                pending_order_context["goal_type"] = goal_type
            context["pending_order_context"] = pending_order_context
            updated_slots.availability_context = context
            pending_slots = updated_slots
            logger.info(
                "[SLOTS] Staged resolved product for direct return: goods_no=%s tire_size=%s product=%s",
                normalized_goods_no,
                normalized_tire_size,
                normalized_product_name,
            )

        def _quantity_benefit_frame_with_recent_context() -> Any | None:
            known_slots: dict[str, Any] = {}
            if initial_slots is not None:
                if getattr(initial_slots, "tire_size", None):
                    known_slots["tire_size"] = initial_slots.tire_size
                if getattr(initial_slots, "goods_no", None):
                    known_slots["goods_no"] = initial_slots.goods_no
            current_frame = build_discovery_intent_frame(user_query, known_slots=known_slots)
            if current_frame.sub_intent == "quantity_benefit_comparison":
                return current_frame

            current_size = normalize_tire_size(user_query)
            current_goods_no = TStationChatServiceV2._resolve_goods_no_from_selection(
                user_query,
                prev_tool_data or [],
                current_tire_size=known_slots.get("tire_size") or current_size,
            )
            pending_frame = _quantity_benefit_continuation_frame_from_pending(
                user_query,
                slots=initial_slots,
                latest_quickreply_tmpl=latest_quickreply_tmpl,
                latest_product_tmpl=latest_product_tmpl,
                current_goods_no=current_goods_no,
            )
            if pending_frame is not None:
                return pending_frame
            if not (current_size or current_goods_no):
                return None

            for message in reversed(messages[:-1]):
                if str(message.get("role") or "") != "user":
                    continue
                previous_text = str(message.get("content") or "").strip()
                if not previous_text:
                    continue
                previous_frame = build_discovery_intent_frame(previous_text, known_slots=known_slots)
                if previous_frame.sub_intent != "quantity_benefit_comparison":
                    continue
                entities = dict(previous_frame.entities)
                if current_size:
                    entities["tire_size"] = current_size
                    entities["explicit_tire_size"] = current_size
                merged_slots = dict(previous_frame.known_slots)
                if current_goods_no:
                    merged_slots["goods_no"] = current_goods_no
                return replace(previous_frame, entities=entities, known_slots=merged_slots, missing_slots=())
            return None

        async def _resolve_quantity_benefit_comparison_with_code() -> tuple[list[dict], dict] | None:
            if domains and not any(
                domain in {MultiAgentDomain.Domain.DISCOVERY, MultiAgentDomain.Domain.TRANSACTION}
                for domain in domains
            ):
                return None

            frame = _quantity_benefit_frame_with_recent_context()
            if frame is None:
                return None

            quantities = tuple(frame.entities.get("quantity_options") or (2, 4))
            if len(quantities) < 2:
                return None
            quantities = tuple(sorted(int(quantity) for quantity in quantities[:2]))

            confirmed_tire_size = (
                frame.entities.get("tire_size")
                or (getattr(initial_slots, "tire_size", None) if initial_slots is not None else None)
            )
            goods_no = str(frame.known_slots.get("goods_no") or "").strip()
            if not goods_no and initial_slots is not None:
                goods_no = str(getattr(initial_slots, "goods_no", None) or "").strip()
            if not goods_no:
                goods_no = TStationChatServiceV2._resolve_goods_no_from_selection(
                    user_query,
                    prev_tool_data or [],
                    current_tire_size=confirmed_tire_size,
                ) or ""

            emitted_events: list[dict] = []
            product_names = tuple(frame.entities.get("product_names") or ())
            if not goods_no:
                if not confirmed_tire_size or not product_names:
                    await _save_quantity_benefit_pending_slots(frame)
                    return emitted_events, _build_quantity_benefit_missing_event(frame)

                from services.tstation.agents.b_discovery_agent.tools import search_product_tool as _search_product_tool
                from services.tstation.template_mapper import try_build_template

                preferred_keyword = _preferred_product_search_keyword(str(product_names[0]))
                search_input = {"keyword": preferred_keyword, "size": confirmed_tire_size, "limit": 10}
                if frame.entities.get("brand_cd"):
                    search_input["brand_cd"] = frame.entities["brand_cd"]

                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "search_product_tool",
                    "display_name": "상품 검색 중...",
                    "source_domain": "discovery",
                })
                try:
                    raw_search = await asyncio.to_thread(_search_product_tool.invoke, search_input)
                    search_result = _tool_result_dict(raw_search)
                except Exception as exc:
                    logger.exception("[QTY_BENEFIT] search_product_tool failed for %s", preferred_keyword)
                    search_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
                _record_code_tool_result("search_product_tool", search_input, search_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Product Search AF]",
                    "agent_class": "Discovery Agent",
                    "status": search_result.get("status", "success"),
                    "source_domain": "discovery",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": search_input,
                    "output": json.dumps(search_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "search_product_tool",
                    "source_domain": "discovery",
                })

                row = _unique_product_row_from_sized_search_result(
                    search_result,
                    preferred_keyword,
                    str(confirmed_tire_size),
                )
                goods_no = str((row or {}).get("goods_no") or "").strip()
                if not goods_no:
                    mapped_event = try_build_template(
                        [{"tool": "search_product_tool", "args": search_input, "data": search_result}],
                        (
                            f"{preferred_keyword} {confirmed_tire_size} 기준 상품을 찾았어요. "
                            f"상품을 선택해 주시면 {quantities[0]}개/{quantities[1]}개 혜택을 비교해 드릴게요."
                        ),
                    )
                    if mapped_event is None:
                        await _clear_quantity_benefit_pending_slots()
                        return emitted_events, _build_quantity_benefit_not_found_event(
                            preferred_keyword,
                            str(confirmed_tire_size),
                        )
                    mapped_goods_no = _goods_no_from_template_event(mapped_event)
                    if mapped_goods_no:
                        goods_no = mapped_goods_no
                    else:
                        event_data = mapped_event.get("data")
                        if isinstance(event_data, dict):
                            event_data["quantityBenefitComparison"] = {
                                "pendingIntent": "quantity_benefit_comparison",
                                "quantityOptions": list(quantities),
                                "productName": str(product_names[0]),
                                "missingSlot": "goods_no",
                            }
                        mapped_event["source_domain"] = MultiAgentDomain.Domain.DISCOVERY.value
                        mapped_event["assistant_response_source"] = "code_quantity_benefit_product_selection"
                        return emitted_events, mapped_event

            from services.tstation.agents.b_discovery_agent.tools import (
                get_cheapest_price_tool as _get_cheapest_price_tool,
            )

            price_results: dict[int, dict] = {}
            for quantity in quantities:
                price_input = {"goods_no_list": [goods_no], "quantity": quantity}
                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "get_cheapest_price_tool",
                    "display_name": "혜택가 조회 중...",
                    "source_domain": "transaction",
                })
                try:
                    raw_price = await asyncio.to_thread(_get_cheapest_price_tool.invoke, price_input)
                    price_result = _tool_result_dict(raw_price)
                except Exception as exc:
                    logger.exception("[QTY_BENEFIT] get_cheapest_price_tool failed goods_no=%s qty=%s", goods_no, quantity)
                    price_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
                price_results[quantity] = price_result
                _record_code_tool_result("get_cheapest_price_tool", price_input, price_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Price AF]",
                    "agent_class": "Transaction Agent",
                    "status": price_result.get("status", "success"),
                    "source_domain": "transaction",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": price_input,
                    "output": json.dumps(price_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "get_cheapest_price_tool",
                    "source_domain": "transaction",
                })

            comparison_event = _build_quantity_benefit_comparison_event(price_results)
            if comparison_event is None:
                await _clear_quantity_benefit_pending_slots()
                return emitted_events, _build_quantity_benefit_missing_event(frame)
            await _clear_quantity_benefit_pending_slots()
            return emitted_events, comparison_event

        async def _resolve_bare_product_search_with_code() -> tuple[list[dict], dict] | None:
            if _router_contract_is_high_confidence_event_content(routing_result):
                return None
            followup_override = _bare_product_search_followup_override(
                user_query,
                context_text=recent_user_context_text,
                routing_result=routing_result,
                pending_intent=getattr(initial_slots, "pending_intent", None) if initial_slots is not None else None,
                goal_type=getattr(initial_slots, "goal_type", None) if initial_slots is not None else None,
                pending_check_topic=getattr(initial_slots, "pending_check_topic", None) if initial_slots is not None else None,
                pending_check_object_type=(
                    getattr(initial_slots, "pending_check_object_type", None) if initial_slots is not None else None
                ),
            )
            if followup_override is not None:
                if followup_override["action"] == "agent":
                    # Supported carried objectives must stay on the deterministic
                    # Discovery policy/tool path rather than collapsing into a
                    # generic code_bare_product_search description.
                    return None
                return [], _build_product_objective_followup_clarification_event(
                    followup_override.get("objective")
                )
            size_only_tool_input = _build_size_only_product_search_tool_input(
                user_query,
                prev_tool_data=prev_tool_data or [],
                recent_context=recent_user_context_text,
                slots=initial_slots,
            )
            is_store_availability_size_followup = _is_size_only_store_availability_continuation(
                user_query,
                prev_tool_data=prev_tool_data or [],
                recent_context=recent_user_context_text,
                messages=messages,
                slots=initial_slots,
            )
            if (
                not is_store_availability_size_followup
                and domains != [MultiAgentDomain.Domain.DISCOVERY]
            ) and not (
                size_only_tool_input
                and domains
                and MultiAgentDomain.Domain.DISCOVERY in domains
            ):
                return None
            confirmed_tire_size = getattr(initial_slots, "tire_size", None) if initial_slots is not None else None
            if size_only_tool_input is None and TStationChatServiceV2._resolve_goods_no_from_selection(
                user_query,
                prev_tool_data or [],
                current_tire_size=confirmed_tire_size,
            ):
                return None
            if not (
                _is_bare_product_name_search_query(user_query)
                or _is_sized_product_name_search_query(user_query)
                or size_only_tool_input is not None
            ):
                return None

            tool_input = _build_bare_product_search_tool_input(user_query) or size_only_tool_input
            if tool_input is None:
                return None

            from services.tstation.agents.b_discovery_agent.tools import (
                get_product_description_tool as _get_product_description_tool,
            )
            from services.tstation.agents.b_discovery_agent.tools import search_product_tool as _search_product_tool
            from services.tstation.agents.c_transaction_agent.tools import get_final_price_tool as _final_price_tool
            from services.tstation.agents.c_transaction_agent.tools import (
                transaction_store_preview_tool as _transaction_store_preview_tool,
            )
            from services.tstation.template_mapper import try_build_template

            product_name = str(tool_input.get("keyword") or "")
            preferred_keyword = product_name

            emitted_events: list[dict] = [{
                "type": "status",
                "status": "tool_start",
                "tool": "search_product_tool",
                "display_name": "상품 검색 중...",
                "source_domain": "discovery",
            }]
            try:
                raw_result = await asyncio.to_thread(_search_product_tool.invoke, tool_input)
                search_result = _tool_result_dict(raw_result)
            except Exception as exc:
                logger.exception("[PRODUCT_SEARCH] search_product_tool failed for %s", product_name)
                search_result = {
                    "status": "error",
                    "http_status": None,
                    "message": str(exc),
                    "data": {},
                }
            _record_code_tool_result("search_product_tool", tool_input, search_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Product Compatibility AF]",
                "agent_class": "Discovery Agent",
                "status": search_result.get("status", "success"),
                "source_domain": "discovery",
            })
            emitted_events.append({
                "type": "tool",
                "input": tool_input,
                "output": json.dumps(search_result, ensure_ascii=False),
                "node": "tools",
                "tool": "search_product_tool",
                "source_domain": "discovery",
            })

            if tool_input.get("size"):
                row = _unique_product_row_from_sized_search_result(
                    search_result,
                    preferred_keyword,
                    str(tool_input.get("size") or ""),
                )
                goods_no = str((row or {}).get("goods_no") or "").strip()
                if goods_no:
                    _stage_resolved_product_slots_for_direct_return(
                        goods_no=goods_no,
                        tire_size=str(tool_input.get("size") or ""),
                        product_name=preferred_keyword,
                        pending_intent="stock" if is_store_availability_size_followup else None,
                        goal_type="store_with_stock" if is_store_availability_size_followup else None,
                    )
                    if is_store_availability_size_followup:
                        tire_size = str(tool_input.get("size") or "")
                        ord_qty = getattr(initial_slots, "ord_qty", None) if initial_slots is not None else None
                        try:
                            ord_qty = int(ord_qty) if ord_qty is not None else None
                        except (TypeError, ValueError):
                            ord_qty = None
                        store_name = _recent_store_name_for_availability_continuation(
                            prev_tool_data=prev_tool_data or [],
                            recent_context=recent_user_context_text,
                            messages=messages,
                            slots=initial_slots,
                        )
                        requested_day_label = _requested_day_label_from_availability_context(
                            user_query,
                            recent_user_context_text,
                        )
                        if not ord_qty:
                            return emitted_events, _build_store_availability_quantity_prompt_event(
                                product_keyword=preferred_keyword,
                                tire_size=tire_size,
                                store_name=store_name,
                                goods_no=goods_no,
                                requested_day_label=requested_day_label,
                            )
                        if not store_name:
                            return emitted_events, _build_store_availability_quantity_prompt_event(
                                product_keyword=preferred_keyword,
                                tire_size=tire_size,
                                store_name=None,
                                goods_no=goods_no,
                                requested_day_label=requested_day_label,
                            )

                        preview_input = {
                            "goods_no": goods_no,
                            "ord_qty": ord_qty,
                            "store_nm": store_name,
                            "include_price": True,
                        }
                        requested_cal_day = _requested_cal_day_from_availability_context(
                            user_query,
                            recent_user_context_text,
                        )
                        if requested_cal_day:
                            preview_input["requested_cal_day"] = requested_cal_day
                        emitted_events.append({
                            "type": "status",
                            "status": "tool_start",
                            "tool": "transaction_store_preview_tool",
                            "display_name": "장착 가능 일정 확인 중...",
                            "source_domain": "transaction",
                        })
                        try:
                            raw_preview = await asyncio.to_thread(
                                _transaction_store_preview_tool.invoke,
                                preview_input,
                            )
                            preview_result = _tool_result_dict(raw_preview)
                        except Exception as exc:
                            logger.exception(
                                "[STORE_AVAILABILITY_SIZE_FOLLOWUP] transaction_store_preview_tool failed goods_no=%s",
                                goods_no,
                            )
                            preview_result = {
                                "status": "error",
                                "http_status": None,
                                "message": str(exc),
                                "data": {},
                            }
                        _record_code_tool_result("transaction_store_preview_tool", preview_input, preview_result)
                        emitted_events.append({
                            "type": "agent_flow",
                            "agent": "[Store/Stock AF]",
                            "agent_class": "Transaction Agent",
                            "status": preview_result.get("status", "success"),
                            "source_domain": "transaction",
                        })
                        emitted_events.append({
                            "type": "tool",
                            "input": preview_input,
                            "output": json.dumps(preview_result, ensure_ascii=False),
                            "node": "tools",
                            "tool": "transaction_store_preview_tool",
                            "source_domain": "transaction",
                        })
                        intro = f"{preferred_keyword} {tire_size} {ord_qty}개 기준으로 {store_name} 장착 가능 여부를 확인했어요."
                        mapped_event = try_build_template(
                            [
                                {"tool": "search_product_tool", "args": tool_input, "data": search_result},
                                {
                                    "tool": "transaction_store_preview_tool",
                                    "args": preview_input,
                                    "data": preview_result,
                                },
                            ],
                            intro,
                        )
                        if mapped_event is not None:
                            mapped_event["source_domain"] = MultiAgentDomain.Domain.TRANSACTION.value
                            mapped_event["assistant_response_source"] = "code_store_availability_size_followup"
                            return emitted_events, mapped_event
                        return emitted_events, _build_store_availability_quantity_prompt_event(
                            product_keyword=preferred_keyword,
                            tire_size=tire_size,
                            store_name=store_name,
                            goods_no=goods_no,
                            requested_day_label=requested_day_label,
                        )

                    if _is_coupon_discount_amount_context(initial_slots):
                        tire_size = str(tool_input.get("size") or "")
                        try:
                            target_quantity = int(getattr(initial_slots, "ord_qty", None) or 1)
                        except (TypeError, ValueError):
                            target_quantity = 1
                        price_input = {"goods_no": goods_no}
                        emitted_events.append({
                            "type": "status",
                            "status": "tool_start",
                            "tool": "get_final_price_tool",
                            "display_name": "최종 혜택가 확인 중...",
                            "source_domain": "transaction",
                        })
                        try:
                            raw_price = await asyncio.to_thread(_final_price_tool.invoke, price_input)
                            price_result = _tool_result_dict(raw_price)
                        except Exception as exc:
                            logger.exception("[PRODUCT_COUPON_PRICE_FOLLOWUP] get_final_price_tool failed for %s", goods_no)
                            price_result = {
                                "status": "error",
                                "http_status": None,
                                "message": str(exc),
                                "data": {},
                            }
                        _record_code_tool_result("get_final_price_tool", price_input, price_result)
                        emitted_events.append({
                            "type": "agent_flow",
                            "agent": "[Price AF]",
                            "agent_class": "Transaction Agent",
                            "status": price_result.get("status", "success"),
                            "source_domain": "transaction",
                        })
                        emitted_events.append({
                            "type": "tool",
                            "input": price_input,
                            "output": json.dumps(price_result, ensure_ascii=False),
                            "node": "tools",
                            "tool": "get_final_price_tool",
                            "source_domain": "transaction",
                        })
                        price_event = _build_product_coupon_price_amount_event(
                            price_result,
                            product_name=str((row or {}).get("goods_nm") or preferred_keyword),
                            tire_size=tire_size,
                            quantity=target_quantity,
                        )
                        if price_event is not None:
                            return emitted_events, price_event
                        return emitted_events, _build_product_coupon_price_no_product_event(
                            str(getattr(initial_slots, "pending_product_name", None) or preferred_keyword),
                            tire_size,
                            quantity=target_quantity,
                        )

                    detail_input = {"goods_no": goods_no}
                    emitted_events.append({
                        "type": "status",
                        "status": "tool_start",
                        "tool": "get_product_description_tool",
                        "display_name": "상품 상세 정보 조회 중...",
                        "source_domain": "discovery",
                    })
                    try:
                        raw_detail = await asyncio.to_thread(_get_product_description_tool.invoke, detail_input)
                        detail_result = _tool_result_dict(raw_detail)
                    except Exception as exc:
                        logger.exception("[PRODUCT_SEARCH] get_product_description_tool failed for %s", goods_no)
                        detail_result = {
                            "status": "error",
                            "http_status": None,
                            "message": str(exc),
                            "data": {},
                        }
                    _record_code_tool_result("get_product_description_tool", detail_input, detail_result)
                    emitted_events.append({
                        "type": "agent_flow",
                        "agent": "[Product Description AF]",
                        "agent_class": "Discovery Agent (Search)",
                        "status": detail_result.get("status", "success"),
                        "source_domain": "discovery",
                    })
                    emitted_events.append({
                        "type": "tool",
                        "input": detail_input,
                        "output": json.dumps(detail_result, ensure_ascii=False),
                        "node": "tools",
                        "tool": "get_product_description_tool",
                        "source_domain": "discovery",
                    })
                    detail_event = _build_product_description_quickreply_event(detail_result)
                    if detail_event is not None:
                        return emitted_events, detail_event
                elif (
                    size_only_tool_input is not None
                    and initial_slots is not None
                    and (
                        getattr(initial_slots, "pending_intent", None) == "price"
                        or getattr(initial_slots, "goal_type", None) == "price_inquiry"
                    )
                    and str(getattr(initial_slots, "pending_product_name", None) or "").strip()
                ):
                    return emitted_events, _build_product_coupon_price_no_product_event(
                        str(getattr(initial_slots, "pending_product_name", None) or preferred_keyword),
                        str(tool_input.get("size") or ""),
                        quantity=getattr(initial_slots, "ord_qty", None),
                    )

            mapped_event = try_build_template(
                [{"tool": "search_product_tool", "args": tool_input, "data": search_result}],
                f"{preferred_keyword} 검색 결과입니다. 원하시는 상품을 선택해 주세요.",
            )
            if mapped_event is None:
                return None
            if not tool_input.get("size") and mapped_event.get("template") != "quickReply":
                logger.warning(
                    "[PRODUCT_SEARCH] unsized bare product search mapped to %s; falling back to agent",
                    mapped_event.get("template"),
                )
                return None
            mapped_event["source_domain"] = MultiAgentDomain.Domain.DISCOVERY.value
            mapped_event["assistant_response_source"] = "code_bare_product_search"
            return emitted_events, mapped_event

        async def _resolve_multi_variant_recommendation_with_code() -> tuple[list[dict], dict] | None:
            stored_context = None
            if initial_slots is not None:
                stored_variants = getattr(initial_slots, "recommendation_variants", None)
                if stored_variants:
                    stored_context = {
                        "variants": stored_variants,
                        "limit_per_variant": getattr(initial_slots, "recommendation_limit_per_variant", None),
                        "source_text": getattr(initial_slots, "recommendation_source_text", None),
                    }
            constraints = _infer_multi_variant_recommendation_constraints(
                messages,
                user_query,
                stored_context=stored_context,
            )
            if not constraints:
                return None

            source_frame = constraints["source_frame"]
            variants = tuple(constraints.get("variants") or ())
            if len(variants) < 2:
                return None

            current_frame = build_discovery_intent_frame(user_query)
            tire_size = (
                current_frame.entities.get("tire_size")
                or source_frame.entities.get("tire_size")
            )
            if not tire_size:
                return None

            merged_entities = dict(source_frame.entities)
            merged_entities["tire_size"] = tire_size
            merged_entities["explicit_tire_size"] = tire_size
            merged_entities["variant_constraints"] = variants
            merged_entities.pop("brand_cd", None)
            merged_frame = replace(source_frame, entities=merged_entities)
            tool_plan = plan_discovery_tools(merged_frame)
            if tool_plan.preferred_tool != "get_products_recommendations_tool":
                return None

            base_args = dict(tool_plan.tool_args_patch)
            base_args.pop("brand_cd", None)
            base_args.setdefault("rcmd_type", "tstation")
            base_args["tire_size"] = tire_size
            base_args["limit"] = int(constraints.get("limit_per_variant") or 1)
            base_args["allow_cross_brand_fill"] = False
            base_args["ignore_policy_patch"] = True

            from services.tstation.agents.b_discovery_agent.tools import (
                get_products_recommendations_tool as _recommendations_tool,
            )
            from services.tstation.template_mapper import try_build_template

            emitted_events: list[dict] = []
            accumulated_tool_data: list[dict] = []
            resolved_variants: list[dict[str, Any]] = []
            for variant in variants:
                tool_input = dict(base_args)
                tool_input.update(dict(variant))
                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "get_products_recommendations_tool",
                    "display_name": "상품 추천 중...",
                    "source_domain": "discovery",
                })
                try:
                    raw_result = await asyncio.to_thread(_recommendations_tool.func, **tool_input)
                    tool_result = _tool_result_dict(raw_result)
                except Exception as exc:
                    logger.exception("[MULTI_VARIANT] recommendation tool failed for variant=%s", variant)
                    tool_result = {
                        "status": "error",
                        "http_status": None,
                        "message": str(exc),
                        "data": {},
                    }
                _record_code_tool_result("get_products_recommendations_tool", tool_input, tool_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Product Recommendation AF]",
                    "agent_class": "Discovery Agent",
                    "status": tool_result.get("status", "success"),
                    "source_domain": "discovery",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": tool_input,
                    "output": json.dumps(tool_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "get_products_recommendations_tool",
                    "source_domain": "discovery",
                })
                data = tool_result.get("data") if isinstance(tool_result, dict) else None
                items = data.get("items") if isinstance(data, dict) else None
                if isinstance(items, list) and items:
                    accumulated_tool_data.append({
                        "tool": "get_products_recommendations_tool",
                        "args": tool_input,
                        "data": tool_result,
                    })
                    resolved_variants.append(dict(variant))

            if not accumulated_tool_data:
                return None

            variant_count = len(resolved_variants)
            requested_count = len(variants)
            if variant_count == requested_count:
                intro = (
                    f"{tire_size} 기준으로 요청하신 조건별 추천 상품을 확인했어요. "
                    "원하시는 상품을 선택해 주세요."
                )
            else:
                intro = (
                    f"{tire_size} 기준으로 요청하신 조건 중 추천 가능한 상품 {variant_count}개를 확인했어요. "
                    "원하시는 상품을 선택해 주세요."
                )

            mapped_event = try_build_template(accumulated_tool_data, intro)
            if mapped_event is None:
                return None
            mapped_event["source_domain"] = MultiAgentDomain.Domain.DISCOVERY.value
            mapped_event["assistant_response_source"] = "code_multi_variant_recommendation"
            return emitted_events, mapped_event

        async def _auto_continue_selected_vehicle(
            listcar_event: dict,
        ) -> tuple[list[dict], dict | None]:
            nonlocal pending_slots
            if _VEHICLE_LIST_REQUEST_RE.search(user_query or ""):
                return [], None
            event_data = listcar_event.get("data")
            if not isinstance(event_data, dict):
                return [], None
            selected = _select_vehicle_from_listcar_event(user_query, event_data)
            if selected is None:
                return [], None

            vehicle_slot_values = _vehicle_selection_slot_values(selected)
            if vehicle_slot_values:
                from schemas.tstation.slots import ConversationSlots

                base_slots = pending_slots
                if base_slots is None:
                    base_slots = initial_slots.model_copy() if initial_slots is not None else ConversationSlots()
                updated_slots = _apply_vehicle_selection_slot_values(base_slots, vehicle_slot_values)
                if updated_slots.model_dump() != base_slots.model_dump():
                    pending_slots = updated_slots
                    logger.info(
                        "[VEHICLE_AUTO_SELECT] staged vehicle slots for next turn: %s",
                        vehicle_slot_values,
                    )

            source_domain = str(listcar_event.get("source_domain") or "").lower()
            selected_car = selected.get("car") or {}
            selected_meta = selected.get("meta") or {}
            car_info = str(selected_car.get("info") or selected_car.get("description") or "선택하신 차량").strip()
            car_no = str(selected_meta.get("carNo") or selected_car.get("licensePlate") or "").strip()
            vehicle_type = str(vehicle_slot_values.get("vehicle_type") or "").strip()

            def _active_purchase_slots() -> Any | None:
                slots = pending_slots or initial_slots
                if slots is None:
                    return None
                if getattr(slots, "pending_intent", None) == "order" or getattr(slots, "goal_type", None) == "place_order":
                    return slots
                return None

            def _recent_product_search_context() -> tuple[str, str | None]:
                for entry in reversed(prev_tool_data or []):
                    if entry.get("tool") != "search_product_tool":
                        continue
                    tool_input = entry.get("input") if isinstance(entry.get("input"), dict) else entry.get("args")
                    keyword = ""
                    brand_cd = None
                    if isinstance(tool_input, dict):
                        keyword = str(tool_input.get("keyword") or "").strip()
                        brand_cd = str(tool_input.get("brand_cd") or "").strip() or None
                    if keyword:
                        return _preferred_product_search_keyword(keyword), brand_cd
                    data = _unwrap_tool_data(entry.get("data"))
                    rows = data.get("items") if isinstance(data, dict) else None
                    if isinstance(rows, list):
                        for row in rows:
                            if not isinstance(row, dict):
                                continue
                            row_name = str(canonical_context_from_tool_boundary(row).get("product_name") or "").strip()
                            if row_name:
                                return _preferred_product_search_keyword(row_name), brand_cd
                return "", None

            def _purchase_product_keyword(slots: Any) -> tuple[str, str | None]:
                slot_model = str(getattr(slots, "tire_model", None) or "").strip()
                if slot_model:
                    return _preferred_product_search_keyword(slot_model), None
                keyword, brand_cd = _recent_product_search_context()
                if keyword:
                    return keyword, brand_cd
                frame = build_discovery_intent_frame(recent_user_context_text)
                product_names = frame.entities.get("product_names") or ()
                if product_names:
                    return _preferred_product_search_keyword(str(product_names[0])), frame.entities.get("brand_cd")
                transaction_frame = build_transaction_intent_frame(recent_user_context_text)
                product_name = str(transaction_frame.known_slots.get("product_name") or "").strip()
                if product_name:
                    return _preferred_product_search_keyword(product_name), None
                return "", None

            def _purchase_store_name(slots: Any) -> str:
                slot_store = str(getattr(slots, "shop_name", None) or "").strip()
                if slot_store:
                    return slot_store
                frame = build_transaction_intent_frame(recent_user_context_text)
                return str(frame.known_slots.get("store_name") or "").strip()

            def _purchase_quantity(slots: Any) -> int | None:
                slot_qty = getattr(slots, "ord_qty", None)
                if slot_qty:
                    try:
                        return int(slot_qty)
                    except (TypeError, ValueError):
                        pass
                frame = build_transaction_intent_frame(recent_user_context_text)
                frame_qty = frame.known_slots.get("quantity") or frame.known_slots.get("ord_qty")
                if frame_qty:
                    try:
                        return int(frame_qty)
                    except (TypeError, ValueError):
                        return None
                return None

            def _purchase_vehicle_missing_event(product_keyword: str, tire_size: str, reason: str) -> dict:
                if reason == "quantity":
                    response = f"{product_keyword} {tire_size} 상품은 확인했어요. 구매 수량을 알려주시면 이어서 확인할게요."
                    quick_replies = [
                        {"label": "2개", "domain": "TRANSACTION"},
                        {"label": "4개", "domain": "TRANSACTION"},
                    ]
                elif reason == "store":
                    response = (
                        f"{product_keyword} {tire_size} 상품은 확인했어요. "
                        "장착 가능 여부를 확인할 매장명이나 지역을 알려주세요."
                    )
                    quick_replies = [
                        {"label": "근처 매장 찾기", "domain": "TRANSACTION"},
                        {"label": "매장명 입력", "domain": "TRANSACTION"},
                    ]
                else:
                    response = (
                        f"{product_keyword} 상품은 확인했지만 {car_info} ({car_no})의 규격 {tire_size}에 맞는 "
                        "상품을 찾지 못했어요. 다른 상품으로 찾아드릴까요?"
                    )
                    quick_replies = [
                        {"label": "대체상품 추천", "domain": "DISCOVERY"},
                        {"label": "사이즈 직접 입력", "domain": "DISCOVERY"},
                    ]
                return {
                    "type": "data",
                    "template": "quickReply",
                    "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
                    "assistant_response_source": "code_vehicle_purchase_continuation",
                    "data": {
                        "assistantResponse": response,
                        "quickReplies": quick_replies,
                        "predictedDomains": ["TRANSACTION", "DISCOVERY"],
                    },
                }

            if source_domain == MultiAgentDomain.Domain.SUPPORT.value or _MAINTENANCE_DDAY_TEXT_RE.search(user_query):
                from services.tstation.agents.e_support_agent.tools import (
                    get_maintenance_dday_tool as _maintenance_dday_tool,
                )

                tool_name = "get_maintenance_dday_tool"
                tool_input = {"mbr_car_reg_seq": selected_meta.get("mbrCarRegSeq") or None}
                emitted_events = [{
                    "type": "status",
                    "status": "tool_start",
                    "tool": tool_name,
                    "display_name": "정비 일정 조회 중...",
                    "source_domain": "support",
                }]
                try:
                    raw_result = await asyncio.to_thread(_maintenance_dday_tool.invoke, tool_input)
                    tool_result = _tool_result_dict(raw_result)
                except Exception as exc:
                    logger.exception("[VEHICLE_AUTO_SELECT] maintenance D-day tool failed")
                    tool_result = {
                        "status": "error",
                        "http_status": None,
                        "message": str(exc),
                        "data": {},
                    }
                _record_code_tool_result(tool_name, tool_input, tool_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[FAQ AF]",
                    "agent_class": "Support Agent",
                    "status": tool_result.get("status", "success"),
                    "source_domain": "support",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": tool_input,
                    "output": json.dumps(tool_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": tool_name,
                    "source_domain": "support",
                })
                return emitted_events, _build_maintenance_dday_event(tool_result, selected, user_query)

            vehicle_info_event = _build_vehicle_information_event(selected, user_query)
            if vehicle_info_event is not None:
                return [], vehicle_info_event

            if _is_oe_replacement_context(recent_user_context_text, user_query):
                return [], _build_oe_replacement_guidance_event(selected, user_query)

            if not (
                source_domain == MultiAgentDomain.Domain.DISCOVERY.value
                or _VEHICLE_RECOMMENDATION_TEXT_RE.search(user_query)
            ):
                return [], None

            staggered_tire_event = _build_staggered_vehicle_tire_selection_event(selected)
            if staggered_tire_event is not None:
                return [], staggered_tire_event

            tire_size = selected_meta.get("tireSize")
            car_lnc_cd = selected_meta.get("carLncCd")
            if not (tire_size or car_lnc_cd):
                return [], None

            purchase_slots = _active_purchase_slots()
            if purchase_slots is not None and tire_size:
                product_keyword, brand_cd = _purchase_product_keyword(purchase_slots)
                if product_keyword:
                    from services.tstation.agents.b_discovery_agent.tools import search_product_tool as _search_product_tool
                    from services.tstation.agents.c_transaction_agent.tools import (
                        transaction_store_preview_tool as _transaction_store_preview_tool,
                    )
                    from services.tstation.template_mapper import try_build_template

                    search_input = {"keyword": product_keyword, "size": tire_size, "limit": 10}
                    if brand_cd:
                        search_input["brand_cd"] = brand_cd
                    emitted_events = [{
                        "type": "status",
                        "status": "tool_start",
                        "tool": "search_product_tool",
                        "display_name": "상품 검색 중...",
                        "source_domain": "discovery",
                    }]
                    try:
                        raw_search = await asyncio.to_thread(_search_product_tool.invoke, search_input)
                        search_result = _tool_result_dict(raw_search)
                    except Exception as exc:
                        logger.exception("[VEHICLE_PURCHASE_CONTINUE] search_product_tool failed for %s", product_keyword)
                        search_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
                    _record_code_tool_result("search_product_tool", search_input, search_result)
                    emitted_events.append({
                        "type": "agent_flow",
                        "agent": "[Product Search AF]",
                        "agent_class": "Discovery Agent",
                        "status": search_result.get("status", "success"),
                        "source_domain": "discovery",
                    })
                    emitted_events.append({
                        "type": "tool",
                        "input": search_input,
                        "output": json.dumps(search_result, ensure_ascii=False),
                        "node": "tools",
                        "tool": "search_product_tool",
                        "source_domain": "discovery",
                    })

                    row = _unique_product_row_from_sized_search_result(search_result, product_keyword, str(tire_size))
                    goods_no = str((row or {}).get("goods_no") or "").strip()
                    if not goods_no:
                        mapped_event = try_build_template(
                            [{"tool": "search_product_tool", "args": search_input, "data": search_result}],
                            (
                                f"{product_keyword} {tire_size} 기준 상품을 찾았어요. "
                                "상품을 선택해 주시면 구매를 이어갈게요."
                            ),
                        )
                        if mapped_event is not None:
                            mapped_event["source_domain"] = MultiAgentDomain.Domain.DISCOVERY.value
                            mapped_event["assistant_response_source"] = "code_vehicle_purchase_product_selection"
                            return emitted_events, mapped_event
                        return emitted_events, _purchase_vehicle_missing_event(product_keyword, str(tire_size), "product")

                    ord_qty = _purchase_quantity(purchase_slots)
                    if not ord_qty:
                        return emitted_events, _purchase_vehicle_missing_event(product_keyword, str(tire_size), "quantity")

                    store_name = _purchase_store_name(purchase_slots)
                    if not store_name:
                        return emitted_events, _purchase_vehicle_missing_event(product_keyword, str(tire_size), "store")

                    preview_input = {
                        "goods_no": goods_no,
                        "ord_qty": ord_qty,
                        "store_nm": store_name,
                        "include_price": True,
                    }
                    emitted_events.append({
                        "type": "status",
                        "status": "tool_start",
                        "tool": "transaction_store_preview_tool",
                        "display_name": "장착 가능 일정 확인 중...",
                        "source_domain": "transaction",
                    })
                    try:
                        raw_preview = await asyncio.to_thread(_transaction_store_preview_tool.invoke, preview_input)
                        preview_result = _tool_result_dict(raw_preview)
                    except Exception as exc:
                        logger.exception(
                            "[VEHICLE_PURCHASE_CONTINUE] transaction_store_preview_tool failed goods_no=%s",
                            goods_no,
                        )
                        preview_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
                    _record_code_tool_result("transaction_store_preview_tool", preview_input, preview_result)
                    emitted_events.append({
                        "type": "agent_flow",
                        "agent": "[Store/Stock AF]",
                        "agent_class": "Transaction Agent",
                        "status": preview_result.get("status", "success"),
                        "source_domain": "transaction",
                    })
                    emitted_events.append({
                        "type": "tool",
                        "input": preview_input,
                        "output": json.dumps(preview_result, ensure_ascii=False),
                        "node": "tools",
                        "tool": "transaction_store_preview_tool",
                        "source_domain": "transaction",
                    })
                    intro = f"{product_keyword} {tire_size} {ord_qty}개 기준으로 {store_name} 장착 가능 여부를 확인했어요."
                    mapped_event = try_build_template(
                        [
                            {"tool": "search_product_tool", "args": search_input, "data": search_result},
                            {"tool": "transaction_store_preview_tool", "args": preview_input, "data": preview_result},
                        ],
                        intro,
                    )
                    if mapped_event is not None:
                        mapped_event["source_domain"] = MultiAgentDomain.Domain.TRANSACTION.value
                        mapped_event["assistant_response_source"] = "code_vehicle_purchase_continuation"
                        return emitted_events, mapped_event
                    return emitted_events, _purchase_vehicle_missing_event(product_keyword, str(tire_size), "store")

            from services.tstation.agents.b_discovery_agent.tools import (
                get_products_recommendations_tool as _recommendations_tool,
            )
            from services.tstation.template_mapper import try_build_template

            tool_name = "get_products_recommendations_tool"
            tool_input = {
                "rcmd_type": _recommendation_type_for_vehicle_auto_continue(user_query),
                "limit": 3,
                "brand_cd": "HK",
            }
            if car_lnc_cd:
                tool_input["car_lnc_cd"] = car_lnc_cd
            elif tire_size:
                tool_input["tire_size"] = tire_size
            if vehicle_type:
                tool_input["vehicle_type"] = vehicle_type

            emitted_events = [{
                "type": "status",
                "status": "tool_start",
                "tool": tool_name,
                "display_name": "상품 추천 중...",
                "source_domain": "discovery",
            }]
            try:
                raw_result = await asyncio.to_thread(_recommendations_tool.invoke, tool_input)
                tool_result = _tool_result_dict(raw_result)
            except Exception as exc:
                logger.exception("[VEHICLE_AUTO_SELECT] recommendation tool failed")
                tool_result = {
                    "status": "error",
                    "http_status": None,
                    "message": str(exc),
                    "data": {},
                }
            _record_code_tool_result(tool_name, tool_input, tool_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Product Recommendation AF]",
                "agent_class": "Discovery Agent",
                "status": tool_result.get("status", "success"),
                "source_domain": "discovery",
            })
            emitted_events.append({
                "type": "tool",
                "input": tool_input,
                "output": json.dumps(tool_result, ensure_ascii=False),
                "node": "tools",
                "tool": tool_name,
                "source_domain": "discovery",
            })
            size_text = f"의 타이어 사이즈 **{tire_size}** 기준" if tire_size else " 기준"
            intro = f"**{car_info} ({car_no})**{size_text}으로 추천해 드릴게요."
            mapped_event = try_build_template(
                [{"tool": tool_name, "args": tool_input, "data": tool_result}],
                intro,
            )
            if mapped_event is not None:
                mapped_event["source_domain"] = MultiAgentDomain.Domain.DISCOVERY.value
                mapped_event["assistant_response_source"] = "code_vehicle_auto_select"
                return emitted_events, mapped_event
            return emitted_events, {
                "type": "data",
                "template": "quickReply",
                "source_domain": MultiAgentDomain.Domain.DISCOVERY.value,
                "assistant_response_source": "code_vehicle_auto_select",
                "data": {
                    "assistantResponse": "선택하신 차량 기준으로 현재 추천 가능한 상품을 찾지 못했어요. 다른 조건으로 다시 찾아볼게요.",
                    "quickReplies": [
                        {"label": "사이즈 직접 입력", "domain": "DISCOVERY"},
                        {"label": "다른 조건으로 찾기", "domain": "DISCOVERY"},
                    ],
                    "predictedDomains": ["DISCOVERY"],
                },
            }

        # 1. Iterate through the main coordinator stream
        yield f"data: {json.dumps({'type': 'agent_flow', 'agent': '[응답 생성 중]', 'status': 'processing'}, ensure_ascii=False)}\n\n"

        coupon_size_list_slots = pending_slots or initial_slots
        if _is_coupon_discount_amount_size_list_followup(user_query, coupon_size_list_slots):
            size_list_keyword = _product_size_list_keyword_from_context(
                user_query,
                [],
                prev_tool_data=[],
                recent_context=recent_user_context_text,
                slots=coupon_size_list_slots,
            )
            if size_list_keyword:
                from services.tstation.agents.b_discovery_agent.tools import search_product_tool as _search_product_tool

                emitted_events: list[dict] = [{
                    "type": "status",
                    "status": "tool_start",
                    "tool": "search_product_tool",
                    "display_name": "다른 규격 확인 중...",
                    "source_domain": "discovery",
                }]
                size_list_input = {"keyword": size_list_keyword, "limit": 10}
                try:
                    raw_size_list = await asyncio.to_thread(_search_product_tool.invoke, size_list_input)
                    size_list_result = _tool_result_dict(raw_size_list)
                except Exception as exc:
                    logger.exception("[COUPON_SIZE_LIST] search_product_tool failed for %s", size_list_keyword)
                    size_list_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
                _record_code_tool_result("search_product_tool", size_list_input, size_list_result)
                emitted_events.extend([
                    {
                        "type": "agent_flow",
                        "agent": "[Product Search AF]",
                        "agent_class": "Discovery Agent",
                        "status": size_list_result.get("status", "success"),
                        "source_domain": "discovery",
                    },
                    {
                        "type": "tool",
                        "input": size_list_input,
                        "output": json.dumps(size_list_result, ensure_ascii=False),
                        "node": "tools",
                        "tool": "search_product_tool",
                        "source_domain": "discovery",
                    },
                ])
                size_list_event = _build_product_size_list_event_from_search_results(
                    user_query,
                    [(size_list_keyword, size_list_result)],
                    prev_tool_data=[],
                    recent_context=recent_user_context_text,
                    slots=coupon_size_list_slots,
                )
                if size_list_event is None:
                    size_list_event = _build_product_size_list_not_found_event(size_list_keyword)
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
                for code_event in emitted_events:
                    yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps(size_list_event, ensure_ascii=False)}\n\n"
                assistant_response = str((size_list_event.get("data") or {}).get("assistantResponse") or "")
                if assistant_response:
                    yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
                yield "data: [DONE]\n\n"
                return

        multi_product_detail_names = _multi_product_detail_continuation_names(
            user_query,
            messages,
            latest_quickreply_tmpl,
        )
        if len(multi_product_detail_names) >= 2:
            multi_product_detail_resolution = await _resolve_multi_product_detail_with_code(multi_product_detail_names)
            if multi_product_detail_resolution is not None:
                code_events, detail_event = multi_product_detail_resolution
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
                for code_event in code_events:
                    yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps(detail_event, ensure_ascii=False)}\n\n"
                assistant_response = str((detail_event.get("data") or {}).get("assistantResponse") or "")
                if assistant_response:
                    yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
                yield "data: [DONE]\n\n"
                return

        multi_product_compare_query = _multi_product_compare_continuation_query(
            user_query,
            messages,
            latest_quickreply_tmpl,
        )
        if multi_product_compare_query:
            product_compare_resolution = await _resolve_product_comparison_with_code(multi_product_compare_query)
            if product_compare_resolution is not None:
                code_events, compare_event = product_compare_resolution
                await _persist_pending_slots_for_direct_return()
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
                for code_event in code_events:
                    yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps(compare_event, ensure_ascii=False)}\n\n"
                assistant_response = str((compare_event.get("data") or {}).get("assistantResponse") or "")
                if assistant_response:
                    yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
                yield "data: [DONE]\n\n"
                return

        if _should_resolve_compare_target_product_pair(
            user_query,
            messages,
            latest_quickreply_tmpl,
            slots=pending_slots or initial_slots,
        ):
            product_compare_resolution = await _resolve_product_comparison_with_code()
            if product_compare_resolution is not None:
                code_events, compare_event = product_compare_resolution
                await _persist_pending_slots_for_direct_return()
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
                for code_event in code_events:
                    yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps(compare_event, ensure_ascii=False)}\n\n"
                assistant_response = str((compare_event.get("data") or {}).get("assistantResponse") or "")
                if assistant_response:
                    yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
                yield "data: [DONE]\n\n"
                return

        if _should_prompt_for_new_product_compare_target(user_query, messages):
            compare_prompt_event = _product_compare_target_prompt_event()
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(compare_prompt_event, ensure_ascii=False)}\n\n"
            assistant_response = str((compare_prompt_event.get("data") or {}).get("assistantResponse") or "")
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        if _should_clarify_ambiguous_multi_product_query(user_query, messages, latest_quickreply_tmpl):
            clarification_event = _multi_product_intent_clarification_event(_product_names_in_text(user_query))
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(clarification_event, ensure_ascii=False)}\n\n"
            assistant_response = str((clarification_event.get("data") or {}).get("assistantResponse") or "")
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        if _PRICE_OR_BENEFIT_ALERT_QUERY_RE.search(user_query or ""):
            alert_event = _price_or_benefit_alert_event()
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[TRANSACTION AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[TRANSACTION AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(alert_event, ensure_ascii=False)}\n\n"
            assistant_response = str((alert_event.get("data") or {}).get("assistantResponse") or "")
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[TRANSACTION AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        if _REMINDING_ALARM_QUERY_RE.search(user_query or "") and not _is_order_arrival_status_query(user_query):
            alarm_event = _reminding_alarm_event()
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[SUPPORT AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[SUPPORT AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(alarm_event, ensure_ascii=False)}\n\n"
            assistant_response = str((alarm_event.get("data") or {}).get("assistantResponse") or "")
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[SUPPORT AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        default_benefit_resolution = await _resolve_default_benefit_with_code()
        if default_benefit_resolution is not None:
            code_events, benefit_event = default_benefit_resolution
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            for code_event in code_events:
                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(benefit_event, ensure_ascii=False)}\n\n"
            assistant_response = str((benefit_event.get("data") or {}).get("assistantResponse") or "")
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        order_history_reorder_resolution = await _resolve_order_history_reorder_with_code()
        if order_history_reorder_resolution is not None:
            code_events, reorder_event = order_history_reorder_resolution
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[TRANSACTION AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            for code_event in code_events:
                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[TRANSACTION AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(reorder_event, ensure_ascii=False)}\n\n"
            assistant_response = str((reorder_event.get("data") or {}).get("assistantResponse") or "")
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[TRANSACTION AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        maintenance_history_resolution = await _resolve_maintenance_history_lookup_with_code()
        if maintenance_history_resolution is not None:
            code_events, maintenance_event = maintenance_history_resolution
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[TRANSACTION AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
