        async def _resolve_quick_order_execute_with_code() -> tuple[list[dict], dict] | None:
            if not _is_preorder_confirmation_reply(user_query, latest_preorder_tmpl):
                return None

            preorder_slot_values = TStationChatServiceV2._preorder_slot_values_from_data(latest_preorder_tmpl) or {}
            slot_values = (
                initial_slots.model_dump()
                if initial_slots is not None and hasattr(initial_slots, "model_dump")
                else dict(initial_slots or {})
            )
            slot_values.update({key: value for key, value in preorder_slot_values.items() if value not in (None, "")})
            slot_values["pending_intent"] = "order"
            slot_values["goal_type"] = "place_order"
            frame = build_transaction_intent_frame(user_query, known_slots=slot_values)
            if frame.intent != "quick_order_execute":
                logger.info(
                    "[QUICK_ORDER_EXECUTE] forcing ready preOrder confirmation despite frame intent=%s missing=%s",
                    frame.intent,
                    frame.missing_slots,
                )
                frame = IntentFrame(
                    domain=PolicyDomain.TRANSACTION,
                    intent="quick_order_execute",
                    sub_intent="confirm",
                    known_slots={**dict(frame.known_slots), **slot_values},
                    missing_slots=(),
                )

            required_fields = ("goods_no", "shop_id", "ord_qty", "requested_cal_day", "rsv_hour")
            missing_required = tuple(field for field in required_fields if not frame.known_slots.get(field))
            if missing_required:
                logger.info(
                    "[QUICK_ORDER_EXECUTE] ready preOrder confirmation missing required slots=%s",
                    missing_required,
                )
                return None

            from services.tstation.agents.c_transaction_agent.tools import quick_order_tool as _quick_order_tool
            from services.tstation.template_mapper import try_build_template

            preorder_payload = _preorder_payload(latest_preorder_tmpl) or {}
            preorder_order_info = preorder_payload.get("orderInfo") if isinstance(preorder_payload.get("orderInfo"), dict) else {}

            goods_no = str(frame.known_slots.get("goods_no") or "").strip()
            shop_id = str(frame.known_slots.get("shop_id") or "").strip()
            requested_cal_day = str(frame.known_slots.get("requested_cal_day") or "").strip()
            rsv_hour = str(frame.known_slots.get("rsv_hour") or "").strip()
            car_lnc_cd = str(frame.known_slots.get("car_lnc_cd") or "").strip() or None
            try:
                ord_qty = int(frame.known_slots.get("ord_qty") or frame.known_slots.get("quantity") or 0)
            except (TypeError, ValueError):
                ord_qty = 0
            if not (goods_no and shop_id and requested_cal_day and rsv_hour and ord_qty > 0):
                return None

            tool_input: dict[str, Any] = {
                "goods_no": goods_no,
                "ord_qty": ord_qty,
                "shop_id": shop_id,
                "rsv_date": requested_cal_day,
                "rsv_hour": rsv_hour,
            }
            if car_lnc_cd:
                tool_input["car_lnc_cd"] = car_lnc_cd

            emitted_events: list[dict] = [{
                "type": "status",
                "status": "tool_start",
                "tool": "quick_order_tool",
                "display_name": "주문서 생성 중...",
                "source_domain": "transaction",
            }]
            try:
                raw_result = await asyncio.to_thread(_quick_order_tool.invoke, tool_input)
                quick_order_result = _tool_result_dict(raw_result)
            except Exception as exc:
                logger.exception(
                    "[QUICK_ORDER_EXECUTE] quick_order_tool failed goods_no=%s shop_id=%s",
                    goods_no,
                    shop_id,
                )
                quick_order_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
            _record_code_tool_result("quick_order_tool", tool_input, quick_order_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Quick Shopping AF]",
                "agent_class": "Transaction Agent",
                "status": quick_order_result.get("status", "success"),
                "source_domain": "transaction",
            })
            emitted_events.append({
                "type": "tool",
                "input": tool_input,
                "output": json.dumps(quick_order_result, ensure_ascii=False),
                "node": "tools",
                "tool": "quick_order_tool",
                "source_domain": "transaction",
            })
            status = str(quick_order_result.get("status") or "").lower()
            unwrapped_quick_order = _unwrap_tool_data(quick_order_result)
            quick_order_flag = (
                str(unwrapped_quick_order.get("result") or "").lower()
                if isinstance(unwrapped_quick_order, dict)
                else ""
            )
            order_form_payload = (
                unwrapped_quick_order.get("data")
                if isinstance(unwrapped_quick_order, dict) and isinstance(unwrapped_quick_order.get("data"), dict)
                else None
            )
            is_success = status == "success" and quick_order_flag not in {"", "false", "0"} and order_form_payload

            mapped_event = try_build_template(
                [{"tool": "quick_order_tool", "args": tool_input, "data": quick_order_result}],
                str(preorder_payload.get("assistantResponse") or ""),
            )
            if not is_success:
                return emitted_events, {
                    "type": "data",
                    "template": "quickReply",
                    "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
                    "assistant_response_source": "code_quick_order_execute_resolver",
                    "data": {
                        "assistantResponse": (
                            "주문서 생성에 실패했어요. 주문 정보를 다시 확인해 주세요."
                        ),
                        "quickReplies": [
                            {"label": "주문 정보 다시 확인", "domain": "TRANSACTION"},
                            {"label": "장바구니 확인", "domain": "TRANSACTION", "url": CTAUrls.CART},
                        ],
                        "predictedDomains": ["TRANSACTION"],
                        "metadata": {
                            "response_shape_key": "quick_order_execute",
                            "quickOrderToolCalled": True,
                            "quickOrderResult": "failed",
                        },
                    },
                }
            if mapped_event is None or mapped_event.get("template") != "orderComplete":
                return emitted_events, {
                    "type": "data",
                    "template": "quickReply",
                    "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
                    "assistant_response_source": "code_quick_order_execute_resolver",
                    "data": {
                        "assistantResponse": (
                            "주문서 생성 결과를 확인했지만 주문/결제 페이지 이동 정보가 부족해요. "
                            "주문 정보를 다시 확인해 주세요."
                        ),
                        "quickReplies": [
                            {"label": "주문 정보 다시 확인", "domain": "TRANSACTION"},
                            {"label": "장바구니 확인", "domain": "TRANSACTION", "url": CTAUrls.CART},
                        ],
                        "predictedDomains": ["TRANSACTION"],
                        "metadata": {
                            "response_shape_key": "quick_order_execute",
                            "quickOrderToolCalled": True,
                            "quickOrderResult": "missing_order_page_payload",
                        },
                    },
                }

            mapped_event["source_domain"] = MultiAgentDomain.Domain.TRANSACTION.value
            mapped_event["assistant_response_source"] = "code_quick_order_execute_resolver"
            event_data = mapped_event.get("data") if isinstance(mapped_event.get("data"), dict) else {}
            order_info = event_data.get("orderInfo") if isinstance(event_data.get("orderInfo"), dict) else {}
            if isinstance(order_info, dict):
                for key in ("carInfo", "product", "quantity", "storeName", "bookingDateTime", "paymentAmount"):
                    if order_info.get(key) in (None, "", 0):
                        replacement = preorder_order_info.get(key)
                        if replacement not in (None, "", 0):
                            order_info[key] = replacement
                if order_info.get("bookingDateTime") in (None, "") and requested_cal_day and rsv_hour:
                    try:
                        order_day = datetime.datetime.strptime(requested_cal_day, "%Y%m%d")
                        order_info["bookingDateTime"] = (
                            f"{order_day.year}년 {order_day.month}월 {order_day.day}일 "
                            f"({_WEEKDAY_KO[order_day.weekday()]}) {int(rsv_hour):02d}:00"
                        )
                    except ValueError:
                        order_info["bookingDateTime"] = str(preorder_order_info.get("bookingDateTime") or "")
            metadata = event_data.get("metadata") if isinstance(event_data.get("metadata"), dict) else {}
            if isinstance(metadata, dict):
                metadata.setdefault("goodsId", goods_no)
                metadata.setdefault("shopId", shop_id)
            if not event_data.get("quickReplies"):
                event_data["quickReplies"] = [
                    {"label": "주문 내역 확인", "domain": "TRANSACTION"},
                    {"label": "배송 상태 확인", "domain": "TRANSACTION"},
                ] if event_data.get("isSuccess") else [
                    {"label": "주문 다시 확인", "domain": "TRANSACTION"},
                    {"label": "예약 시간 다시 선택", "domain": "TRANSACTION"},
                ]
            return emitted_events, mapped_event

        quick_order_execute_resolution = await _resolve_quick_order_execute_with_code()
        if quick_order_execute_resolution is not None:
            code_events, order_event = quick_order_execute_resolution
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[TRANSACTION AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            for code_event in code_events:
                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[TRANSACTION AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(order_event, ensure_ascii=False)}\n\n"
            assistant_response = str((order_event.get("data") or {}).get("assistantResponse") or "")
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[TRANSACTION AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        async def _resolve_pure_inventory_stock_with_code() -> tuple[list[dict], dict] | None:
            slot_state = pending_slots or initial_slots
            if not _is_pure_inventory_stock_ready(slot_state):
                return None

            slot_values = (
                slot_state.model_dump()
                if slot_state is not None and hasattr(slot_state, "model_dump")
                else dict(slot_state or {})
            )
            frame = build_transaction_intent_frame(user_query, known_slots=slot_values)
            if frame.intent != "stock_store_search" or frame.sub_intent != "stock":
                if not _is_quantity_only_stock_followup_text(user_query):
                    return None
                frame = build_transaction_intent_frame(
                    "재고 있어?",
                    known_slots=slot_values,
                )
                if frame.intent != "stock_store_search" or frame.sub_intent != "stock":
                    return None
            if str(frame.known_slots.get("stock_check_mode") or "") != "inventory_only":
                return None

            goods_no = str(frame.known_slots.get("goods_no") or "").strip()
            tire_size = str(frame.known_slots.get("tire_size") or "").strip()
            store_name = str(
                frame.known_slots.get("shop_name")
                or frame.known_slots.get("store_name")
                or ""
            ).strip()
            shop_id = str(frame.known_slots.get("shop_id") or "").strip()
            store_context: dict[str, Any] = _store_context_from_mapping(
                {
                    "shopId": shop_id,
                    "shopName": store_name,
                    "xpos": frame.known_slots.get("xpos") or frame.known_slots.get("user_xpos"),
                    "ypos": frame.known_slots.get("ypos") or frame.known_slots.get("user_ypos"),
                    "address": frame.known_slots.get("address"),
                }
            )
            try:
                ord_qty = int(frame.known_slots.get("ord_qty") or frame.known_slots.get("quantity") or 0)
            except (TypeError, ValueError):
                ord_qty = 0
            if not (goods_no and tire_size and ord_qty > 0):
                return None
            if not (shop_id or store_name):
                return None

            from services.tstation.agents.c_transaction_agent.tools import (
                get_logistics_inventory_tool as _get_logistics_inventory_tool,
                get_store_inventory_tool as _get_store_inventory_tool,
                get_store_list_tool as _get_store_list_tool,
            )
            from services.tstation.template_mapper import try_build_template

            emitted_events: list[dict] = []
            tool_entries: list[dict[str, Any]] = []

            if not shop_id:
                list_input = {"store_nm": store_name, "limit": 10}
                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "get_store_list_tool",
                    "display_name": "매장 조회 중...",
                    "source_domain": "transaction",
                })
                try:
                    raw_list = await asyncio.to_thread(_get_store_list_tool.invoke, list_input)
                    list_result = _tool_result_dict(raw_list)
                except Exception as exc:
                    logger.exception("[PURE_INVENTORY_STOCK] get_store_list_tool failed store=%s", store_name)
                    list_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
                _record_code_tool_result("get_store_list_tool", list_input, list_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Store AF]",
                    "agent_class": "Transaction Agent",
                    "status": list_result.get("status", "success"),
                    "source_domain": "transaction",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": list_input,
                    "output": json.dumps(list_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "get_store_list_tool",
                    "source_domain": "transaction",
                })
                tool_entries.append({"tool": "get_store_list_tool", "args": list_input, "data": list_result})

                list_data = _unwrap_tool_data(list_result)
                stores = list_data.get("stores") if isinstance(list_data, dict) else None
                if not isinstance(stores, list):
                    stores = []
                matched_store = _store_name_exact_match_row(store_name, [store for store in stores if isinstance(store, dict)])
                if matched_store is None:
                    mapped_event = try_build_template(
                        tool_entries,
                        f"{store_name} 매장 확인 결과예요.",
                    )
                    if mapped_event is not None:
                        mapped_event["source_domain"] = MultiAgentDomain.Domain.TRANSACTION.value
                        mapped_event["assistant_response_source"] = "code_pure_inventory_stock_store_resolution"
                        return emitted_events, mapped_event
                    return emitted_events, {
                        "type": "data",
                        "template": "quickReply",
                        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
                        "assistant_response_source": "code_pure_inventory_stock_store_resolution",
                        "data": {
                            "assistantResponse": "확인할 매장을 먼저 정해야 재고를 조회할 수 있어요. 매장명을 다시 확인해 주세요.",
                            "quickReplies": [
                                {"label": "매장명 다시 입력", "domain": "TRANSACTION"},
                                {"label": "다른 매장 찾기", "domain": "TRANSACTION"},
                            ],
                            "predictedDomains": ["TRANSACTION"],
                        },
                    }
                shop_id = str(matched_store.get("shop_id") or "").strip()
                resolved_store_name = str(matched_store.get("shop_nm") or matched_store.get("shop_name") or "").strip()
                if resolved_store_name:
                    store_name = resolved_store_name
                store_context = _store_context_from_mapping({**matched_store, "shopId": shop_id, "shopName": store_name})
                if not shop_id:
                    return emitted_events, {
                        "type": "data",
                        "template": "quickReply",
                        "source_domain": MultiAgentDomain.Domain.TRANSACTION.value,
                        "assistant_response_source": "code_pure_inventory_stock_store_resolution",
                        "data": {
                            "assistantResponse": "매장 정보를 정확히 확인하지 못해 재고 조회를 진행하지 않았어요. 매장을 다시 선택해 주세요.",
                            "quickReplies": [
                                {"label": "매장명 다시 입력", "domain": "TRANSACTION"},
                                {"label": "다른 매장 찾기", "domain": "TRANSACTION"},
                            ],
                            "predictedDomains": ["TRANSACTION"],
                        },
                    }
                if initial_slots is not None:
                    initial_slots.shop_id = shop_id
                    if store_name:
                        initial_slots.shop_name = store_name

            inventory_input = {
                "goods_list": [{"goodsNo": goods_no, "qty": str(ord_qty)}],
                "shop_id_list": [{"shopId": shop_id}],
            }
            emitted_events.append({
                "type": "status",
                "status": "tool_start",
                "tool": "get_store_inventory_tool",
                "display_name": "매장 재고 확인 중...",
                "source_domain": "transaction",
            })
            try:
                raw_inventory = await asyncio.to_thread(_get_store_inventory_tool.invoke, inventory_input)
                inventory_result = _tool_result_dict(raw_inventory)
            except Exception as exc:
                logger.exception("[PURE_INVENTORY_STOCK] get_store_inventory_tool failed goods_no=%s shop_id=%s", goods_no, shop_id)
                inventory_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
            _record_code_tool_result("get_store_inventory_tool", inventory_input, inventory_result)
            emitted_events.append({
                "type": "agent_flow",
                "agent": "[Store/Stock AF]",
                "agent_class": "Transaction Agent",
                "status": inventory_result.get("status", "success"),
                "source_domain": "transaction",
            })
            emitted_events.append({
                "type": "tool",
                "input": inventory_input,
                "output": json.dumps(inventory_result, ensure_ascii=False),
                "node": "tools",
                "tool": "get_store_inventory_tool",
                "source_domain": "transaction",
            })
            tool_entries.append({"tool": "get_store_inventory_tool", "args": inventory_input, "data": inventory_result})

            store_stock_available = _pure_inventory_has_store_stock(
                inventory_result,
                shop_id=shop_id,
                requested_qty=ord_qty,
            )
            logistics_result: dict | None = None
            if not store_stock_available:
                logistics_input = {"goods_no": goods_no}
                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "get_logistics_inventory_tool",
                    "display_name": "물류 재고 확인 중...",
                    "source_domain": "transaction",
                })
                try:
                    raw_logistics = await asyncio.to_thread(_get_logistics_inventory_tool.invoke, logistics_input)
                    logistics_result = _tool_result_dict(raw_logistics)
                except Exception as exc:
                    logger.exception("[PURE_INVENTORY_STOCK] get_logistics_inventory_tool failed goods_no=%s", goods_no)
                    logistics_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
                _record_code_tool_result("get_logistics_inventory_tool", logistics_input, logistics_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Inventory AF]",
                    "agent_class": "Transaction Agent",
                    "status": logistics_result.get("status", "success"),
                    "source_domain": "transaction",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": logistics_input,
                    "output": json.dumps(logistics_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "get_logistics_inventory_tool",
                    "source_domain": "transaction",
                })
                tool_entries.append({
                    "tool": "get_logistics_inventory_tool",
                    "args": logistics_input,
                    "data": logistics_result,
                })
                return emitted_events, _build_pure_inventory_stock_event(
                    store_name=store_name,
                    tire_size=tire_size,
                    ord_qty=ord_qty,
                    logistics_result=logistics_result,
                    store_context=store_context,
                    goods_no=goods_no,
                )

            intro = f"{store_name or '선택한 매장'}에서 {tire_size} {ord_qty}개 기준 재고를 확인했어요."
            mapped_event = try_build_template(tool_entries, intro)
            if mapped_event is not None:
                mapped_event["source_domain"] = MultiAgentDomain.Domain.TRANSACTION.value
                mapped_event["assistant_response_source"] = "code_pure_inventory_stock_resolver"
                return emitted_events, mapped_event

            return emitted_events, _build_pure_inventory_stock_event(
                store_name=store_name,
                tire_size=tire_size,
                ord_qty=ord_qty,
                logistics_result=logistics_result,
                store_context=store_context,
                goods_no=goods_no,
            )

        pure_inventory_stock_resolution = await _resolve_pure_inventory_stock_with_code()
        if pure_inventory_stock_resolution is not None:
            code_events, stock_event = pure_inventory_stock_resolution
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[TRANSACTION AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            for code_event in code_events:
                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[TRANSACTION AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            if stock_event is not None:
                yield f"data: {json.dumps(stock_event, ensure_ascii=False)}\n\n"
                assistant_response = str((stock_event.get("data") or {}).get("assistantResponse") or "")
                if assistant_response:
                    yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[TRANSACTION AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        async def _resolve_recent_product_size_availability_with_code() -> tuple[list[dict], dict] | None:
            requested_size = normalize_tire_size(user_query)
            context = _recent_product_set_size_availability_context(
                user_query,
                prev_tool_data=prev_tool_data or [],
                routing_result=routing_result,
                messages=messages,
                latest_quickreply_tmpl=latest_quickreply_tmpl,
            )
            if context is None:
                size_only_tool_input = _build_size_only_product_search_tool_input(
                    user_query,
                    prev_tool_data=prev_tool_data or [],
                    recent_context=recent_user_context_text,
                    slots=initial_slots,
                )
                if size_only_tool_input is not None:
                    return None
                if (
                    str(getattr(routing_result, "discovery_followup_intent", "") or "").strip()
                    == "recent_product_set_size_availability"
                    or _is_recent_product_size_availability_query(user_query)
                ):
                    return [], _build_recent_product_size_availability_missing_context_event(requested_size)
                return None

            emitted_events: list[dict] = []
            available_names: list[str] = []
            missing_names: list[str] = []
            resolved_by_existing_rows = (
                context["tool"] == "search_product_tool" and bool(_FOLLOWUP_PRODUCT_REFERENCE_RE.search(user_query))
            )
            search_results_by_name: dict[str, dict] = {}

            if resolved_by_existing_rows:
                existing_event = _build_recent_product_size_availability_event_from_rows(
                    user_query,
                    prev_tool_data=prev_tool_data or [],
                    messages=messages,
                    latest_quickreply_tmpl=latest_quickreply_tmpl,
                )
                if existing_event is not None:
                    return emitted_events, existing_event

            from services.tstation.agents.b_discovery_agent.tools import search_product_tool as _search_product_tool

            for product_name in context["product_names"]:
                tool_input = {"keyword": product_name, "size": context["tire_size"], "limit": 10}
                emitted_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "search_product_tool",
                    "display_name": "규격 확인 중...",
                    "source_domain": "discovery",
                })
                try:
                    raw_result = await asyncio.to_thread(_search_product_tool.invoke, tool_input)
                    search_result = _tool_result_dict(raw_result)
                except Exception as exc:
                    logger.exception("[RECENT_PRODUCT_SIZE_AVAILABILITY] search_product_tool failed for %s", product_name)
                    search_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
                search_results_by_name[product_name] = search_result
                _record_code_tool_result("search_product_tool", tool_input, search_result)
                emitted_events.append({
                    "type": "agent_flow",
                    "agent": "[Product Compatibility AF]",
                    "agent_class": "Discovery Agent",
                    "status": search_result.get("status", "success"),
                    "source_domain": "discovery",
                })
                emitted_events.append({
                    "type": "tool",
                    "input": tool_input,
                    "output": json.dumps(search_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "search_product_tool",
                    "source_domain": "discovery",
                })

                matched_row = _unique_product_row_from_sized_search_result(
                    search_result,
                    product_name,
                    context["tire_size"],
                )
                if matched_row is not None:
                    available_names.append(product_name)
                else:
                    missing_names.append(product_name)

            event = _build_recent_product_size_availability_event(
                context["tire_size"],
                context["product_names"],
                available_names,
                missing_names,
                source_tool=context["tool"],
            )
            if event is None:
                return None
            return emitted_events, event

        recent_product_size_availability_resolution = await _resolve_recent_product_size_availability_with_code()
        if recent_product_size_availability_resolution is not None:
            code_events, recent_product_size_availability_event = recent_product_size_availability_resolution
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            for code_event in code_events:
                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(recent_product_size_availability_event, ensure_ascii=False)}\n\n"
            assistant_response = str((recent_product_size_availability_event.get("data") or {}).get("assistantResponse") or "")
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        product_size_list_event = _build_product_size_list_event_from_search_results(
            user_query,
            [],
            prev_tool_data=prev_tool_data or [],
            recent_context=recent_user_context_text,
            slots=initial_slots,
        )
        product_size_list_code_events: list[dict] = []
        pending_size_list_product = (
            str(getattr(initial_slots, "pending_product_name", None) or "").strip()
            if initial_slots is not None
            else ""
        )
        if _is_product_size_list_intent(user_query) and (product_size_list_event is None or pending_size_list_product):
            size_list_keyword = _product_size_list_keyword_from_context(
                user_query,
                [],
                prev_tool_data=[],
                recent_context=recent_user_context_text,
                slots=initial_slots,
            )
            if size_list_keyword:
                from services.tstation.agents.b_discovery_agent.tools import search_product_tool as _search_product_tool

                size_list_input = {"keyword": size_list_keyword, "limit": 10}
                product_size_list_code_events.append({
                    "type": "status",
                    "status": "tool_start",
                    "tool": "search_product_tool",
                    "display_name": "상품 검색 중...",
                    "source_domain": "discovery",
                })
                try:
                    raw_size_list = await asyncio.to_thread(_search_product_tool.invoke, size_list_input)
                    size_list_result = _tool_result_dict(raw_size_list)
                except Exception as exc:
                    logger.exception("[PRODUCT_SIZE_LIST] search_product_tool failed for %s", size_list_keyword)
                    size_list_result = {"status": "error", "http_status": None, "message": str(exc), "data": {}}
                _record_code_tool_result("search_product_tool", size_list_input, size_list_result)
                product_size_list_code_events.append({
                    "type": "agent_flow",
                    "agent": "[Product Search AF]",
                    "agent_class": "Discovery Agent",
                    "status": size_list_result.get("status", "success"),
                    "source_domain": "discovery",
                })
                product_size_list_code_events.append({
                    "type": "tool",
                    "input": size_list_input,
                    "output": json.dumps(size_list_result, ensure_ascii=False),
                    "node": "tools",
                    "tool": "search_product_tool",
                    "source_domain": "discovery",
                })
                product_size_list_event = _build_product_size_list_event_from_search_results(
                    user_query,
                    [(size_list_keyword, size_list_result)],
                    prev_tool_data=[],
                    recent_context=recent_user_context_text,
                    slots=initial_slots,
                )
                if product_size_list_event is None and pending_size_list_product:
                    product_size_list_event = _build_product_size_list_not_found_event(size_list_keyword)
        if product_size_list_event is not None:
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            for code_event in product_size_list_code_events:
                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(product_size_list_event, ensure_ascii=False)}\n\n"
            assistant_response = str((product_size_list_event.get("data") or {}).get("assistantResponse") or "")
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        bare_product_search_resolution = await _resolve_bare_product_search_with_code()
        if bare_product_search_resolution is not None:
            code_events, product_event = bare_product_search_resolution
            await _persist_pending_slots_for_direct_return()
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            for code_event in code_events:
                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(product_event, ensure_ascii=False)}\n\n"
            assistant_response = str((product_event.get("data") or {}).get("assistantResponse") or "")
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        multi_variant_resolution = await _resolve_multi_variant_recommendation_with_code()
        if multi_variant_resolution is not None:
            code_events, deterministic_variant_event = multi_variant_resolution
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            for code_event in code_events:
                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(deterministic_variant_event, ensure_ascii=False)}\n\n"
            assistant_response = str(
                (deterministic_variant_event.get("data") or {}).get("assistantResponse") or ""
            )
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        oe_replacement_followup_resolution = await _resolve_oe_replacement_followup_with_code(
            initial_slots.tire_size
        )
        if oe_replacement_followup_resolution is not None:
            code_events, followup_event = oe_replacement_followup_resolution
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'start'}, ensure_ascii=False)}\n\n"
            for code_event in code_events:
                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DISCOVERY AGENT]', 'status': 'done'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps(followup_event, ensure_ascii=False)}\n\n"
            assistant_response = str((followup_event.get("data") or {}).get("assistantResponse") or "")
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        history_selected_vehicle_prompt_event = current_vehicle_selection_prompt_event.get()
        if history_selected_vehicle_prompt_event is not None:
            yield f"data: {json.dumps(history_selected_vehicle_prompt_event, ensure_ascii=False)}\n\n"
            assistant_response = str(
                (history_selected_vehicle_prompt_event.get("data") or {}).get("assistantResponse") or ""
            )
            if assistant_response:
                yield f"data: {json.dumps({'type': 'message', 'content': assistant_response, 'agent': '[DISCOVERY AGENT]'}, ensure_ascii=False)}\n\n"
            yield f"data: {json.dumps({'type': 'sub-agent', 'agent': '[DONE]', 'status': 'success'}, ensure_ascii=False)}\n\n"
            yield "data: [DONE]\n\n"
            return

        # Track whether a code-mapper-eligible tool was called — if so, suppress token streaming
        # to avoid the "long text flashes then gets replaced by card" UX issue.
        from services.tstation.template_mapper import _TOOL_TEMPLATE_MAP

        _SUPPRESS_ON_TOOLS = frozenset(
            tool
            for tool, template in _TOOL_TEMPLATE_MAP.items()
            if template in {"product", "voucher", "cheapestProduct", "previewYoutube", "location", "datepick"}
        )
        _suppress_tokens = False

        speculative_guard = None
        if classify_future is not None:
            speculative_guard = {
                "confirm_event": threading.Event(),
                "mutating_tools": _SPECULATIVE_MUTATING_TOOLS,
            }

        coordinator_iter = _coordinator.stream(
            messages,
            domains=domains,
            slot_context=slot_context,
            session_id=session_id,
            tool_context=tool_context,
            user_id=user_id,
            trace_id=trace_id,
            parent_span_id=parent_span_id,
            skip_decision=skip_decision,
            slot_context_with_intent=slot_context_with_intent,
            classify_future=classify_future,
            speculative_guard=speculative_guard,
            routing_result=routing_result,
            initial_slots=initial_slots,
        )
        async for event in _async_from_sync_iter(coordinator_iter):
            _lat_now = time.perf_counter()
            event_type = event.get("type")

            # --- INTERCEPT TOKENS (Draft Response only — FE ignores `token` events
            # already and renders text from data.assistantResponse on the final
            # template, so streaming partial tokens to the client adds no UI value
            # and inflates SSE bandwidth. Keep accumulating into draft_response so
            # the local QC / sanitize step still has the full text). ---
            if event_type == "token":
                if event.get("content"):
                    if _lat_waiting_post_tool_output_since is not None:
                        _post_tool_ms = (_lat_now - _lat_waiting_post_tool_output_since) * 1000
                        _lat_agent_post_tool_output_ms += _post_tool_ms
                        logger.debug(f"[LATENCY]   llm_post_tool_output={_post_tool_ms:.0f}ms")
                        _lat_waiting_post_tool_output_since = None
                    if not _suppress_tokens:
                        draft_response += event["content"]
                        draft_for_qc += event["content"]
                    if not _lat_first_token_seen:
                        _lat_first_token_seen = True
                        _lat_first_token_time = _lat_now
                        if _lat_think_start is not None:
                            logger.debug(f"[LATENCY]   llm_think={(_lat_now - _lat_think_start)*1000:.0f}ms")
                continue

            # --- INTERCEPT MESSAGES (History Sync ONLY) ---
            if event_type == "message":
                original_message_events.append(event)
                continue

            # --- COLLECT SOURCE DATA (Tools Only = True Ground Truth) ---
            if event_type == "tool":
                yield f"data: {json.dumps(event, ensure_ascii=False)}\n\n"
                tool_name = event.get("tool", "Unknown")
                called_tool_names.add(tool_name)
                if tool_name in _lat_tool_start:
                    _tool_ms = (_lat_now - _lat_tool_start.pop(tool_name)) * 1000
                    _lat_tool_ms += _tool_ms
                    logger.debug(f"[LATENCY]   tool={tool_name} {_tool_ms:.0f}ms")
                _lat_waiting_post_tool_output_since = _lat_now
                # Suppress tokens when a "list display" tool is called (card will replace text).
                # Exclude car lookup tools — agent may need to show selection text first.
                if tool_name in _SUPPRESS_ON_TOOLS:
                    _suppress_tokens = True
                input_data = event.get("input", {})
                output_data = event.get("output", "")
                source_parts = []
                if input_data:
                    source_parts.append(f"Input: {json.dumps(input_data, ensure_ascii=False)}")
                if output_data:
                    filtered = filter_source_data(tool_name, output_data)
                    source_parts.append(f"Output: {filtered}")
                if source_parts:
                    source_data_chunks.append(f"Tool [{tool_name}]:\n" + "\n".join(source_parts))

                # Collect structured tool results for context preservation
                if output_data:
                    ctx_item = filter_for_context(tool_name, output_data, input_data)
                    if ctx_item:
                        tool_context_items.append(ctx_item)
                    parsed_for_verifier = qc_verifier.parse_tool_output(output_data)
                    if tool_error := _tool_error_summary(tool_name, parsed_for_verifier or output_data):
                        tool_errors.append(tool_error)
                    if parsed_for_verifier is None and tool_name in _HIGH_RISK_POST_TOOL_CONTRACT_TOOLS:
                        post_tool_response_decision = _tool_parse_failure_response_decision(tool_name)
                        for behavior in post_tool_response_decision.forbidden_behaviors:
                            if behavior not in post_tool_forbidden_behaviors:
                                post_tool_forbidden_behaviors.append(behavior)
                        post_tool_policy_metadata.update(dict(post_tool_response_decision.metadata))
                        post_tool_policy_metadata.setdefault("tools", [])
                        if tool_name not in post_tool_policy_metadata["tools"]:
                            post_tool_policy_metadata["tools"].append(tool_name)
                        aggregate_response_decision = ResponseDecision(
                            response_shape=post_tool_response_decision.response_shape,
                            template=post_tool_response_decision.template,
                            required_slots=post_tool_response_decision.required_slots,
                            forbidden_behaviors=tuple(post_tool_forbidden_behaviors),
                            assistant_guidance=post_tool_response_decision.assistant_guidance,
                            metadata=dict(post_tool_policy_metadata),
                        )
                        policy_slots: dict[str, Any] = {}
                        if initial_slots is not None and hasattr(initial_slots, "model_dump"):
                            policy_slots.update({
                                key: value
                                for key, value in initial_slots.model_dump().items()
                                if value not in (None, "", [], {})
                            })
                        if pending_slots is not None and hasattr(pending_slots, "model_dump"):
                            policy_slots.update({
                                key: value
                                for key, value in pending_slots.model_dump().items()
                                if value not in (None, "", [], {})
                            })
                        if isinstance(input_data, dict):
                            policy_slots.update({
                                key: value
                                for key, value in input_data.items()
                                if value not in (None, "", [], {})
                            })
                        turn_contract = build_turn_contract(
                            user_text=user_query,
                            intent_frame=IntentFrame(
                                domain=PolicyDomain.TRANSACTION,
                                intent=_post_tool_policy_intent(tool_name),
                                known_slots=policy_slots,
                                source=f"tool_parse_failure:{tool_name}",
                            ),
                            response_decision=aggregate_response_decision,
                            routing_result=routing_result,
                            merged_slots=pending_slots or initial_slots,
                            action_mode=stream_action_mode,
                            context_state=stream_context_state,
                            resume_source=stream_resume_source,
                        )
                        logger.info("[TURN_CONTRACT] post-tool parse-failure update %s", turn_contract.to_dict())
                    if parsed_for_verifier is not None:
                        structured_sources.append((tool_name, parsed_for_verifier))
                        mapper_entry = {
                            "tool": tool_name,
                            "args": dict(input_data or {}) if isinstance(input_data, dict) else {},
                            "data": parsed_for_verifier,
                        }
                        if tool_name == "get_products_recommendations_tool":
                            mapper_entry["effective_args"] = _effective_recommendation_tool_args(
                                input_data if isinstance(input_data, dict) else {}
                            )
                        mapper_tool_items.append(mapper_entry)
                        if tool_name == "search_product_tool":
                            search_keyword = str(input_data.get("keyword") or "").strip()
                            search_product_tool_results.append((search_keyword, parsed_for_verifier))
                        elif tool_name in _HIGH_RISK_POST_TOOL_CONTRACT_TOOLS:
                            policy_slots: dict[str, Any] = {}
                            if initial_slots is not None and hasattr(initial_slots, "model_dump"):
                                policy_slots.update({
                                    key: value
                                    for key, value in initial_slots.model_dump().items()
                                    if value not in (None, "", [], {})
                                })
                            if pending_slots is not None and hasattr(pending_slots, "model_dump"):
                                policy_slots.update({
                                    key: value
                                    for key, value in pending_slots.model_dump().items()
                                    if value not in (None, "", [], {})
                                })
                            if isinstance(input_data, dict):
                                policy_slots.update({
                                    key: value
                                    for key, value in input_data.items()
                                    if value not in (None, "", [], {})
                                })
                            tool_error_summary = _tool_error_summary(tool_name, parsed_for_verifier)
                            if tool_name in {"transaction_store_preview_tool", "get_store_inventory_tool"}:
                                post_tool_intent = "inventory_availability"
                                post_tool_response_decision = decide_transaction_response(
                                    intent=post_tool_intent,
                                    user_text=user_query,
                                    known_slots=policy_slots,
                                    tool_result=parsed_for_verifier,
                                )
                            elif tool_error_summary is not None:
                                post_tool_intent = _post_tool_policy_intent(tool_name)
                                post_tool_response_decision = _tool_error_response_decision(tool_name)
                            else:
                                post_tool_intent = _post_tool_policy_intent(tool_name)
                                post_tool_response_decision = None
                            if post_tool_response_decision is not None:
                                for behavior in post_tool_response_decision.forbidden_behaviors:
                                    if behavior not in post_tool_forbidden_behaviors:
                                        post_tool_forbidden_behaviors.append(behavior)
                                post_tool_policy_metadata.update(dict(post_tool_response_decision.metadata))
                                post_tool_policy_metadata.setdefault("tools", [])
                                if tool_name not in post_tool_policy_metadata["tools"]:
                                    post_tool_policy_metadata["tools"].append(tool_name)
                                post_tool_response_decision = ResponseDecision(
                                    response_shape=post_tool_response_decision.response_shape,
                                    template=post_tool_response_decision.template,
                                    required_slots=post_tool_response_decision.required_slots,
                                    forbidden_behaviors=tuple(post_tool_forbidden_behaviors),
                                    assistant_guidance=post_tool_response_decision.assistant_guidance,
                                    metadata=dict(post_tool_policy_metadata),
                                )
                            elif post_tool_forbidden_behaviors:
                                post_tool_response_decision = ResponseDecision(
                                    response_shape=ResponseShape.NO_RESULT,
                                    template=TemplateName.QUICK_REPLY,
                                    forbidden_behaviors=tuple(post_tool_forbidden_behaviors),
                                    assistant_guidance=(
                                        "이전 고위험 tool 결과의 실패/금지 조건을 같은 턴 끝까지 유지한다."
                                    ),
                                    metadata=dict(post_tool_policy_metadata),
                                )
                            inventory_frame = IntentFrame(
                                domain=PolicyDomain.TRANSACTION,
                                intent=post_tool_intent,
                                known_slots=policy_slots,
                                source=f"tool_result:{tool_name}",
                            )
                            turn_contract = build_turn_contract(
                                user_text=user_query,
                                intent_frame=inventory_frame,
                                response_decision=post_tool_response_decision,
                                routing_result=routing_result,
                                merged_slots=pending_slots or initial_slots,
                                action_mode=stream_action_mode,
                                context_state=stream_context_state,
                                resume_source=stream_resume_source,
                            )
                            logger.info("[TURN_CONTRACT] post-tool update %s", turn_contract.to_dict())
                    turn_tool_slots: dict[str, Any] = {}
                    if tool_name == "search_product_tool" and isinstance(parsed_for_verifier, dict):
                        data = parsed_for_verifier.get("data")
                        items = data.get("items") if isinstance(data, dict) else None
                        if isinstance(items, list) and len(items) == 1 and isinstance(items[0], dict):
                            item = items[0]
                            canonical_item = canonical_context_from_tool_boundary(item)
                            if canonical_item.get("goods_no"):
                                turn_tool_slots["goods_no"] = canonical_item.get("goods_no")
                            tire_size = canonical_item.get("tire_size")
                            if tire_size:
                                turn_tool_slots["tire_size"] = tire_size
                    elif (
                        tool_name == "transaction_store_preview_tool"
                        and isinstance(input_data, dict)
                        and _allows_outer_tool_slot_staging(tool_name, stream_action_mode)
                    ):
                        preserve_confirmed_preview_slots = _is_confirmed_product_store_scope_followup(
                            user_query,
                            initial_slots,
                        )
                        input_goods_no = input_data.get("goods_no")
                        if (
                            preserve_confirmed_preview_slots
                            and initial_slots is not None
                            and getattr(initial_slots, "goods_no", None)
                        ):
                            input_goods_no = getattr(initial_slots, "goods_no", None)
                        if input_goods_no:
                            turn_tool_slots["goods_no"] = input_goods_no
                        tire_size = input_data.get("tire_size")
                        if tire_size:
                            turn_tool_slots["tire_size"] = tire_size
                        quantity = input_data.get("ord_qty") or input_data.get("quantity")
                        if (
                            preserve_confirmed_preview_slots
                            and initial_slots is not None
                            and getattr(initial_slots, "ord_qty", None)
                        ):
                            quantity = getattr(initial_slots, "ord_qty", None)
                        if quantity:
                            try:
                                turn_tool_slots["ord_qty"] = int(quantity)
                            except (TypeError, ValueError):
                                pass
                        region = input_data.get("region_code") or input_data.get("region")
                        if region:
                            turn_tool_slots["region"] = region
                        requested_cal_day = input_data.get("requested_cal_day")
                        if requested_cal_day:
                            turn_tool_slots["requested_cal_day"] = str(requested_cal_day)
                            turn_tool_slots["availability_intent"] = "today_install"
                    if turn_tool_slots:
                        base_slots = pending_slots
                        if base_slots is None:
                            base_slots = initial_slots.model_copy() if initial_slots is not None else ConversationSlots()
                        updated_slots = base_slots.apply_runtime_values(
                            turn_tool_slots,
                            source=f"outer_tool:{tool_name}",
                        )
                        if updated_slots.model_dump() != base_slots.model_dump():
                            pending_slots = updated_slots
                            logger.info("[SLOTS] staged outer tool slots from %s: %s", tool_name, turn_tool_slots)

                    coupon_decision = await _get_coupon_gate_decision()
                    if (
                        tool_name == "get_my_coupons_tool"
                        and not coupon_resolver_ran
                        and _is_owned_coupon_expiry_lookup_query(user_query)
                    ):
                        coupon_resolver_ran = True
                        code_events, deterministic_coupon_event = (
                            await _resolve_owned_coupon_expiry_lookup_with_code(parsed_for_verifier)
                        )
                        for code_event in code_events:
                            yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                    elif (
                        tool_name == "get_my_coupons_tool"
                        and not coupon_resolver_ran
                        and (
                            _is_product_coupon_eligibility_decision(coupon_decision)
                            or _is_product_coupon_eligibility_query(user_query)
                        )
                    ):
                        coupon_resolver_ran = True
                        product_coupon_resolution = await _resolve_product_coupon_eligibility_with_code(
                            parsed_for_verifier,
                            target_product_name=(
                                coupon_decision.product_name if coupon_decision is not None else None
                            ),
                        )
                        if product_coupon_resolution is not None:
                            code_events, deterministic_coupon_event = product_coupon_resolution
                            for code_event in code_events:
                                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                    elif (
                        tool_name == "get_my_coupons_tool"
                        and not coupon_resolver_ran
                        and (
                            _is_owned_coupon_best_discount_decision(coupon_decision)
                            or _is_owned_coupon_best_discount_query(user_query)
                        )
                    ):
                        coupon_resolver_ran = True
                        code_events, deterministic_coupon_event = (
                            await _resolve_owned_coupon_best_discount_with_code(parsed_for_verifier)
                        )
                        for code_event in code_events:
                            yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                    elif (
                        tool_name == "get_my_coupons_tool"
                        and not coupon_resolver_ran
                        and (
                            _is_coupon_applicable_products_decision(
                                coupon_decision,
                                user_text=user_query,
                                slots=pending_slots or initial_slots,
                                recent_context=recent_user_context_text,
                            )
                            or (
                                coupon_decision is None
                                and _COUPON_APPLICABILITY_INTENT_RE.search(user_query)
                                and not _COUPON_ISSUE_INTENT_RE.search(user_query)
                            )
                        )
                    ):
                        coupon_resolver_ran = True
                        code_events, deterministic_coupon_event = (
                            await _resolve_coupon_applicability_with_code(parsed_for_verifier)
                        )
                        for code_event in code_events:
                            yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"

                continue

            if event_type == "internal_slots":
                pending_slots = event.get("slots")
                continue

            # --- INTERCEPT EARLY DONE EVENT ---
            if event_type == "sub-agent" and event.get("agent") == "[DONE]":
                coordinator_done_event = event
                continue

            # --- INTERCEPT DATA EVENTS (UI Template Agent) ---
            if event_type == "data":
                if _lat_waiting_post_tool_output_since is not None:
                    _post_tool_ms = (_lat_now - _lat_waiting_post_tool_output_since) * 1000
                    _lat_agent_post_tool_output_ms += _post_tool_ms
                    logger.debug(f"[LATENCY]   post_tool_data_event={_post_tool_ms:.0f}ms")
                    _lat_waiting_post_tool_output_since = None
                last_template = event.get("template") or last_template
                event_template_source = event.pop("template_source", None)
                if isinstance(event_template_source, str):
                    last_template_source = event_template_source
                event_response_source = event.pop("assistant_response_source", None)
                if isinstance(event_response_source, str):
                    last_assistant_response_source = event_response_source
                event_data = event.get("data", {})
                if is_external_price_comparison_request(user_query):
                    deterministic_external_price_event = _build_external_price_comparison_event_from_search_results(
                        user_query,
                        [
                            *search_product_tool_results,
                            *_external_price_search_results_from_sources(structured_sources),
                        ],
                    )
                    if deterministic_external_price_event is not None:
                        logger.info("[EXTERNAL_PRICE] replacing data event with external price policy summary")
                        event = deterministic_external_price_event
                        last_template = "quickReply"
                        last_template_source = "code_mapper"
                        last_assistant_response_source = "code_external_price_comparison_policy"
                        event_data = event.get("data", {})
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[DISCOVERY AGENT]",
                        }]
                if event.get("template") == "listCar":
                    if (
                        _should_apply_product_attribute_resolver(user_query, called_tool_names)
                        and _should_replace_listcar_with_product_attribute_lookup(event, user_query)
                    ):
                        product_attribute_resolution = await _resolve_product_attribute_with_code()
                        if product_attribute_resolution is not None:
                            code_events, attribute_event = product_attribute_resolution
                            logger.info("[PRODUCT_ATTRIBUTE] replacing accidental listCar with search result summary")
                            for code_event in code_events:
                                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                            event = attribute_event
                            last_template = "quickReply"
                            last_template_source = "code_mapper"
                            last_assistant_response_source = "code_product_attribute_resolver"
                            event_data = event.get("data", {})
                    code_events, auto_selected_event = await _auto_continue_selected_vehicle(event)
                    if event.get("template") == "listCar" and auto_selected_event is not None:
                        logger.info("[VEHICLE_AUTO_SELECT] replacing listCar with continued vehicle flow")
                        for code_event in code_events:
                            yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                        event = auto_selected_event
                        last_template = event.get("template") or last_template
                        last_template_source = "code_mapper"
                        last_assistant_response_source = "code_vehicle_auto_select"
                        event_data = event.get("data", {})
                    elif _is_oe_replacement_context(recent_user_context_text, user_query):
                        event = _build_oe_replacement_guidance_event(
                            None,
                            user_query,
                            include_vehicle_selection=True,
                        )
                        last_template = "quickReply"
                        last_template_source = "code_mapper"
                        last_assistant_response_source = "code_oe_replacement_guidance"
                        event_data = event.get("data", {})
                    coerced_event = _coerce_unmatched_vehicle_listcar_to_owner_prompt(event, user_query)
                    if coerced_event is not None:
                        from schemas.tstation.slots import ConversationSlots

                        plate_match = _VEHICLE_PLATE_RE.search(user_query or "")
                        pending_plate = (
                            re.sub(r"[^0-9가-힣]", "", plate_match.group(0))
                            if plate_match
                            else None
                        )
                        if pending_plate:
                            base_slots = pending_slots
                            if base_slots is None:
                                base_slots = initial_slots.model_copy() if initial_slots is not None else ConversationSlots()
                            updated_slots = base_slots.model_copy()
                            updated_slots.pending_vehicle_lookup_car_no = pending_plate
                            if updated_slots.model_dump() != base_slots.model_dump():
                                pending_slots = updated_slots
                                logger.info(
                                    "[VEHICLE_OWNER_LOOKUP] staged pending unmatched plate=%s",
                                    pending_plate,
                                )
                        event = coerced_event
                        last_template = "quickReply"
                        last_template_source = "code_mapper"
                        last_assistant_response_source = "code_vehicle_owner_lookup_prompt"
                        event_data = event.get("data", {})
                if event.get("template") == "product" and _is_product_size_list_intent(user_query):
                    deterministic_size_list_event = _build_product_size_list_event_from_search_results(
                        user_query,
                        search_product_tool_results,
                        prev_tool_data=prev_tool_data or [],
                        recent_context=recent_user_context_text,
                        slots=pending_slots or initial_slots,
                    )
                    if deterministic_size_list_event is not None:
                        logger.info("[PRODUCT_SIZE_LIST] replacing product card with size list quickReply")
                        event = deterministic_size_list_event
                        last_template = "quickReply"
                        last_template_source = "code_mapper"
                        last_assistant_response_source = "code_product_size_list"
                        event_data = event.get("data", {})
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                coerced_event = None
                if intent_group != "existing_reservation_management" and _allows_transaction_action_mode(stream_action_mode):
                    coerced_event = coerce_reservation_quickreply_to_datepick(
                        event,
                        structured_sources,
                        pending_slots or initial_slots,
                    )
                if coerced_event is not None:
                    logger.warning(
                        "[TEMPLATE_COERCE] transaction_store_preview quickReply time chips → datepick"
                    )
                    event = coerced_event
                    last_template = "datepick"
                    last_template_source = "code_mapper"
                    last_assistant_response_source = "code_mapper_preview_quickreply"
                    event_data = event.get("data", {})
                coerced_event = None
                if intent_group != "existing_reservation_management" and _allows_transaction_action_mode(stream_action_mode):
                    coerced_event = coerce_order_preview_quickreply_to_datepick(
                        event,
                        structured_sources,
                        pending_slots or initial_slots,
                    )
                if coerced_event is not None:
                    logger.warning(
                        "[TEMPLATE_COERCE] transaction_store_preview order quickReply → datepick"
                    )
                    event = coerced_event
                    last_template = "datepick"
                    last_template_source = "code_mapper"
                    last_assistant_response_source = "code_mapper_order_preview_quickreply"
                    event_data = event.get("data", {})
                coerced_event = filter_datepick_to_requested_weekday(event, user_query)
                if coerced_event is not None:
                    logger.warning(
                        "[TEMPLATE_COERCE] datepick filtered to requested weekday"
                    )
                    event = coerced_event
                    last_template = "datepick"
                    last_template_source = last_template_source or "code_mapper"
                    last_assistant_response_source = "code_mapper_weekday_filter"
                    event_data = event.get("data", {})
                coerced_event = filter_datepick_to_requested_date(event, user_query)
                if coerced_event is not None:
                    logger.warning(
                        "[TEMPLATE_COERCE] datepick filtered to requested date"
                    )
                    event = coerced_event
                    last_template = "datepick"
                    last_template_source = last_template_source or "code_mapper"
                    last_assistant_response_source = "code_mapper_date_filter"
                    event_data = event.get("data", {})
                coerced_event = _coerce_vehicle_type_compatibility_listcar_to_quickreply(event, user_query)
                if coerced_event is not None:
                    logger.warning(
                        "[TEMPLATE_COERCE] discovery SUV/passenger compatibility listCar → quickReply"
                    )
                    event = coerced_event
                    last_template = "quickReply"
                    last_template_source = "code_mapper"
                    last_assistant_response_source = "code_mapper_vehicle_type_compatibility_guard"
                    event_data = event.get("data", {})
                coerced_event = _coerce_non_selection_listcar_to_quickreply(event)
                if coerced_event is not None:
                    logger.warning(
                        "[TEMPLATE_COERCE] discovery listCar advice turn → quickReply"
                    )
                    event = coerced_event
                    last_template = "quickReply"
                    last_template_source = "code_mapper"
                    last_assistant_response_source = "code_mapper_listcar_advice_guard"
                    event_data = event.get("data", {})
                if TStationChatServiceV2._should_drop_template_for_intent_group(event, intent_group):
                    logger.warning(
                        "[CONTEXT_POLICY] dropped stale template=%s intent_group=%s user_query=%r",
                        event.get("template"),
                        intent_group,
                        user_query[:80],
                    )
                    continue
                for value in _quick_reply_domain_values_from_event(event):
                    if value not in next_quick_reply_domain_values:
                        next_quick_reply_domain_values.append(value)
                for value in _predicted_domain_values_from_event(event):
                    if value not in next_predicted_domain_values:
                        next_predicted_domain_values.append(value)
                if (
                    str(event.get("source_domain", "")).lower() == MultiAgentDomain.Domain.DISCOVERY.value
                    and event.get("template") in {"product", "quickReply", "listCar"}
                ):
                    deterministic_external_price_event = _build_external_price_comparison_event_from_search_results(
                        user_query,
                        search_product_tool_results,
                    )
                    if deterministic_external_price_event is not None:
                        logger.info("[EXTERNAL_PRICE] replacing discovery event with external price policy summary")
                        event = deterministic_external_price_event
                        last_template = "quickReply"
                        last_template_source = "code_mapper"
                        last_assistant_response_source = "code_external_price_comparison_policy"
                        event_data = event.get("data", {})
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[DISCOVERY AGENT]",
                        }]
                    comparison_query = _comparison_query_with_recent_context(
                        user_query,
                        messages,
                        latest_quickreply_tmpl,
                        slots=pending_slots or initial_slots,
                    )
                    deterministic_compare_event = (
                        None
                        if (
                            deterministic_external_price_event is not None
                            or _should_skip_product_compare_override(user_query, called_tool_names)
                        )
                        else _build_product_comparison_event_from_search_results(
                            comparison_query,
                            search_product_tool_results,
                        )
                    )
                    if (
                        _is_product_comparison_query(comparison_query)
                        and (
                            event.get("template") == "product"
                            or deterministic_compare_event is None
                            or _is_product_compare_missing_event(deterministic_compare_event)
                        )
                    ):
                        product_compare_resolution = await _resolve_product_comparison_with_code()
                        if product_compare_resolution is not None:
                            code_events, deterministic_compare_event = product_compare_resolution
                            for code_event in code_events:
                                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                    if deterministic_compare_event is not None:
                        logger.info("[PRODUCT_COMPARE] replacing discovery event with product detail comparison")
                        event = deterministic_compare_event
                        last_template = "quickReply"
                        last_template_source = "code_mapper"
                        last_assistant_response_source = "code_product_compare_resolver"
                        event_data = event.get("data", {})
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[DISCOVERY AGENT]",
                        }]
                    apply_product_attribute_resolver = (
                        False
                        if deterministic_external_price_event is not None
                        else _should_apply_product_attribute_resolver(
                            user_query,
                            called_tool_names,
                        )
                    )
                    deterministic_attribute_event = (
                        _build_product_attribute_event_from_search_results(
                            user_query,
                            search_product_tool_results,
                        )
                        if apply_product_attribute_resolver
                        else None
                    )
                    if (
                        apply_product_attribute_resolver
                        and (
                            event.get("template") == "product"
                            or deterministic_attribute_event is None
                            or _is_product_attribute_fallback_event(event)
                        )
                    ):
                        product_attribute_resolution = await _resolve_product_attribute_with_code()
                        if product_attribute_resolution is not None:
                            code_events, deterministic_attribute_event = product_attribute_resolution
                            for code_event in code_events:
                                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                    if deterministic_attribute_event is not None:
                        logger.info("[PRODUCT_ATTRIBUTE] replacing discovery event with search result summary")
                        event = deterministic_attribute_event
                        last_template = "quickReply"
                        last_template_source = "code_mapper"
                        last_assistant_response_source = "code_product_attribute_resolver"
                        event_data = event.get("data", {})
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[DISCOVERY AGENT]",
                        }]
                    stored_context = None
                    if initial_slots is not None:
                        stored_variants = getattr(initial_slots, "recommendation_variants", None)
                        if stored_variants:
                            stored_context = {
                                "variants": stored_variants,
                                "limit_per_variant": getattr(initial_slots, "recommendation_limit_per_variant", None),
                                "source_text": getattr(initial_slots, "recommendation_source_text", None),
                            }
                    multi_variant_constraints = _infer_multi_variant_recommendation_constraints(
                        messages,
                        user_query,
                        stored_context=stored_context,
                    )
                    requested_variant_count = len(tuple((multi_variant_constraints or {}).get("variants") or ()))
                    if requested_variant_count >= 2:
                        multi_variant_resolution = await _resolve_multi_variant_recommendation_with_code()
                        if multi_variant_resolution is not None:
                            code_events, deterministic_variant_event = multi_variant_resolution
                            for code_event in code_events:
                                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                            logger.info("[MULTI_VARIANT] replacing discovery event with fan-out result")
                            event = deterministic_variant_event
                            last_template = event.get("template") or last_template
                            last_template_source = "code_mapper"
                            last_assistant_response_source = "code_multi_variant_recommendation"
                            event_data = event.get("data", {})
                if isinstance(event_data, dict):
                    _stage_comparison_context_slots(event)
                    confirmed_product_slots = TStationChatServiceV2._confirmed_product_slot_values_from_event(event)
                    if confirmed_product_slots:
                        from schemas.tstation.slots import ConversationSlots

                        base_slots = pending_slots
                        if base_slots is None:
                            base_slots = initial_slots.model_copy() if initial_slots is not None else ConversationSlots()
                        updated_slots = base_slots.apply_runtime_values(
                            confirmed_product_slots,
                            source="product_event",
                        )
                        if updated_slots.model_dump() != base_slots.model_dump():
                            pending_slots = updated_slots
                            logger.info(
                                "[PRODUCT_SLOT_STAGE] staged confirmed product slots from event: %s",
                                confirmed_product_slots,
                            )
                    can_commit_transaction_event_slots = _allows_transaction_action_mode(stream_action_mode)
                    if last_template == "preOrder" and can_commit_transaction_event_slots:
                        _standardize_preorder_metadata(event_data, pending_slots or initial_slots)
                    preorder_slots = (
                        TStationChatServiceV2._preorder_slot_values_from_data(event_data)
                        if can_commit_transaction_event_slots
                        else None
                    )
                    if preorder_slots:
                        from schemas.tstation.slots import ConversationSlots

                        base_slots = pending_slots
                        if base_slots is None:
                            base_slots = initial_slots.model_copy() if initial_slots is not None else ConversationSlots()
                        updated_slots = _apply_order_snapshot_slots(
                            base_slots,
                            preorder_slots,
                            source="preorder_event",
                        )
                        if updated_slots.model_dump() != base_slots.model_dump():
                            pending_slots = updated_slots
                            logger.info("[PREORDER_SLOT_COMMIT] staged canonical order snapshot: %s", preorder_slots)
                    datepick_slots = (
                        TStationChatServiceV2._datepick_slot_values_from_data(event)
                        if can_commit_transaction_event_slots
                        else None
                    )
                    if datepick_slots and (
                        getattr(pending_slots or initial_slots, "goal_type", None) == "place_order"
                        or getattr(pending_slots or initial_slots, "pending_intent", None) == "order"
                        or (
                            getattr(pending_slots or initial_slots, "goods_no", None) is not None
                            and getattr(pending_slots or initial_slots, "ord_qty", None) is not None
                        )
                    ):
                        from schemas.tstation.slots import ConversationSlots

                        base_slots = pending_slots
                        if base_slots is None:
                            base_slots = initial_slots.model_copy() if initial_slots is not None else ConversationSlots()
                        updated_slots = _apply_order_snapshot_slots(
                            base_slots,
                            datepick_slots,
                            source="datepick_event",
                            fill_only=True,
                        )
                        if updated_slots.model_dump() != base_slots.model_dump():
                            pending_slots = updated_slots
                            logger.info("[DATEPICK_SLOT_STAGE] staged order slots from datepick event: %s", datepick_slots)
                    if event_data.get("assistantResponse"):
                        assistant_response = _sanitize_response(event_data["assistantResponse"])
                        event_data["assistantResponse"] = assistant_response
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        source_domain = str(event.get("source_domain", "ui_template")).upper()
                        assistant_msg_event = {
                            "type": "message",
                            "content": assistant_response,
                            "agent": f"[{source_domain} AGENT]",
                        }
                        original_message_events.append(assistant_msg_event)
                        logger.debug(
                            f"[COORDINATOR] Captured assistantResponse from data event ({source_domain}): {assistant_response[:50]}..."
                        )
                    # For Path B templates only — LLM wrote the JSON so QC must verify it.
                    # Path A templates (code mapper) are correct by construction; including their
                    # JSON confuses QC into unnecessary text rewrites.
                    if last_template in _LLM_WRITTEN_TEMPLATES:
                        template_payload = {k: v for k, v in event_data.items() if k != "assistantResponse"}
                        if template_payload:
                            draft_for_qc += f"\n\n[Template: {last_template}]\n{json.dumps(template_payload, ensure_ascii=False)}"
                if (
                    isinstance(event_data, dict)
                    and str(event.get("source_domain", "")).lower()
                    == MultiAgentDomain.Domain.TRANSACTION.value
                    and _COUPON_ISSUE_INTENT_RE.search(user_query)
                ):
                    event = _coupon_issue_event()
                    last_template = "quickReply"
                    last_template_source = "code_mapper"
                    last_assistant_response_source = "code_coupon_issue_guard"
                    event_data = event.get("data", {})
                    assistant_response = str(event_data.get("assistantResponse") or "")
                    draft_response = assistant_response
                    draft_for_qc = assistant_response
                    original_message_events = [{
                        "type": "message",
                        "content": assistant_response,
                        "agent": "[TRANSACTION AGENT]",
                    }]
                coerced_event = _coerce_order_summary_quickreply_to_preorder(event, initial_slots)
                if coerced_event is not None:
                    logger.warning(
                        "[TEMPLATE_COERCE] transaction order summary quickReply → preOrder"
                    )
                    event = coerced_event
                    last_template = "preOrder"
                    last_template_source = "code_mapper"
                    last_assistant_response_source = "code_preorder_summary_guard"
                    event_data = event.get("data", {})
                    assistant_response = str(event_data.get("assistantResponse") or "")
                    draft_response = assistant_response
                    draft_for_qc = assistant_response
                    original_message_events = [{
                        "type": "message",
                        "content": assistant_response,
                        "agent": "[TRANSACTION AGENT]",
                    }]
                # Inject quickReplies into orderComplete (LLM-written path; mapper path injects via _map_order_complete).
                if last_template == "orderComplete" and isinstance(event_data, dict) and "quickReplies" not in event_data:
                    if event_data.get("isSuccess"):
                        event_data["quickReplies"] = [
                            {"label": "주문 내역 확인", "domain": "TRANSACTION"},
                            {"label": "배송 상태 확인", "domain": "TRANSACTION"},
                        ]
                    else:
                        event_data["quickReplies"] = [
                            {"label": "다시 시도", "domain": "TRANSACTION"},
                        ]
                # Defensive fallback for quickReply template: if LLM emitted empty quickReplies,
                # inject context-aware chips so the user is never stranded. Skip when the turn
                # is an auto-chained handoff (nextAction.type == "continue") because the
                # coordinator runs the next agent in the same turn and chips would be noise.
                # Chip set is selected from called_tool_names so the fallback matches the
                # conversation context (e.g., order list → order-related chips, not a generic
                # "1:1 문의" pair which makes the order flow look broken).
                if (
                    last_template == "quickReply"
                    and isinstance(event_data, dict)
                    and last_assistant_response_source != "code_product_compare_resolver"
                ):
                    source_domain = str(event.get("source_domain", "ui_template")).lower()
                    repaired_product_description_event = _build_repaired_product_description_event(
                        structured_sources=structured_sources,
                        called_tool_names=called_tool_names,
                        source_domain=source_domain,
                        user_text=user_query,
                    )
                    if repaired_product_description_event is not None:
                        logger.info("[PRODUCT_DESCRIPTION] replaced quickReply with deterministic detail summary")
                        event = repaired_product_description_event
                        last_template = "quickReply"
                        last_template_source = "code_mapper"
                        last_assistant_response_source = "code_product_description"
                        event_data = event.get("data", {})
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[DISCOVERY AGENT]",
                        }]
                    if source_domain == MultiAgentDomain.Domain.DISCOVERY.value:
                        comparison_query = _comparison_query_with_recent_context(
                            user_query,
                            messages,
                            latest_quickreply_tmpl,
                            slots=pending_slots or initial_slots,
                        )
                        deterministic_compare_event = (
                            None
                            if _should_skip_product_compare_override(user_query, called_tool_names)
                            else _build_product_comparison_event_from_search_results(
                                comparison_query,
                                search_product_tool_results,
                            )
                        )
                        if (
                            _is_product_comparison_query(comparison_query)
                            and (
                                deterministic_compare_event is None
                                or _is_product_compare_missing_event(deterministic_compare_event)
                            )
                        ):
                            product_compare_resolution = await _resolve_product_comparison_with_code()
                            if product_compare_resolution is not None:
                                code_events, deterministic_compare_event = product_compare_resolution
                                for code_event in code_events:
                                    yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                        if deterministic_compare_event is not None:
                            logger.info("[PRODUCT_COMPARE] replacing quickReply with existing search results")
                            event = deterministic_compare_event
                            last_template = "quickReply"
                            last_template_source = "code_mapper"
                            last_assistant_response_source = "code_product_compare_resolver"
                            event_data = event.get("data", {})
                            assistant_response = str(event_data.get("assistantResponse") or "")
                            draft_response = assistant_response
                            draft_for_qc = assistant_response
                            original_message_events = [{
                                "type": "message",
                                "content": assistant_response,
                                "agent": "[DISCOVERY AGENT]",
                            }]
                        elif "search_product_tool" not in called_tool_names:
                            product_compare_resolution = await _resolve_product_comparison_with_code()
                            if product_compare_resolution is not None:
                                code_events, deterministic_grade_event = product_compare_resolution
                                for code_event in code_events:
                                    yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                                logger.info("[PRODUCT_COMPARE] replacing quickReply with code result")
                                event = deterministic_grade_event
                                last_template = "quickReply"
                                last_template_source = "code_mapper"
                                last_assistant_response_source = "code_product_compare_resolver"
                                event_data = event.get("data", {})
                                assistant_response = str(event_data.get("assistantResponse") or "")
                                draft_response = assistant_response
                                draft_for_qc = assistant_response
                                original_message_events = [{
                                    "type": "message",
                                    "content": assistant_response,
                                    "agent": "[DISCOVERY AGENT]",
                                }]
                    current_policy_decision = _response_decision_for_source_domain(source_domain)
                    if _normalize_policy_guidance_leak_quickreply(
                        event_data,
                        source_domain=source_domain,
                        decision=current_policy_decision,
                    ):
                        logger.info("[POLICY] quickReply assistant_guidance leak normalized")
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[DISCOVERY AGENT]" if source_domain == "discovery" else "[TRANSACTION AGENT]",
                        }]
                    if (
                        intent_group == "existing_reservation_management"
                        and event.get("template") == "quickReply"
                        and _normalize_existing_reservation_change_quickreply(
                            event_data,
                            last_user_text=user_query,
                            called_tool_names={tool_name for tool_name, _ in structured_sources},
                        )
                    ):
                        logger.info("[RESERVATION_CHANGE] normalized direct-change guidance")
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[TRANSACTION AGENT]",
                        }]
                    if (
                        source_domain == MultiAgentDomain.Domain.TRANSACTION.value
                        and event.get("template") == "quickReply"
                        and _should_replace_vague_store_detail_quickreply(event_data)
                        and not _is_active_order_flow_slots(pending_slots or initial_slots)
                    ):
                        store_detail_event = _store_detail_quickreply_from_sources(
                            structured_sources,
                            str(event_data.get("assistantResponse") or ""),
                        )
                        if store_detail_event is not None:
                            logger.info("[STORE_DETAIL] replaced vague quickReply with deterministic store detail")
                            event = store_detail_event
                            last_template = "quickReply"
                            last_template_source = "code_mapper"
                            last_assistant_response_source = "code_store_detail_resolver"
                            event_data = event.get("data", {})
                            assistant_response = str(event_data.get("assistantResponse") or "")
                            draft_response = assistant_response
                            draft_for_qc = assistant_response
                            original_message_events = [{
                                "type": "message",
                                "content": assistant_response,
                                "agent": "[TRANSACTION AGENT]",
                            }]
                    coupon_decision = await _get_coupon_gate_decision()
                    if (
                        deterministic_coupon_event is None
                        and not coupon_resolver_ran
                        and source_domain in {
                            MultiAgentDomain.Domain.TRANSACTION.value,
                            MultiAgentDomain.Domain.DISCOVERY.value,
                        }
                        and (
                            _is_product_coupon_eligibility_decision(coupon_decision)
                            or _is_product_coupon_eligibility_query(user_query)
                        )
                    ):
                        coupon_resolver_ran = True
                        product_coupon_resolution = await _resolve_product_coupon_eligibility_with_code(
                            target_product_name=(
                                coupon_decision.product_name if coupon_decision is not None else None
                            )
                        )
                        if product_coupon_resolution is not None:
                            code_events, deterministic_coupon_event = product_coupon_resolution
                            for code_event in code_events:
                                yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                    elif (
                        deterministic_coupon_event is None
                        and not coupon_resolver_ran
                        and source_domain in {
                            MultiAgentDomain.Domain.TRANSACTION.value,
                            MultiAgentDomain.Domain.DISCOVERY.value,
                        }
                        and (
                            _is_owned_coupon_best_discount_decision(coupon_decision)
                            or _is_owned_coupon_best_discount_query(user_query)
                        )
                    ):
                        coupon_resolver_ran = True
                        code_events, deterministic_coupon_event = (
                            await _resolve_owned_coupon_best_discount_with_code()
                        )
                        for code_event in code_events:
                            yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                    elif (
                        deterministic_coupon_event is None
                        and not coupon_resolver_ran
                        and source_domain in {
                            MultiAgentDomain.Domain.TRANSACTION.value,
                            MultiAgentDomain.Domain.DISCOVERY.value,
                        }
                        and (
                            _is_coupon_applicable_products_decision(
                                coupon_decision,
                                user_text=user_query,
                                slots=pending_slots or initial_slots,
                                recent_context=recent_user_context_text,
                            )
                            or (coupon_decision is None and _is_strong_coupon_applicability_query(user_query))
                        )
                    ):
                        coupon_resolver_ran = True
                        code_events, deterministic_coupon_event = (
                            await _resolve_coupon_applicability_with_code()
                        )
                        for code_event in code_events:
                            yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                    elif (
                        deterministic_coupon_event is None
                        and not coupon_resolver_ran
                        and source_domain == MultiAgentDomain.Domain.TRANSACTION.value
                        and (
                            _is_coupon_applicable_products_decision(
                                coupon_decision,
                                user_text=user_query,
                                slots=pending_slots or initial_slots,
                                recent_context=recent_user_context_text,
                            )
                            or (
                                coupon_decision is None
                                and _COUPON_APPLICABILITY_INTENT_RE.search(user_query)
                                and not _COUPON_ISSUE_INTENT_RE.search(user_query)
                            )
                        )
                        and (
                            re.search(
                                r"쿠폰\s*번호|cpn_no|기획전\s*번호|쿠폰함",
                                str(event_data.get("assistantResponse") or ""),
                                re.IGNORECASE,
                            )
                            or _SIZE_FIRST_COUPON_TEXT_RE.search(
                                str(event_data.get("assistantResponse") or "")
                            )
                        )
                    ):
                        coupon_resolver_ran = True
                        code_events, deterministic_coupon_event = (
                            await _resolve_coupon_applicability_with_code()
                        )
                        for code_event in code_events:
                            yield f"data: {json.dumps(code_event, ensure_ascii=False)}\n\n"
                    if deterministic_coupon_event is not None:
                        logger.info("[COUPON_RESOLVER] replacing LLM quickReply with code result")
                        event = deterministic_coupon_event
                        last_template = "quickReply"
                        last_template_source = "code_mapper"
                        last_assistant_response_source = "code_coupon_resolver"
                        event_data = event.get("data", {})
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[TRANSACTION AGENT]",
                        }]
                    elif _normalize_unmatched_coupon_quickreply(
                        event_data,
                        called_tool_names=called_tool_names,
                        source_domain=source_domain,
                        last_user_text=user_query,
                    ):
                        logger.info("[COUPON_RESOLVER] normalized unmatched coupon quickReply")
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[TRANSACTION AGENT]",
                        }]
                    if _normalize_booking_preview_quickreply(event_data, called_tool_names):
                        logger.info(
                            "[QUICKREPLY_FILTER] booking preview chips normalized"
                        )
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[TRANSACTION AGENT]",
                        }]
                    if _sanitize_transaction_cta_contracts(event_data, source_domain=source_domain):
                        logger.info("[QUICKREPLY_FILTER] sanitized transaction CTA contracts")
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[TRANSACTION AGENT]",
                        }]
                    if _normalize_price_policy_quickreply(
                        event_data,
                        source_domain=source_domain,
                        last_user_text=user_query,
                    ):
                        logger.info("[POLICY][price] quickReply normalized by response decision")
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[TRANSACTION AGENT]",
                        }]
                    if _normalize_discovery_policy_quickreply(
                        event_data,
                        source_domain=source_domain,
                        decision=_response_decision_for_source_domain(source_domain),
                    ):
                        logger.info("[POLICY][discovery] quickReply normalized by response decision")
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[DISCOVERY AGENT]",
                        }]
                    if _normalize_recommendation_approximation_response(event_data, turn_contract):
                        logger.info("[POLICY][discovery] recommendation approximation notice appended")
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[DISCOVERY AGENT]",
                        }]
                    if _ensure_my_goods_review_lookup_cta(
                        event_data,
                        cta_required=_my_goods_review_lookup_cta_required(
                            routing_result=routing_result,
                            turn_contract=turn_contract,
                        ),
                    ):
                        logger.info("[POLICY][support] goods review lookup CTA enforced")
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[SUPPORT AGENT]",
                        }]
                    elif _ensure_store_review_write_cta(
                        event_data,
                        cta_required=_store_review_write_cta_required(
                            routing_result=routing_result,
                            turn_contract=turn_contract,
                        ),
                    ):
                        logger.info("[POLICY][support] store review write CTA enforced")
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[SUPPORT AGENT]",
                        }]
                    coerced_event = None
                    if (
                        intent_group != "existing_reservation_management"
                        and last_assistant_response_source != "discovery_policy"
                        and _allows_transaction_action_mode(stream_action_mode)
                    ):
                        coerced_event = coerce_schedule_confirmation_quickreply_to_datepick(
                            event,
                            user_text=user_query,
                            latest_datepick_data=latest_datepick_tmpl,
                            structured_sources=[
                                *[
                                    (str(entry.get("tool") or ""), entry.get("data"))
                                    for entry in (prev_tool_data or [])
                                    if isinstance(entry, dict) and isinstance(entry.get("data"), dict)
                                ],
                                *structured_sources,
                            ],
                            default_source_domain=MultiAgentDomain.Domain.TRANSACTION.value,
                        )
                    if coerced_event is not None:
                        logger.warning(
                            "[TEMPLATE_COERCE] schedule confirmation quickReply → latest datepick"
                        )
                        event = coerced_event
                        last_template = "datepick"
                        last_template_source = "code_mapper"
                        last_assistant_response_source = "code_mapper_schedule_confirmation"
                        event_data = event.get("data", {})
                        assistant_response = str(event_data.get("assistantResponse") or "")
                        draft_response = assistant_response
                        draft_for_qc = assistant_response
                        original_message_events = [{
                            "type": "message",
                            "content": assistant_response,
                            "agent": "[TRANSACTION AGENT]",
                        }]
                    existing_chips = event_data.get("quickReplies")
                    chips_empty = not isinstance(existing_chips, list) or len(existing_chips) == 0
                    next_action = event.get("nextAction") or {}
                    is_handoff = isinstance(next_action, dict) and next_action.get("type") == "continue"
                    is_current_quickreply = event.get("template") == "quickReply"
                    if is_current_quickreply and chips_empty and not is_handoff:
                        fallback_chips, fallback_label = _choose_quickreply_fallback(
                            called_tool_names,
                            source_domain,
                            assistant_response,
                        )
                        logger.warning(
                            "[QUICKREPLY_FALLBACK] empty quickReplies (domain=%s tools=%s) → %s",
                            source_domain,
                            sorted(called_tool_names),
                            fallback_label,
                        )
                        event_data["quickReplies"] = fallback_chips
                    if (
                        is_current_quickreply
                        and _inject_store_detail_chip_for_contact_guidance(
                            event_data,
                            tool_data_list=[*(prev_tool_data or []), *tool_context_items],
                            messages=messages,
                        )
                    ):
                        logger.info("[QUICKREPLY_FILTER] injected store detail chip for store-contact guidance")
                    if (
                        is_current_quickreply
                        and _inject_order_history_chip_for_cancel_guidance(
                            event_data,
                            tool_data_list=[*(prev_tool_data or []), *tool_context_items],
                            last_user_text=user_query,
                        )
                    ):
                        logger.info("[QUICKREPLY_FILTER] injected order history chip for cancel guidance")
                    if (
                        is_current_quickreply
                        and _normalize_order_cancel_request_guidance(
                            event_data,
                            tool_data_list=[*(prev_tool_data or []), *tool_context_items],
                            last_user_text=user_query,
                        )
                    ):
                        logger.info("[QUICKREPLY_FILTER] normalized order cancel request guidance")
                    if is_current_quickreply and _inject_destination_cta_for_guidance(event_data):
                        logger.info("[QUICKREPLY_FILTER] injected destination CTA for guidance")
                    if (
                        is_current_quickreply
                        and not is_handoff
                        and _looks_like_generic_dead_end_chips(event_data.get("quickReplies"))
                    ):
                        recovery = _discovery_recovery_chips_for_text(
                            str(event_data.get("assistantResponse") or ""),
                            source_domain,
                        )
                        if recovery is not None:
                            recovery_chips, recovery_label = recovery
                            logger.warning(
                                "[QUICKREPLY_FALLBACK] replacing discovery dead-end chips "
                                "(domain=%s tools=%s) → %s",
                                source_domain,
                                sorted(called_tool_names),
                                recovery_label,
                            )
                            event_data["quickReplies"] = recovery_chips
                            event_data["predictedDomains"] = _dedupe_domain_values([
                                str(chip.get("domain", ""))
                                for chip in recovery_chips
                                if isinstance(chip, dict)
                            ])
                if isinstance(event_data, dict) and _normalize_cart_url_for_cart_check_chip(event_data):
                    logger.info("[QUICKREPLY_FILTER] normalized cart URL for cart-check chip")
                if isinstance(event_data, dict) and _remove_home_quick_reply_chips(event_data):
                    logger.info(
                        "[QUICKREPLY_FILTER] removed home chip from %s template",
                        last_template,
                    )
                validation_event = dict(event)
                validation_event["assistant_response_source"] = last_assistant_response_source
                validation_event["called_tools"] = sorted(called_tool_names)
                validation_event["execution_plan"] = list(getattr(turn_contract, "execution_plan", ()) or ())
                validation_event["source_domain"] = str(event.get("source_domain") or "").lower()
                validation_event["response_shape_key"] = _response_shape_key_for_source_domain(
                    validation_event["source_domain"]
                )
                try:
                    template_contract_violated = violates_response_template_contract(
                        validation_event,
                        turn_contract,
                    )
                except Exception:
                    logger.exception(
                        "[TURN_CONTRACT] validation failed template=%s source_domain=%s response_shape=%s",
                        validation_event.get("template"),
                        validation_event.get("source_domain"),
                        validation_event.get("response_shape_key"),
                    )
                    template_contract_violated = bool(turn_contract)
                if template_contract_violated and turn_contract is not None:
                    logger.warning(
                        "[TURN_CONTRACT] blocked template=%s response_shape=%s required_slots=%s intent=%s",
                        validation_event.get("template"),
                        validation_event.get("response_shape_key"),
                        list(turn_contract.required_slots) if turn_contract else [],
                        turn_contract.intent if turn_contract else None,
                    )
                    event = _build_turn_contract_fallback_event(
                        turn_contract=turn_contract,
                        user_text=user_query,
                        tool_data_list=[
                            *tool_context_items,
                            *mapper_tool_items,
                            *[
                                {"tool": tool_name, "data": tool_output}
                                for tool_name, tool_output in structured_sources
                            ],
                        ],
                    ) or build_response_policy_guard_event(turn_contract)
                    last_template = "quickReply"
                    last_template_source = "turn_contract"
                    last_assistant_response_source = str(
                        event.get("assistant_response_source") or "code_turn_contract_template_guard"
                    )
                    event_data = event.get("data", {})
                    assistant_response = str(event_data.get("assistantResponse") or "")
                    draft_response = assistant_response
                    draft_for_qc = assistant_response
                    original_message_events = [{
                        "type": "message",
                        "content": assistant_response,
                        "agent": "[TRANSACTION AGENT]",
                    }]
                if isinstance(event_data, dict) and _normalize_tstation_cta_urls_for_origin(event_data):
                    logger.info("[CTA_URL] rebased T-Station CTA URLs to request origin host")
                if _augment_recent_product_set_ranking_metadata(event, user_query):
                    logger.info("[RECENT_PRODUCT_SET] augmented ranking response metadata")
                # Buffer data event — yield after QC so assistantResponse is always verified
                buffered_data_events.append(event)
                continue

            # --- RESET DRAFT when a new sub-agent starts (multi-agent chaining) ---
            # The second agent receives the first agent's context and produces a unified response,
            # so we only need the last agent's output for QC.
            if event_type == "sub-agent" and event.get("agent", "") != "[UI TEMPLATE AGENT]":
                _sub_status = event.get("status")
                _sub_agent = event.get("agent", "?")
                if _sub_status == "start":
                    if _lat_prev_agent_done is not None:
                        _decision_ms = (_lat_now - _lat_prev_agent_done) * 1000
                        _lat_decide_next_action_ms += _decision_ms
                        logger.debug(f"[LATENCY] decide_next_action={_decision_ms:.0f}ms")
                    _lat_agent_start = _lat_now
                    _lat_agent_name = _sub_agent
                    _lat_think_start = None
                    _lat_pre_tool_think_start = None
                    _lat_first_token_seen = False
                    _lat_first_token_time = None
                    _lat_waiting_post_tool_output_since = None
                    agent_count += 1
                    if agent_count > 1 and draft_response.strip():
                        logger.debug(
                            f"[QC_LAYER] Resetting draft_response for agent #{agent_count} — last agent should produce unified response"
                        )
                        draft_response = ""
                        draft_for_qc = ""
                        original_message_events = []
                        buffered_data_events = []
                        last_template_source = None
                        last_assistant_response_source = None
                elif _sub_status == "done" and _lat_agent_start is not None:
                    _llm_gen = (_lat_now - _lat_first_token_time) * 1000 if _lat_first_token_time else 0
                    _lat_agent_llm_generation_ms += _llm_gen
                    if _lat_waiting_post_tool_output_since is not None:
                        _post_tool_ms = (_lat_now - _lat_waiting_post_tool_output_since) * 1000
                        _lat_agent_post_tool_output_ms += _post_tool_ms
                        logger.debug(f"[LATENCY]   post_tool_done={_post_tool_ms:.0f}ms")
                        _lat_waiting_post_tool_output_since = None
                    logger.debug(
                        f"[LATENCY] agent={_lat_agent_name} total={(_lat_now - _lat_agent_start)*1000:.0f}ms "
                        f"llm_gen={_llm_gen:.0f}ms"
                    )
                    _lat_prev_agent_done = _lat_now

            # Track tool_start and LLM think timing from status events
            if event_type == "status":
                _status_val = event.get("status", "")
                if _status_val == "tool_start":
                    if _lat_pre_tool_think_start is not None:
                        _pre_tool_ms = (_lat_now - _lat_pre_tool_think_start) * 1000
                        _lat_agent_pre_tool_think_ms += _pre_tool_ms
                        logger.debug(f"[LATENCY]   llm_pre_tool_think={_pre_tool_ms:.0f}ms")
                        _lat_pre_tool_think_start = None
                    _lat_tool_start[event.get("tool", "?")] = _lat_now
                elif _status_val == "생각 중...":
                    if _lat_pre_tool_think_start is None:
                        _lat_pre_tool_think_start = _lat_now
                    _lat_think_start = _lat_now
                    _lat_first_token_seen = False

            # Pass all other events (UI templates, agent flows) through
            yield f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

        _t_agents = time.perf_counter()

        if not (
            str(draft_response or "").strip()
            or buffered_data_events
            or any(str(evt.get("content") or "").strip() for evt in original_message_events)
        ):
            no_output_fallback_event = _build_no_visible_output_fallback_event(
                user_text=user_query,
                turn_contract=turn_contract,
                structured_sources=structured_sources,
                tool_data_list=tool_context_items,
                called_tool_names=called_tool_names,
                source_domain=str(turn_contract.domain or "") if turn_contract is not None else "",
            )
            if no_output_fallback_event is not None:
                logger.warning(
                    "[NO_VISIBLE_OUTPUT] tool_called=%s forcing safe fallback=%s",
                    sorted(called_tool_names),
                    str(no_output_fallback_event.get("assistant_response_source") or ""),
                )
                assistant_response = str((no_output_fallback_event.get("data") or {}).get("assistantResponse") or "")
                buffered_data_events = [no_output_fallback_event]
                original_message_events = [{
                    "type": "message",
                    "content": assistant_response,
                    "agent": (
                        "[DISCOVERY AGENT]"
                        if str(no_output_fallback_event.get("source_domain") or "").lower()
                        == MultiAgentDomain.Domain.DISCOVERY.value
                        else "[TRANSACTION AGENT]"
                    ),
                }]
                draft_response = assistant_response
                draft_for_qc = assistant_response
                last_template = "quickReply"
                last_template_source = "no_visible_output_guard"
                last_assistant_response_source = str(
                    no_output_fallback_event.get("assistant_response_source")
                    or "code_no_visible_output_guard"
                )

        # 2. QC VERIFIER (deterministic)
        # Gated by AI_QC_ENABLED. Scans the draft for prices, goods_no, and
        # shop_id literals and checks them against the raw tool outputs
        # collected this turn. Pass-through policy: mismatches are logged and
        # surfaced in the Langfuse trace, but the draft is NEVER rewritten —
        # the verifier has no safe replacement value, and rewriting was the
        # source of the prior LLM QC's false-positive problem.
        if draft_response.strip():
            draft_response = _sanitize_response(draft_response)

            _qc_passed = True
            repair_attempt_count = 0
            contract_violations: list[dict[str, Any]] = []
            hard_violations: list[dict[str, Any]] = []
            policy_warnings: list[dict[str, Any]] = []
            _contract_sensitive_qc = bool(
                turn_contract
                and (
                    turn_contract.blocking_required_slots
                    or turn_contract.resolvable_required_slots
                    or (turn_contract.response_decision or {}).get("forbidden_behaviors")
                )
            )
            _parallel_qc = _s.AI_QC_ENABLED and _s.AI_QC_PARALLEL and not _contract_sensitive_qc
            if _s.AI_QC_ENABLED and _s.AI_QC_PARALLEL and _contract_sensitive_qc:
                logger.info("[QC_VERIFIER] forcing sequential QC for contract-sensitive turn")

            # PARALLEL MODE: yield data events immediately so FE renders without waiting for QC.
            if _parallel_qc:
                for buffered_evt in buffered_data_events:
                    _mark_first_visible()
                    yield f"data: {json.dumps(buffered_evt, ensure_ascii=False)}\n\n"

            if _s.AI_QC_ENABLED:
                _qc_started_at = time.perf_counter()
                qc_skip_reason = _qc_skip_reason(
                    called_tool_names,
                    last_template,
                    last_template_source,
                    last_assistant_response_source,
                )
                current_contract_source_domain = str(
                    ((buffered_data_events[-1] if buffered_data_events else {}) or {}).get("source_domain") or ""
                ).lower()
                current_contract_response_shape_key = _response_shape_key_from_event(
                    buffered_data_events[-1] if buffered_data_events else None
                ) or _response_shape_key_for_source_domain(
                    current_contract_source_domain
                )
                current_contract_compare_metric = _compare_metric_from_event(
                    buffered_data_events[-1] if buffered_data_events else None
                )
                contract_violations = response_contract_violations(
                    template=last_template,
                    assistant_response_text=draft_for_qc,
                    assistant_response_source=last_assistant_response_source,
                    compare_metric=current_contract_compare_metric,
                    response_shape_key=current_contract_response_shape_key,
                    called_tools=sorted(called_tool_names),
                    tool_inputs=[
                        {
                            "tool": item.get("tool"),
                            "args": item.get("args"),
                            "effective_args": item.get("effective_args"),
                        }
                        for item in mapper_tool_items
                        if isinstance(item, Mapping)
                    ],
                    source_domain=current_contract_source_domain,
                    contract=turn_contract,
                )
                hard_violations = hard_contract_violations(contract_violations)
                policy_warnings = warning_contract_violations(contract_violations)
                ranking_qc_metadata = _recent_product_set_ranking_metadata(turn_contract)
                ranking_qc_sources = (
                    [*_prev_tool_data_structured_sources(prev_tool_data), *structured_sources]
                    if ranking_qc_metadata
                    else structured_sources
                )
                ranking_qc_enabled = bool(ranking_qc_metadata and ranking_qc_sources)
                expected_brand_cd_for_qc = ""
                if turn_contract and turn_contract.domain == "discovery" and turn_contract.intent == "product_recommendation":
                    expected_brand_cd_for_qc = str(
                        (turn_contract.known_slots or {}).get("brand_cd")
                        or ""
                    ).strip()

                if (
                    (called_tool_names and qc_skip_reason is None)
                    or ranking_qc_enabled
                    or (hard_violations and not _parallel_qc)
                ):
                    qc_executed = True
                    try:
                        with _trace_span(
                            "qc",
                            trace_id=trace_id,
                            parent_span_id=parent_span_id,
                            input={
                                "user_query": user_query,
                                "draft": draft_for_qc,
                                "source_tool_count": len(ranking_qc_sources),
                                "ranking_qc": ranking_qc_metadata,
                                "turn_contract": turn_contract.to_dict() if turn_contract else None,
                            },
                        ) as _qc_span:
                            mismatches = (
                                qc_verifier.verify_draft(
                                    draft_for_qc,
                                    ranking_qc_sources,
                                    ranking_metric=ranking_qc_metadata.get("metric"),
                                    ranking_direction=ranking_qc_metadata.get("direction"),
                                    ranking_price_basis=ranking_qc_metadata.get("price_basis"),
                                    expected_brand_cd=expected_brand_cd_for_qc,
                                )
                                if (called_tool_names and qc_skip_reason is None) or ranking_qc_enabled
                                else []
                            )
                            if (
                                mismatches
                                and not hard_violations
                                and not _parallel_qc
                                and repair_attempt_count <= 1
                            ):
                                repaired_event = _repair_qc_mismatch_event(
                                    buffered_data_events[-1] if buffered_data_events else None,
                                    mismatches=mismatches,
                                )
                                repaired_response = None
                                if repaired_event is not None:
                                    repaired_response = str(
                                        ((repaired_event.get("data") or {}).get("assistantResponse") or "")
                                    ).strip()
                                if repaired_response:
                                    repair_attempt_count += 1
                                    repaired_mismatches = qc_verifier.verify_draft(
                                        repaired_response,
                                        ranking_qc_sources,
                                        ranking_metric=ranking_qc_metadata.get("metric"),
                                        ranking_direction=ranking_qc_metadata.get("direction"),
                                        ranking_price_basis=ranking_qc_metadata.get("price_basis"),
                                        expected_brand_cd=expected_brand_cd_for_qc,
                                    )
                                    if not repaired_mismatches:
                                        mismatches = []
                                        buffered_data_events = [repaired_event]
                                        event_data = repaired_event.get("data", {})
                                        assistant_response = repaired_response
                                        draft_response = repaired_response
                                        draft_for_qc = repaired_response
                                        last_template = "quickReply"
                                        last_template_source = "qc_repair"
                                        last_assistant_response_source = "code_qc_mismatch_repair"
                                        repaired_agent = (
                                            str(original_message_events[-1].get("agent") or "[DISCOVERY AGENT]")
                                            if original_message_events
                                            else "[DISCOVERY AGENT]"
                                        )
                                        original_message_events = [{
                                            "type": "message",
                                            "content": repaired_response,
                                            "agent": repaired_agent,
                                        }]
                                        logger.info("[QC_VERIFIER] repaired factual mismatch before fallback")
                                    else:
                                        mismatches = repaired_mismatches
                            _qc_passed = not mismatches and not hard_violations
                            if _qc_passed:
                                if policy_warnings:
                                    logger.info("[QC_VERIFIER] PASS with contract warning(s): %s", policy_warnings)
                                    _qc_summary = f"PASS_WITH_WARNING ({len(policy_warnings)})"
                                else:
                                    logger.debug("[QC_VERIFIER] PASS")
                                    _qc_summary = "PASS"
                            else:
                                logger.warning(
                                    "[QC_VERIFIER] %d mismatch(es), %d hard contract violation(s), "
                                    "%d warning(s): %s %s %s",
                                    len(mismatches),
                                    len(hard_violations),
                                    len(policy_warnings),
                                    [m.as_dict() for m in mismatches],
                                    hard_violations,
                                    policy_warnings,
                                )
                                _qc_summary = (
                                    f"MISMATCH ({len(mismatches)})"
                                    if mismatches
                                    else f"CONTRACT_VIOLATION ({len(hard_violations)})"
                                )
                            _qc_span.update(
                                output=_truncate({
                                    "summary": _qc_summary,
                                    "verdict": "PASS" if _qc_passed else "MISMATCH",
                                    "mismatches": [m.as_dict() for m in mismatches],
                                    "contract_violations": contract_violations,
                                    "hard_contract_violations": hard_violations,
                                    "qc_policy_warnings": policy_warnings,
                                }),
                            )
                            if hard_violations and turn_contract is not None and not _parallel_qc:
                                fallback_event = _build_recommendation_contract_fallback_event(
                                    hard_violations,
                                    turn_contract,
                                ) or _build_turn_contract_fallback_event(
                                    turn_contract=turn_contract,
                                    user_text=user_query,
                                    tool_data_list=tool_context_items,
                                ) or build_response_policy_guard_event(turn_contract)
                                buffered_data_events = [fallback_event]
                                last_template = "quickReply"
                                last_template_source = "turn_contract_qc"
                                last_assistant_response_source = str(
                                    fallback_event.get("assistant_response_source")
                                    or "code_turn_contract_qc_guard"
                                )
                                event_data = fallback_event.get("data", {})
                                assistant_response = str(event_data.get("assistantResponse") or "")
                                draft_response = assistant_response
                                draft_for_qc = assistant_response
                                fallback_source_domain = str(
                                    fallback_event.get("source_domain") or current_contract_source_domain or ""
                                ).lower()
                                original_message_events = [{
                                    "type": "message",
                                    "content": assistant_response,
                                    "agent": (
                                        "[DISCOVERY AGENT]"
                                        if fallback_source_domain == MultiAgentDomain.Domain.DISCOVERY.value
                                        else "[TRANSACTION AGENT]"
                                    ),
                                }]
                            elif hard_violations and _parallel_qc:
                                logger.warning(
                                    "[TURN_CONTRACT] QC contract violation observed after parallel data emission: %s",
                                    hard_violations,
                                )
                            elif mismatches and not _parallel_qc:
                                fallback_event = _qc_inventory_availability_recovery_event(
                                    mapper_tool_items,
                                    mismatches,
                                ) or _qc_factual_mismatch_guard_event(mismatches)
                                buffered_data_events = [fallback_event]
                                last_template = str(fallback_event.get("template") or "quickReply")
                                last_template_source = "qc_verifier"
                                last_assistant_response_source = str(
                                    fallback_event.get("assistant_response_source")
                                    or "code_qc_factual_mismatch_guard"
                                )
                                event_data = fallback_event.get("data", {})
                                assistant_response = str(event_data.get("assistantResponse") or "")
                                draft_response = assistant_response
                                draft_for_qc = assistant_response
                                original_message_events = [{
                                    "type": "message",
                                    "content": assistant_response,
                                    "agent": "[TRANSACTION AGENT]",
                                }]
                            elif mismatches and _parallel_qc:
                                logger.warning(
                                    "[QC_VERIFIER] factual mismatch observed after parallel data emission: %s",
                                    [m.as_dict() for m in mismatches],
                                )
                    except Exception as e:
                        logger.warning(f"[QC_VERIFIER] Verifier failed, using original draft: {e}")
                elif called_tool_names:
                    logger.debug(
                        "[QC_VERIFIER] Skipped QC: reason=%s template=%s source=%s response_source=%s tools=%s",
                        qc_skip_reason,
                        last_template,
                        last_template_source,
                        last_assistant_response_source,
                        sorted(called_tool_names),
                    )
                _lat_qc_ms = (time.perf_counter() - _qc_started_at) * 1000

            if not _parallel_qc:
                # SEQUENTIAL (default): data events were buffered; yield them as-is now.
                # Verifier never rewrites the draft, so no patching is needed.
                for buffered_evt in buffered_data_events:
                    _mark_first_visible()
                    yield f"data: {json.dumps(buffered_evt, ensure_ascii=False)}\n\n"

            if original_message_events:
                final_msg_event = original_message_events[-1]
                final_msg_event["content"] = draft_response
                _mark_first_visible()
                yield f"data: {json.dumps(final_msg_event, ensure_ascii=False)}\n\n"
        else:
            # FALLBACK HISTORY SYNC: If no text was generated, only yield message events
            # if they actually contain text. We DO NOT want to save empty assistant
            # messages to Redis, as it pollutes the LLM's future context window.
            for msg_event in original_message_events:
                if msg_event.get("content", "").strip():  # <-- ONLY yield if it has text
                    _mark_first_visible()
                    yield f"data: {json.dumps(msg_event, ensure_ascii=False)}\n\n"

        # 4. PERSIST NEXT-TURN CONTEXT
        if session_id and (
            tool_context_items
            or next_quick_reply_domain_values
            or next_predicted_domain_values
            or pending_slots is not None
        ):
            try:
                from services.tstation.chat_history_service import get_chat_history_service

                history_svc = get_chat_history_service()

                await history_svc.finalize_chat_context_async(
                    session_id=session_id,
                    tool_data=tool_context_items,
                    quick_reply_domains=next_quick_reply_domain_values,
                    predicted_domains=next_predicted_domain_values,
                    user_id=user_id,
                )
                if pending_slots is not None:
                    await history_svc.save_slots_async(session_id, pending_slots, user_id=user_id)
            except Exception as e:
                logger.warning(f"[STREAM_CTX] Failed to save stream context: {e}")

        _t_qc = time.perf_counter()
        _lat_stream_total_ms = (_t_qc - _t_request_start) * 1000
        logger.debug(
            f"[LATENCY] stream — agents={(_t_agents - _t_stream_start)*1000:.0f}ms "
            f"first_visible={_lat_first_visible_ms or 0:.0f}ms "
            f"pre_tool_think={_lat_agent_pre_tool_think_ms:.0f}ms "
            f"post_tool_output={_lat_agent_post_tool_output_ms:.0f}ms "
            f"llm_gen={_lat_agent_llm_generation_ms:.0f}ms "
            f"tools={_lat_tool_ms:.0f}ms "
            f"decision={_lat_decide_next_action_ms:.0f}ms "
            f"qc={_lat_qc_ms:.0f}ms "
            f"stream_total={_lat_stream_total_ms:.0f}ms"
        )

        if parent_span is not None:
            # The augmented user message has a CONVERSATION CONTEXT prefix and
            # a [current_time: ...] suffix injected upstream. Strip them so the
            # trace name reflects what the user actually typed (e.g.
            # "벤투스 S2 AS 225/55R17") instead of the augmentation header.
            _last_user_raw = next(
                (m.get("content", "") for m in reversed(messages) if m.get("role") == "user"), ""
            )
            _last_user = StreamingMultiAgentCoordinator._extract_current_user_input(_last_user_raw) or _last_user_raw
            # Trace `output` carries the actual assistant response so the Langfuse
            # trace list shows what the user saw. Routing / tool / template / QC
            # metadata moves to `metadata` (and the `qc` child span already holds
            # the verdict + result for drill-down).
            _route = "→".join(d.value for d in domains) if domains else ""
            final_status, error_class, user_visible_error = _trace_final_error_state(
                tool_errors=tool_errors,
                draft_response=draft_response,
                buffered_data_events=buffered_data_events,
                original_message_events=original_message_events,
                last_assistant_response_source=last_assistant_response_source,
            )
            _trace_metadata = {
                "route": _route,
                "tools": sorted(called_tool_names),
                "called_tools": sorted(called_tool_names),
                "tool_error_count": len(tool_errors),
                "tool_errors": tool_errors[:10],
                "final_status": final_status,
                "error_class": error_class,
                "user_visible_error": user_visible_error,
                "template": last_template,
                "final_template": last_template,
                "template_source": last_template_source,
                "template_qc_policy": _TEMPLATE_QC_POLICY.get(last_template or ""),
                "assistant_response_source": last_assistant_response_source,
                "source_domain": (
                    str((buffered_data_events[-1].get("source_domain") or "")).lower()
                    if buffered_data_events
                    else None
                ),
                "session_id": session_id,
                "trace_id": trace_id,
                "turn_contract": turn_contract.to_dict() if turn_contract else None,
                "qc": "PASS" if _qc_passed else "CORRECTED",
                "qc_executed": qc_executed,
                "qc_skip_reason": qc_skip_reason,
                "contract_violations": contract_violations,
                "hard_contract_violations": hard_violations,
                "qc_policy_warnings": policy_warnings,
                "latency_ms": int(_lat_stream_total_ms),
                "latency_first_visible_ms": (
                    round(_lat_first_visible_ms) if _lat_first_visible_ms is not None else None
                ),
                "latency_stream_total_ms": round(_lat_stream_total_ms),
                "latency_agent_pre_tool_think_ms": round(_lat_agent_pre_tool_think_ms),
                "latency_agent_post_tool_output_ms": round(_lat_agent_post_tool_output_ms),
                "latency_agent_llm_generation_ms": round(_lat_agent_llm_generation_ms),
                "latency_qc_ms": round(_lat_qc_ms),
            }
            _trace_output = _truncate(draft_response)
            _trace_input = _truncate(_last_user)
            # Set both the parent span's own output AND the trace-level output.
            safe_trace_update(parent_span, output=_trace_output)
            safe_trace_update(
                parent_span,
                trace=True,
                name=(_last_user[:60] if _last_user else "chat"),
                input=_trace_input,
                output=_trace_output,
                metadata=_trace_metadata,
            )
            # Create a final "✅ response" observation that carries the
            # user-visible answer as its I/O. Langfuse v3 trace overview falls
            # back to displaying the latest child chain's I/O (e.g. QC chain
            # returning "PASS", or the agent chain dumping the message
            # history) when no other signal wins. By making this the very last
            # observation in the trace with input=user-message and output=
            # assistant-response, the trace overview reads what the user
            # actually saw — regardless of which child chains ran earlier.
            if trace_id and _tracing_enabled:
                try:
                    # Name the final span with the user's question — Langfuse v3
                    # also derives trace.name from the latest observation, so a
                    # generic "response" name would override the user-message
                    # trace name we set on the parent span.
                    _response_span_name = (_last_user[:60] if _last_user else "response")
                    response_span = tracer.start_span(
                        name=_response_span_name,
                        trace_context={"trace_id": trace_id, "parent_span_id": parent_span_id},
                        input=_trace_input,
                    )
                    safe_trace_update(response_span, output=_trace_output)
                    safe_trace_update(
                        response_span,
                        trace=True,
                        name=_response_span_name,
                        input=_trace_input,
                        output=_trace_output,
                    )
                    response_span.end()
                except Exception as exc:
                    logger.debug("[TRACE] response span failed: %s", exc)
            logger.debug(
                "[TRACE] Sealed trace output (%d chars) route=%s qc=%s recording=%s",
                len(draft_response),
                _route or "?",
                "PASS" if _qc_passed else "CORRECTED",
                getattr(getattr(parent_span, "_otel_span", None), "is_recording", lambda: "?")(),
            )
            parent_span.end()
            # Force immediate OTel batch export so the trace.output update we just
            # set is visible in Langfuse UI without waiting for the next periodic
            # flush.
            try:
                tracer.flush()
            except Exception as exc:
                logger.debug("[TRACE] flush failed: %s", exc)

        # 5. FINALIZE THE STREAM
        if coordinator_done_event:
            yield f"data: {json.dumps(coordinator_done_event, ensure_ascii=False)}\n\n"

        yield f"data: {json.dumps({'type': 'DONE'}, ensure_ascii=False)}\n\n"
        yield "data: [DONE]\n\n"
